window.__SUM[10]={"LR003638":{"pair":"a -> Mc1r","headline":"Agouti antagonises MC1R in functional and binding studies across three abstract-only papers; ligand is an inhibitor, not an agonist.","interaction_type":"direct binding","direction_and_effect":"Agouti is an antagonist of the MSH receptor and blocks alpha-MSH stimulation of adenylyl cyclase [PMID:7935841]. Recombinant ASIP inhibits alpha-MSH-stimulated cAMP at hMC1R, with competitive antagonism seen only at hMC1R [PMID:9058374]. Alanine mutants of agouti (Arg116, Phe118) greatly lower affinity for MC1R, 3 and 4 [PMID:9454589]. Curators label the effect inverse agonist for two papers and antagonist for one.","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[{"value":"pKd 8.6","assay":"melanocortin receptor binding inhibition, curator-recorded for alanine-scanning study","system":"mouse agouti, mouse receptor","cite":"PMID:9454589"}],"species_and_systems":"Mouse agouti and mouse receptor in two papers [PMID:7935841, PMID:9454589]; human ASIP at human MC1R in stably transfected L cells and OS3 cells [PMID:9058374]. The mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Agouti is flagged secreted [flag]; the abstract calls mouse agouti a paracrine signalling molecule [PMID:9058374].","caveats":"All three papers read as abstracts only. The pKd value is curator-recorded and not stated in the abstract text. Abstract of PMID:9454589 concerns mutants and gives no wild-type constant.","key_references":[{"PMID":"9058374","why":"Human ASIP inhibits cAMP at hMC1R; competitive antagonism"},{"PMID":"7935841","why":"Agouti identified as MSH receptor antagonist"},{"PMID":"9454589","why":"Agouti residues needed for melanocortin receptor binding"}],"covers":["LR003638"]},"LR003557":{"pair":"ADAM15 -> ITGA5","headline":"ADAM15 disintegrin domain engages integrin alpha5beta1 on MOLT-4 T cells, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Metargidin Fc chimera bound MOLT-4 cells, and alpha5beta1 contributes to this binding; adhesion was mediated by the disintegrin domain and inhibited by RGD peptides [PMID:9914169]. Specificity was confirmed in solid-phase assays with purified recombinant integrins [PMID:9914169].","molecular_requirements":"The receptor is alpha5beta1; alpha5 alone is not shown. Adhesion is divalent-cation dependent and enhanced by Mn2+ [PMID:9914169].","affinity_potency":[],"species_and_systems":"Human proteins and human cell lines; ADAM15 ectodomain-Fc chimera [PMID:9914169].","localisation_and_range":"ADAM15 is a type I transmembrane glycoprotein and flagged not secreted [PMID:9914169] [flag].","caveats":"One paper, abstract only; alpha5beta1 only 'contributes' to binding. Two other judged rows were abstract-insufficient or different-entity.","key_references":[{"PMID":"9914169","why":"ADAM-15 binding to alpha5beta1 on MOLT-4 cells"}],"covers":["LR000007","LR003557"]},"LR005393":{"pair":"ADAM17 -> IL1R2","headline":"ADAM17 recognises IL-1RII through its extracellular domains; this is a protease-substrate interaction, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Deletion variants showed that only the extracellular domains of ADAM17 are needed for interaction with the substrates IL-6R and IL-1RII; the membrane-proximal domain is mandatory for recognition of these type-I transmembrane proteins [PMID:22575642].","molecular_requirements":"The membrane-proximal domain of ADAM17 is required; transmembrane and cytoplasmic regions are dispensable [PMID:22575642].","affinity_potency":[],"species_and_systems":"Cell assays with tagged ADAM17 deletion variants; species not reported in our evidence [PMID:22575642].","localisation_and_range":"Both are membrane proteins; ADAM17 flagged not secreted [flag].","caveats":"One paper, abstract only; affinity not reported. Evidence is of substrate recognition, not signalling.","key_references":[{"PMID":"22575642","why":"ADAM17 membrane-proximal domain recognises IL-1RII"}],"covers":["LR002067","LR005393"]},"LR003566":{"pair":"ADAM2 -> CD9","headline":"CD9 is required for high-avidity ADAM2 (fertilin beta) binding to egg alpha6beta1, but is not shown to contact ADAM2 directly.","interaction_type":"functional only","direction_and_effect":"Anti-CD9 mAb JF9 inhibits sperm-egg binding and fusion in a dose-dependent manner and disrupts binding of fertilin- or fertilin-beta-disintegrin-coated beads to eggs [PMID:10518536].","molecular_requirements":"High-avidity binding between fertilin beta (ADAM 2) and alpha6beta1 requires cooperation between alpha6beta1 and CD9 [PMID:10518536]. CD9 associates with beta1 integrins [PMID:10518536].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm [PMID:10518536]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg membrane contact.","caveats":"Abstract read only. The curator note says CD9 is required for high-avidity binding but not shown to directly contact ADAM2; CD9 acts as a co-factor of the integrin, so this is an indirect, co-receptor-type relationship.","key_references":[{"PMID":"10518536","why":"Anti-CD9 blocks fertilin-bead binding and sperm-egg fusion in mouse"}],"covers":["LR000016","LR003566"]},"LR003575":{"pair":"ADAM9 -> ITGB5","headline":"ADAM9 disintegrin domain adhesion depends on alphaVbeta5; antibody-inhibition evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Myeloma cell adhesion to the recombinant ADAM9 (MDC-9) disintegrin domain was completely blocked by anti-alpha(v)beta(5) but not antibodies to other subunits; RGD peptides had no effect [PMID:11162558]. Curated effect: Stimulatory [flag].","molecular_requirements":"beta5 acts as part of alphaVbeta5; the alphaV partner is needed per the antibody target [PMID:11162558]. Binding was Mn2+/Ca2+ dependent.","affinity_potency":[],"species_and_systems":"Human; myeloma cells and recombinant disintegrin domain [PMID:11162558]. Mouse pair is ortholog-inferred.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Abstract-only, antibody inhibition rather than direct binding [PMID:11162558]. Affinity not reported. No database record in this dossier.","key_references":[{"PMID":"11162558","why":"alphaVbeta5 antibody blocks adhesion to the disintegrin domain"}],"covers":["LR000025","LR003575"]},"LR003584":{"pair":"ADM -> CALCR","headline":"Adrenomedullin activates CTR with low potency alone; potency rises with RAMP (one abstract-only paper plus GtoPdb).","interaction_type":"functional only","direction_and_effect":"With hCTR(I1-) alone, hAM raised cAMP but remained about 100-fold less potent than hCT; co-expression with RAMP increased apparent AM potency toward that of CT [PMID:12565884]. GtoPdb lists ADM as full agonist [DB:GtoPdb].","molecular_requirements":"RAMP co-expression increases AM potency; the combination is sensitive to salmon CT-(8-32), not hAM-(22-52) [PMID:12565884].","affinity_potency":[{"value":"pEC50 6.5-8.4","assay":"GtoPdb agonist record","system":"not specified","cite":"PMID:12565884"}],"species_and_systems":"Human receptor transfected in HEK-293 cells [PMID:12565884].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"Functional cAMP data only; no binding data. Alone, potency is about 100-fold lower than calcitonin [PMID:12565884]. Two further rows pending and one abstract_insufficient.","key_references":[{"PMID":"12565884","why":"cAMP response of CTR with and without RAMP"}],"covers":["LR000034","LR003584"]},"LR009371":{"pair":"ADRA2A -> GNAI2","headline":"Only a BioGRID FRET record; no paper confirms a ligand-receptor role. Likely a receptor-G protein transducer pair rather than a secreted ligand.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists ADRA2A - GNAI2 by FRET [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and cells of the FRET experiment are not reported in our evidence.","localisation_and_range":"ADRA2A is flagged receptor [flag]; no secretion or localisation flag for GNAI2.","caveats":"No papers support it: two were different_entity and two abstract_insufficient. Support is a single database record.","key_references":[],"covers":["LR009371"]},"LR008480":{"pair":"AFDN -> EPHB2","headline":"Database-only protein interaction between AFDN and EPHB2; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID and IntAct list a two-hybrid interaction between AFDN (MLLT4) and EPHB2 [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; EPHB2 flagged receptor and transmembrane, not secreted [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR008480"]},"LR003593":{"pair":"AGRP -> MC5R","headline":"AGRP(87-132) binds cells expressing MC5R and inhibits alpha-MSH signalling in one abstract-only paper; weaker than at MC3R and MC4R.","interaction_type":"direct binding","direction_and_effect":"[125I]AGRP(87-132) bound only to cells expressing MC3R, MC4R and MC5R in conventional and photoemulsion binding studies [PMID:9892020]. AGRP(87-132) dose-dependently inhibited alpha-MSH-generated cAMP at cloned melanocortin receptors [PMID:9892020]. GtoPdb lists an antagonist interaction [DB:GtoPdb].","molecular_requirements":"The C-terminal cysteine-rich domain AGRP(87-132), a 46-amino acid variant, is equipotent to an 111-amino acid variant; N-terminal deletion did not alter receptor subtype specificity [PMID:9892020]. NDP-MSH and the AGRP fragment displace each other competitively [PMID:9892020].","affinity_potency":[{"value":"pIC50 6.5","assay":"inhibition of alpha-MSH-generated cAMP / binding","system":"cloned melanocortin receptor, human AGRP(87-132)","cite":"PMID:9892020"}],"species_and_systems":"Chemically synthesised human AGRP(87-132) and a mouse [Leu127Pro]AGRP variant on cloned receptors; curation tags human/human [PMID:9892020].","localisation_and_range":"AGRP is flagged secreted [flag].","caveats":"Single abstract-only paper. The abstract does not say which receptor the pIC50 6.5 refers to; the curator tied it to MC5R, and the value is lower than the pIC50 values given for MC3R and MC4R elsewhere. Direct competition with NDP-MSH is shown for the melanocortin receptors collectively [PMID:9892020].","key_references":[{"PMID":"9892020","why":"Binding and cAMP inhibition by synthetic AGRP(87-132) at MC3R, MC4R and MC5R"}],"covers":["LR000043","LR003593"]},"LR002099":{"pair":"ALCAM -> ALCAM","headline":"ALCAM binds itself homophilically with weak measured affinity (KD 29-48 microM); the interaction is mentioned in a second paper as background.","interaction_type":"direct binding","direction_and_effect":"ALCAM mediates adhesion through homophilic ALCAM-ALCAM or heterophilic ALCAM-CD6 interactions [PMID:23052204]. Tetraspanin CD9 upregulated both [PMID:23052204]; the homophilic effect was not measured directly. UniProt notes homotypic interactions with ALCAM-expressing cells [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond ALCAM chains interacting.","affinity_potency":[{"value":"KD 29-48 microM; Koff >= 5.3 s-1","assay":"homophilic binding measured in the study","system":"human CD166","cite":"PMID:15048703"}],"species_and_systems":"Human proteins and leukocytes [PMID:15048703, PMID:23052204]. IntAct lists molecular sieving and solid phase assays [DB:IntAct Q13740-Q13740].","localisation_and_range":"Membrane-bound adhesion molecule acting between cells (juxtacrine); ALCAM carries secreted and transmembrane flags [flag].","caveats":"Affinity is about 100-fold weaker than ALCAM-CD6 [PMID:15048703]. Abstracts only. PMID:23052204 is about CD9 regulation, and the cited sentence is background.","key_references":[{"PMID":"15048703","why":"Measures homophilic CD166 affinity versus CD6"},{"PMID":"23052204","why":"CD9 raises ALCAM homophilic and heterophilic adhesion"}],"covers":["LR002099","LR005425"]},"LR001649":{"pair":"AMELX -> CD63","headline":"Amelogenin interacts with CD63; supported by abstract-level mapping data from one paper.","interaction_type":"direct binding","direction_and_effect":"Amelogenin interacts with CD63 and LAMP1 and moves into CD63/LAMP1-positive vesicles after addition to cultured cells [PMID:17708745]. Effect direction: not reported in our evidence.","molecular_requirements":"The amelogenin region PLSPILPELPLEAW engages CD63 residues 165-205 [PMID:17708745].","affinity_potency":[],"species_and_systems":"Curators recorded human ligand and receptor; the human pair is ortholog-inferred, and cells are described only as cultured cells [PMID:17708745].","localisation_and_range":"Amelogenin is flagged secreted [flag]; the paper proposes interactions at ameloblast secretory surfaces, with endocytic clearance context [PMID:17708745].","caveats":"Abstract-only read of a single paper. The human and mouse pairs are both projected by orthology. No affinity values or database records.","key_references":[{"PMID":"17708745","why":"Amelogenin-CD63 interaction region mapping"}],"covers":["LR001649","LR005037"]},"LR005429":{"pair":"ANGPT2 -> ITGB1","headline":"Ang2 binds the beta1-integrin subunit in ELISA and activates beta1-integrin; supported by a full-text paper and an abstract-only glioma paper.","interaction_type":"direct binding","direction_and_effect":"Ang2, but not Ang1, activates beta1-integrin, leading to endothelial destabilization; this occurs independently of Tie2 [PMID:25635707]. Ang2 also interacts with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, ERK1/2 and JNK [PMID:16424009]. Agonist at the integrin.","molecular_requirements":"Ang2 directly bound the beta1-integrin subunit in ELISA; the Ang2 superclustering and coiled-coil domains were needed for activation (an Ang2-Ang1 chimera activated beta1-integrin like Ang2, the Ang1-Ang2 chimera did not) [PMID:25635707]. The glioma pathway needed both beta1 and alpha(v) integrins [PMID:16424009].","affinity_potency":[],"species_and_systems":"Endothelial cells, CHO and HeLa cells, ELISA, and Ang2 transgenic mice [PMID:25635707]; human glioma cells and murine xenografts [PMID:16424009]. BioGRID has reconstituted complex and affinity capture records [DB:BioGRID].","localisation_and_range":"ANGPT2 is flagged as secreted and ITGB1 as a receptor and not secreted [flag]; Ang2 localised to cell-matrix adhesions in HeLa cells [PMID:25635707].","caveats":"The ELISA shows binding to the beta1 subunit alone with no affinity value in our evidence. The glioma paper was read as an abstract and concerns the alphaVbeta1 heterodimer. Ang1 does not activate beta1-integrin [PMID:25635707]. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"25635707","why":"Direct ELISA binding of Ang2 to beta1-integrin; activation requires Ang2 not Ang1"},{"PMID":"16424009","why":"Ang2/alphaVbeta1 signalling in Tie2-deficient glioma cells"}],"covers":["LR002103","LR005429"]},"LR005438":{"pair":"ANGPTL4 -> LEPR","headline":"ANGPTL4 is reported to bind the leptin receptor by SPR and co-IP in one mouse heterotopic-ossification study.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4, induced from brown fat after tenotomy, binds LepR on PRRX1+ mesenchymal cells and promotes chondrogenesis and heterotopic ossification; curator labels it agonist [PMID:38147550]. LepR disruption in PRRX1+ cells or ANGPTL4 deletion impedes this [PMID:38147550].","molecular_requirements":"Co-IP shows full-length LepR and the N-terminal fragment pull down ANGPTL4, while the fragment lacking the N-terminus does not; docking suggests the C-terminus of ANGPTL4 is the contact site [PMID:38147550].","affinity_potency":[{"value":"ABS (tr_KD) = 21.924","assay":"SPR, ANGPTL4 with LepR; units not given","system":"as reported; leptin comparator ABS (tr_KD) = 8.103","cite":"PMID:38147550"}],"species_and_systems":"Mouse tenotomy model, HEK293 co-IP with GST-ANGPTL4; AlphaFold mouse IDs used for docking [PMID:38147550]. The curator fields say human, which looks inconsistent. Human pair is ortholog-inferred.","localisation_and_range":"ANGPTL4 is flagged secreted; LEPR transmembrane [flag]; serum factor acting on cells at the injury site [PMID:38147550].","caveats":"Abstract plus full-text excerpts. The affinity figure has no units and is described as higher than leptin, so treat the number cautiously. Signalling through LepR by ANGPTL4 is not directly shown in the excerpts.","key_references":[{"PMID":"38147550","why":"ANGPTL4 binds LepR and drives heterotopic ossification"}],"covers":["LR002116","LR005438"]},"LR005447":{"pair":"APLP1 -> CNTN4","headline":"APLP1 binds CNTN4 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN4; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. APLP1 appeared to interact more strongly with CNTN4 than with CNTN3 or CNTN5 [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002130","LR005447"]},"LR005456":{"pair":"APOA2 -> TREM2","headline":"Listed in BioGRID and UniProt from one paper; no curator-verified paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a reconstituted complex for TREM2 and APOA2 [DB:BioGRID]; UniProt states TREM2 acts as a receptor for apolipoproteins including APOA2 and enhances their uptake in microglia [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database records.","localisation_and_range":"TREM2 is flagged secreted and receptor [flag].","caveats":"Two papers were judged abstract_insufficient. Both records point to PMID 27477018 [DB:BioGRID][DB:UniProt].","key_references":[],"covers":["LR002139","LR005456"]},"LR001658":{"pair":"APOB -> ENO1","headline":"One abstract-level paper shows apoB binding surface ENO1 with higher affinity than plasminogen and driving inflammation.","interaction_type":"direct binding","direction_and_effect":"ApoB from RA synovial fluid was identified as a ligand of ENO1 with higher affinity than plasminogen; binding on monocytes elicited TNF-alpha, IL-1beta and IL-6 via p38 MAPK and NF-kB, and apoB worsened K/BxN serum-transfer arthritis [PMID:29997113].","molecular_requirements":"Not reported in our evidence beyond ENO1 itself.","affinity_potency":[],"species_and_systems":"Human synovial fluid and peripheral blood mononuclear cells, and mouse arthritis; LDLR-knockout mice showed arthritis severity comparable with wild type [PMID:29997113]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted; ENO1 is expressed on the surface of immune cells, more in RA patients [PMID:29997113].","caveats":"Binding was shown by ligand blotting, binding assay and surface plasmon resonance, but no value is given in the abstract. Abstract only; single paper.","key_references":[{"PMID":"29997113","why":"ApoB-ENO1 binding and pro-inflammatory effect in arthritis"}],"covers":["LR001658","LR005045"]},"LR008543":{"pair":"APOB -> MTTP","headline":"Database records only (two-hybrid, co-IP); MTTP carries no receptor annotation and no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists two-hybrid and affinity capture-western records and IntAct lists co-immunoprecipitation [DB:BioGRID][DB:IntAct]; UniProt says APOB interacts with MTTP [DB:UniProt]. Signalling effect not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"MTTP has no receptor or transmembrane flag in our evidence [flag]; localisation not reported.","caveats":"Only a review-only row was judged. The partner may be a physical interactor rather than a signalling receptor.","key_references":[],"covers":["LR008543"]},"LR005465":{"pair":"APOE -> TREM2","headline":"Two independent abstract-level binding studies; apoE binds TREM2 and the R47H variant weakens it.","interaction_type":"direct binding","direction_and_effect":"ApoE showed high-affinity binding to human TREM2 and increased TREM2-dependent phagocytosis of apoE-bound apoptotic N2a cells by primary microglia [PMID:26374899]. A protein microarray screen found apolipoproteins including APOE as TREM2 ligands; TREM2 overexpression enhanced APOE uptake [PMID:27477018].","molecular_requirements":"Binding was reduced by AD-associated TREM2 variants (R47H vastly reduced) [PMID:26374899] [PMID:27477018]. TREM2 signals with adaptor DAP12 [PMID:26374899].","affinity_potency":[],"species_and_systems":"Human proteins in biochemical assays; microglia and heterologous cells [PMID:26374899] [PMID:27477018]. Mouse pair is ortholog-inferred.","localisation_and_range":"TREM2 flagged secreted and receptor; ApoE secreted [flag].","caveats":"Both abstract only; affinity described as high but no number in our evidence.","key_references":[{"PMID":"26374899","why":"apoE-TREM2 binding and R47H"},{"PMID":"27477018","why":"microarray screen of TREM2 ligands"}],"covers":["LR002150","LR005465"]},"LR003629":{"pair":"APP -> CD74","headline":"CD74 co-precipitates with APP in cell overexpression, and APP-CD74 is a predicted endothelium-to-macrophage axis in mouse kidney injury; support is limited.","interaction_type":"direct binding","direction_and_effect":"CD74 interacts with APP and acts as a negative regulator of Abeta, reducing secreted Abeta40 and Abeta42 without changing sAPPalpha or sAPPbeta, apparently by diverting APP to CD74-induced vacuoles [PMID:19849849]. In mouse kidney injury, cell-communication analysis placed APP-CD74 as the dominant endothelial-to-macrophage pair, and the paper reports a co-IP showing direct interaction [PMID:39351084].","molecular_requirements":"Mature APP, not the C-terminal fragments, bound CD74; the 33 kDa N-terminal CD74 fragment bound APP but not the 14 kDa one, and the luminal trimeric region (1-115 deletion lacks it) and the first 23 residues were required [PMID:19849849]. CD74 did not pull down Notch or APLP2 [PMID:19849849]. No complex partners reported for the kidney study.","affinity_potency":[],"species_and_systems":"Binding: human HeLa and HEK293APP cells, with both human and mouse CD74 isoforms binding APP [PMID:19849849]. Kidney: mouse UUO and IRI models plus macrophage-endothelial co-culture [PMID:39351084].","localisation_and_range":"APP and CD74 are both flagged transmembrane, and APP is also flagged secreted [flag]. The kidney paper describes endothelial APP signalling to macrophage CD74 across cells [PMID:39351084].","caveats":"The 2009 paper concerns APP processing and trafficking inside cells, not CD74 as a signalling receptor for APP [PMID:19849849]. The kidney inference rests mainly on scRNA-seq with limited validation, and the co-IP cell system is not specified in our excerpts [PMID:39351084]. Both curated papers were read from abstracts plus excerpts. IntAct lists one solid-phase assay record [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"19849849","why":"Co-IP mapping of CD74-APP interaction and effect on Abeta"},{"PMID":"39351084","why":"APP-CD74 endothelial-macrophage axis in mouse kidney injury"}],"covers":["LR000080","LR003629"]},"LR005474":{"pair":"APP -> DCC","headline":"APP acts as a netrin-1-dependent co-receptor for DCC in commissural axon guidance; one paper read as abstract only.","interaction_type":"functional only","direction_and_effect":"APP interacts with DCC in the presence of netrin-1 and enhances netrin-1-mediated DCC signalling, such as MAPK activation; the authors conclude APP functions as a co-receptor for DCC [PMID:22782894]. Inactivation of APP in mice is associated with reduced commissural axon outgrowth [PMID:22782894].","molecular_requirements":"APP is part of the DCC receptor complex; the interaction requires netrin-1 [PMID:22782894]. Netrin-1 itself also interacts with APP [PMID:22782894].","affinity_potency":[],"species_and_systems":"Commissural axon growth cones; APP-inactivated mice [PMID:22782894]. Other experimental details are not reported in our evidence. Both database species rows are ortholog-inferred.","localisation_and_range":"Described as expressed at the growth cone [PMID:22782894]; APP and DCC are both flagged transmembrane receptor-capable [flag]. Range not reported.","caveats":"APP is a co-receptor here, not a classical ligand, so the ligand-receptor direction is questionable. Single paper, abstract only; no database record. Whether APP and DCC bind directly without netrin-1 is not reported in our evidence.","key_references":[{"PMID":"22782894","why":"APP-DCC complex in netrin-1 axon guidance"}],"covers":["LR002159","LR005474"]},"LR007094":{"pair":"APP -> SORL1","headline":"Database records support direct APP-SORL1 binding; the two papers are variant trafficking studies, not binding assays.","interaction_type":"direct binding","direction_and_effect":"SORL1 binds APP and retains it in the trans-Golgi network, reducing processing to sAPPalpha and Abeta [DB:UniProt]. SORL1 variants disrupted APP endosomal retention and raised Abeta secretion [PMID:42630093] [PMID:42149354].","molecular_requirements":"SORL1:APP(18-770) complex in the endosome lumen [DB:Reactome]; structure by x-ray crystallography [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human iPSC neurons and organoids [PMID:42630093]; SH-SY5Y and APPswe-expressing HEK293 cells [PMID:42149354].","localisation_and_range":"Endosomal/Golgi trafficking, not extracellular signalling [PMID:42149354] [DB:Reactome].","caveats":"Both papers are abstract-only and functional, so they show effects of SORL1 loss on APP, not binding. Binding rests on databases (co-IP, fluorescence polarization, cross-linking) [DB:IntAct] [DB:BioGRID]. The relationship is trafficking receptor-cargo.","key_references":[{"PMID":"42630093","why":"SORL1 variant impairs APP sorting in human neurons"},{"PMID":"42149354","why":"SORL1 frameshift variant impairs APP retention"}],"covers":["LR007094"]},"LR009380":{"pair":"AREG -> ERBB3","headline":"Indirect: functional coupling through EGFR heterodimerisation in Ba/F3 cells, not direct ERBB3 binding.","interaction_type":"functional only","direction_and_effect":"AR stimulated ErbB receptor tyrosine phosphorylation and coupled to physiologic responses in Ba/F3 cells; the curator note says EGFR couples AR to ErbB-3 [PMID:8702723].","molecular_requirements":"EGFR is needed as the binding partner and heterodimerises with ErbB-3 per the curator note [PMID:8702723].","affinity_potency":[],"species_and_systems":"Mouse Ba/F3 cell lines expressing defined human ErbB combinations [PMID:8702723].","localisation_and_range":"AREG flagged secreted [flag].","caveats":"Abstract only. ErbB3 is not a direct amphiregulin binder per curator note; the abstract states results for singly and pairwise expressed receptors.","key_references":[{"PMID":"8702723","why":"AR coupling to ErbB family receptors"}],"covers":["LR009380"]},"LR005483":{"pair":"ARTN -> SDC3","headline":"ARTN binds the heparan sulfate chains of syndecan-3 with 10-50 nM affinity by SPR; one full-text paper, matrix-bound ligand.","interaction_type":"direct binding","direction_and_effect":"Immobilized, matrix-bound ARTN uses syndecan-3 as a receptor distinct from the GFRalpha-RET route, binding its heparan sulfate (HS) chains with high affinity; the interaction mediates cell spreading and neurite outgrowth with Src kinase involvement (agonist-type signalling) [PMID:21200028].","molecular_requirements":"Binding is through HS chains: heparinase III treatment strongly inhibited the GDNF-syndecan-3 interaction (shown for GDNF, not ARTN, in the excerpts) [PMID:21200028]. Whether syndecan-3 signals alone or presents ARTN to RET is not settled in our evidence.","affinity_potency":[{"value":"Kd 10-50 nM","assay":"surface plasmon resonance, immobilized ligand with HS-carrying syndecan-3 ectodomain (reported as range for GDNF, NRTN and ARTN)","system":"syndecan-3 purified from rat brain","cite":"PMID:21200028"}],"species_and_systems":"Ligand and receptor recorded as human; the SPR receptor was purified from rat brain [PMID:21200028]. Mouse pair is ortholog-inferred.","localisation_and_range":"ARTN is flagged secreted [flag]; the paper's effect needs ARTN immobilized on matrix, not soluble [PMID:21200028].","caveats":"Single paper. The Kd range is shared across three ligands, not ARTN alone. Syndecan-3 binding is via sugar chains, so it is a proteoglycan/heparan sulfate interaction rather than a classical protein-protein receptor.","key_references":[{"PMID":"21200028","why":"SPR and cell assays showing GFLs including ARTN use syndecan-3"}],"covers":["LR002169","LR005483"]},"LR003647":{"pair":"Azgp1 -> Itgav","headline":"Mouse Azgp1 is supported as an integrin alphaVbeta3 ligand by a single abstract-level cell adhesion study; direct binding was not shown.","interaction_type":"functional only","direction_and_effect":"Cell adhesion to Znalpha2gp was inhibited by RGDS and ELRGDV peptides and by an antibody against the vitronectin receptor, suggesting the RGD region of Znalpha2gp interacts with alphavbeta3 [PMID:9813179]. This is an adhesion (ligand-anchoring) readout; agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"The evidence concerns the alphavbeta3 heterodimer (vitronectin receptor), not Itgav alone; Itgb3 is the partner chain. Whether one chain is enough is not reported in our evidence [PMID:9813179].","affinity_potency":[],"species_and_systems":"Human Znalpha2gp was used with mouse MC3T3-E1 osteoblast-like cells, so the receptor tested is the mouse cell-surface integrin; the pair here is projected from this evidence [PMID:9813179].","localisation_and_range":"Ligand is flagged secreted and the receptor as a receptor [flag]; in the assay Znalpha2gp was coated on plates and cells adhered to it, i.e. a surface-bound presentation [PMID:9813179].","caveats":"Single paper, read as abstract only. No binding assay or affinity. The ligand protein in the experiments was human, not mouse [PMID:9813179]. The integrin chain assignment rests on the paper naming alphavbeta3.","key_references":[{"PMID":"9813179","why":"RGD- and anti-vitronectin-receptor-blocked adhesion of MC3T3-E1 cells to Znalpha2gp"}],"covers":["LR003647"]},"LR009731":{"pair":"B2M -> CD3G","headline":"B2M and CD3G co-occur only as chains in TCR-CD3 and peptide-MHC cryo-EM structures; no direct contact is shown in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. PDB entries are TCR-CD3 engaging peptide-MHC I [DB:PDB 7PHR] and a TCR-CD3 with HLA-A2 MAGEA4 peptide [DB:PDB 8ES8].","molecular_requirements":"Structures contain a B2M chain and a CD3G chain within a larger assembly (6 PDB records) [DB:PDB 7PHR]; whether B2M contacts CD3G is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB only (6 records)). The judged row was classified review_only.","key_references":[],"covers":["LR009731"]},"LR012386":{"pair":"BAMBI -> FZD7:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD7:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012386"]},"LR003656":{"pair":"BMP10 -> BMPR1A","headline":"Functional evidence only: ALK3 (BMPR1A) overexpression and knockdown change BMP10 signalling in cell lines; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred BMP10 signalling, and ALK3 shRNA in MC3T3 cells suppressed Smad signalling induced by BMP10 and two other ligands; BMP10 activated Smad1/5/8 but not Smad2/3 [PMID:16049014]. GtoPdb lists BMP10 as an agonist at BMPR1A [DB:GtoPdb].","molecular_requirements":"ALK3 or ALK6 was sufficient in COS7 cells; whether a type II partner is needed is not reported for this pair in our evidence (the same paper's shRNA implicates BMPRII and ActRIIA in BMP10 signalling [PMID:16049014]).","affinity_potency":[],"species_and_systems":"COS7 and MC3T3 cell lines, reporter assays; curators annotate human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Abstract read only. The result is a signalling readout, not binding, so indirect effects cannot be excluded.","key_references":[{"PMID":"16049014","why":"ALK3 overexpression/knockdown and BMP10 signalling"}],"covers":["LR000107","LR003656"]},"LR011693":{"pair":"BMP15:GDF2 -> ACVR1B:BMPR1B:BMPR2","headline":"Unsupported as a heterocomplex pair: no judged paper, and the database records concern GDF2 alone.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF2 as an agonist at BMPR1B and BMPR2 [DB:GtoPdb]. UniProt says GDF2 interacts with ACVRL1, BMPR2 and ACVR2B with high affinity in vitro [DB:UniProt].","molecular_requirements":"BioGRID lists reconstituted GDF2 complexes with BMPR2 and ACVR2A [DB:BioGRID]. No record covers a BMP15:GDF2 ligand complex or ACVR1B.","affinity_potency":[],"species_and_systems":"No paper in the dossier; species not reported in our evidence.","localisation_and_range":"GDF2 and BMP15 are annotated as secreted [flag].","caveats":"Two papers are still pending. Nothing in our evidence shows BMP15 and GDF2 acting as one ligand unit, or the three-chain receptor.","key_references":[],"covers":["LR011693"]},"LR003665":{"pair":"BMP2 -> ACVR1","headline":"Functional evidence only: knockdown of ALK2/3 blocks BMP2 signalling in human granulosa-lutein cells; ALK2 not separated from ALK3.","interaction_type":"functional only","direction_and_effect":"BMP2 stimulated SMAD1/5/8 phosphorylation, blocked by BMP type I receptor inhibitors dorsomorphin and dorsomorphin homolog 1 but not SB431542; ALK2/3 or BMPR2/ACVR2B knockdown reversed it and restored PTX3 expression [PMID:28977600]. Downstream, BMP2 suppressed PTX3. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"ALK2 and ALK3 were knocked down as a pair in the abstract, together with type II BMPR2/ACVR2B [PMID:28977600]; the individual ACVR1 contribution is not isolated.","affinity_potency":[],"species_and_systems":"Primary and immortalised human granulosa-lutein cells [PMID:28977600]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP2 is annotated as secreted [flag].","caveats":"Abstract only; no binding data. Other database records shown name BMPR1B rather than ACVR1 (BioGRID) [DB:BioGRID], and Reactome gives a generic 'binds the receptor complex' [DB:Reactome]. One row is pending.","key_references":[{"PMID":"28977600","why":"ALK2/3 and BMPR2/ACVR2B knockdown reverses BMP2 signalling"}],"covers":["LR000116","LR003665"]},"LR005492":{"pair":"BMP2 -> RGMA","headline":"RGMA binds BMP2 directly by SPR with the weakest affinity among RGMs; one paper plus structure records.","interaction_type":"direct binding","direction_and_effect":"RGM family members are described as co-receptors enhancing cellular responses to BMPs [PMID:23029472]. RGMA showed the lowest affinity for most BMPs tested [PMID:23029472].","molecular_requirements":"Not reported in our evidence beyond binding to RGMA.","affinity_potency":[{"value":"Kd 22 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"SPR, species not reported; mouse pair projected from human. PDB 4UHY holds a structure with BMP2 and RGMA chains [DB:PDB 4UHY].","localisation_and_range":"RGMA flagged secreted and receptor [flag].","caveats":"Single paper, read as abstract with limited excerpts; the Kd is from the curator's assay note. IntAct also records SPR [DB:IntAct].","key_references":[{"PMID":"23029472","why":"SPR of RGMs with BMPs"}],"covers":["LR002178","LR005492"]},"LR003674":{"pair":"BMP3 -> ACVR2B","headline":"BMP3 binds ACVR2B directly by SPR (Kd ~53 nM) and acts through it to suppress osteoblast differentiation; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"BMP3 binds ActRIIb with 30-fold higher affinity than ActRII [PMID:17924656]. In bone marrow stromal cells, Acvr2b knockdown reduces BMP3's suppressive effect on osteoblast differentiation, so BMP3 acts as an antagonist of osteogenic signalling through ACVR2B [PMID:22074949]. UniProt records BMP3 associating with type II receptor ACVR2B to activate SMAD2-dependent and SMAD-independent signalling [DB:UniProt].","molecular_requirements":"ACVR2B is the type II receptor; a type I partner is not reported in our evidence. Binding specificity is linked to Lys-30 interactions with residue 76 differences between ActRII and ActRIIb [PMID:17924656].","affinity_potency":[{"value":"Kd approximately 53 nM","assay":"surface plasmon resonance (BIAcore), BMP-3 with ActRIIb","system":"human proteins (curated experiment species)","cite":"PMID:17924656"},{"value":"Kd approximately 1.8 microM","assay":"SPR, BMP-3 with ActRII (ACVR2A), for comparison","system":"human proteins","cite":"PMID:17924656"}],"species_and_systems":"Binding paper: recombinant protein SPR plus Smad luciferase assays [PMID:17924656]. Functional paper: primary bone marrow stromal cell cultures; curators record human ligand and receptor, though the abstract mentions mouse knockout/transgenic models as background [PMID:22074949].","localisation_and_range":"BMP3 is flagged secreted and ACVR2B a transmembrane receptor [flag].","caveats":"Both papers were read as abstracts only. The functional paper shows knockdown reduces the effect, not direct binding. The pair's human record is ortholog-inferred per the dossier.","key_references":[{"PMID":"17924656","why":"SPR binding of BMP-3 to ActRII and ActRIIb with Kd values"},{"PMID":"22074949","why":"Acvr2b knockdown reduces BMP3 suppression of osteoblast differentiation"}],"covers":["LR000125","LR003674"]},"LR011198":{"pair":"BMP5 -> ACVR1","headline":"BMP5 to ACVR1 rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Three screened papers were judged abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR011198"]},"LR003683":{"pair":"BMP6 -> ACVR2A","headline":"BMP6 binds ActR-II (ACVR2A) in a 1999 cross-linking study, but the key data are 'not shown'; BioGRID and GtoPdb agree.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. BMP-6 bound ActR-II and ActR-IIB in singly transfected cells [PMID:10504300]. GtoPdb lists BMP6 as agonist at ACVR2A [DB:GtoPdb].","molecular_requirements":"Type II receptor binding was seen without a type I receptor in this paper [PMID:10504300]; further requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6 with transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. BioGRID has an affinity-capture-Western record from this paper and a reconstituted-complex record from another [DB:BioGRID][PMID:18070108]. Both species pairs are projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted and ACVR2A transmembrane [flag].","caveats":"The binding result is marked 'data not shown' in the paper's text, so only the authors' statement supports it. Affinity not reported.","key_references":[{"PMID":"10504300","why":"cross-linking of BMP-6 to ActR-II/ActR-IIB"}],"covers":["LR000134","LR003683"]},"LR007139":{"pair":"BMP6 -> BMPR1B:BMPR2","headline":"Complex row with one paper showing BMP-6 binding BMPR-IB together with BMPR-II in ROB-C26 cells.","interaction_type":"direct binding","direction_and_effect":"BMP-6 binding to BMPR-IB together with BMPR-II was detected in ROB-C26 cells; GtoPdb lists BMP6 as agonist at both BMPR1B and BMPR2 [DB:GtoPdb].","molecular_requirements":"Both chains named in the evidence sentence [PMID:10504300]. BioGRID has BMPR2-BMP6 affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Cell systems ROB-C26, C2C12, MC3T3-E1; curator recorded human ligand and receptor species [PMID:10504300]. Abstract-level read for this row.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Cell-type dependent: in C2C12 and MC3T3-E1 the profile is ALK-2-dominant, while the BMPR-IB profile is the ROB-C26 one [PMID:10504300]. Single paper; no affinity value.","key_references":[{"PMID":"10504300","why":"BMP-6 binds BMPR-IB with BMPR-II in ROB-C26 cells"}],"covers":["LR007139"]},"LR003692":{"pair":"BMP7 -> BMPR1B","headline":"BMP7 binds BMPR1B (ALK-6) efficiently; SPR KD 9 nM and COS-cell binding support it.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP7) bound ALK-6 efficiently in transfected COS cells [PMID:8006002]. BMP7 bound the type I receptor BMPR-IB with comparable affinity to its type II receptors in SPR [PMID:19735544]. GtoPdb lists agonist action [DB:GtoPdb].","molecular_requirements":"BMPR1B is a type I chain. Binding in COS cells was seen without type II receptors and increased with co-transfected DAF-4 [PMID:8006002].","affinity_potency":[{"value":"KD(kin) 9.0 nM","assay":"SPR, immobilised BMPR-IB ECD, soluble BMP7","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Human proteins, SPR and COS cells plus various nontransfected cell lines [PMID:19735544][PMID:8006002]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"PMID 8006002 was read as abstract only. The BMPR-IB KD(eq) is reported as not evaluated; the 9 nM is the kinetic KD [PMID:19735544]. Other judged papers: three abstract_insufficient, one different_entity, one pending.","key_references":[{"PMID":"19735544","why":"SPR affinity of BMP7 for BMPR-IB"},{"PMID":"8006002","why":"OP-1 binds ALK-6 efficiently in COS cells"}],"covers":["LR000143","LR003692"]},"LR007148":{"pair":"BMP7 -> BMPR1B:BMPR2","headline":"One abstract-level paper supports BMP7 binding BMPR-II in association with BMPR-IB.","interaction_type":"direct binding","direction_and_effect":"BMPR-II binds BMP-2 and BMP-7 in association with type I receptors including BMPR-IB [PMID:7791754]. GtoPdb lists agonist action for each chain [DB:GtoPdb].","molecular_requirements":"Association of BMPR-II with BMP type I receptors is ligand dependent in mammalian cells; BMPR-II binds BMP-7 alone but binding is enhanced by type I coexpression [PMID:7791754].","affinity_potency":[],"species_and_systems":"Cloned human BMPR-II, mammalian cells [PMID:7791754].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Single paper, abstract only; the BMPR-IB role is listed among several type I partners. Four papers were review_only, two abstract_insufficient.","key_references":[{"PMID":"7791754","why":"BMPR-II binds BMP-7 with BMPR-IB among type I partners"}],"covers":["LR007148"]},"LR001667":{"pair":"BMP8A -> BMPR1A","headline":"BMP8A acts through BMPR1A (ALK3) in mouse spermatogonia (functional, abstract-level); GtoPdb and UniProt agree.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). BMPR1A (ALK3 per curator note) with ACVR2A or BMPR2 mediated SMAD1/5/8 activation [PMID:28465413]. GtoPdb lists an agonist record [DB:GtoPdb]; UniProt says BMP8A associates with type I receptor BMPR1A [DB:UniProt].","molecular_requirements":"The type I receptor needs a type II partner, ACVR2A or BMPR2 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"Paper evidence is functional only, abstract-level. The paper gives ALK3, which the curators equate with BMPR1A.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001667"]},"LR007157":{"pair":"BMP8A -> BMPR1B:BMPR2","headline":"BMP8A -> BMPR1B:BMPR2 has database records only; no paper confirmed this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at BMPR1B and at BMPR2 [DB:GtoPdb]; UniProt says BMP8A associates with BMPR1A and BMPR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"One abstract was insufficient and three papers were review-only. UniProt names BMPR1A, not BMPR1B, as the type I partner.","key_references":[],"covers":["LR007157"]},"LR002189":{"pair":"BPI -> GPC4","headline":"BPI binds glycan-dependent GPC4 on bovine retinal pigment epithelium by affinity chromatography; one abstract-level paper, hedged as 'putative'.","interaction_type":"direct binding","direction_and_effect":"BPI acts as an agonist at the pair: heparitinase, PI-specific phospholipase C and anti-GPC4 antibody suppressed BPI-induced ERK and Akt phosphorylation, and heparitinase inhibited BPI effects on VEGF and PDGF-B mRNA [PMID:18055828].","molecular_requirements":"GPC4 was identified as the BPI-binding 36-kDa band; the effect of heparitinase and PI-PLC suggests a heparan sulfate-bearing, GPI-anchored form is needed. Co-receptors are not reported in our evidence [PMID:18055828].","affinity_potency":[],"species_and_systems":"Human rBPI(21) on bovine retinal pigment epithelial membranes; the human-mouse projection is ortholog-inferred, not experimental [PMID:18055828].","localisation_and_range":"Both entities are flagged is_secreted [flag]; the paper describes GPC4 as a cell-surface protein [PMID:18055828], so membrane-bound presentation is likely.","caveats":"Binding is described with the hedge 'putative' and rests on affinity chromatography plus mass spectrometry; abstract only; no affinity reported [PMID:18055828].","key_references":[{"PMID":"18055828","why":"Affinity-column pull-down and functional blockade identifying GPC4 as a BPI-binding protein."}],"covers":["LR002189","LR005503"]},"LR002198":{"pair":"C1QA -> LAIR1","headline":"C1q engages LAIR-1 through its collagen-like region, binding human proteins and cells; supports an inhibitory signal.","interaction_type":"direct binding","direction_and_effect":"C1q collagen-like region engages and activates the inhibitory immunoreceptor LAIR-1 [PMID:28325905]. C1q cross-links CD33 and LAIR-1 on monocytes; the curator labels the effect antagonist (inhibitory) [PMID:28325905].","molecular_requirements":"The collagen-like region is the LAIR-1 binding part [PMID:28325905]. CD33 association is reported in monocytes [PMID:28325905].","affinity_potency":[],"species_and_systems":"Human monocytes and transfected HEK293T cells (slot blots of lysates) [PMID:28325905].","localisation_and_range":"C1q annotated secreted; LAIR1 annotated transmembrane [flag].","caveats":"The excerpts present the LAIR-1 binding as previously reported by the authors, so this paper adds dose-dependent binding in slot blot rather than new characterisation. No affinity reported. Two confirmed rows counted, one shown.","key_references":[{"PMID":"28325905","why":"C1q binding of LAIR-1 and CD33"}],"covers":["LR002198","LR005512"]},"LR005519":{"pair":"C1QB -> LAIR1","headline":"C1q (via its collagen-like region) binds and activates LAIR-1 on human monocytes; one paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"The abstract states that C1q CLR engaging and activating LAIR-1 is a non-complement route to immune quiescence, and that C1q crosslinks LAIR-1 and CD33 [PMID:28325905]. The CLR-LAIR-1 activation is stated in the abstract's first sentence; in this paper's excerpts, C1q bound LAIR-1 in a dose-dependent manner on HEK293T lysates, described as previously reported by the authors.","molecular_requirements":"Domain-resolved: the collagen-like region (CLR) of C1q engages LAIR-1, whereas the globular head binds CD33 [PMID:28325905]. This row encodes the C1QB chain of the hexameric C1q; chain-alone activity is not shown.","affinity_potency":[],"species_and_systems":"Human: HEK293T cells transfected with LAIR-1 (slot blot), human monocytes (proximity ligation assay) [PMID:28325905].","localisation_and_range":"C1q secreted (ligand flag), LAIR1 transmembrane (receptor flag) [flag]; C1q bridges LAIR-1 and CD33 on one monocyte [PMID:28325905].","caveats":"The LAIR-1 arm is largely background in this paper (the new claim is CD33); the visible abstract does not give the LAIR-1 measurement. Single paper; chain-level attribution inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q CLR engages LAIR-1 and bridges it with CD33 on human monocytes"}],"covers":["LR002205","LR005519"]},"LR005528":{"pair":"C1QL2 -> ADGRB3","headline":"C1QL2 binds ADGRB3 (BAI3) thrombospondin-repeat domain with high affinity; abstract-level paper plus BioGRID and UniProt.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins bind BAI3 and, at submicromolar levels, decrease synapse density in cultured neurons; the BAI3 thrombospondin-repeat fragment prevented this [PMID:21262840]. Effect direction for C1QL2 alone is not reported in our evidence.","molecular_requirements":"Binding is to the BAI3 extracellular thrombospondin-repeat domain, mediated by the globular C1q domain of the ligand [PMID:21262840].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in the abstract and not labelled by the curator; the human and mouse interactions are both ortholog-inferred. BioGRID lists Affinity Capture-MS [DB:BioGRID] and UniProt lists the interaction [DB:UniProt].","localisation_and_range":"C1QL2 secreted and ADGRB3 transmembrane per flags [flag].","caveats":"Abstract only; the paper covers all four C1ql proteins collectively; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002215","LR005528"]},"LR008741":{"pair":"C3 -> CD81","headline":"No curated paper supports it; only Reactome complex records in which CD81 sits with CD19 and CR2.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect reported. Reactome lists CR2:C3d,C3dg,iC3b binding CD19:CD81 [DB:Reactome].","molecular_requirements":"CD81 appears only as a partner of CD19 in a CR2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"not reported in our evidence","localisation_and_range":"Not assessed.","caveats":"No papers confirmed; reviews, other entities and insufficient abstracts only. Direct C3-CD81 binding is not shown.","key_references":[],"covers":["LR008741"]},"LR001676":{"pair":"C3 -> NRP1","headline":"NRP1 binds C3 fragments (C3d, iC3b) in one full-text paper; the C4d Kd is the only measured affinity.","interaction_type":"direct binding","direction_and_effect":"A cDNA library screen with C4d identified NRP1, which also strongly bound recombinant C3d and iC3b, but only weakly C3b [PMID:31572401]. A solid-phase assay with NRP1-Ig confirmed binding to immobilized split products [PMID:31572401].","molecular_requirements":"Binding maps to the NRP1 b1 domain per the curator's assay detail [PMID:31572401]. Co-receptors not reported.","affinity_potency":[{"value":"KD 0.71 \u03bcM","assay":"dose-dependent saturable binding of C4d (not C3 fragments)","system":"NRP1-expressing cells","cite":"PMID:31572401"}],"species_and_systems":"Human proteins; NRP1 expressed on monocyte-derived dendritic cells, not monocytes [PMID:31572401].","localisation_and_range":"NRP1 is flagged transmembrane and secreted [flag]; binds surface-deposited fragments (contact).","caveats":"The measured Kd is for C4d, not for C3 fragments. Ligand forms are C3d and iC3b, not intact C3; C3b bound only weakly.","key_references":[{"PMID":"31572401","why":"NRP1 as receptor for complement split products"}],"covers":["LR001676","LR005053"]},"LR007184":{"pair":"C4A -> C5AR2","headline":"Supported only by UniProt text on dearginated C4a; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states C5AR2 also acts as receptor for dearginated C3a, C4a and C5a peptides [DB:UniProt].","molecular_requirements":"Dearginated form (C4adesArg) specified [DB:UniProt].","affinity_potency":[],"species_and_systems":"not reported in our evidence","localisation_and_range":"Not assessed.","caveats":"No papers; the single judged row was a different entity. Ligand is a processed fragment, not full C4A.","key_references":[],"covers":["LR007184"]},"LR005537":{"pair":"CADM1 -> CADM4","headline":"Direct heterophilic CADM1-CADM4 binding by SPR, with a cell-spreading readout; single primary paper.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc bound CADM4 in SPRi, an interaction the paper calls new [PMID:30131958]. ATN1 adult T-cell leukemia cells spread on CADM4-Fc-coated glass; CADM1 knockdown or a neutralizing anti-CADM1 antibody blocked spreading, so CADM1 on the cell engages CADM4 [PMID:30131958]. Adhesion rather than classical agonism.","molecular_requirements":"Whole ectodomains were used; no co-receptor or extra subunit is reported as required. SPRi detects only direct two-molecule binding [PMID:30131958].","affinity_potency":[{"value":"Kd 192.7 nM","assay":"SPRi, CADM1-Fc analyte on immobilised CADM4-Fc","system":"purified Fc fusions from 293-F cells","cite":"PMID:30131958"}],"species_and_systems":"Human proteins; recombinant SPRi, 293FT co-culture immunoprecipitation (CADM4-FLAG with CADM1-GFP) and ATN1 cell assays [PMID:30131958]. Mouse pair is projected from human.","localisation_and_range":"Both partners are flagged membrane-bound, not secreted [flag]; this fits contact-dependent (juxtacrine) signalling, with trans interaction between neighbouring cells shown by co-culture immunoprecipitation [PMID:30131958].","caveats":"Single paper. The curated sentence here is abstract-level; the full-text excerpts support it. The paper notes earlier affinity chromatography and cell-adhesion studies did not detect this interaction, and suggests it may give weak adhesion [PMID:30131958]. Weakest affinity of the CADM1 partners tested.","key_references":[{"PMID":"30131958","why":"SPRi binding, Kd and cell-spreading assay"}],"covers":["LR002227","LR005537"]},"LR006842":{"pair":"CADM3 -> EPB41L1","headline":"Intracellular CADM3 (NECL1) association with protein 4.1N from an in vitro binding assay; not a classical ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"In vitro binding assay proved association of NECL1 with protein 4.1N; NECL1 recruits 4.1N to the plasma membrane through its C-terminus [PMID:15893517]. No signalling direction reported.","molecular_requirements":"Requires the NECL1 cytoplasmic C-terminus [PMID:15893517].","affinity_potency":[],"species_and_systems":"Human and mouse NECL1 cloning; binding assay in vitro, species of assay not stated in the abstract read [PMID:15893517].","localisation_and_range":"Cytoplasmic adaptor interaction at the cell-cell junction, not extracellular; EPB41L1 carries no receptor or transmembrane flag [flag].","caveats":"Abstract only, one paper. This is an intracellular scaffold link and would not support extracellular CCC inference.","key_references":[{"PMID":"15893517","why":"In vitro binding of NECL1 to protein 4.1N"}],"covers":["LR006842"]},"LR001685":{"pair":"CADM3 -> NECTIN3","headline":"Heterophilic CADM3-nectin-3 adhesion shown in cell-aggregation assay; one abstract-level paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-3, but not nectin-2 or Necl-5 [PMID:15741237]. Reactome lists a Necl-1:Nectin-3 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-aggregation assays; abstract only, human-labelled [PMID:15741237]. Human pair is ortholog-inferred; mouse is not.","localisation_and_range":"Membrane-bound [flag]; Necl-1 is neural-specific at axon-glia contact sites [PMID:15741237]. Contact-dependent.","caveats":"Abstract only; one review-only row not shown. No affinity reported.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-3"}],"covers":["LR001685","LR005061"]},"LR005546":{"pair":"CADM4 -> CADM3","headline":"CADM4 and CADM3 interact by SPRi (family-wide screen); direct binding, one paper, no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2, CADM3 and CADM4 with all CADM family proteins [PMID:30131958]. No functional effect or direction is reported for this pair.","molecular_requirements":"SPRi only detects direct two-molecule interactions [PMID:30131958]. No accessory subunit reported.","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Both flagged transmembrane [flag]; adhesion between cells is described for the CADM family [PMID:30131958].","caveats":"Family-level statement from a single paper; the tabulated Kd values are for CADM1 only. CADM3 interactions with Nectins 1 and 3 were not detected by SPRi, though reported elsewhere [PMID:30131958]. Affinity for CADM4-CADM3 not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002236","LR005546"]},"LR003719":{"pair":"CALCB -> CALCR","headline":"beta-CGRP to calcitonin receptor rests only on GtoPdb agonist records; no paper in our evidence supports it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists beta-CGRP as agonist of CALCR, with one record giving full agonist and pEC50 without a value [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. The receptor entity is annotated as AMY1 receptor [flag], suggesting a RAMP1-containing complex, but no paper here tests this.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"No curator-confirmed papers: all judged rows were different_entity, abstract_insufficient or review_only. Treat as database-only.","key_references":[],"covers":["LR000174","LR003719"]},"LR009605":{"pair":"CALM1 -> CNGA2","headline":"Calmodulin-CNGA2 is supported by one cryo-EM structure only.","interaction_type":"direct binding","direction_and_effect":"A cryo-EM structure of human olfactory CNGA2/A4/B1 in a CaM-bound closed state is listed [DB:PDB 9UPG]. Effect on channel gating beyond the closed state is not reported in our evidence.","molecular_requirements":"CNGA2 is in a CNGA2/A4/B1 channel in the structure [DB:PDB 9UPG].","affinity_potency":[],"species_and_systems":"Human, cryo-EM.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR009605"]},"LR006824":{"pair":"CALM1 -> PDE1C","headline":"Calmodulin-PDE1C rests on a GtoPdb activator record alone.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists calmodulin as activator of PDE1C [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. Rows were different_entity or abstract_insufficient.","key_references":[],"covers":["LR006824"]},"LR008507":{"pair":"CALM2 -> EGFR","headline":"CALM2-EGFR rests on IntAct association records.","interaction_type":"direct binding","direction_and_effect":"IntAct lists five records, including anti-bait coimmunoprecipitation [DB:IntAct EBI-1256982] and ubiquitin reconstruction [DB:IntAct EBI-5234930]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; methods per IntAct.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. The records are identical to CALM1-EGFR, so isoform specificity is not shown.","key_references":[],"covers":["LR008507"]},"LR008462":{"pair":"CALM2 -> MYLK","headline":"CALM2-MYLK rests on a GtoPdb activator record.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM2 as activator of MYLK [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. Four rows were different_entity; MYLK is flagged receptor [flag].","key_references":[],"covers":["LR008462"]},"LR008471":{"pair":"CALM2 -> PDE1C","headline":"CALM2 activates PDE1C according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM2 as an activator of PDE1C (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008471"]},"LR005555":{"pair":"CBLN1 -> NRXN3","headline":"CBLN1 signals with NRXN3 splice variant in cerebellum; UniProt notes only weak binding to one isoform.","interaction_type":"conflicting","direction_and_effect":"In cerebellum, Nrxn3SS4+-Cbln1 signalling regulated AMPA-receptors, whereas Nrxn1SS4+-Cbln1 had no manifest effect [PMID:36205393].","molecular_requirements":"Splice variant matters: the SS4+ form of Nrxn3 is used, and UniProt says Cbln1 weakly interacts with the NRXN3 short isoform and not at all with the long isoform [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse genetic models (conditional and constitutive knockouts) in cerebellum and brain slices [PMID:36205393]; curators recorded human.","localisation_and_range":"CBLN1 is flagged secreted and NRXN3 transmembrane [flag].","caveats":"The paper's headline sentence is about Cbln2; the Cbln1 result is a secondary finding. Binding between CBLN1 and NRXN3 is weak or isoform-dependent per UniProt. Abstract only. A second confirmed paper was not shown.","key_references":[{"PMID":"36205393","why":"Nrxn3SS4+-Cbln1 regulates AMPA receptors in cerebellum"}],"covers":["LR002245","LR005555"]},"LR003728":{"pair":"CCL11 -> ACKR4","headline":"CCL11 (eotaxin) competes for binding to ACKR4 (reported as CCR11) at low-nM IC50; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Eotaxin bound the receptor with greater affinity than MCP-1 but acted as an agonist in chemotaxis assays only at 100-fold higher concentrations [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 = 6.7 nM","assay":"competition binding against radiolabeled MCP-4","system":"receptor transfected into murine L1.2 cells","cite":"PMID:10734104"}],"species_and_systems":"Human receptor expressed in mouse L1.2 cells [PMID:10734104]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, ACKR4 transmembrane [flag].","caveats":"Abstract only. The paper named the receptor CCR11 and framed it as a functional chemotactic receptor [PMID:10734104].","key_references":[{"PMID":"10734104","why":"Competition binding and chemotaxis for the MCP-family receptor"}],"covers":["LR000183","LR003728"]},"LR003755":{"pair":"CCL2 -> CCR1","headline":"Weak evidence: one 1993 abstract-read paper shows MCP-1 binding CCR1 with varying affinity but poor signalling.","interaction_type":"direct binding","direction_and_effect":"MCP-1 bound C-C CKR-1; binding affinity did not predict signal strength, and MCP-1 induced calcium mobilization only at high concentrations [PMID:7679328].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; the abstract does not specify the expression system [PMID:7679328]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"No affinity value reported for MCP-1 in our evidence. Abstract only. One paper was abstract_insufficient, one pending, one review-only. No database records.","key_references":[{"PMID":"7679328","why":"CCR1 cloning; MCP-1 binds with varying affinity, weak calcium response"}],"covers":["LR000234","LR003755"]},"LR006752":{"pair":"Ccl21b -> Cxcr3","headline":"Mouse CCL21 acting on mouse CXCR3 is supported by binding, signalling and knockout data, but the papers do not specify Ccl21b.","interaction_type":"functional only","direction_and_effect":"CCL21 triggered calcium flux in mouse CXCR3-transfected cells [PMID:9653165], and in mouse microglia a Cl- current and chemotaxis that were absent in CXCR3-knockout but retained in CCR7-knockout cells [PMID:11907075]. SLC/6Ckine showed lower-affinity binding to murine CXCR3 [PMID:10556837]. Murine 6C-kine inhibited tumour growth in SCID mice [PMID:11225989].","molecular_requirements":"CXCR3 alone mediated the microglial response without CCR7 [PMID:11907075].","affinity_potency":[],"species_and_systems":"Murine CXCR3 in L1.2 cells [PMID:10556837], mouse CXCR3-transfected cells [PMID:9653165], mouse microglia in slices and culture [PMID:11907075], and murine 6C-kine in a human tumour xenograft in SCID mice [PMID:11225989].","localisation_and_range":"Ligand flagged secreted and receptor flagged a receptor [flag]; no transmembrane flag is given.","caveats":"Abstract-only reads; no affinity for CCL21 is quoted; binding was lower affinity than IP10, ITAC and Mig [PMID:10556837]. Papers name CCL21/6Ckine generically, so Ccl21b is not distinguished. No database record. The abstract of PMID:11225989 notes human 6C-kine does not bind CXCR3.","key_references":[{"PMID":"9653165","why":"CCL21 identified as mouse CXCR3 ligand"},{"PMID":"11907075","why":"CXCR3 knockout abolishes CCL21 response in microglia"},{"PMID":"10556837","why":"lower-affinity binding to murine CXCR3"}],"covers":["LR006752"]},"LR008282":{"pair":"CCL23 -> ACKR2","headline":"Asserted only by UniProt's list of chemokines recognised by ACKR2; no paper evidence is shown.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ACKR2 acts as a receptor for chemokines including CCL23 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, ACKR2 flagged transmembrane [flag].","caveats":"No paper was confirmed; the one judged paper was review-only. The UniProt text is a general function statement citing PMIDs 18201974 and 23479571, which are not shown as judged papers [DB:UniProt].","key_references":[],"covers":["LR008282"]},"LR003746":{"pair":"CCL24 -> CCR2","headline":"CCL24 (eotaxin-2) binds CCR2 as an antagonist, shown in one human cell-line study.","interaction_type":"direct binding","direction_and_effect":"Antagonist: eotaxin-2 is reported to be an antagonist of CCR2 [PMID:15207250]; GtoPdb also lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"CCR2 expressed alone in a CHO cell line was sufficient [PMID:15207250].","affinity_potency":[{"value":"pIC50 6.2","assay":"curated binding/inhibition value","system":"CHO cell line with CCR2 in a defined genomic site","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor in engineered CHO cells [PMID:15207250]. The mouse pair is ortholog-inferred with no mouse data.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Single paper, abstract only. Not an activating pair; downstream effect on cells in vivo is not reported in our evidence.","key_references":[{"PMID":"15207250","why":"CHO lines show eotaxin-2 antagonises CCR2"}],"covers":["LR000220","LR003746"]},"LR005564":{"pair":"Ccl28 -> Gpr182","headline":"Mouse Ccl28 is bound with high affinity and scavenged by Gpr182 (atypical receptor) in one paper that includes a Kd table.","interaction_type":"direct binding","direction_and_effect":"GPR182 binds and efficiently scavenges CCL28, with no classical G-protein signalling after ligand stimulation, so it acts as a scavenger rather than a signalling receptor [PMID:37554323]. UniProt says it is the only atypical receptor for CCL28 and CXCL13 [DB:UniProt].","molecular_requirements":"Beta-arrestins are required for ligand-independent internalisation and scavenging [PMID:37554323]. Other requirements: not reported in our evidence.","affinity_potency":[{"value":"Kd 10 nM","assay":"competition binding, mCCL28 on mGPR182","system":"cells expressing mouse GPR182","cite":"PMID:37554323"},{"value":"Kd 14 nM","assay":"competition scavenging, mCCL28 on mGPR182","system":"cells expressing mouse GPR182","cite":"PMID:37554323"}],"species_and_systems":"Mouse CCL28 on mouse GPR182 in cell assays; GPR182-deficient mice show elevated chemokine levels in serum and secondary lymphoid organs and an impaired T-independent antibody response [PMID:37554323]. The curator species field lists human, but the excerpt table gives the mouse values.","localisation_and_range":"Ccl28 is flagged as secreted [flag].","caveats":"Single paper. The effect label 'agonist' does not match a scavenging role [PMID:37554323].","key_references":[{"PMID":"37554323","why":"Kd and scavenging data for CCL28 on GPR182"}],"covers":["LR005564"]},"LR003764":{"pair":"CCL4 -> ACKR2","headline":"Human D6/ACKR2 is promiscuous for beta-chemokines, but the verified paper names murine MIP-1b, not human CCL4; weak, indirect support.","interaction_type":"direct binding","direction_and_effect":"D6 (ACKR2) is a promiscuous beta-chemokine receptor with relatively high affinity for most beta-chemokines [PMID:9405404]. UniProt lists CCL4 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 in transduced cells, with displacement of radioiodinated murine MIP-1a; the highest-affinity ligands included murine MIP-1a and MIP-1b [PMID:9405404]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"CCL4 is flagged as secreted and ACKR2 as transmembrane [flag].","caveats":"No human CCL4 value appears in our excerpts; the pair rests on a murine ligand against the human receptor. Five review-only papers are not shown. No affinity numbers in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 with beta-chemokine binding"}],"covers":["LR000250","LR003764"]},"LR001694":{"pair":"CCL4L1 -> CCR1","headline":"One paper shows CCL4L1 behaves like CCL4 in chemotaxis assays on CCR1-expressing cells; no binding data for CCR1.","interaction_type":"functional only","direction_and_effect":"Chemotaxis assays with CCR1-expressing cells showed no substantial difference between CCL4L1 and CCL4 [PMID:15240137]. The curator labels this agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant: CCL4L1 produced in E. coli, tested on cells expressing the receptor [PMID:15240137]. The curator labels both species human.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"CCL4L1 differs from CCL4 by a single amino acid, so the evidence is a paralog comparison, not a CCL4L1-specific affinity. Abstract-level read; no database record. CCR1-specific binding is not reported in our evidence.","key_references":[{"PMID":"15240137","why":"CCL4L1 vs CCL4 binding and chemotaxis at CCR1, CCR3 and CCR5"}],"covers":["LR001694"]},"LR003773":{"pair":"CCL5 -> SDC4","headline":"One abstract-level paper reports RANTES co-immunoprecipitating with syndecan-4 on human macrophages; proteoglycan binding, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"RANTES associated with syndecan-1 and syndecan-4 but not syndecan-2 or betaglycan in co-immunoprecipitation from human monocyte-derived macrophages [PMID:14637022]. Glycosaminidase pre-treatment strongly reduced RANTES binding to syndecan-4 [PMID:14637022]. BioGRID lists Affinity Capture-Western [DB:BioGRID].","molecular_requirements":"Glycosaminoglycan chains are implicated; the authors suggest such binding facilitates subsequent RANTES-CCR5 interaction [PMID:14637022]. No signalling through syndecan-4 reported.","affinity_potency":[],"species_and_systems":"Human macrophages, endogenous proteins [PMID:14637022]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 flagged secreted; syndecan-4 flagged as a receptor only, with no transmembrane flag [flag].","caveats":"Abstract only; association by co-IP, no affinity. Entirely dependent on one paper and its BioGRID record.","key_references":[{"PMID":"14637022","why":"RANTES co-IPs with syndecan-4 on human macrophages"}],"covers":["LR000263","LR003773"]},"LR003782":{"pair":"CCL8 -> ACKR2","headline":"Human ACKR2 (D6) is a promiscuous CC-chemokine binder; the paper lists MCP2 (CCL8) among the highest-affinity ligands, without an affinity value.","interaction_type":"direct binding","direction_and_effect":"The full text states the highest-affinity ligands for human D6 appear to include murine MIP-1a, MIP-1b, murine JE and human MCP2 [PMID:9405404]. D6 did not flux calcium on ligand binding [PMID:9405404]. BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt lists CCL8 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, 125I-MIP-1a tracer [PMID:9405404]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR2 flagged transmembrane receptor [flag].","caveats":"No numeric affinity for MCP2 in our evidence; the dossier does not state that MCP2 is CCL8, which is the curators' mapping.","key_references":[{"PMID":"9405404","why":"D6/ACKR2 binds MCP2 with high affinity"}],"covers":["LR000272","LR003782"]},"LR003917":{"pair":"CCN1 -> ITGAM","headline":"CCN1 supports monocyte adhesion through integrin alphaMbeta2; alphaM I-domain binding mapped to a CCN1 peptide. Chain-only (alphaM) evidence.","interaction_type":"direct binding","direction_and_effect":"THP-1 and peripheral blood monocytes adhered to Cyr61 (CCN1) mainly through alphaMbeta2, and a GST-alphaM I-domain bound immobilized Cyr61 [PMID:12036876]. Activated monocytes adhered to the CCN1 H2 peptide (SSVKKYRPKYCGS), blocked by anti-alphaM mAb 2LPM19c, and GST-alphaMI bound this peptide [PMID:12736251].","molecular_requirements":"The ITGAM chain pairs with beta2 as alphaMbeta2; heparan sulfate proteoglycans act as co-receptors, since heparin or heparinase I partly inhibited adhesion [PMID:12036876]. Adhesion was activation-dependent.","affinity_potency":[],"species_and_systems":"Human THP-1 cells, human monocytes, HEK293 cells expressing alphaMbeta2 and GST-fusion I-domain; human CCN1. Mouse and any other pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers were read as abstracts only. Evidence is adhesion and I-domain binding, with no affinity. The dossier's alphaM and beta2 entries describe the same alphaMbeta2 heterodimer evidence.","key_references":[{"PMID":"12036876","why":"alphaMbeta2 identified as monocyte adhesion receptor for CCN1"},{"PMID":"12736251","why":"alphaM binding site mapped to CCN1 H2 peptide"}],"covers":["LR000420","LR003917"]},"LR005573":{"pair":"CCN2 -> FGFR1","headline":"CCN2 binds FGFR1 with a reported Kd of 362 nM; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Full-length CCN2 bound FGF receptor 1, while its C-terminal (CT) module did not [PMID:21914781]. Whether CCN2 activates or modulates FGFR1 signalling is not reported in our evidence; the CT module reduced FGF2-induced ERK, p38 and JNK phosphorylation in chondrocytic cells [PMID:21914781].","molecular_requirements":"The CT module alone is not sufficient for FGFR1 binding [PMID:21914781]. Other requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 362 nM","assay":"binding of CCN2 to FGFR1 (solid-phase binding and SPR)","system":"species unspecified","cite":"PMID:21914781"}],"species_and_systems":"Species of the proteins is not specified; signalling work used chondrocytic HCS-2/8 cells [PMID:21914781].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Primary focus of the paper is CCN2 CT module binding to FGF2 (Kd 5.5 nM), not to the receptor [PMID:21914781]. Which assay produced the 362 nM value is not stated.","key_references":[{"PMID":"21914781","why":"Kd of CCN2 binding to FGFR1"}],"covers":["LR002272","LR005573"]},"LR003890":{"pair":"CCN2 -> ITGB2","headline":"CCN2 is a ligand for integrin alphaMbeta2 (ITGAM/ITGB2) on monocytes; two abstract-level papers, binding shown via the alphaM subunit.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaMbeta2 mediates monocyte adhesion to CCN2 (CTGF) [PMID:12036876]. A GST-alphaM I domain bound CTGF and the CCN2 H2 peptide (TSVKTYRAKFCGV) [PMID:12036876][PMID:12736251].","molecular_requirements":"The binding evidence involves the alphaM I domain, not the beta2 chain; ITGB2 is the partner chain of the alphaMbeta2 heterodimer that mediated adhesion [PMID:12036876]. Whether beta2 alone binds CCN2 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human THP-1 cells, peripheral blood monocytes, and recombinant GST-alphaMI [PMID:12036876][PMID:12736251].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstracts only. Direct binding is to the alphaM I domain (chain-level evidence for ITGAM), so the ITGB2 pair rests on its being the heterodimer partner. One further judged row was abstract_insufficient [PMID:12036876].","key_references":[{"PMID":"12036876","why":"alphaMbeta2-mediated monocyte adhesion to CTGF"},{"PMID":"12736251","why":"Mapping of the CCN2 H2 site binding alphaM I domain"}],"covers":["LR000384","LR003890"]},"LR002279":{"pair":"CCN3 -> ITGB1","headline":"CCN3 binds integrin alpha5beta1 directly (half-maximal binding 50 nM); beta1 evidence is via the alpha5beta1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist for alpha5beta1-dependent adhesion and migration of HUVECs [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522]. UniProt also notes that CCN3 inhibits MMP9 expression through ITGB1 engagement [DB:UniProt PMID 21871891].","molecular_requirements":"ITGB1 pairs with ITGA5 (binding shown) and ITGA6 (adhesion, no direct binding) in this paper [PMID:12695522]. Whether the beta1 chain alone suffices is not reported in our evidence.","affinity_potency":[{"value":"50 nM","assay":"half-maximal binding (EC50) to alpha5beta1, solid-phase ELISA","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"The 50 nM value is for the alpha5beta1 heterodimer, not ITGB1 alone. Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002279","LR005580"]},"LR005069":{"pair":"CCN4 -> ITGA5","headline":"Functional evidence only: CCN4-driven fibroblast migration depends on alpha5beta1 integrin; direct ITGA5 binding not shown.","interaction_type":"functional only","direction_and_effect":"CCN4-induced migration of dermal fibroblasts appears to work via alpha5beta1 integrin receptors, further stimulating ERK/JNK signalling; the dossier labels CCN4 an agonist [PMID:29330021].","molecular_requirements":"The paper implicates the alpha5beta1 integrin heterodimer; whether one chain alone suffices is not reported in our evidence. Both ITGA5 and ITGB1 pairs rest on the same single paper [PMID:29330021].","affinity_potency":[],"species_and_systems":"Human adult dermal fibroblasts (siRNA knockdown or adenoviral CCN4) and Ccn4-knockout mouse dermal fibroblasts and wounds [PMID:29330021].","localisation_and_range":"CCN4 is flagged secreted and the integrin as a receptor [flag]; matrix-associated paracrine action is plausible but not stated in our evidence.","caveats":"No binding assay is reported; the link to the integrin is inferred from migration experiments, and the paper was read mainly as abstract plus excerpts. No database record supports this pair. The integrin subunit is a chain of a heterodimer.","key_references":[{"PMID":"29330021","why":"CCN4 wound healing via alpha5beta1 in dermal fibroblasts"}],"covers":["LR001700","LR005069"]},"LR005582":{"pair":"Cd2 -> Cd59b","headline":"Mouse Cd2-Cd59b is projected from a human CD2-CD59 rosetting paper; not tested in mouse.","interaction_type":"direct binding","direction_and_effect":"The only evidence is the human CD2-CD59 rosetting and CD59 binding paper, which concludes CD2 binds CD59 [PMID:1385156].","molecular_requirements":"Not reported in our evidence for mouse Cd59b specifically.","affinity_potency":[],"species_and_systems":"The paper used human CD59 on CHO transfectants and human T cells; the mouse pair is ortholog-inferred and Cd59b is a paralog [PMID:1385156].","localisation_and_range":"Not reported in our evidence beyond the entity flags [flag].","caveats":"Projected from human evidence, not tested in mouse, and Cd59b is one of two mouse CD59 paralogs. Abstract read only; no database record.","key_references":[{"PMID":"1385156","why":"Human CD2-CD59 rosetting paper (source of projection)"}],"covers":["LR005582"]},"LR005078":{"pair":"CD226 -> PVR","headline":"Well supported: PVR (CD155) binds CD226 (DNAM-1) by reciprocal Fc-chimera staining; the mouse pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"PVR-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained PVR CHO-K transfectants; the DNAM-1/PVR interaction enhanced NK-mediated tumour lysis [PMID:15607800].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in COS-7 and CHO-K transfectants [PMID:15607800]; the mouse interaction was projected from human evidence.","localisation_and_range":"PVR is flagged secreted and transmembrane, CD226 transmembrane [flag]; contact between NK cell and target.","caveats":"Only one paper in our evidence (abstract only); no affinity reported. Database records exist (BioGRID, IntAct incl. SPR and others) [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"15607800","why":"Reciprocal Fc-chimera binding of PVR and DNAM-1"}],"covers":["LR001711","LR005078"]},"LR003791":{"pair":"Cd24a -> Selp","headline":"CD24 binds P-selectin in three papers using purified CD24, beads and cells; no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Latex beads coated with purified CD24 and neutrophils bound P-selectin-IgG; carcinoma cells and CD24-beads bound activated platelets or P-selectin CHO cells in a P-selectin-dependent way, blocked by soluble CD24 [PMID:9129046]. Brain-derived HSA also bound P-selectin [PMID:9048906]. Affinity-purified CD24 glycoforms supported P-selectin binding [PMID:20351695]. BioGRID and IntAct also record it [DB:BioGRID][DB:IntAct].","molecular_requirements":"Binding needs divalent cations [PMID:9129046][PMID:9048906], is sensitive to high salt [PMID:9048906], and was abolished by O-sialoglycoprotein endopeptidase but not sialidase [PMID:9129046]. Glycosylation matters: both SN3b-positive and -negative glycoforms bound [PMID:20351695].","affinity_potency":[],"species_and_systems":"Human carcinoma cell lines, neutrophils and glycoforms [PMID:9129046][PMID:20351695]; brain HSA was described as mouse CD24 in the abstract [PMID:9048906].","localisation_and_range":"Both flagged not secreted [flag]; cell-contact interaction.","caveats":"All three papers read as abstracts only. The pair is a mouse pair, but two papers describe human CD24 material. No affinity or in-vivo effect.","key_references":[{"PMID":"9129046","why":"CD24 on carcinoma cells and neutrophils binds P-selectin"},{"PMID":"9048906","why":"Brain HSA binds P-selectin but not E-selectin"},{"PMID":"20351695","why":"Purified CD24 glycoforms support P-selectin binding"}],"covers":["LR003791"]},"LR010847":{"pair":"CD36 -> TLR6","headline":"CD36 co-precipitates with TLR6 (and TLR4) after ligand stimulation in human THP-1 cells; a co-receptor complex.","interaction_type":"direct binding","direction_and_effect":"Stimulation of THP-1 monocytes with CD36 ligands induced co-precipitation of CD36 with TLR4 and TLR6 [PMID:20037584]; Abeta1-42 and oxLDL signal via a CD36-TLR4-TLR6 pathway, with TLR2-TLR6 not activated by Abeta in the reporter assay [PMID:20037584].","molecular_requirements":"CD36, TLR4 and TLR6 all required for maximal induction; bacterial CD36 ligands instead preferentially activate TLR2-TLR6 [PMID:20037584]. UniProt notes a TLR2:TLR6:CD14:CD36 cluster for diacylated lipopeptides [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human THP-1 co-IP, HEK293 reporter, mouse knockout macrophages and microglia [PMID:20037584].","localisation_and_range":"Cell-surface/intracellular receptor complex [PMID:20037584].","caveats":"Receptor-Receptor pair; co-IP does not show direct binding to TLR6 specifically. Evidence rests on one paper.","key_references":[{"PMID":"20037584","why":"CD36-TLR4-TLR6 complex"}],"covers":["LR010847"]},"LR002288":{"pair":"CD40LG -> ITGA4","headline":"Soluble CD40L activates alpha4beta1 integrin in cell-free and cell-surface assays; one paper, alpha4 chain-level evidence only.","interaction_type":"direct binding","direction_and_effect":"Soluble CD40L bound and activated soluble and cell-surface alphavbeta3, alpha5beta1 and alpha4beta1; soluble CD40L activated soluble integrins in cell-free conditions, so inside-out signalling is not required [PMID:33571526].","molecular_requirements":"Evidence is for the alpha4beta1 heterodimer, not ITGA4 alone; the paper tests an allosteric site 2 beyond the classical trimeric-interface site [PMID:33571526].","affinity_potency":[],"species_and_systems":"Soluble integrins and CHO cells (full text read) [PMID:33571526]; species of cells not detailed in our excerpts; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; the paper notes sCD40L is released by proteolytic cleavage, allowing action at distant sites [PMID:33571526].","caveats":"Single paper; no affinity reported; chain-only attribution (ITGB1 partner not in this pair).","key_references":[{"PMID":"33571526","why":"CD40L activates alpha4beta1 and other integrins"}],"covers":["LR002288","LR005587"]},"LR005591":{"pair":"CD40LG -> ITGB3","headline":"CD40L binding to integrin beta3 (alphaIIbbeta3 and alphavbeta3) is supported by several abstract-level binding papers and UniProt.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble CD40L bound purified alphaIIbbeta3 and activated platelets in a beta3-dependent manner, induced platelet spreading and promoted aggregation; CD40L lacking the KGD motif did not restore thrombosis in CD40L-null mice, and CD40-deficient mice thrombosed normally [PMID:11875495]. Integrin alphavbeta3 bound CD40L in a KGD-independent manner [PMID:31331973]. CD154 binds alphaIIbbeta3 with ~4-fold higher affinity than alpha5beta1 [PMID:22461623]. UniProt lists ITGAV:ITGB3 as a receptor for CD40LG [DB:UniProt].","molecular_requirements":"Evidence is for beta3 heterodimers (alphaIIb:beta3, alphav:beta3). Mutants lacking binding to CD40 or alphaIIbbeta3 map to distinct CD154 residues [PMID:22461623]. Soluble CD40L also activates alphavbeta3 in cell-free conditions [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human and mouse platelets, purified integrin, mouse thrombosis model [PMID:11875495]; human cells in later papers [PMID:31331973][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; recombinant soluble CD40L used [PMID:11875495].","caveats":"All shown papers are abstract-only; no numeric affinity for this pair reported. Four more confirmed papers are not shown.","key_references":[{"PMID":"11875495","why":"Binding of soluble CD40L to purified alphaIIbbeta3 and platelets"},{"PMID":"31331973","why":"alphavbeta3 as a CD40L receptor"},{"PMID":"22461623","why":"alphaIIbbeta3 vs alpha5beta1 affinity"}],"covers":["LR002292","LR005591"]},"LR005087":{"pair":"CD47 -> SIRPA","headline":"CD47 binds SIRPA, well supported by binding, affinity, structure and database records.","interaction_type":"direct binding","direction_and_effect":"SIRPalpha binds CD47 through its IgV domain, and Gln67, Ala/Val at position 57 and Met102 determine this binding [PMID:17070842]. SIRP-Fc fusions supported cell adhesion that was blocked by antibody, with CD47 identified as the ligand [PMID:10572074]. Physical-interaction and structural records exist [DB:PDB 2JJS][DB:IntAct P78324-Q08722].","molecular_requirements":"Single-chain pair; the SIRPalpha IgV domain is the binding unit [PMID:17070842].","affinity_potency":[{"value":"Kd approximately 2 microM","assay":"soluble SIRP binding to CD47 (compared with SIRPgamma)","system":"human proteins","cite":"PMID:15294972"}],"species_and_systems":"Human proteins in all three papers per curators [PMID:17070842][PMID:15294972][PMID:10572074]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Both partners carry transmembrane flags, so signalling is by cell contact [flag]; CD47 also carries a secreted flag [flag].","caveats":"Papers are abstract-only. The Kd comes as a comparator in a SIRPgamma paper [PMID:15294972]. One abstract was insufficient and is not shown.","key_references":[{"PMID":"17070842","why":"SIRPalpha IgV residues governing CD47 binding"},{"PMID":"15294972","why":"SIRPalpha Kd approximately 2 microM"},{"PMID":"10572074","why":"CD47 identified as the ligand for SIRP in adhesion"}],"covers":["LR001720","LR005087"]},"LR002297":{"pair":"CD72 -> CD6","headline":"Soluble CD72 was reported to bind CD6 on activated human CD4+ T cells in a single 2024 study; no other evidence is in our dossier.","interaction_type":"direct binding","direction_and_effect":"Soluble CD72 (sCD72) pulled down CD6 from activated CD4+ T cells by mass spectrometry and co-immunoprecipitation, and the authors describe it as a possible ligand-receptor interaction [PMID:39026665]. sCD72 raised IL-17A and IFN-gamma in activated CD4+ T cells and increased their proliferation, possibly through SLP-76-AKT-mTOR signalling [PMID:39026665]. This is a stimulatory effect on the T cell.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD4+ T cells, with a recombinant sCD72 made of amino acids 117 to 359 secreted by HEK-293T cells [PMID:39026665].","localisation_and_range":"The soluble extracellular form acts [PMID:39026665]; the full-length CD72 flag says transmembrane and CD6 flag says secreted and transmembrane [flag].","caveats":"Single paper; the curator read the abstract but full text is listed as available. The authors call CD6 a potential receptor and the interaction possible. The pull-down used a cross-linker, so direct contact is not shown separately. No database records and no affinity in our evidence. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"39026665","why":"Identifies and validates the sCD72-CD6 interaction and its T-cell effects"}],"covers":["LR002297","LR005596"]},"LR005096":{"pair":"CD84 -> CD84","headline":"CD84 binds itself (homophilic) according to a 2001 binding study and database records.","interaction_type":"direct binding","direction_and_effect":"CD84-Ig bound CD84-transfected cells and no other CD2-subfamily receptor, showing CD84 binds itself [PMID:11564780]. Concurrent ligation of CD84 with CD3 enhanced IFN-gamma secretion, a costimulatory effect [PMID:11564780].","molecular_requirements":"Only the first extracellular domain is involved, shown with human/mouse chimeras, and the interaction was independent of the cytoplasmic tail [PMID:11564780].","affinity_potency":[],"species_and_systems":"Human CD84-Ig and transfected cells and platelets [PMID:11564780]; mouse pair ortholog-inferred. Reactome lists CD84 homodimerisation [DB:Reactome] and BioGRID/IntAct list reconstituted-complex and cosedimentation records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Cell-surface homophilic contact between cells; flags show secreted and receptor annotations [flag].","caveats":"One paper read as abstract only; no affinity in our evidence. Since both partners are the same protein, direction is not meaningful.","key_references":[{"PMID":"11564780","why":"CD84-Ig binds CD84 transfectants; first domain mediates binding"}],"covers":["LR001731","LR005096"]},"LR005609":{"pair":"CDH2 -> CDH4","headline":"Only a BioGRID co-precipitation record; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. BioGRID lists CDH4 - CDH2 by Affinity Capture-Western [DB:BioGRID] [PMID:10662782].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both are flagged as membrane receptors; CDH2 is flagged transmembrane [flag].","caveats":"Seven papers were judged as different entity or abstract-insufficient, none confirmed. Affinity capture is not proof of direct binding.","key_references":[],"covers":["LR002311","LR005609"]},"LR005618":{"pair":"CDH8 -> CDH11","headline":"Preferred heterophilic type II cadherin pair in SPR on mouse proteins; human pair inferred.","interaction_type":"direct binding","direction_and_effect":"The cadherin-8 surface supported heterophilic binding of cadherin-11 as its strongest interaction, followed by homophilic cadherin-8 binding [PMID:29742438].","molecular_requirements":"Cadherin-8 and -11 form one specificity group preferring each other [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Heterophilic cadherin-8/-11 SPR"}],"covers":["LR002320","LR005618"]},"LR001739":{"pair":"CEACAM5 -> CD1D","headline":"CEACAM5 binds CD1d through its B3 domain, from one abstract-level paper with full-text support.","interaction_type":"direct binding","direction_and_effect":"CEACAM5 is the only CEACAM member interacting with CD1d, through the B3 domain, making CD1d more class-I-like for activation of CD8+ suppressor T cells [PMID:24104458]. Deleting B3 fragments 2 to 5 abolished CEACAM5-CD1d binding [PMID:24104458].","molecular_requirements":"B3 domain integrity (fragments 2 to 5) is needed [PMID:24104458].","affinity_potency":[],"species_and_systems":"Human cells and proteins, including 293T, FO-1 and CHO transfectants [PMID:24104458]. IntAct lists a solid phase assay [DB:IntAct].","localisation_and_range":"CEACAM5 is a GPI-anchored glycoprotein on intestinal epithelial cells [PMID:24104458].","caveats":"One paper; affinity not reported. The same paper's claim that only CEACAM5 binds CD1d rests on that single study.","key_references":[{"PMID":"24104458","why":"CEACAM5 B3 domain binds CD1d"}],"covers":["LR001739"]},"LR000299":{"pair":"CGB3 -> LHCGR","headline":"hCG beta (CGB3) binds and activates the human LH/CG receptor; direct binding shown in several human-system papers, though not gene-specific.","interaction_type":"direct binding","direction_and_effect":"Annotated as stimulatory ligand-receptor [flag]. GtoPdb lists a full agonist [DB:GtoPdb]; stimulation of the receptor by hCG or LH increased cAMP [PMID:12727981].","molecular_requirements":"hCG consists of a common alpha-subunit and a hormone-specific beta-subunit; the beta-subunit interacts with the receptor exodomain and alters its interaction with the alpha-subunit [PMID:10446903]. The extracellular domain alone binds choriogonadotropin with high affinity [PMID:2254302]. Binding to the leucine-rich-repeat domain is similar for hCG and LH, and the hinge region (exon 10) is implicated in differing signalling [PMID:26441830]. PDB complexes 7FIG, 7FIH, 7FII are listed [DB:PDB 7FIG].","affinity_potency":[{"value":"ED50 4.3 ng/ml (hCG) and 4.8 ng/ml (LH)","assay":"[125I]hCG displacement","system":"human LH receptor in 293 cells","cite":"PMID:1922095"},{"value":"pKd 9.899999618530273 to 11.800000190734863","assay":"GtoPdb affinity range, citing PMID 12727981 and 1922095","system":"not specified beyond GtoPdb","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in COS-7 and 293 cells and transfected cells; recombinant expression [PMID:12727981][PMID:1922095].","localisation_and_range":"Ligand flagged secreted and receptor flagged transmembrane receptor [flag]; endocrine hormone acting on a membrane receptor.","caveats":"Papers name hCG/LH and the receptor generally; none in our evidence is specific to the CGB3 gene product as distinct from other hCG beta genes. All cited papers were read as abstracts only except where noted. The GtoPdb affinity range is a database value, not tied to a single assay in our dossier.","key_references":[{"PMID":"1922095","why":"hCG and LH displace [125I]hCG on human LH receptor, ED50 given"},{"PMID":"2254302","why":"Receptor extracellular domain binds choriogonadotropin with high affinity"},{"PMID":"26441830","why":"Full-text study of hinge region and hormone-specific signalling"}],"covers":["LR000299"]},"LR005627":{"pair":"CIRBP -> LY96","headline":"Extracellular CIRP binds MD2 (LY96) by surface plasmon resonance; one paper, abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Human CIRP residues 106-125 bind MD2 with high affinity; CIRP is a danger signal acting on the TLR4-MD2 complex [PMID:24097189]. Recombinant CIRP stimulates TNF-alpha and HMGB1 release from macrophages [PMID:24097189].","molecular_requirements":"MD2 binding is mapped to CIRP residues 106-125 [PMID:24097189]; TLR4 is the partner in the TLR4-MD2 complex.","affinity_potency":[],"species_and_systems":"Surface plasmon resonance with human CIRP peptide; macrophage and rodent hemorrhage/sepsis models [PMID:24097189].","localisation_and_range":"CIRP flagged secreted [flag]; released into circulation from cells [PMID:24097189].","caveats":"Abstract read; no Kd value reported in our evidence, only 'high affinity'.","key_references":[{"PMID":"24097189","why":"CIRP binds TLR4-MD2, TLR4 and MD2 by SPR"}],"covers":["LR002344","LR005627"]},"LR003809":{"pair":"CLCF1 -> IL6ST","headline":"IL6ST (gp130) is engaged only as a signalling chain of the CNTFR complex; evidence is functional activation, not direct binding.","interaction_type":"functional only","direction_and_effect":"The CLF/CLC complex activated gp130, LIFR and STAT3 and supported motor neuron survival [PMID:10966616]. CLC-CNTFR displayed activity on cells with gp130-LIFR [PMID:11285233]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"gp130 acts downstream of CNTFR: curator notes say it is a signalling chain engaged by the complex, not an independent CLC binding partner [PMID:11285233]. UniProt says binding to CNTFR induces gp130 heterodimerisation with LIFR [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-level evidence only [PMID:10966616][PMID:11285233].","localisation_and_range":"Ligand flagged secreted and IL6ST a transmembrane receptor [flag].","caveats":"Both papers abstract only. Direct CLCF1-IL6ST binding is not shown in our evidence; do not score this pair without CNTFR.","key_references":[{"PMID":"10966616","why":"gp130 and LIFR activation by CLF/CLC"},{"PMID":"11285233","why":"CLC-CNTFR activity on gp130-LIFR cells"}],"covers":["LR000303","LR003809"]},"LR001748":{"pair":"CLEC2A -> KLRF2","headline":"KACL (CLEC2A) is the ligand of the activating NK receptor NKp65 (KLRF2): binding, structure and function support it.","interaction_type":"direct binding","direction_and_effect":"NKp65 stimulated NK cytotoxicity and proinflammatory cytokine release on engagement of cell-bound KACL; keratinocytes stimulated NKp65-expressing cells in a KACL-dependent way [PMID:20194751]. UniProt describes CLEC2A as a ligand stimulating activating receptor NKp65 [DB:UniProt].","molecular_requirements":"NKp65 has an amino-terminal hemITAM required for cytotoxicity [PMID:20194751]. No other subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; NK92MI cells and keratinocytes [PMID:20194751]. Structure [DB:PDB 4IOP]; SPR, ITC and x-ray records [DB:IntAct].","localisation_and_range":"Both partners are membrane-bound (flags), so signalling is contact-dependent [flag]; KACL expression is mainly restricted to keratinocytes [PMID:20194751].","caveats":"Paper read as abstract only; the abstract says high affinity but gives no value. One additional review-only row.","key_references":[{"PMID":"20194751","why":"KACL/NKp65 identified as ligand-receptor pair"}],"covers":["LR001748"]},"LR005636":{"pair":"CLSTN3 -> NRXN3","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN3 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN3 specifically; the paper title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown. Earlier debate on whether Nrxns bind Clstn3 directly is noted [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002356","LR005636"]},"LR005645":{"pair":"CNTN1 -> PTPRB","headline":"Contactin binds the carbonic anhydrase domain of RPTPbeta; abstract-level evidence from two BioGRID-recorded papers.","interaction_type":"direct binding","direction_and_effect":"A recombinant Fc fusion with the C domain of RPTPbeta binds contactin and supports neuronal adhesion and neurite growth; contactin and Nr-CAM formed a complex that bound betaCFS [PMID:9049255]. Antibodies to Nr-CAM and contactin inhibited betaCFS-induced neurite outgrowth [PMID:9049255].","molecular_requirements":"The carbonic anhydrase (C) domain of RPTPbeta is the contactin-binding region [PMID:9049255]. Contactin acts together with Nr-CAM in the complex [PMID:9049255].","affinity_potency":[],"species_and_systems":"Neurons and recombinant Fc fusions; species not specified [PMID:9049255]. BioGRID lists reconstituted complexes [DB:BioGRID].","localisation_and_range":"RPTPbeta exists as soluble and receptor forms sharing extracellular regions [PMID:9049255]; contactin is GPI-anchored by annotation [flag].","caveats":"Abstract-only; the complex included Nr-CAM, so binding to contactin alone is based on the earlier C-domain result cited as previous work. The second BioGRID paper (7628014) is not among the judged rows shown.","key_references":[{"PMID":"9049255","why":"Contactin/Nr-CAM complex binds RPTPbeta betaCFS"}],"covers":["LR002365","LR005645"]},"LR003818":{"pair":"CNTN2 -> NRP1","headline":"TAG1 reported to interact with NRP1 in mouse sensory-neuron Sema3A receptor trafficking; abstract-only.","interaction_type":"direct binding","direction_and_effect":"TAG1 interacts with NRP1, changing its association with L1 so L1 is lost from the complex after Sema3A binding [PMID:22836270]. Without TAG1, NRP1 and L1 failed to separate and Plexin signalling was not initiated [PMID:22836270].","molecular_requirements":"Sema3A receptor complex contains NRP1 (ligand-binding subunit), PlexinA4 and L1 [PMID:22836270].","affinity_potency":[],"species_and_systems":"Mouse spinal sensory neuron growth cones [PMID:22836270]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Intracellular endosomal sorting and raft association in growth cones [PMID:22836270]; both partners carry secreted/receptor flags [flag].","caveats":"Abstract-only; interaction is described in a trafficking context, direct binding assay details are not in our evidence. TAG1 acts as a sorting regulator rather than classical ligand.","key_references":[{"PMID":"22836270","why":"TAG1 interacts with NRP1 in Sema3A trafficking"}],"covers":["LR000312","LR003818"]},"LR002369":{"pair":"CNTN3 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN3; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN3 is annotated non-secreted and PTPRG non-secreted [flag]; contact-mediated signalling is implied by the annotation, not shown.","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN3 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002369","LR005649"]},"LR005654":{"pair":"COL11A1 -> DDR2","headline":"DDR2 mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"DDR2 and integrin a2b1, but not integrin a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024]. Collagen XI in collagen I matrices inhibited CAF-mediated remodeling and migration [PMID:36233024].","molecular_requirements":"DDR2 is one of two receptors identified; neither was shown alone to be sufficient in our evidence [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs from non-small cell lung cancer settings; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the abstract says collagen type XI without naming the chain (COL11A1 or COL11A2), and the binding is a cell-based readout rather than purified-protein binding [PMID:36233024].","key_references":[{"PMID":"36233024","why":"DDR2 and a2b1 mediate CAF binding to collagen XI"}],"covers":["LR002375","LR005654"]},"LR006851":{"pair":"COL11A1 -> ITGA11:ITGB1","headline":"Evidence is an abstract-level TNBC study showing COL11A1 binding to ITGB1 only; the named integrin heterodimer is not tested.","interaction_type":"functional only","direction_and_effect":"COL11A1 promoted TNBC metastasis by binding ITGB1, initiating a FAK/YAP cascade; siRNA and rotating magnetic fields suppressed tumour growth and lung metastasis, reversed by an ITGB1 agonist [PMID:41391796].","molecular_requirements":"The paper names the integrin b1 chain only; the alpha subunit (ITGA11) is not reported in our evidence, so the heterodimer assignment is not supported [PMID:41391796].","affinity_potency":[],"species_and_systems":"TNBC cells and an in vivo tumour model; the abstract does not give host species [PMID:41391796].","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; no alpha-subunit-specific data. Other judged papers were review-only, so no primary support for this heterodimer in our evidence [PMID:41391796].","key_references":[{"PMID":"41391796","why":"COL11A1 binding ITGB1 in TNBC"}],"covers":["LR006851"]},"LR002378":{"pair":"COL11A2 -> ITGB1","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A2.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"ITGB1 is named only as part of a2b1 [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR002378","LR005657"]},"LR003827":{"pair":"COL18A1 -> KDR","headline":"Endostatin (collagen XVIII fragment) directly interacts with KDR and blocks VEGF signalling; one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Endostatin blocked VEGF-induced KDR/Flk-1 tyrosine phosphorylation and ERK, p38 and FAK activation in HUVEC, and inhibited VEGF165 binding to endothelial cells and purified KDR ectodomain and VEGF121 binding to KDR; direct interaction was confirmed by affinity chromatography [PMID:12029087]. Antagonist: endostatin did not bind VEGF, so the block is at the receptor [PMID:12029087].","molecular_requirements":"Ligand is endostatin, the C-terminal fragment of collagen XVIII, not full-length COL18A1 [PMID:12029087].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells and purified KDR ectodomain; abstract only [PMID:12029087]. BioGRID: reconstituted complex [DB:BioGRID, PMID:12029087].","localisation_and_range":"Ligand is a secreted fragment; receptor is a transmembrane kinase.","caveats":"Abstract-only read; no affinity reported; one paper, and the BioGRID record cites the same paper.","key_references":[{"PMID":"12029087","why":"Endostatin directly interacts with KDR/Flk-1 and blocks VEGF signalling"}],"covers":["LR000321","LR003827"]},"LR001757":{"pair":"COL1A1 -> GP6","headline":"GPVI is a platelet collagen receptor; recombinant GPVI binds collagen, with PDB structures of the complex; evidence not chain-specific.","interaction_type":"direct binding","direction_and_effect":"Recombinant human and mouse GPVI bound collagen, and the soluble protein blocked collagen-induced platelet aggregation [PMID:10961879]. Curator records stimulatory.","molecular_requirements":"GPVI associates with the FcR-gamma chain [PMID:10961879]. Collagen was used generically, not resolved to COL1A1 versus COL1A2.","affinity_potency":[],"species_and_systems":"Recombinant human and mouse GPVI, platelets; abstract only [PMID:10961879]. PDB lists structures 5OU8 and 5OU9 with chains of P02452 and Q9HCN6 [DB:PDB 5OU8] [DB:PDB 5OU9].","localisation_and_range":"Receptor is restricted to megakaryocytes and platelets and is membrane-bound [PMID:10961879]; collagen is matrix.","caveats":"Paper read as abstract only; collagen type not stated; no affinity reported.","key_references":[{"PMID":"10961879","why":"Cloning of GPVI and binding to collagen"}],"covers":["LR001757","LR005115"]},"LR005663":{"pair":"COL1A1 -> LAIR1","headline":"Collagens, including type I, are high-affinity ligands of inhibitory LAIR-1; one paper plus a BioGRID complex record.","interaction_type":"direct binding","direction_and_effect":"Collagens are high-affinity ligands for the inhibitory receptor LAIR-1, and LAIR-1 cross-linking inhibits immune cell function; recorded as antagonist [PMID:16754721].","molecular_requirements":"Depends on the conserved Gly-Pro-Hyp collagen repeats, shared across collagens [PMID:16754721].","affinity_potency":[],"species_and_systems":"Human leukocytes and purified collagens; human, rat and mouse LAIR-1-IgG bound transfected cells in the full-text excerpts [PMID:16754721]. Reconstituted complex in BioGRID [DB:BioGRID].","localisation_and_range":"LAIR1 is flagged transmembrane [flag]; COL1A1 secreted/matrix [flag], so contact-dependent with matrix.","caveats":"Abstract-level read (full text available). Paper concerns collagens generally; the excerpt shown highlights collagen XVII. No affinity value in our evidence. COL1A1 is not separated from COL1A2.","key_references":[{"PMID":"16754721","why":"Collagens are high-affinity ligands for LAIR-1"}],"covers":["LR002384","LR005663"]},"LR003836":{"pair":"COL1A2 -> CD44","headline":"Affinity-purified lymphocyte CD44 bound native type I collagen fibrils in one 1992 study.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound native type I collagen fibrils, laminin and fibronectin, but not gelatin [PMID:1730778]; effect not reported in our evidence.","molecular_requirements":"Not reported for collagen; fibronectin binding was via the chondroitin sulfate-containing CD44 form [PMID:1730778].","affinity_potency":[],"species_and_systems":"Human lymphocyte CD44 purified protein binding assay [PMID:1730778].","localisation_and_range":"CD44 is flagged secreted and transmembrane [flag]; collagen is matrix [flag].","caveats":"Single paper, focused on fibronectin. The collagen result is for type I collagen as a whole, not COL1A2 alone. No database support.","key_references":[{"PMID":"1730778","why":"Affinity-purified CD44 binds native type I collagen fibrils"}],"covers":["LR000330","LR003836"]},"LR002387":{"pair":"COL1A2 -> DDR2","headline":"Type I collagen binds and activates DDR2, with higher affinity than for DDR1; supported by two full-text papers.","interaction_type":"direct binding","direction_and_effect":"Collagen types I, III, IV and V stimulated phosphorylation of DDR2 in 293 cells; recorded as agonist [PMID:9659899].","molecular_requirements":"Native triple-helical collagen is needed per the abstract [PMID:9659899]. DDR2 binding was detectable at 1 mg loading; type I collagen had about 3-fold higher affinity for DDR2 than DDR1 per the curator note [PMID:9659900].","affinity_potency":[],"species_and_systems":"Radiolabelled DDR2-Fc binding to bovine dermal collagen I, human receptor [PMID:9659900]; human collagen on human 293 cells [PMID:9659899].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"No Kd reported in our evidence. Collagen I is a heterotrimer; COL1A2-specific contribution not shown. One row review_only.","key_references":[{"PMID":"9659900","why":"Slot-blot binding of DDR2 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR2 phosphorylation"}],"covers":["LR002387","LR005666"]},"LR003845":{"pair":"COL2A1 -> ITGB1","headline":"Collagen II signals through ITGB1 in several studies, including a 2019 full-text paper; chain-only evidence with alpha partners varying.","interaction_type":"direct binding","direction_and_effect":"On interacting with COL2A1, ITGB1 competed with BMP receptors for SMAD1, inhibiting SMAD1 activation and nuclear import; COL2A1 also activated ITGB1-induced ERK1/2 phosphorylation, and blocking ITGB1 reversed COL2A1 effects [PMID:30854241]. Curator label: antagonist (of chondrocyte hypertrophy).","molecular_requirements":"ITGB1 is described as the major receptor for COL2A1; alpha partners are not specified there [PMID:30854241]. Other papers implicate alpha2beta1 [PMID:7688313; PMID:7520045] and alpha10beta1 [PMID:9685391].","affinity_potency":[],"species_and_systems":"Human cell lines SW1353 and Hs819.T, human articular chondrocytes, and a Col2a1 p.Gly1170Ser mouse model [PMID:30854241]; bovine chondrocytes [PMID:7688313].","localisation_and_range":"ITGB1 is flagged not secreted [flag]; collagen is a matrix ligand, so contact-dependent.","caveats":"Seven confirmed papers, one pending; shown ones are mostly abstract-read. The 2019 paper used blocking antibody and phosphorylation readouts, not binding measurements. ITGB1 is a shared chain, so signals could reflect any beta1 integrin.","key_references":[{"PMID":"30854241","why":"COL2A1 signals via ITGB1 to suppress BMP-SMAD1"},{"PMID":"9685391","why":"Alpha10beta1 purified on collagen II"},{"PMID":"7688313","why":"Chondrocyte adhesion blocked by anti-beta 1"}],"covers":["LR000339","LR003845"]},"LR005672":{"pair":"COL3A1 -> LAIR1","headline":"Collagens, including III, are high-affinity ligands of inhibitory receptor LAIR-1; full text shows binding to collagens I and III.","interaction_type":"direct binding","direction_and_effect":"Collagens are high-affinity LAIR-1 ligands and directly inhibit immune cell activation in vitro [PMID:16754721]. hLAIR-1 IgG bound collagens I and III by BIAcore, and both human and mouse LAIR-1 IgG immunoprecipitated human collagen III [PMID:16754721]. Curator label: antagonist (inhibitory receptor).","molecular_requirements":"Interaction depends on the conserved Gly-Pro-Hyp repeats; a single triple-helical collagen III molecule interacted with about 9.7 LAIR-1 proteins [PMID:16754721]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human LAIR-1 IgG; mouse and rat LAIR-1 IgG also tested; K562, RBL-2H3 and Ba/F3 transfectants [PMID:16754721]; mouse pair projected.","localisation_and_range":"LAIR1 flagged transmembrane, not secreted; collagen III is a secreted matrix ligand [flag].","caveats":"Pan-collagen motif, not a collagen III-specific interaction. A numeric affinity is not given in the excerpt. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"16754721","why":"Collagens are high-affinity LAIR-1 ligands"}],"covers":["LR002393","LR005672"]},"LR002396":{"pair":"COL4A1 -> DDR1","headline":"Direct but weak collagen IV binding and phosphorylation of DDR1 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR1 and induced receptor phosphorylation, but binding and phosphorylation were consistently weaker than with fibril-forming collagens [PMID:9659900].","molecular_requirements":"DDR1 is a collagen receptor tyrosine kinase; no co-receptor requirement is reported in our evidence. The tested material was commercial type IV collagen [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot binding and phosphorylation assays; mouse pair is projected from human [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002396","LR005675"]},"LR003854":{"pair":"COL4A3 -> CD47","headline":"COL4A3 peptide affinity-purified CD47 from tumour cells; abstract only, peptide-based.","interaction_type":"direct binding","direction_and_effect":"CD47/IAP was isolated from melanoma and prostate cells by affinity purification with the alpha3(IV)179-208 peptide [PMID:10493512]; the peptide inhibits tumour cell proliferation via increased cAMP per the abstract [PMID:10493512].","molecular_requirements":"CD47 was found alongside the beta3 integrin subunit and the alpha(v)beta3 complex [PMID:10493512]; whether CD47 acts alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human tumour cells; a peptide, not full-length COL4A3 [PMID:10493512].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; peptide bait only; Mr 52,000 band identified as CD47. No affinity reported. Human pair labelled orthology-inferred in the dossier.","key_references":[{"PMID":"10493512","why":"CD47 and alpha(v)beta3 as receptors for alpha3(IV) chain"}],"covers":["LR000348","LR003854"]},"LR005708":{"pair":"COLEC12 -> PILRA","headline":"COLEC12 is reported as a novel PILR\u03b1 binding partner, dependent on sialylated O-glycans; supported by SPR in IntAct and Reactome.","interaction_type":"direct binding","direction_and_effect":"COLEC12 and NPDC1 were identified as novel PILR\u03b1 binding partners; PILR\u03b1 is described as an inhibitory receptor [PMID:22396535]. Sialylated O-glycans on the ligands are compulsory for PILR\u03b1 binding [PMID:22396535].","molecular_requirements":"Binding requires sialylated O-glycans on COLEC12 and conserved PILR\u03b1 arginine (Arg-133 mouse, Arg-126 human) [PMID:22396535].","affinity_potency":[],"species_and_systems":"Both mouse and human PILR\u03b1 were tested by mutagenesis; human pair is primary, mouse is ortholog-inferred [PMID:22396535]. IntAct records surface plasmon resonance [DB:IntAct].","localisation_and_range":"Ligand is not flagged secreted; PILR\u03b1 is flagged both secreted and transmembrane [flag]. Binding is to a membrane-type ligand, range not otherwise reported.","caveats":"Abstract read only. Reactome lists the binding reaction, citing this paper among others [DB:Reactome]. No affinity in our evidence.","key_references":[{"PMID":"22396535","why":"Identifies COLEC12 as PILR\u03b1 ligand; sialylated O-glycan dependence"}],"covers":["LR002429","LR005708"]},"LR010667":{"pair":"COMP -> ITGA3:ITGB1","headline":"No verified paper supports this specific integrin complex; the pair appears to be a database or name-level assertion.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; five papers were judged abstract_insufficient and none confirmed.","molecular_requirements":"The only database record names alpha5beta1, alphaVbeta3 and CD47, not alpha3beta1 [DB:Reactome R-HSA-2426259].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No confirmed papers. The Reactome COMP binding reaction lists Integrin alpha5beta1, alphaVbeta3 and CD47, so it does not directly support alpha3beta1 [DB:Reactome R-HSA-2426259].","key_references":[],"covers":["LR010667"]},"LR003881":{"pair":"CSF1 -> CSF1R","headline":"CSF1 binds and activates CSF1R; supported by binding and functional papers plus structures, though the papers were read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"CSF1 specifically bound murine CSF-1 receptor (c-fms) and, with the growth factor present, the receptor was phosphorylated on tyrosine in membrane preparations [PMID:2408759]. Curators label the effect agonist/stimulatory [PMID:8355686]. Co-addition of M-CSF and IL-34 gave a distinct activation pattern with higher tyrosine phosphorylation at low concentrations [PMID:26095744].","molecular_requirements":"The three N-terminal Ig-like domains of CSF1R form the high-affinity binding region; domains 1-2 alone did not interact with M-CSF, domain 3 was needed, and domains 4-5 did not bind and may inhibit [PMID:8355686]. A single receptor chain is involved; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding mapping used murine c-fms segments expressed in Sf9 cells [PMID:8355686]; binding and phosphorylation used mouse macrophage preparations [PMID:2408759]; the IL-34/M-CSF study used cells expressing the receptor [PMID:26095744]. Curators record the mouse pair and a human pair projected from it by orthology (human pair flagged ortholog-inferred).","localisation_and_range":"Annotation flags mark CSF1 as both secreted and transmembrane, and CSF1R as a transmembrane receptor [flag]; range (soluble versus membrane-bound ligand) is not reported in our evidence.","caveats":"All three shown papers were read as abstracts only. The 2015 paper reports a possible M-CSF/IL-34 heteromer, so some activation patterns may reflect the combination rather than CSF1 alone [PMID:26095744]. Databases (BioGRID, IntAct, PDB 4WRL/4WRM, Reactome, UniProt) also record the complex, but several records involve CSF1 together with IL-34 [DB:PDB 4WRL] [DB:Reactome]. GtoPdb lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"2408759","why":"Murine CSF-1 binding and ligand-induced receptor phosphorylation"},{"PMID":"8355686","why":"Maps the high-affinity CSF1 binding region to Ig-like domains 1-3"},{"PMID":"26095744","why":"M-CSF plus IL-34 alters receptor phosphorylation"}],"covers":["LR000375","LR003881"]},"LR008246":{"pair":"CSF2 -> CSF2RA:CSF2RB","headline":"GM-CSF signals through a heterodimeric alpha/beta receptor, supported by structure, binding and functional studies.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the human GM-CSF/receptor ternary complex was reported, assembling into a dodecamer or higher-order complex [PMID:18692472]. Cells carrying both chains reconstitute signalling, mitogenesis and transformation [PMID:8910448] and differentiation in response to human GM-CSF [PMID:9211889]. Curators label the effect stimulatory.","molecular_requirements":"Both chains are needed for the high-affinity receptor: alpha is ligand-specific with low affinity, and betac, shared with IL-3 and IL-5 receptors, lacks ligand binding alone [PMID:18692472] [PMID:10572088]. Betac alone bound no cytokine [PMID:1702217]. His-367 of betac is critical for high-affinity binding [PMID:8278375]. Since tools score complexes by weakest subunit, both chains matter.","affinity_potency":[],"species_and_systems":"Human proteins in structural and binding work; mouse-cell hosts (NIH-3T3, WT-19) were used for functional assays [PMID:8910448] [PMID:9211889]. A mouse in vivo study knocked out macrophage Csf2ra after myocardial infarction [PMID:42121865].","localisation_and_range":"Ligand annotated secreted, non-transmembrane [flag]; receptor chains are annotated as receptors [flag].","caveats":"Papers were read as abstracts only. The 2026 mouse study concerns Csf2ra alone and the other 2026 paper is scRNA-seq co-expression, so neither shows binding [PMID:42121865] [PMID:42272179]. Two further papers were judged abstract_insufficient.","key_references":[{"PMID":"18692472","why":"Crystal structure of the GM-CSF ternary receptor complex"},{"PMID":"1702217","why":"Betac reconstitutes the high-affinity receptor"},{"PMID":"8278375","why":"Betac His-367 needed for high-affinity binding"}],"covers":["LR008246"]},"LR005726":{"pair":"CST3 -> LRP2","headline":"Cystatin C binds megalin (LRP2) directly and is endocytosed via it; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Cystatin C binds directly to megalin in a Ca-dependent manner by quartz-crystal microbalance; it is endocytosed specifically via megalin in L2 cells, and kidney-specific megalin knockout mice show megalin mediates proximal tubular uptake [PMID:17462596]. Megalin acts as an endocytic (clearance) receptor.","molecular_requirements":"Calcium is required [PMID:17462596]; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Quartz-crystal microbalance with unspecified species; rat L2 cells; kidney-specific megalin knockout mice [PMID:17462596]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"CST3 flagged secreted [flag]; uptake occurs in proximal tubule cells [PMID:17462596]. UniProt also records the interaction [DB:UniProt].","caveats":"One paper, read as abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"17462596","why":"QCM binding plus megalin-dependent endocytosis of cystatin C"}],"covers":["LR002450","LR005726"]},"LR000389":{"pair":"CTHRC1 -> FZD5","headline":"CTHRC1 co-precipitates with Fzd5 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 and Wnt3a co-precipitated with Fzd5, and Cthrc1 enhanced Wnt3a-Fzd5 binding; Cthrc1 also co-precipitated with Fzd3 and Fzd6 and no binding to Smo [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000389","LR003895"]},"LR001766":{"pair":"CXADR -> CXADR","headline":"Homophilic CXADR adhesion reported in one mouse cell-aggregation study; not a distinct ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"C6 cells transfected with mouse CAR aggregated homophilically, and this was inhibited by antibodies against the extracellular domain [PMID:10814828]. This indicates self-association driving adhesion, not a separate ligand and receptor.","molecular_requirements":"Not reported in our evidence beyond the extracellular domain being the antibody target [PMID:10814828].","affinity_potency":[],"species_and_systems":"Mouse protein (mCAR) expressed in transfected C6 cells, aggregation assay [PMID:10814828]. The human pair is ortholog-inferred. IntAct has one protein-array record for human P78310 with itself [DB:IntAct].","localisation_and_range":"Both partners carry secreted and receptor flags [flag]; the paper describes a membrane protein mediating cell-cell adhesion [PMID:10814828].","caveats":"No direct binding assay, no affinity. Human version is inferred from the mouse result plus a protein-array record only [DB:IntAct]. Only an abstract was read.","key_references":[{"PMID":"10814828","why":"Homophilic aggregation of mCAR-transfected cells"}],"covers":["LR001766","LR005124"]},"LR002459":{"pair":"CXCL10 -> TLR4","headline":"CXCL10 needs TLR4 together with CXCR3 for osteoclastogenic cytokine induction in mouse cells; no direct binding is shown.","interaction_type":"functional only","direction_and_effect":"TLR4 did not mediate CXCL10-induced migration, but CXCR3 and TLR4 were both required for CXCL10-stimulated osteoclastogenic cytokine production in CD4+ T cells [PMID:28724396].","molecular_requirements":"Requires both CXCR3 and TLR4 for cytokine induction; CXCR3 alone for migration [PMID:28724396].","affinity_potency":[],"species_and_systems":"Knockout mouse cells and an arthritis model [PMID:28724396]. Human pair is ortholog-inferred.","localisation_and_range":"CXCL10 is flagged secreted [flag].","caveats":"No direct binding shown in our evidence; TLR4 may act as co-requirement rather than a receptor. Single paper.","key_references":[{"PMID":"28724396","why":"CXCR3 and TLR4 in CXCL10 signalling"}],"covers":["LR002459","LR005735"]},"LR005735":{"pair":"CXCL10 -> TLR4","headline":"CXCL10 needs TLR4 together with CXCR3 for osteoclastogenic cytokine induction in mouse cells; no direct binding is shown.","interaction_type":"functional only","direction_and_effect":"TLR4 did not mediate CXCL10-induced migration, but CXCR3 and TLR4 were both required for CXCL10-stimulated osteoclastogenic cytokine production in CD4+ T cells [PMID:28724396].","molecular_requirements":"Requires both CXCR3 and TLR4 for cytokine induction; CXCR3 alone for migration [PMID:28724396].","affinity_potency":[],"species_and_systems":"Knockout mouse cells and an arthritis model [PMID:28724396]. Human pair is ortholog-inferred.","localisation_and_range":"CXCL10 is flagged secreted [flag].","caveats":"No direct binding shown in our evidence; TLR4 may act as co-requirement rather than a receptor. Single paper.","key_references":[{"PMID":"28724396","why":"CXCR3 and TLR4 in CXCL10 signalling"}],"covers":["LR002459","LR005735"]},"LR000398":{"pair":"CXCL12 -> ACKR3","headline":"CXCL12 is a high-affinity ligand of ACKR3 (CXCR7), an atypical arrestin-recruiting scavenger receptor; well supported by papers and databases.","interaction_type":"direct binding","direction_and_effect":"CXCL12 binds RDC1/CXCR7 specifically and saturably with apparent KD approximately 0.4 nM, and promoted internalisation and chemotactic signals in CXCR4-negative cells [PMID:16107333]. Later work found CXCR7 activation does not cause Ca2+ mobilization or cell migration [PMID:16940167], and that CXCR7 recruits beta-arrestin and acts as a scavenger of CXCL12 by internalisation and degradation [PMID:20956518][PMID:20161793]. GtoPdb lists an agonist [DB:GtoPdb]; PDB structures exist [DB:PDB 7SK3].","molecular_requirements":"Single receptor chain in these papers. ACKR3 also binds CXCL11 [PMID:20161793]. CXCR4 is a separate CXCL12 receptor that need not be present [PMID:16107333].","affinity_potency":[{"value":"KD approximately 0.4 nM","assay":"binding","system":"RDC1/CXCR7 in T lymphocytes","cite":"PMID:16107333"},{"value":"EC50 30 nM","assay":"beta-arrestin recruitment","system":"CXCR7 cells","cite":"PMID:20956518"},{"value":"pEC50 7.52-7.9","assay":"GtoPdb affinity record","system":"human, per database","cite":"PMID:20956518"}],"species_and_systems":"Human ligand and receptor in cells; scavenging also shown in adult mouse heart valves and human umbilical vein endothelium [PMID:20161793].","localisation_and_range":"CXCL12 flagged secreted, ACKR3 transmembrane [flag]; paracrine.","caveats":"All four shown papers were read as abstracts. Papers disagree on signalling: chemotactic signalling in [PMID:16107333] versus none in [PMID:16940167]; CXCR7 function is described as controversial [PMID:20161793]. Little CXCR7 down-regulation by CXCL12 was seen in primary cells [PMID:20161793].","key_references":[{"PMID":"16107333","why":"Original binding KD for CXCL12 at RDC1/CXCR7"},{"PMID":"20161793","why":"Scavenger function of CXCR7 for CXCL12"},{"PMID":"20956518","why":"CXCL12 beta-arrestin recruitment EC50 at CXCR7"}],"covers":["LR000398","LR003903"]},"LR007175":{"pair":"CXCL13 -> ACKR4","headline":"Weak-to-moderate binding of CXCL13 (BLC) to ACKR4 (CCX CKR) shown in one abstract-only 2000 paper; lower affinity than ELC, SLC and TECK.","interaction_type":"direct binding","direction_and_effect":"Radiolabelled-ligand competition showed CXCL13 (BLC) as a lower-affinity ligand of human CCX CKR (ACKR4), with IC50 <150 nM, versus <15 nM for ELC, SLC and TECK [PMID:10706668]. Whether CXCL13 triggers any signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence; binding was to CCX CKR expressed in cells, with no co-receptor or subunit requirement described.","affinity_potency":[{"value":"IC50 <150 nM","assay":"radiolabelled chemokine competition binding (CXCL13/BLC as competitor)","system":"CCX CKR-expressing cells","cite":"PMID:10706668"}],"species_and_systems":"Human chemokine and human receptor in transfected cells; adhesion to immobilised chemokines (stalkokines) was also used [PMID:10706668]. A BioGRID record lists a reconstituted complex from the same paper [DB:BioGRID].","localisation_and_range":"CXCL13 is flagged secreted and ACKR4 is flagged as a transmembrane receptor [flag]; a soluble ligand acting on a cell-surface receptor.","caveats":"Single paper, read as abstract only. CXCL13 is explicitly the weaker ligand class [PMID:10706668]. The database record rests on the same paper [DB:BioGRID]. No in vivo or mouse evidence is reported in our evidence.","key_references":[{"PMID":"10706668","why":"Radioligand competition and adhesion screen assigning CXCL13 as a lower-affinity ACKR4 ligand"}],"covers":["LR007175"]},"LR003908":{"pair":"CXCL13 -> CXCR3","headline":"One abstract-only 2001 paper reports CXCL13 binding and activating human CXCR3 with unusual pharmacology; CXCR5 is its conventional receptor.","interaction_type":"direct binding","direction_and_effect":"Human CXCL13 (BCA-1) competed with radiolabelled IP-10 for binding to human CXCR3, drove chemotaxis of CXCR3 transfectants (blocked by anti-CXCR3 antibody) and stimulated GTP gamma S binding [PMID:11554781]. It induced no calcium flux and attenuated the IP-10-induced calcium flux, suggesting biased or partial agonism [PMID:11554781].","molecular_requirements":"Not reported in our evidence; effects were shown in CXCR3-transfected cells.","affinity_potency":[],"species_and_systems":"Human CXCL13 on human CXCR3 expressed in Ba/F3 and 293EBNA cell lines [PMID:11554781]. The mouse pair is projected from human evidence, not tested.","localisation_and_range":"CXCL13 is flagged secreted [flag]; soluble ligand, cell-surface GPCR.","caveats":"Single paper, abstract only; no affinity value reported in our evidence. Calcium response is absent and IP-10 signalling is dampened, so effect is mixed. The abstract names CXCR5 as the previously known receptor for CXCL13 [PMID:11554781]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"11554781","why":"Competition binding, chemotaxis and GTP gamma S data for CXCL13 on CXCR3"}],"covers":["LR000403","LR003908"]},"LR002468":{"pair":"CXCL17 -> CXCR4","headline":"One 2024 BRET study reports CXCL17 as a low-potency, GAG-dependent inhibitor of CXCR4; no second source.","interaction_type":"functional only","direction_and_effect":"CXCL17 produced no agonist response at CCR1-10 or CXCR1-3, 5 and 6, but inhibited CXCL12-mediated CXCR4 Gi and beta-arrestin-2 responses and competed for CXCL12 binding [PMID:38502733]. It also decreased the basal beta-arrestin-2 BRET, indicating inhibition of constitutive CXCR4 activity [PMID:38502733].","molecular_requirements":"Inhibition of ligand binding occurred only in intact cells, mimicked by GAG binders surfen and protamine sulfate; disrupting putative GAG binding domains in CXCL17 prevented CXCR4 binding, implying a GAG-containing accessory protein [PMID:38502733].","affinity_potency":[{"value":"pIC50 6.93 \u00b1 0.28","assay":"inhibition of CXCL12 Gi BRET response","system":"HEK293 cells","cite":"PMID:38502733"},{"value":"pKi = 6.25 \u00b1 0.19","assay":"NanoBRET competition with CXCL12-AF647","system":"HEK293 cells with Nluc/CXCR4","cite":"PMID:38502733"},{"value":"pIC50 = 7.24 \u00b1 0.08","assay":"decrease of basal CXCR4/beta-arrestin2 BRET","system":"HEK293 cells","cite":"PMID:38502733"}],"species_and_systems":"Recombinant human-labelled pair in HEK293, Cos-7 and HeLa cells; species of the proteins not stated in our excerpts [PMID:38502733].","localisation_and_range":"CXCL17 flagged secreted [flag]; mucosal chemokine per the abstract [PMID:38502733].","caveats":"Single abstract/excerpt-based paper. Low potency compared with AMD3100 (pIC50 = 7.52 \u00b1 0.03). Not shown in purified membranes. No in vivo data. No database record.","key_references":[{"PMID":"38502733","why":"BRET evidence that CXCL17 inhibits CXCR4 signalling and ligand binding"}],"covers":["LR002468","LR005742"]},"LR005744":{"pair":"CXCL2 -> ACKR1","headline":"One abstract-only mouse intravital paper shows neutrophil junctional breaching by CXCL2 depends on ACKR1; no binding data.","interaction_type":"functional only","direction_and_effect":"In cytokine-stimulated mouse cremaster muscle, neutrophil-derived CXCL2 was critical for breaching endothelial junctions, and this activity depended on ACKR1, enriched within endothelial junctions [PMID:30446388]. Transmigrating neutrophils created a junctional chemokine depot of ACKR1-presented CXCL2, enabling unidirectional luminal-to-abluminal migration [PMID:30446388].","molecular_requirements":"Not reported in our evidence; ACKR1 acts as a presenting receptor, with no signalling reported.","affinity_potency":[],"species_and_systems":"Mouse in vivo (confocal intravital microscopy); the human pair is projected from mouse [PMID:30446388].","localisation_and_range":"Soluble chemokine presented on endothelial junctions by a transmembrane receptor [PMID:30446388]; CXCL2 flagged secreted [flag].","caveats":"Single paper read as abstract; no direct binding or affinity reported in our evidence. The human pair is inferred, not tested.","key_references":[{"PMID":"30446388","why":"Intravital evidence of ACKR1-dependent CXCL2 activity at endothelial junctions"}],"covers":["LR002470","LR005744"]},"LR002477":{"pair":"DAG1 -> NRXN3","headline":"Neurexin-3 splice variants that bind dystroglycan enable inhibitory synapse function; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Neurexin-3 splice variants mediating binding to dystroglycan enable inhibitory synapse function in rescue experiments in Neurexin-3 conditional knockout mice; a minimal dystroglycan-binding fragment sustains this [PMID:36997523].","molecular_requirements":"Splice-variant dependent; no other subunits reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse conditional knockout rescue [PMID:36997523]. The human pair is ortholog-projected.","localisation_and_range":"Neurexin-3 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag].","caveats":"Abstract only. Physical binding is not shown in this paper in our evidence. One further review-only row not shown.","key_references":[{"PMID":"36997523","why":"Neurexin-3 dystroglycan-binding variants rescue inhibitory synapse function"}],"covers":["LR002477","LR005751"]},"LR005753":{"pair":"DCN -> KDR","headline":"Decorin binds VEGFR-2 (KDR) and competes with VEGF-E in human trophoblasts; measured Ki.","interaction_type":"direct binding","direction_and_effect":"Antagonist: DCN displaced 125I-VEGF-E, inhibited VEGF-E-induced migration by interfering with ERK1/2 activation; LRR5 fragments blocked the interaction [PMID:21659473].","molecular_requirements":"Binding abrogated by a VEGFR-2-blocking antibody, indicating overlap between the ligand-binding and DCN-binding domains [PMID:21659473].","affinity_potency":[{"value":"Ki 3.93-5.78 nM","assay":"competition against 125I-VEGF-E (Kd 566 pM)","system":"extravillous trophoblasts","cite":"PMID:21659473"}],"species_and_systems":"Human extravillous trophoblasts, native and recombinant VEGFR-2; far-Western and co-IP [PMID:21659473]. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Decorin flagged secreted; KDR transmembrane receptor [flag].","caveats":"One paper, abstract only; affinity is 7- to 10-fold lower than VEGF-E [PMID:21659473].","key_references":[{"PMID":"21659473","why":"Binding, competition and antagonism at VEGFR-2"}],"covers":["LR002479","LR005753"]},"LR001775":{"pair":"DCN -> TLR4","headline":"Decorin acts as a TLR2/TLR4 ligand in macrophages in one paper; functional evidence with a pull-down in HEK cells.","interaction_type":"functional only","direction_and_effect":"Decorin activated MAPKs p44/p42 and p38 and increased TNFalpha and IL-12p70 release in a TLR2- and TLR4-dependent manner; binding assays in HEK cells indicated decorin could pull down TLR2 and TLR4 [PMID:22087031].","molecular_requirements":"TLR2 and TLR4 both implicated; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages, septic and tumour mouse models; HEK cells expressing TLR4 [PMID:22087031]. Human pair is ortholog-projected from the mouse data.","localisation_and_range":"Decorin flagged secreted; TLR4 flagged receptor [flag].","caveats":"Single paper, no affinity; same evidence as DCN-TLR2 [PMID:22087031].","key_references":[{"PMID":"22087031","why":"Decorin as endogenous TLR2/TLR4 ligand"}],"covers":["LR001775","LR005132"]},"LR008408":{"pair":"DEFB4B -> TLR4","headline":"The cited paper shows TLR4 drives HBD-2 production, not that HBD-2 binds TLR4; evidence does not support the stated direction.","interaction_type":"conflicting","direction_and_effect":"TLR4-neutralising antibody reduced C. pneumoniae-induced HBD-2 mRNA and protein production in U937 cells and monocytes [PMID:19735472]. That places TLR4 upstream of HBD-2 expression; HBD-2 acting on TLR4 is not shown in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human U937 cells and monocytes infected with C. pneumoniae [PMID:19735472].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only. The paper does not test HBD-2 as a TLR4 ligand and does not distinguish DEFB4B from DEFB4A. No other evidence for this pair.","key_references":[{"PMID":"19735472","why":"TLR4 mediates HBD-2 induction (not ligand binding)"}],"covers":["LR008408"]},"LR002486":{"pair":"DHH -> GAS1","headline":"Functional evidence only: Gas1 acts as a Hedgehog co-receptor potentiating Dhh signalling in endothelial cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Gas1 promotes Dhh binding to Smo and potentiates Dhh effects; Gas1 deficiency phenocopies Dhh deficiency, including VCAM-1 and ICAM-1 overexpression [PMID:33028094]. Direct Dhh-Gas1 binding is not reported in our evidence.","molecular_requirements":"Described as a hedgehog co-receptor alongside Cdon, which acts as a decoy that prevents Dhh binding to Ptch1 [PMID:33028094]. Subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used endothelial cells with siRNA and EC-specific conditional knockout mice (mouse in vivo); the human pair is listed, with the mouse pair projected by ortholog inference.","localisation_and_range":"DHH is flagged both secreted and transmembrane, GAS1 as a receptor and not secreted [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as an abstract only. The finding is a knockdown/knockout phenotype and a binding-to-Smo statement, not a measured Dhh-Gas1 interaction.","key_references":[{"PMID":"33028094","why":"Gas1 potentiates Dhh signalling in endothelial cells; Cdon acts as decoy"}],"covers":["LR002486","LR005754"]},"LR003935":{"pair":"DKK1 -> LRP6","headline":"Very well supported direct, high-affinity binding with crystal structures; DKK1 inhibits Wnt signalling through LRP6.","interaction_type":"direct binding","direction_and_effect":"Dkk1 is a high-affinity ligand for LRP6 and inhibits Wnt signalling by preventing Wnt-induced Fz-LRP6 complex formation, binding neither Wnt nor Fz [PMID:11448771]. LRP6 is a specific high-affinity receptor for Dkk1 and Dkk2 [PMID:11357136]. Dkk1 competes with Wnt3a and Wnt9b for LRP6 binding [PMID:20093360].","molecular_requirements":"A single Dkk1 molecule can bind both LRP6(1-2) and LRP6(3-4); the C-terminal domain binds LRP6(3-4) and the N-terminal domain binds LRP6(1-2) [PMID:22000856]. Dkk1 binding is independent of Fz [PMID:11433302]. Reconstituted complex and X-ray records exist [DB:BioGRID] [DB:IntAct].","affinity_potency":[{"value":"K(D) = 0.39 nM","assay":"cell surface binding with [125I] Dkk-1","system":"human Dkk-1, cell surface site","cite":"PMID:11433302"},{"value":"Kd of 67 nM","assay":"isothermal titration calorimetry","system":"Dkk1 with LRP6(3-4), 1:1 complex","cite":"PMID:22000856"}],"species_and_systems":"Recombinant proteins in vitro: human LRP6 ectodomain and mouse Fz8 CRD in insect cells [PMID:20093360], Xenopus embryos [PMID:11357136]; cell-based assays elsewhere. Mouse pair is ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted; LRP6 as a transmembrane receptor [flag].","caveats":"The two affinity values come from different assays and constructs, so they are not directly comparable. Most papers were read as abstracts. Two review-only and two abstract-insufficient rows are not shown.","key_references":[{"PMID":"11448771","why":"Dkk-1 is a high-affinity LRP6 ligand and blocks Fz-LRP6 complex"},{"PMID":"11433302","why":"K(D) = 0.39 nM binding; LRP6 is the receptor"},{"PMID":"22000856","why":"Structure and Kd 67 nM for Dkk1-LRP6(3-4)"}],"covers":["LR000443","LR003935"]},"LR003944":{"pair":"DLL4 -> NOTCH2","headline":"Supported by an ELISA binding assay and functional assays; DLL4 activates NOTCH2 less than NOTCH1.","interaction_type":"direct binding","direction_and_effect":"Dll4 binding to Notch2 EGF1-12 was recapitulated in an ELISA-based assay [PMID:22842086]. In cell assays DLL4 activates NOTCH2 less than NOTCH1 [PMID:30289388]; DLL4-NOTCH1 activation was more than twice that of DLL4-NOTCH2 without Fringes, and LFNG enhanced NOTCH2 activation by DLL1 and DLL4 [PMID:32820046].","molecular_requirements":"Notch2 EGF repeats 1-12 sufficed for Dll4 binding in the ELISA [PMID:22842086]. Reactome lists DLL4 binding NOTCH2 and a DLL4:NOTCH2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human and mouse ligand/receptor material used in the ELISA and cell assays; the human record is ortholog-inferred, the mouse record is not [PMID:22842086][PMID:30289388].","localisation_and_range":"Both partners annotated transmembrane, DLL4 not secreted [flag].","caveats":"Abstracts only for two of three papers. The antibody paper was a methods study; the binding assay was used as a tool, not characterised as a primary finding [PMID:22842086]. Affinity not reported in our evidence.","key_references":[{"PMID":"22842086","why":"ELISA binding of Notch2 EGF1-12 to Dll4"},{"PMID":"30289388","why":"Ectodomain-dependent DLL4 selectivity"},{"PMID":"32820046","why":"Fringe and ligand effects on NOTCH2"}],"covers":["LR000452","LR003944"]},"LR005762":{"pair":"DRAXIN -> DCC","headline":"Direct structural evidence that Draxin binds the DCC N-terminal Ig domains; a single paper, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Draxin interacts with DCC through its N-terminal four immunoglobulin domains, shown by crystal structures [PMID:29503192]. Draxin captures Netrin-1 and tethers it to DCC, modulating Netrin-mediated fasciculation [PMID:29503192]. Listed effect is agonist.","molecular_requirements":"The Draxin C-terminal region binds DCC Ig1-Ig4 at a relatively weak site; Netrin-1 binds a separate adjacent Draxin site [PMID:29503192]. Netrin-1 is part of the proposed functional triad.","affinity_potency":[],"species_and_systems":"Recombinant proteins in crystallography and cell-based binding; the dossier labels species as human [PMID:29503192].","localisation_and_range":"Draxin annotated secreted, DCC transmembrane [flag]; the model has Draxin bridging axons decorated with DCC [PMID:29503192].","caveats":"Abstract plus excerpts only. The binding is described as relatively weak and no Kd is in our evidence. The paper's focus is the Netrin-1 axis.","key_references":[{"PMID":"29503192","why":"Crystal structures of Draxin/DCC and Draxin/Netrin-1"}],"covers":["LR002494","LR005762"]},"LR002495":{"pair":"DRAXIN -> LRP6","headline":"Weak support: one abstract-only paper on Neucrin (the name used for Draxin) reports binding to LRP6 and Wnt antagonism.","interaction_type":"direct binding","direction_and_effect":"Neucrin bound LDL receptor-related protein 6 and inhibited stabilisation of cytosolic beta-catenin, so it acts as an antagonist of canonical Wnt signalling [PMID:19857465].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in the dossier; the paper describes mouse and human Neucrin [PMID:19857465].","localisation_and_range":"DRAXIN annotated secreted, LRP6 transmembrane [flag]; Neucrin is described as a secreted antagonist [PMID:19857465].","caveats":"Abstract only; the binding assay type is not given. The abstract uses the name Neucrin, so whether it is the entity curated as DRAXIN is a name-mapping assumption not checkable in our evidence.","key_references":[{"PMID":"19857465","why":"Neucrin binds LRP6 and inhibits Wnt"}],"covers":["LR002495","LR005763"]},"LR001784":{"pair":"DSC1 -> DSG2","headline":"Heterophilic DSC1-DSG2 binding supported by a family-wide study and database records.","interaction_type":"direct binding","direction_and_effect":"Dsg and Dsc ectodomains form heterophilic adhesive dimers across the family, with affinities characteristic of each pair, including DSC1:DSG2 [PMID:27298358]. BioGRID lists reconstituted complex and affinity capture-Western for DSC1-DSG2 [DB:BioGRID]; IntAct lists a solid phase assay [DB:IntAct].","molecular_requirements":"Strand-swap binding; Dsg2 and Dsc1 crystal structures were solved separately [PMID:27298358].","affinity_potency":[],"species_and_systems":"Human ectodomains; mouse record is ortholog-inferred [PMID:27298358].","localisation_and_range":"Both annotated transmembrane [flag]; trans-cellular adhesion [PMID:27298358].","caveats":"Abstract read only; no pair-specific affinity in our evidence. One of 25 companion rows from a single paper.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc binding and structures"}],"covers":["LR001784","LR005140"]},"LR001793":{"pair":"DSC3 -> DSG3","headline":"DSC3 -> DSG3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001793","LR005149"]},"LR005771":{"pair":"DSG3 -> DSC1","headline":"DSG3 -> DSC1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002503","LR005771"]},"LR008192":{"pair":"EDIL3 -> ITGAV:ITGB3","headline":"In vivo mouse genetics link Del-1 to beta3 integrin in the HSC niche; alphaV is not named.","interaction_type":"functional only","direction_and_effect":"Del-1-induced HSC proliferation and myeloid commitment were mediated by beta3 integrin on hematopoietic progenitors [PMID:28846069].","molecular_requirements":"Only the beta3 chain is named; the alphaV partner is assumed from the complex [PMID:28846069].","affinity_potency":[],"species_and_systems":"Mouse, Del-1-deficient mice, bone-marrow HSC niche; the dossier lists a human pair.","localisation_and_range":"Described as a secreted extracellular matrix protein with a juxtacrine function [PMID:28846069].","caveats":"Abstract only; in vivo genetics, no binding measurement.","key_references":[{"PMID":"28846069","why":"Del-1 acts via beta3 integrin in HSC niche"}],"covers":["LR008192"]},"LR003953":{"pair":"EDN2 -> EDNRA","headline":"ET-2 acts as a full agonist on ETA in vitro; functional evidence only, abstracts only.","interaction_type":"functional only","direction_and_effect":"ET-2 constricts human isolated blood vessels via ETA, full agonist, equipotent with ET-1 with an EC50 value of 5.7 nM [PMID:7647976]; chicken EDNRA in HEK293 cells was activated by EDN1 and EDN2 [PMID:31351053]; in rat ovary the contraction by EDN2 was mediated by EDNRA, not EDNRB [PMID:20450830]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"EC50 5.7 nM","assay":"vasoconstriction, ET-2 equipotent with ET-1","system":"human isolated blood vessels","cite":"PMID:7647976"}],"species_and_systems":"Human blood vessels [PMID:7647976], chicken receptor in HEK293 cells [PMID:31351053], rat ovary [PMID:20450830]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"ET-2 is annotated secreted and EDNRA transmembrane [flag].","caveats":"No direct binding paper is shown; all three papers were read as abstracts only. Selectivity for ETA over ETB is shown in rat ovary only [PMID:20450830]. The dossier also lists pIC50 8.2 as the affinity field for the first paper [PMID:7647976].","key_references":[{"PMID":"7647976","why":"human vessels, ET-2 full agonist via ETA"},{"PMID":"20450830","why":"rat ovary, EDN2 contraction via EDNRA"},{"PMID":"31351053","why":"chicken EDNRA activated by EDN1/EDN2"}],"covers":["LR000462","LR003953"]},"LR003962":{"pair":"EFNA1 -> EPHA5","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA5 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000471","LR003962"]},"LR000479":{"pair":"EFNA2 -> EPHA5","headline":"Ephrin-A2 and EphA5 are co-expressed in mouse hippocampus; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Both EphA5 and ephrin-A ligands (2 and 5) are expressed in adult mouse hippocampus; immunoadhesins targeting receptor or ligand sites were used with a behavioural readout [PMID:10531456]. UniProt lists EPHA5 as an EFNA2 binder [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult mouse hippocampus, in vitro and behavioural [PMID:10531456].","localisation_and_range":"EFNA2 annotated transmembrane, EPHA5 transmembrane [flag].","caveats":"The shown evidence is co-expression and a protein-targeting study, not binding between this pair; abstract only.","key_references":[{"PMID":"10531456","why":"EphA5 and ephrin-A2/A5 in learning"}],"covers":["LR000479","LR003970"]},"LR003980":{"pair":"EFNA3 -> EPHA7","headline":"Ephrin-A3 binds EphA7 in rat striatal lysates and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in rat striatal tissue [PMID:10366629]. Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat postnatal striatum lysates and in situ hybridisation [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA3 is flagged membrane-bound; EPHA7 is flagged both secreted and transmembrane [flag].","caveats":"10366629 was read as an abstract only; 22568954 was a browser read with an unverifiable quote. BioGRID lists an affinity capture-Western record [DB:BioGRID].","key_references":[{"PMID":"10366629","why":"Ephrin-A3 binds EphA7 in rat striatum"},{"PMID":"22568954","why":"ELISA binding ranking"}],"covers":["LR000489","LR003980"]},"LR000497":{"pair":"EFNA4 -> EPHA7","headline":"No verified paper; one IntAct comigration record supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists a 'direct interaction by comigration in sds page' record for EFNA4 and EPHA7 [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred.","localisation_and_range":"Both flagged secreted and transmembrane [flag].","caveats":"All judged papers were review-only or abstract-insufficient; evidence is a single database assay type.","key_references":[],"covers":["LR000497","LR003988"]},"LR007193":{"pair":"EFNB1 -> EPHA2","headline":"No curator-verified paper; support is only IntAct records.","interaction_type":"database-asserted only","direction_and_effect":"not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists surface plasmon resonance and solid-phase assay records from PMID 35922511, species not given [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Rests on database records alone. Judged papers were abstract_insufficient (2) or about a different entity (1) [DB:IntAct].","key_references":[],"covers":["LR007193"]},"LR005807":{"pair":"EPHA10 -> EFNA5","headline":"EPHA10-EFNA5 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA5 flags are non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002539","LR005807"]},"LR005816":{"pair":"EPHA3 -> EFNA4","headline":"EPHA3-EFNA4 rests on a BioGRID reconstituted complex; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EPHA3-EFNA4 as a reconstituted complex [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Both partners are flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Eight judged rows were review-only or abstract-insufficient; single database record, no affinity data.","key_references":[],"covers":["LR002548","LR005816"]},"LR002549":{"pair":"EPHA3 -> EFNA5","headline":"EphA3 binds ephrin-A5 with a crystal structure and ELISA binding data from three sources; strongly supported but affinity values not in dossier.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of the EphA3 ligand-binding domain with its preferred ligand ephrin-A5 shows a pronounced tilt of ephrin-A5 that enlarges the interface beyond the canonical pocket [PMID:25993310]. Ephrin-A5 Fc binds EphA receptors with high apparent affinity in ELISA [PMID:22568954]. UniProt says activation by EFNA5 regulates adhesion, cytoskeleton and migration [DB:UniProt].","molecular_requirements":"The ligand-binding domain of EphA3 is sufficient for the structure [PMID:25993310]. Buried surface area: 1,298 \u00c52 for ephrin-A5 on EphA3 versus 847 \u00c52 on EphA2 [PMID:25993310].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the structural paper [PMID:25993310]; the ELISA paper does not specify species [PMID:22568954]. PDB 4L0P is a structure of the pair [DB:PDB 4L0P].","localisation_and_range":"EPHA3 is flagged secreted, which is unlikely for a transmembrane Eph receptor; EFNA5 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Abstract read for the structure paper; the ELISA paper was browser-read and its quote is unverified (spot-check pending). No numeric affinity in our evidence.","key_references":[{"PMID":"25993310","why":"EphA3/ephrin-A5 complex structure"},{"PMID":"22568954","why":"ELISA: ephrin-A5 Fc binds EphA receptors"}],"covers":["LR002549","LR005817"]},"LR005159":{"pair":"EPHA4 -> EFNB1","headline":"EPHA4-EFNB1 rests on one SPR record in IntAct; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists surface plasmon resonance between the two proteins [DB:IntAct]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Six judged rows were review-only or abstract-insufficient; a single database record, no affinity values in our dossier.","key_references":[],"covers":["LR001803","LR005159"]},"LR005825":{"pair":"EPHA5 -> EFNA1","headline":"EPHA5-EFNA1 rests on a single UniProt statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both pairs are ortholog-inferred.","localisation_and_range":"EFNA1 is flagged secreted, EPHA5 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; one database sentence only, no affinity data.","key_references":[],"covers":["LR002557","LR005825"]},"LR002558":{"pair":"EPHA5 -> EFNA2","headline":"EPHA5-EFNA2 rests on a single UniProt statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both pairs are ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; one database sentence only, no affinity data.","key_references":[],"covers":["LR002558","LR005826"]},"LR005834":{"pair":"EPHA6 -> EFNA5","headline":"Database-only pair: a single IntAct co-immunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only an anti-tag coimmunoprecipitation record exists [DB:IntAct EBI-54501476], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002566","LR005834"]},"LR002567":{"pair":"EPHA7 -> EFNA1","headline":"UniProt lists EPHA7 among receptors bound by EFNA1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA1 entry) states it binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect and direction are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners carry secreted and transmembrane flags [flag]; the actual range is unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. Only a UniProt subunit sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002567","LR005835"]},"LR005843":{"pair":"EPHA8 -> EFNA4","headline":"Database-only pair: a single IntAct co-immunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EPHA8 is transmembrane-flagged; EFNA4 carries secreted and transmembrane flags [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. The IntAct record is an anti-tag coimmunoprecipitation [DB:IntAct EBI-54500804], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002575","LR005843"]},"LR002576":{"pair":"EPHA8 -> EFNA5","headline":"Database-only pair: IntAct co-immunoprecipitations and a UniProt interaction statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA5 entry) states it interacts with EPHA8 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct records are anti-tag coimmunoprecipitations [DB:IntAct EBI-21873799], [DB:IntAct EBI-54775381]; these do not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002576","LR005844"]},"LR002585":{"pair":"EPHB2 -> EFNA5","headline":"UniProt asserts an EPHB2-EFNA5 interaction, one entry only by similarity; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt EPHB2 entry states it interacts with EFNA5 (by similarity), and the EFNA5 entry states it binds EPHB2 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. The EPHB2 entry is marked by similarity, so it is not independent direct evidence. This is a cross-class (EphB receptor with ephrin-A) assertion; affinity not reported in our evidence.","key_references":[],"covers":["LR002585","LR005853"]},"LR005861":{"pair":"EPHB3 -> EFNB3","headline":"EPHB3-hFc binds EFNB3-expressing cells in one henipavirus paper where it served as an expression control; a BioGRID reconstituted complex also exists.","interaction_type":"direct binding","direction_and_effect":"Soluble EPHB3 (1,210-0.4 nM, fivefold dilution) stained cells expressing wild-type EFNB3 and an EFNB3-Y120F mutant to validate their expression [PMID:38426726]. No agonist or antagonist effect was reported.","molecular_requirements":"Not reported beyond the two partners.","affinity_potency":[],"species_and_systems":"Flow cytometry on cell lines expressing EFNB2 or EFNB3 with soluble human-Fc-tagged EPHB3; the species of the cell lines and of EPHB3 is not reported in our excerpts [PMID:38426726].","localisation_and_range":"Both partners transmembrane-flagged [flag]; binding was shown with soluble EPHB3-hFc to cell-surface ephrin [PMID:38426726].","caveats":"The paper's focus is Nipah virus use of EFNB3; EPHB3 binding is described as 'previously reported' and was used as a control; no EPHB3 Kd is reported in our excerpts. The Kd values in the excerpts (1.45 nM, 0.34 nM) are for a Hendra virus protein, not EPHB3. BioGRID lists a Reconstituted Complex [DB:BioGRID 287713]. Two papers were abstract-insufficient.","key_references":[{"PMID":"38426726","why":"Soluble EPHB3-hFc binding to EFNB2- and EFNB3-expressing cells, used as a validation control in a henipavirus study."}],"covers":["LR002593","LR005861"]},"LR005870":{"pair":"EPHB6 -> EPHA2","headline":"Receptor-receptor heterodimerisation of EPHB6 with EPHA2 in breast cancer cells, abstract only; not a classical ligand-receptor binding.","interaction_type":"functional only","direction_and_effect":"The paper reports that EPHB6, a kinase-deficient receptor, interacts with EPHA2 in mammalian cells (first A-type/B-type Eph heterodimer reported), and proposes that EPHB6 suppresses tumour invasiveness by sequestering kinase-sufficient oncogenic EPH receptors [PMID:21737611]. The curator labels this antagonist. EPHB6 does not interact with EPHA10 [PMID:21737611].","molecular_requirements":"Not reported beyond the two partners; EPHB6 is described as kinase-deficient [PMID:21737611].","affinity_potency":[],"species_and_systems":"Human breast carcinoma cell lines, mammalian cell co-expression; abstract only [PMID:21737611].","localisation_and_range":"EPHB6 carries secreted and transmembrane flags; EPHA2 is transmembrane-flagged [flag]. Heterodimerisation is within the membrane (cis or on the same cell); range is not reported.","caveats":"Abstract-only reading. This is a receptor-receptor association, so a ligand-to-receptor direction is not shown. The BioGRID record is Affinity Capture-Western [DB:BioGRID 3496524]. Direct physical binding is not distinguished from complex formation in our evidence.","key_references":[{"PMID":"21737611","why":"EPHB6 heterodimerises with EPHA2 in breast carcinoma cell lines."}],"covers":["LR002602","LR005870"]},"LR008372":{"pair":"EZR -> PDPN","headline":"No verified evidence for EZR as ligand to PDPN; UniProt describes an intracellular podoplanin-ezrin interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported as a ligand-receptor signal; UniProt records podoplanin interacting with ezrin via its cytoplasmic domain [DB:UniProt].","molecular_requirements":"Cytoplasmic-domain interaction with ezrin and moesin [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human UniProt entries.","localisation_and_range":"PDPN is flagged non-secreted and a receptor [flag].","caveats":"The only judged row is different_entity. The interaction is cytoskeletal adaptor binding, not extracellular ligand-receptor signalling.","key_references":[],"covers":["LR008372"]},"LR008309":{"pair":"F11R -> F11R","headline":"F11R/JAM-A homophilic interaction enhances platelet adhesion under flow; functional, abstract-level.","interaction_type":"functional only","direction_and_effect":"Interactions of F11R/JAM-A on flowing platelets with its surface-bound counterpart enhance platelet binding to fibrinogen under high shear stress [PMID:40132981]. Soluble form was shown elsewhere to activate platelets via homophilic interactions (background in abstract).","molecular_requirements":"Not reported in our evidence beyond homophilic dimer; Reactome lists F11R dimerisation [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human platelets, flow chamber assays [PMID:40132981]. IntAct solid phase record [DB:IntAct].","localisation_and_range":"Transmembrane, juxtacrine contact [flag].","caveats":"Abstract-only; three further rows were abstract_insufficient. Self-pair; no affinity.","key_references":[{"PMID":"40132981","why":"Platelet F11R/JAM-A homophilic interaction under flow"}],"covers":["LR008309"]},"LR009533":{"pair":"F2 -> GP9","headline":"Only a Reactome complex reaction links thrombin to GP9; no direct evidence.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists thrombin binding to GP1b:IX:V; the interaction is annotated as stimulatory [DB:Reactome R-HSA-429529].","molecular_requirements":"GP9 is a member of the GP1b:IX:V complex; direct thrombin binding to GP9 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entity; experimental system not reported in our evidence.","localisation_and_range":"GP9 annotated as a receptor [flag]; no further localisation data.","caveats":"Database assertion only; the one judged paper was about a different entity.","key_references":[],"covers":["LR009533"]},"LR007067":{"pair":"F2 -> THBD","headline":"Thrombin binds thrombomodulin directly and the complex acts as a cofactor; strong evidence.","interaction_type":"direct binding","direction_and_effect":"Thrombin binds thrombomodulin at anion binding exosite 1 [PMID:14691232]. The thrombin-thrombomodulin complex, rather than free thrombin, is the likely physiologic activator of TAFI [PMID:8663147]; UniProt describes thrombomodulin as a cofactor for thrombin activation of protein C [DB:UniProt P07204]. Annotation lists the effect as stimulatory.","molecular_requirements":"Binding is at thrombin exosite 1, competing with a monoclonal antibody [PMID:14691232]. In the TAFI reaction thrombin and thrombomodulin form a binary complex, then a ternary complex with TAFI [PMID:8663147].","affinity_potency":[{"value":"Kd = 8.6 nM","assay":"kinetic model of thrombin-thrombomodulin binding within TAFI activation","system":"purified plasma proteins","cite":"PMID:8663147"}],"species_and_systems":"Human proteins, purified [PMID:14691232] [PMID:8663147]. Structures [DB:PDB 1DX5] and SPR records exist [DB:IntAct].","localisation_and_range":"THBD is annotated transmembrane [flag]; Reactome places the complex at the plasma membrane [DB:Reactome R-HSA-141038].","caveats":"Both papers were abstract-only. The Biacore/ITC paper reports similar KDs for TM and antibody but the abstract gives no numeric KD [PMID:14691232]. The TAFI paper is functional and its Kd is a model parameter [PMID:8663147]. Thrombomodulin is a cofactor for thrombin enzymatic activity rather than a classical signalling receptor.","key_references":[{"PMID":"14691232","why":"Binding kinetics/thermodynamics of thrombin-thrombomodulin"},{"PMID":"8663147","why":"Thrombin-thrombomodulin complex activates TAFI; Kd 8.6 nM"}],"covers":["LR007067"]},"LR007436":{"pair":"FASLG -> TNFRSF6B","headline":"FASLG binds the soluble decoy receptor DcR3 (TNFRSF6B), which blocks FasL-induced apoptosis; supported by binding and database records.","interaction_type":"direct binding","direction_and_effect":"DcR3 is a soluble decoy that binds FasL and inhibits FasL-induced apoptosis [PMID:9872321]. UniProt describes TNFRSF6B as a decoy receptor that blocks apoptosis [DB:UniProt]. Other papers call DcR3 a receptor for FasL and LIGHT, acting as a decoy and also as an effector on dendritic cells [PMID:11994433] and inducing reverse signaling in monocytes [PMID:14697332].","molecular_requirements":"No subunit requirement reported; DcR3 is a single soluble chain with no transmembrane region [PMID:10318773].","affinity_potency":[],"species_and_systems":"TR6/DcR3-His selectively bound FasL-FLAG among soluble TNF ligands by immunoprecipitation [PMID:10318773]. Other work used human cells (monocytes, dendritic cells) [PMID:14697332] [PMID:11994433]. SPR record in IntAct and PDB 4MSV and 5L36 contain both chains [DB:IntAct] [DB:PDB 4MSV] [DB:PDB 5L36].","localisation_and_range":"DcR3 has no transmembrane region and is secreted [PMID:10318773]; the entity flags list it as not a receptor and not transmembrane [flag]. It acts as a soluble scavenger of FasL.","caveats":"Decoy role, not signaling receptor, for FasL. Two of the papers [PMID:14697332] [PMID:11994433] state binding only as background in the abstract. One review-only row not used. Affinity not reported in our evidence.","key_references":[{"PMID":"9872321","why":"Discovery of DcR3 binding FasL and inhibiting apoptosis."},{"PMID":"10318773","why":"Immunoprecipitation: TR6/DcR3 binds FasL and LIGHT."}],"covers":["LR007436"]},"LR008291":{"pair":"FCER2 -> CDH2","headline":"No paper evidence; only one IntAct record (SPR) supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond an IntAct SPR entry [DB:IntAct P06734-P19022].","localisation_and_range":"CD23 is flagged secreted and transmembrane; CDH2 is flagged transmembrane [flag].","caveats":"Supported by a single IntAct record (SPR, cited to PMID 35922511) with no curator-verified paper; one judged paper was abstract-insufficient. Likely a high-throughput screen hit; treat as unvalidated.","key_references":[],"covers":["LR008291"]},"LR000569":{"pair":"FGA -> ITGB1","headline":"Fibrinogen binds purified alpha5beta1 (beta1 chain pairing); one abstract-level solid-phase paper.","interaction_type":"direct binding","direction_and_effect":"Fibrinogen bound purified alpha5beta1 specifically and saturably with Mn2+, blocked by RGD peptides and anti-alpha5beta1 antibodies [PMID:11011154].","molecular_requirements":"Evidence is for alpha5beta1; ITGB1 is paired with ITGA5, and other beta1 integrins are not tested. The Aalpha572-574 RGD is required [PMID:11011154].","affinity_potency":[],"species_and_systems":"Human proteins (curator fields), purified solid-phase.","localisation_and_range":"FGA flagged secreted; ITGB1 not secreted [flag].","caveats":"Abstract only; no affinity. Chain-only attribution to beta1.","key_references":[{"PMID":"11011154","why":"fibrinogen-alpha5beta1 binding"}],"covers":["LR000569"]},"LR005168":{"pair":"FGF1 -> CSPG4","headline":"Cell-surface FGF1 interaction with CSPG4 from one abstract-read proximity-labelling study; proposed as a reservoir.","interaction_type":"direct binding","direction_and_effect":"An APEX2-FGF1 proximity-labelling screen in RPE1 cells identified CSPG4 (NG2) and CD44 as FGF1 interactors, co-localized with FGF1 at the cell surface [PMID:29812912]. They are proposed as storage molecules forming an FGF1 reservoir rather than direct signalling receptors [PMID:29812912].","molecular_requirements":"Not reported in our evidence beyond FGF1's heparin-binding moiety being implicated for the companion CD44 interaction [PMID:29812912].","affinity_potency":[],"species_and_systems":"Human FGF1 and human RPE1 cells [PMID:29812912]. Mouse record is ortholog-inferred.","localisation_and_range":"CSPG4 is flagged secreted, receptor and transmembrane [flag]; the paper describes cell-surface localisation [PMID:29812912].","caveats":"Abstract only; proximity labelling is indirect and no affinity is reported. Shared paper with the CD44 pair. No database records.","key_references":[{"PMID":"29812912","why":"Proximity labelling identifies CSPG4 and CD44 as FGF1 interactors"}],"covers":["LR001813","LR005168"]},"LR004079":{"pair":"FGF1 -> FGFR2","headline":"Well-supported direct FGF1-FGFR2 binding shown by crystal structures and functional assays in human proteins.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show a complex of human FGF1 with a two-domain extracellular fragment of human FGFR2, and a dimeric FGFR2 ectodomain induced by FGF1 plus a heparin decasaccharide [PMID:10618369][PMID:11069186]. FGF1 is stated to activate all FGFRs in BaF3 assays [PMID:16597617], and full-length FGF1 stimulated FGFR2 phosphorylation more than truncated FGF1 [PMID:14732692].","molecular_requirements":"Structure is a 1:1 FGF1:FGFR2 complex arranged as a dimer [PMID:10618369]; heparin bridges two FGF1 and two receptor chains in the ternary assembly [PMID:11069186].","affinity_potency":[],"species_and_systems":"Human FGF1 and human FGFR2 fragments (crystallography) [PMID:10618369]; FGFR2 phosphorylation in RCS cells [PMID:14732692]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 secreted and FGFR2 transmembrane receptor [flag].","caveats":"Two papers were browser-read with quotes pending spot-check [PMID:16597617][PMID:14732692]. No affinity values in our evidence. Two review-only papers were also judged. Database records include PDB [DB:PDB 1DJS], BioGRID, IntAct and Reactome [DB:Reactome R-HSA-8853189].","key_references":[{"PMID":"10618369","why":"Crystal structure of human FGF1 with FGFR2 fragment"},{"PMID":"11069186","why":"FGF1-FGFR2-heparin ternary structure"},{"PMID":"14732692","why":"FGF1 forms and FGFR2 phosphorylation"}],"covers":["LR000595","LR004079"]},"LR000596":{"pair":"FGF1 -> FGFR3","headline":"Well-supported direct FGF1-FGFR3 binding, with crystal structure, binding and signalling data in human proteins.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of three-Ig FGFR3c in complex with FGF1 is reported, with FGF1 described as binding promiscuously to each of the seven principal FGFRs [PMID:14732692]. FGF1 binds FGFR3c more strongly than FGF2 but gives lower activation-loop phosphorylation [PMID:21894939]. FGF1 is the agonist in these assays.","molecular_requirements":"The D1 domain and D1-D2 linker are dispensable for binding, and the three-Ig form shows lower affinity for FGF1 and heparin than the two-Ig form [PMID:14732692]. Ternary complexes with FGF1 and FGFR3c form with perlecan heparan sulfate [PMID:24509440].","affinity_potency":[],"species_and_systems":"Human FGF1 and FGFR3 in recombinant structure [PMID:14732692]; HEK 293T cells [PMID:21894939]; ternary-complex assay [PMID:24509440]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 secreted; FGFR3 transmembrane receptor [flag].","caveats":"Numerical affinities are not given in our evidence. Two of the papers were abstract level [PMID:14732692]. A BaF3 paper was browser-read with quote pending spot-check [PMID:16597617]. Two review-only papers were judged. Database: PDB [DB:PDB 1RY7], BioGRID, IntAct.","key_references":[{"PMID":"14732692","why":"Crystal structure of FGFR3c with FGF1"},{"PMID":"21894939","why":"FGF1 versus FGF2 binding and phosphorylation at FGFR3c"},{"PMID":"24509440","why":"Heparan-sulfate-dependent FGF1-FGFR3c ternary complexes"}],"covers":["LR000596","LR004080"]},"LR000578":{"pair":"FGF16 -> FGFR3","headline":"FGF16 shows activity toward FGFR3b-expressing cells and FGFRc isoforms in a BaF3 panel; functional evidence only.","interaction_type":"functional only","direction_and_effect":"These FGFs activated FGFRc isoforms and FGFR4 with high activity and, unlike other FGFs, consistently showed activity toward FGFR3b-expressing cells [PMID:16597617]. Agonist.","molecular_requirements":"Isoform matters: the paper notes activity on both c forms and FGFR3b [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR3 a membrane receptor [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 panel including FGFR3b"}],"covers":["LR000578","LR004062"]},"LR000587":{"pair":"FGF18 -> FGFR4","headline":"FGF18 activates the two-Ig-domain FGFR4 in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 activated the two Ig-like domain forms of FGFR4 (4delta) [PMID:16597617]. Agonist.","molecular_requirements":"The active form is the two Ig-like domain FGFR4 variant [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4 delta"}],"covers":["LR000587","LR004071"]},"LR004097":{"pair":"FGF2 -> GPC4","headline":"Recombinant glypican-4 binds FGF2 through heparan sulfate chains and dampens FGF2 mitogenesis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant glypican-4 binds FGF2 and suppressed the mitogenic effect of FGF2 on E13 cortical precursor cells, so it acts as an inhibitory modulator rather than a signal-transducing receptor [PMID:11066092]. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","molecular_requirements":"Binding is via glypican-4's heparan sulfate chains [PMID:11066092]. Whether the core protein contributes, or whether FGF receptors are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"FGF2 and glypican-4 expression were studied in rat E13 cortical precursor cultures and developing mouse brain [PMID:11066092]. Human and mouse pairs are ortholog-inferred, not tested directly.","localisation_and_range":"Glypican-4 is described as a GPI-anchored cell-surface proteoglycan, so it is membrane-tethered (juxtacrine/contact) [PMID:11066092]; the entity flags list it as secreted [flag].","caveats":"Single paper, read as abstract only. Its effect is inhibitory, so this is a modulator/co-receptor-type pair, not classical agonism. Affinity not reported.","key_references":[{"PMID":"11066092","why":"Recombinant GPC4 binds FGF2 via HS chains and suppresses FGF2 mitogenic effect"}],"covers":["LR000613","LR004097"]},"LR004088":{"pair":"FGF23 -> FGFR2","headline":"FGF23 binds FGFR2c in several studies (SPR, mitogenesis, cell binding); functional and binding evidence.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates c isoforms of FGFR1-3 and FGFR4 but not b isoforms [PMID:16081635, PMID:16597617]. A separate study reports FGF-23 binding FGFR-2c but not FGFR-1c (data not shown) [PMID:12032146].","molecular_requirements":"c splice forms required; highly sulfated GAGs promote activity [PMID:16081635].","affinity_potency":[],"species_and_systems":"Human reagents per curators [PMID:16081635]; the 2002 binding result is a receptor extracellular domain assay with species not stated [PMID:12032146].","localisation_and_range":"Not reported beyond flags; FGF23 secreted [flag].","caveats":"The FGFR2 binding sentence in PMID 12032146 is 'data not shown'; it also contradicts FGFR1c binding reported elsewhere [PMID:12032146, PMID:16081635]. PMID 16081635 read as abstract only.","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis for FGF23 on c isoforms"},{"PMID":"12032146","why":"FGF-23 binds FGFR-2c"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000604","LR004088"]},"LR005177":{"pair":"FGF4 -> FGFRL1","headline":"FGF4 binds FGFRL1 with high affinity; FGFRL1 acts as a decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF4 (among FGF2, FGF3, FGF8, FGF10, FGF22), and FGFRL1 expressed in Xenopus embryos antagonised FGFR signalling, supporting a decoy role [PMID:19920134].","molecular_requirements":"FGFRL1 has an FGFR-like extracellular domain but lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. Heparin dependence is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding shown by ligand dot blot, cell-based binding and surface plasmon resonance; shed ectodomain from C2C12 myoblasts and HEK293 cells; antagonism tested in Xenopus embryos [PMID:19920134]. Mouse pair is projected from human.","localisation_and_range":"FGFRL1 ectodomain is shed from the cell membrane by an unidentified protease, so both soluble and membrane-bound forms exist [PMID:19920134]. FGF4 is flagged secreted [flag].","caveats":"Abstract-only reading. The abstract gives \"high affinity\" without a number; no Kd is reported in our evidence. Binding is not resolved per ligand in the abstract.","key_references":[{"PMID":"19920134","why":"Shows FGFRL1 shedding, FGF binding (incl. FGF4) and antagonism of FGFR signalling"}],"covers":["LR001822","LR005177"]},"LR002639":{"pair":"FGG -> ITGAM","headline":"Eosinophil adhesion to fibrinogen depends on alphaMbeta2; one functional paper only.","interaction_type":"functional only","direction_and_effect":"Airway eosinophil adhesion to fibrinogen was alphaMbeta2-mediated and blocked by anti-alphaMbeta2 [PMID:16601240].","molecular_requirements":"The receptor is the alphaMbeta2 (ITGAM:ITGB2) heterodimer; the ligand assayed was whole fibrinogen, not the gamma chain alone [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils from airway and blood (organism not stated in the dossier abstract) [PMID:16601240]. The mouse pair is ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"One paper, abstract only, adhesion not direct binding. Chain-level assignment to FGG is by this resource's encoding. No database records.","key_references":[{"PMID":"16601240","why":"Eosinophil adhesion to fibrinogen via alphaMbeta2"}],"covers":["LR002639","LR005905"]},"LR005906":{"pair":"FGG -> ITGB3","headline":"Fibrinogen gamma chain binds alphaIIbbeta3 (beta3 chain) by structure and binding assays; alphaVbeta3 also reported.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the gammaC peptide bound to alphaIIbbeta3, with the MIDAS ion on beta3 binding the gammaC Asp [PMID:18710925]. RGD binding activates high-affinity fibrinogen binding [PMID:2018974]. Fibrinogen bound activated alphaIIbbeta3 on murine platelets [PMID:23551977]. Fibrinogen was recognised by alphaVbeta3 and alphaIIbbeta3 [PMID:15031111].","molecular_requirements":"Binding needs the alpha/beta heterodimer; beta3 alone is not tested by these papers as the full receptor. Chain-level separation of fibrinogen is not made in [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human structures and platelets [PMID:18710925][PMID:2018974]; mouse platelets in vivo [PMID:23551977]; human fibrinogen on mouse trophoblasts [PMID:15031111].","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"Several papers abstract-only. PDB 2VDO-2VDR [DB:PDB 2VDO], IntAct ELISA and BioGRID records support binding [DB:IntAct][DB:BioGRID].","key_references":[{"PMID":"18710925","why":"Structure of alphaIIbbeta3 with fibrinogen gammaC peptide"},{"PMID":"23551977","why":"Fibrinogen-bound alphaIIbbeta3 on mouse platelets in vivo"},{"PMID":"2018974","why":"RGD activation of fibrinogen binding"}],"covers":["LR002640","LR005906"]},"LR002648":{"pair":"FLRT2 -> ADGRL2","headline":"FLRT2 acts on LPHN2 (ADGRL2) in endothelial cells, but evidence is functional and from an abstract-level read.","interaction_type":"functional only","direction_and_effect":"In human endothelial cells, silencing endogenous FLRT2 increased ECM-elicited migration, and recombinant FLRT2 reduced it, with no response when LPHN2 was silenced; FLRT2 loss lowered cAMP and active Rap1 [PMID:34581723]. The paper describes FLRT2-activated LPHN2 inhibiting YAP/TAZ and focal adhesions [PMID:34581723]; the curated row labels it antagonist.","molecular_requirements":"A mouse Lphn2 lacking the olfactomedin domain (dOLF) did not rescue the phenotype, and is described as not binding FLRT2, so the OLF domain is required [PMID:34581723]. Uncleaved FLRT2 may also act in cell-cell contacts [PMID:34581723].","affinity_potency":[],"species_and_systems":"Human endothelial cells (siRNA, recombinant rhFLRT2), mouse Lphn2 constructs, and lphn2a-knockout zebrafish [PMID:34581723]. Pair listed for human and mouse (mouse ortholog-inferred).","localisation_and_range":"FLRT2 is flagged secreted and transmembrane [flag]; the paper describes autocrine/paracrine signalling and a soluble ~75 kD recombinant FLRT2 form [PMID:34581723].","caveats":"No direct binding measurement is shown in the excerpts; the OLF-mutant is said not to bind FLRT2. Curated read depth was abstract only.","key_references":[{"PMID":"34581723","why":"Endothelial FLRT2-LPHN2 signalling via OLF domain; siRNA, recombinant protein, zebrafish."}],"covers":["LR002648","LR005914"]},"LR005915":{"pair":"FLRT2 -> ADGRL3","headline":"Well supported direct binding of FLRT2 to LPHN3 (ADGRL3), with a measured Kd and crystallographic and cell-based studies.","interaction_type":"direct binding","direction_and_effect":"FLRT proteins were identified as endogenous latrophilin ligands; ecto-LPHN3-Fc bound strongly to FLRT1 and FLRT2 on cells [PMID:22405201]. FLRT2-LPHN3 drives adhesion of HeLa cells in stripe assays, while cortical neurons expressing endogenous FLRTs are repelled by LPHN3 [PMID:25728924]. Unc5D in cis switches FLRT2-dependent adhesion to Lphn3 [PMID:27091502].","molecular_requirements":"FLRT2 and LPHN3 ectodomains suffice for binding (SPR); the LPHN3 Olf domain carries the FLRT-binding site [PMID:25728924]. FLRT2 can bind Lphn3 and Unc5D simultaneously in a ternary complex, 1:1:2 FLRT2:Unc5D:Lphn3 [PMID:27091502].","affinity_potency":[{"value":"Kd 18\u201340 nM","assay":"Surface plasmon resonance, FLRT2 with LPHN3 Lec-Olf","system":"Purified recombinant proteins","cite":"PMID:25728924"}],"species_and_systems":"Binding studies used purified proteins and cells; the curated rows list human, while paper text refers to mouse Lphn3/FLRT2 and rat Unc5D [PMID:27091502, PMID:25728924]. Mouse pair is listed as not ortholog-inferred.","localisation_and_range":"Both partners carry transmembrane flags [flag]; the interaction occurs in trans between adjacent cells [PMID:22405201].","caveats":"Outcome counts also include abstract_insufficient, review_only and pending rows not shown. Effect depends on context (adhesion vs repulsion; Unc5D in cis) [PMID:25728924, PMID:27091502].","key_references":[{"PMID":"25728924","why":"SPR Kd for FLRT2-LPHN3 and structural basis."},{"PMID":"22405201","why":"FLRTs identified as latrophilin ligands; FLRT2 binds LPHN3."},{"PMID":"27091502","why":"FLRT2:Unc5D:Lphn3 ternary complex."}],"covers":["LR002649","LR005915"]},"LR002657":{"pair":"FLRT3 -> ADGRL3","headline":"FLRT3 binds latrophilin-3 (ADGRL3) with high affinity in trans; well supported by binding, structure and function.","interaction_type":"direct binding","direction_and_effect":"FLRT3 and LPHN3 ectodomains interact with high affinity in trans; blocking with soluble LPHN3, or LPHN3 or FLRT3 shRNA, reduced excitatory synapse density in cultured neurons, and FLRT3 shRNA in vivo decreased afferent input strength and dendritic spine number in dentate granule cells [PMID:22405201]. An antibody (LK30) agonist of ADGRL3 broke the ADGRL3-teneurin interaction but not ADGRL3-FLRT3 [PMID:36746957].","molecular_requirements":"FLRT3 and ADGRL3 form a complex that also takes UNC5B or UNC5D [DB:UniProt]. LK30 binds ADGRL3 without displacing FLRT3, forming a trimeric FLRT3/ADGRL3/LK30 complex on SEC [PMID:36746957]. FLRT3 binding is via the Olf domain [PMID:36746957].","affinity_potency":[],"species_and_systems":"Rat brain extract, HEK293 cells, cultured neurons and mass spectrometry [PMID:22405201]; the 2016 structural paper mentions Lphn3 binds FLRT3 as background [PMID:27091502]; HEK293T and purified proteins [PMID:36746957]. Dossier covers human and mouse.","localisation_and_range":"FLRT3 annotated secreted and transmembrane, ADGRL3 transmembrane [flag]; interaction shown in trans between cells [PMID:22405201]. UniProt describes cell-cell adhesion via ADGRL3 on adjacent cells [DB:UniProt].","caveats":"No affinity value in our evidence. The 2016 sentence is a passing statement, not a new test [PMID:27091502]. Four further papers were abstract-insufficient, two review-only, one pending. Database records: PDB 5CMN structure [DB:PDB 5CMN], IntAct x-ray crystallography [DB:IntAct].","key_references":[{"PMID":"22405201","why":"FLRTs identified as latrophilin ligands; high-affinity trans interaction and synapse effects"},{"PMID":"36746957","why":"FLRT3 binding retained when teneurin binding is blocked"},{"PMID":"27091502","why":"Structural context of FLRT/Lphn3 complexes"}],"covers":["LR002657","LR005923"]},"LR005924":{"pair":"FLRT3 -> FLRT3","headline":"FLRT3 interacts homophilically, shown by cell aggregation and structure-guided mutants; the pair is FLRT3 with itself.","interaction_type":"direct binding","direction_and_effect":"FLRT3-FLRT3 homophilic interactions regulate their tangential distribution, and FLRT-transfected cells sort from non-transfected cells, suggesting altered adhesion [PMID:25374360][PMID:16440004]. FLRT proteins can physically interact [PMID:16440004]. Signalling direction is not applicable to a homophilic adhesion; effect not reported beyond adhesion.","molecular_requirements":"Homophilic binding uses a surface distinct from the Unc5-binding surface; separate mutants block FLRT-FLRT (FLRTFF) and FLRT-Unc5 (UF) binding [PMID:25374360]. Complexes of FLRT3, ADGRL3 and UNC5B/UNC5D are noted [DB:UniProt].","affinity_potency":[],"species_and_systems":"Cloned mouse Flrt3 in cell-aggregation, mutagenesis and neuron repulsion assays [PMID:25374360]; the 2006 paper used FLRT-transfected cultured cells with species unspecified (abstract only) [PMID:16440004].","localisation_and_range":"FLRT3 annotated secreted and transmembrane [flag]; adhesion is by cell-surface contact [PMID:25374360].","caveats":"The human pair is ortholog-inferred from mouse. The 2006 evidence is functional (cell sorting) and read as abstract only [PMID:16440004]. No affinity reported. IntAct lists a molecular sieving record [DB:IntAct].","key_references":[{"PMID":"25374360","why":"FLRT3 homophilic adhesion and structural basis"},{"PMID":"16440004","why":"FLRTs interact and drive cell sorting"}],"covers":["LR002658","LR005924"]},"LR000659":{"pair":"FN1 -> ITGA4","headline":"Fibronectin is reported as a ligand of the alpha4 integrin via CS-1, but both papers study alpha4beta1 and are abstract-level.","interaction_type":"functional only","direction_and_effect":"The fibronectin CS-1 peptide costimulated T-cell proliferation exclusively through alpha4beta1 and not alpha4beta7 [PMID:9842903]. CS-1 and Hep II fibronectin ligands triggered different intracellular events and migration in B lymphoid cells [PMID:9117345]. Agonist/adhesion.","molecular_requirements":"Both papers refer to the alpha4beta1 dimer, so alpha4 alone is not tested. Alpha4beta7 did not mediate costimulation by CS-1 [PMID:9842903].","affinity_potency":[],"species_and_systems":"T cells and B lymphoid cells in vitro; species not stated in our evidence; mouse pair is orthology-inferred.","localisation_and_range":"FN1 flagged secreted; matrix-to-cell contact is inferred from flags [flag].","caveats":"No direct binding assay is in the shown evidence; IntAct has one FACS record [DB:IntAct]. 2 more papers were abstract-insufficient.","key_references":[{"PMID":"9842903","why":"CS-1 costimulates T cells through alpha4beta1"},{"PMID":"9117345","why":"alpha4beta1 binding to CS-1/Hep II induces migration and signalling"}],"covers":["LR000659","LR004143"]},"LR000668":{"pair":"FN1 -> ITGB8","headline":"Beta8-containing integrins mediate chick neuron interaction with fibronectin; functional evidence only, in chick.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 antibody inhibited sensory neurite outgrowth on fibronectin-coated substrata; antibodies to beta1 and beta8 were completely effective only in combination on the C-terminal 40-kDa fibronectin fragment [PMID:7542940].","molecular_requirements":"Beta8 acts with one or more unidentified alpha subunits; beta1 also contributes [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick embryonic sensory neurons; human and mouse pairs are inferred by homology [PMID:7542940].","localisation_and_range":"Fibronectin flagged secreted [flag]; matrix substrate, inferred from the assay.","caveats":"Antibody blocking, no direct binding, no affinity. Abstract only. The paper is per beta8 subunit; the binding entity is an alpha/beta heterodimer.","key_references":[{"PMID":"7542940","why":"First ligands for beta8 integrins incl. fibronectin"}],"covers":["LR000668","LR004152"]},"LR002666":{"pair":"FSTL1 -> CD14","headline":"FSTL1 interacts with CD14 and activates TLR4-dependent innate responses in human cells.","interaction_type":"direct binding","direction_and_effect":"Recombinant FSTL1 induced IL-6 or IL-8 in a CD14- and TLR4-dependent manner and induced tolerance to a second LPS stimulation; it acts as an endogenous TLR4 agonist [PMID:22265692]. Agonist.","molecular_requirements":"CD14 acts as a co-receptor for TLR4 signalling [PMID:22265692]; TLR4 is required [PMID:22265692].","affinity_potency":[],"species_and_systems":"Human cells with recombinant FSTL1 [PMID:22265692]; mouse pair inferred. IntAct lists SPR and FACS assays [DB:IntAct].","localisation_and_range":"Both entities flagged secreted [flag]; CD14 flagged receptor [flag].","caveats":"The binding itself is described as from a previous study (background); this paper adds functional evidence. Abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"22265692","why":"FSTL1 evokes TLR4 responses via CD14"}],"covers":["LR002666","LR005932"]},"LR005933":{"pair":"FSTL1 -> FZD4","headline":"FSTL1 binds FZD4 directly in human-protein pull-downs and enhances Wnt3a-FZD4 association; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"FSTL1 interacted with FZD4 through its EC domain and increased Wnt3a association with FZD4, promoting Wnt/beta-catenin signalling (agonist/enhancer) [PMID:35525270].","molecular_requirements":"The EC domain of FSTL1 is the FZD4-binding part; the VWC and FS domains did not bind FZD4. FSTL1 did not interact with the coreceptor LRP6 alone, but LRP6 pulled down FSTL1 in the presence of FZD4, so FSTL1, FZD4 and LRP6 formed a complex [PMID:35525270].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in HEK293T cells and a pull-down with recombinant FSTL1 and FZD4-Fc supported a direct interaction; the experiments used human proteins. The mouse pair is projected from human evidence; kidney fibrosis experiments were in mouse obstructed kidneys [PMID:35525270].","localisation_and_range":"FSTL1 is flagged as secreted [flag]; FZD4 is flagged as a receptor [flag].","caveats":"Only one paper; no affinity reported in our evidence. FSTL1 also bound Wnt3a, so the effect may depend on the Wnt ligand present. FSTL1 also co-precipitated with FZD5, so the binding is not specific to FZD4 [PMID:35525270].","key_references":[{"PMID":"35525270","why":"Co-IP and recombinant pull-down showing direct FSTL1-FZD4 binding via the EC domain"}],"covers":["LR002667","LR005933"]},"LR000677":{"pair":"GAL -> GALR2","headline":"Galanin binds and activates GALR2 with sub-nanomolar to nanomolar affinity in human receptor assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Galanin is a full agonist: human GALR2 signals mainly via phosphatidylinositol hydrolysis and calcium mobilisation [PMID:9880084], and GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. hGALR2 tolerates N-terminal extension and C-terminal deletion of galanin [PMID:9880084]. Amino-terminal galanin fragments displace binding; carboxy-terminal fragments do not [PMID:9685625].","affinity_potency":[{"value":"Ki 0.86 +/- 0.12 nM","assay":"125I-galanin competition binding","system":"human GalR2","cite":"PMID:9480833"},{"value":"K(D) = 0.3 nM","assay":"125I-galanin radioligand binding","system":"recombinant human GALR2","cite":"PMID:9832121"},{"value":"<10 nM","assay":"binding affinity","system":"CHO cells overexpressing hGalR2","cite":"PMID:11600206"}],"species_and_systems":"Experiments used human GALR2 in HEK-293 and CHO cells, plus a cloned mouse GalR2 shown to be functional [PMID:9832122]. The mouse pair is projected from human evidence.","localisation_and_range":"GAL is flagged as secreted and GALR2 as a transmembrane receptor [flag].","caveats":"All papers were read as abstracts only. [PMID:24517231] is mainly about spexin activating GALR2/3.","key_references":[{"PMID":"9480833","why":"Cloning of human GALR2 with Ki 0.86 nM galanin binding"},{"PMID":"9832121","why":"Kd 0.3 nM binding and PLC/calcium coupling of human GALR2"},{"PMID":"9880084","why":"Functional signalling of human GALR2 via phosphoinositide hydrolysis"}],"covers":["LR000677","LR004161"]},"LR004169":{"pair":"GCG -> GLP2R","headline":"The proglucagon product GLP-2 is a high-affinity GLP2R agonist; evidence concerns GLP-2, not glucagon itself.","interaction_type":"direct binding","direction_and_effect":"GLP-2 raised cAMP in GLP-2R-expressing cells, but GLP-1 and related peptides did not [PMID:9990065]. GLP-2(3-33) bound with 7.5% of the affinity of GLP-2(1-33) and was a weak partial agonist that shifted the GLP-2(1-33) dose-response to the right [PMID:11738243]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[{"value":"Kd 0.57 nM","assay":"saturable radioligand binding","system":"cells expressing GLP-2R","cite":"PMID:9990065"},{"value":"EC50 0.58 nM","assay":"cAMP production","system":"cells expressing GLP-2R","cite":"PMID:9990065"},{"value":"Ki 0.06 nM","assay":"displacement by synthetic rat GLP-2","system":"cells expressing GLP-2R","cite":"PMID:9990065"}],"species_and_systems":"Cloned rat and human GLP-2R [PMID:9990065]; transfected human receptor in vitro and mice in vivo [PMID:11738243]. The mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GLP2R transmembrane [flag]. Reactome lists GLP2R with GCG(146-178) [DB:Reactome].","caveats":"Abstract-only. The ligand is the GLP-2 peptide from proglucagon, not glucagon; glucagon activity at GLP2R is not shown. One paper is pending.","key_references":[{"PMID":"9990065","why":"Cloning of GLP-2R with Kd, EC50 and Ki"},{"PMID":"11738243","why":"GLP-2(3-33) binding and activity at human GLP-2R"}],"covers":["LR000685","LR004169"]},"LR008273":{"pair":"GDF1 -> ACVR1C:ACVR2A","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at the ACVR1C and ACVR2A subunits (listed separately) [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. Two papers were review-only and four abstract-insufficient. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR008273"]},"LR000686":{"pair":"GDF10 -> ACVR1B","headline":"Functional evidence only: GDF10 (BMP-3b) activity needs ALK-4 with ActRIIA in mouse C2C12 cells; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"BMP-3b (GDF10) stimulated activin/TGF-beta-responsive promoters and directly activated Smad2/3 phosphorylation and PAI-1 expression, while failing to activate Smad1/5/8; it also suppressed BMP-2-induced osteoblast markers [PMID:22155034]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"Receptor-construct inhibition indicated activity was facilitated by the combination of ALK-4 and ActRIIA, not ALK-2/-3/-6 [PMID:22155034]; ALK-4 alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Mouse myoblastic C2C12 cells in the abstract [PMID:22155034]; the human and mouse pairs are both ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"Evidence is a single paper read as an abstract only (the abstract is cut off); no binding assay or affinity. The curator-assigned effect 'antagonist' reflects antagonism of BMP-2 signalling, whereas the paper reports GDF10 activating Smad2/3.","key_references":[{"PMID":"22155034","why":"BMP-3b signalling via ALK-4/ActRIIA and Smad2/3 in C2C12 cells"}],"covers":["LR000686","LR004170"]},"LR010748":{"pair":"GDF10 -> ACVR1B:ACVR2A","headline":"Database-asserted only: GtoPdb lists GDF10 as agonist at both chains; no verified paper evidence for this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records GDF10 as agonist for ACVR1B and for ACVR2A separately [DB:GtoPdb].","molecular_requirements":"Complex of ACVR1B and ACVR2A; each chain is only asserted individually in the database [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species of experiments not reported in our evidence.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"No judged papers; two other papers were review-only or had insufficient abstracts, so nothing verified. Affinity not reported.","key_references":[],"covers":["LR010748"]},"LR005942":{"pair":"GDF10 -> BMPR1A","headline":"GDF10 binds a BMPR2/ALK3 receptor pair in mouse hepatic stellate cells; ALK3 alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"Autocrine GDF10 binds BMPR2/ALK3 to elicit SMAD1/5/8-SMAD7 signalling, which inhibits TGF-beta-SMAD2/3 signalling and suppresses stellate-cell activation [PMID:40125634]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"GDF10-Fc bound HEK293 cells overexpressing both Bmpr2 and Alk3 better than other single receptors or pairs; SPR showed dose-dependent binding to a BMPR2:ALK3-Fc heterodimer; knockdown of Bmpr2 and/or Alk3 abolished the effect [PMID:40125634]. ALK3 is therefore paired with BMPR2.","affinity_potency":[],"species_and_systems":"Primary mouse hepatic stellate cells, HEK293 transfectants and mouse receptor ectodomains; mouse and human liver expression [PMID:40125634].","localisation_and_range":"GDF10 is flagged secreted [flag]; the paper describes an autocrine loop in hepatic stellate cells [PMID:40125634].","caveats":"Single paper; binding to ALK3 alone is not separated from the BMPR2:ALK3 heterodimer. The paper words the receptor as 'potential'. No affinity number in our evidence. Human and mouse pairs are ortholog-inferred.","key_references":[{"PMID":"40125634","why":"BMPR2/ALK3 binding and signalling of GDF10 in stellate cells"}],"covers":["LR002677","LR005942"]},"LR010793":{"pair":"GDF10 -> BMPR2","headline":"GDF10 binds BMPR2 in mouse hepatic stellate cell work, with highest binding when ALK3 is co-expressed.","interaction_type":"direct binding","direction_and_effect":"GDF10 bound BMPR2 with higher affinity than other receptors tested, and drives SMAD1/5/8-SMAD7 signalling that inhibits stellate-cell activation [PMID:40125634]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"BMPR2 is a type II receptor; binding was higher with Bmpr2 plus Alk3 co-expressed, SPR used a BMPR2:ALK3-Fc heterodimer, and the effect depended on both Bmpr2 and Alk3 [PMID:40125634].","affinity_potency":[],"species_and_systems":"Primary mouse hepatic stellate cells, HEK293 cells, mouse ectodomains [PMID:40125634].","localisation_and_range":"GDF10 flagged secreted [flag]; autocrine in stellate cells [PMID:40125634].","caveats":"Single paper; no numeric affinity in our evidence (the quoted 'higher affinity' is a cell-binding comparison). Functional rescue is for the BMPR2/ALK3 pair, not BMPR2 alone.","key_references":[{"PMID":"40125634","why":"GDF10 binds BMPR2/ALK3 and signals through SMAD1/5/8-SMAD7"}],"covers":["LR010793"]},"LR004178":{"pair":"GDF2 -> BMPR2","headline":"BMP9 binds the type-II receptor BMPRII, with measured affinity, and needs it for signalling in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists agonist [DB:GtoPdb]. BMPR-II and ACTR-IIA were both required for the response in endothelial cells [PMID:28646109]. The BMP-9 pro-region complex bound strongly to ALK-1 and BMPR-II by BIAcore [PMID:15851468].","molecular_requirements":"Type-II receptor partnered with a type-I receptor: ALK1 predominantly in endothelial cells, ALK2 in myoblasts [PMID:17311849]; ALK2 was the key type-I receptor for monocyte recruitment [PMID:28646109].","affinity_potency":[{"value":"KD 627.6 pm","assay":"SPR binding of BMP9 to BMPRII ECD","system":"recombinant proteins","cite":"PMID:22718755"},{"value":"KD of 21.6 pm","assay":"SPR binding of BMP9 to ActRIIB (comparator)","system":"recombinant proteins","cite":"PMID:22718755"}],"species_and_systems":"Recombinant SPR [PMID:22718755][PMID:15851468]; transfected COS cells [PMID:17311849]; human endothelial cells [PMID:28646109]. Mouse pair projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"BMPRII binding alone is weak in COS cells [PMID:17311849] and about 30-fold weaker than ActRIIB [PMID:22718755]. Two binding sentences are unverified browser reads [PMID:15851468][PMID:22718755]; the 28646109 row is abstract only.","key_references":[{"PMID":"22718755","why":"SPR KD for BMP9-BMPRII versus ActRIIB"},{"PMID":"15851468","why":"BIAcore: pro-region complex binds BMPR-II"},{"PMID":"17311849","why":"Weak BMP-9 binding to BMPR-II in COS cells"}],"covers":["LR000694","LR004178"]},"LR000695":{"pair":"GDF2 -> ENG","headline":"BMP9 (GDF2) binds the endoglin ectodomain directly; crystal structure, SPR and BLI data support a co-receptor/decoy role.","interaction_type":"direct binding","direction_and_effect":"Structural work shows BMP9 binding to the ENG orphan domain, described as compatible with type I but not type II receptor recognition [PMID:28564608]. Membrane ENG is a co-receptor and BMP9 is labelled agonist at the receptor level [PMID:17311849]. Soluble ENG ECD-Fc acts as an antagonist/decoy that reduced VEGF-induced vessel formation and tumour burden [PMID:21737454].","molecular_requirements":"BMP9 contacts a hydrophobic groove of ENG orphan domain 1 (OR1); OR2 alone does not bind, and point mutants (Q270A/I271A, S278P, F282V) abolished binding [PMID:28564608]. Two ENG copies embrace homodimeric BMP9 (2:2 heterotetramer) [PMID:28564608][DB:UniProt]. ENG and type II receptors bind overlapping sites on BMP9 [PMID:21737454].","affinity_potency":[{"value":"KD 9.81 \u00d7 10\u22129 M (ENG ectodomain); 2.95 \u00d7 10\u22127 M (OR); 1.79 \u00d7 10\u22127 M (MOR)","assay":"biolayer interferometry (BLI)","system":"recombinant human ENG constructs with BMP9","cite":"PMID:28564608"}],"species_and_systems":"Crystal structures use human ENG and BMP9 [PMID:28564608]. ECD-Fc work used mouse and human endoglin in SPR, cell assays, chick CAM and mouse tumour models [PMID:21737454]. COS cells, bovine aortic and glioblastoma cells in [PMID:17311849]. The mouse pair is projected from human evidence.","localisation_and_range":"BMP9 is flagged secreted [flag]; ENG is described as a transmembrane co-receptor, with a shed soluble form [PMID:21737454]. Acts in endothelial cells [PMID:17311849].","caveats":"Two of three papers were read as abstracts only. Two cited reports show high-affinity binding without a Kd in our excerpts [PMID:17311849][PMID:21737454]. Soluble ENG is antagonistic whereas membrane ENG supports signalling.","key_references":[{"PMID":"28564608","why":"Crystal structure and BLI kinetics of ENG-BMP9"},{"PMID":"21737454","why":"Direct high-affinity binding of ENG ECD-Fc to BMP9, orphan domain mapping"},{"PMID":"17311849","why":"BMP9 binds ALK1 and endoglin in transfected cells"}],"covers":["LR000695","LR004179"]},"LR007229":{"pair":"GDF3 -> ACVR1B:ACVR2B","headline":"Complex pair with no curator-verified paper; rests on GtoPdb and UniProt records for individual subunits.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as agonist of both subunits (ACVR1B and ACVR2B) as separate records [DB:GtoPdb]. UniProt says GDF3 acts through a receptor complex of ACVR1B and the co-receptor CRIPTO [DB:UniProt].","molecular_requirements":"UniProt names CRIPTO as a co-receptor, which is not part of this complex entry [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the database evidence is not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor complex is flagged transmembrane [flag].","caveats":"No papers; only review-level sources were judged. The type I plus type II pairing is not shown as a unit in our evidence.","key_references":[],"covers":["LR007229"]},"LR002684":{"pair":"GDF3 -> ACVR1C","headline":"GDF3 signals via ALK7 (ACVR1C) with Cripto in adipose tissue; mouse functional evidence, binding not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 can signal via ALK7 and Cripto [PMID:18480259]. Gdf3-/- mice had less adipose tissue and partial resistance to diet-induced obesity, phenocopied by ALK7-deficient mice [PMID:18480259]. Agonist [PMID:18480259][DB:GtoPdb].","molecular_requirements":"Cripto is the co-receptor named alongside ALK7 [PMID:18480259][DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse knockouts and signalling assays; curators label mouse ligand and receptor [PMID:18480259].","localisation_and_range":"GDF3 is flagged secreted [flag]; acts in adipose tissue [PMID:18480259].","caveats":"Abstract only. No direct binding data. The signalling readout in the abstract is not detailed.","key_references":[{"PMID":"18480259","why":"GDF3 signals via ALK7 and Cripto; matching Gdf3 and Alk7 knockout phenotypes"}],"covers":["LR002684","LR005949"]},"LR005951":{"pair":"GDF3 -> ACVR2B","headline":"GDF3 signalling involves ActRIIB (with ALK4 and Cripto) in reporter assays; binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4, type II receptors ActRIIA and ActRIIB, and Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"The paper tests the full set (ALK4, ActRIIA, ActRIIB, Cripto), so the role of this receptor alone is not separated; native GDF3 needs a heterologous prodomain, Furin or Nodal to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Heterologous cell reporter assays; curators label human [PMID:17936261]. The human pair is ortholog-inferred and the mouse pair listed as direct.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor is flagged transmembrane [flag].","caveats":"Abstract only. No direct binding data; the paper treats the type II receptors as a group.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002686","LR005951"]},"LR008264":{"pair":"GDF6 -> ACVR2B:BMPR1A","headline":"No paper confirms this combination; only database annotation of the chains, with no direct evidence for the complex.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in any verified paper in our evidence. UniProt says GDF6 seems to positively regulate chondrogenic differentiation through BMPR1A, BMPR1B, BMPR2 and ACVR2A subunits, activating SMAD1-SMAD5-SMAD8 [DB:UniProt]. A BioGRID record concerns GDF6 with BMPR1B only [DB:BioGRID].","molecular_requirements":"Complex requirement is untested: no curator-verified paper covers ACVR2B and BMPR1A together.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"The single judged paper was review_only. ACVR2B is not named in the UniProt note.","key_references":[],"covers":["LR008264"]},"LR004187":{"pair":"GDF6 -> BMPR1B","headline":"GDF6 binds BMPR1B (ALK6) with high affinity and ALK6 confers GDF6 signalling; three concordant papers, two abstract-only.","interaction_type":"direct binding","direction_and_effect":"rhBMP13 (GDF6 alias) bound ALK6 [PMID:21702718]. ALK6 overexpression in COS7 cells conferred GDF6 signalling [PMID:16049014]. CDMP-2 had affinity for BMPR-IB and BMPR-II [PMID:9525338]. Effect is stimulatory (Smad1/5/8).","molecular_requirements":"ALK3 or ALK6 suffices as type I receptor in COS7 [PMID:16049014]; BMPR-IB transduced a signal in the presence of BMPR-II [PMID:9525338].","affinity_potency":[{"value":"KD (kin) 0.5 nM","assay":"Bio-Layer Interferometry, immobilised ALK6-Fc, rhBMP13 (GDF6 alias)","system":"recombinant proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant proteins and C3H10T1/2 cells [PMID:21702718]; COS7 and MC3T3 cells [PMID:16049014]; ATDC5, ROB-C26, MC3T3-E1 [PMID:9525338]. Human pair listed directly; mouse ortholog-inferred. BioGRID reconstituted-complex record [DB:BioGRID].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"PMID:16049014 and PMID:9525338 were read as abstracts only; ligand identity relies on alias names (BMP13, CDMP-2).","key_references":[{"PMID":"21702718","why":"BLI affinity of GDF6 (BMP13) for ALK6"},{"PMID":"16049014","why":"ALK6 overexpression confers GDF6 signalling"},{"PMID":"9525338","why":"CDMP-2 binds BMPR-IB"}],"covers":["LR000703","LR004187"]},"LR006806":{"pair":"GDF9 -> BMPR1A","headline":"Weak, conflicting functional support: a soluble BMPR1A ectodomain partly blocks GDF9, but a full-text paper says GDF9 uses ALK5, not ALK3/BMPR1A.","interaction_type":"conflicting","direction_and_effect":"The BMPR-IA ectodomain was only partially effective in blocking GDF-9 action on granulosa cells, suggesting it may take part [PMID:12135884]. A cattle study states GDF9 binds BMPRII and ALK5 (TGFBR1), whereas ALK3 (BMPR1A) is the BMP15 type I receptor [PMID:39018835]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Type II partner BMPRII was the most effective blocker [PMID:12135884]; no BMPR1A-specific requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Ectodomain-Fc blockade used rat granulosa cells and ovary with human GDF9 [PMID:12135884]; the second paper is a bovine in vivo FSH study that measured mRNA, not binding [PMID:39018835].","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Antagonist blockade is indirect, and no direct BMPR1A binding was shown (abstract only) [PMID:12135884]. The pair-absent paper argues against BMPR1A as a GDF9 receptor [PMID:39018835].","key_references":[{"PMID":"12135884","why":"Ectodomain-Fc blockade, BMPR-IA partially effective"},{"PMID":"39018835","why":"Full text assigns GDF9 to ALK5 not ALK3"}],"covers":["LR006806"]},"LR004196":{"pair":"GDNF -> RET","headline":"Well established, but RET binds GDNF only as a GDNF-GFRA1 complex; low or no affinity for GDNF alone.","interaction_type":"direct binding","direction_and_effect":"GDNF with GFRalpha1 activates RET: Neuro-2a cells expressing GDNFR-alpha showed rapid Ret autophosphorylation [PMID:8674117]; GDNF signalling through Ret was also seen with TrnR2 [PMID:9182803]. UniProt, Reactome and PDB record the interaction [DB:UniProt][DB:Reactome][DB:PDB 4UX8].","molecular_requirements":"GFR alpha co-receptor is required: RETECD has low or no detectable affinity for GDNF or GFR alpha1 alone, and contacts both in the complex via cadherin-like domains 1-3 [PMID:14514671]. GFRA2 can substitute [PMID:9182803]. Score with GFRA1 (or GFRA2) as well as RET.","affinity_potency":[],"species_and_systems":"Human RET mutagenesis in [PMID:14514671]; Neuro-2a cells and rat spinal cord motor neurons in [PMID:8674117]; fibroblasts in [PMID:9182803]. Mouse pair ortholog-inferred.","localisation_and_range":"GDNF is flagged secreted [flag]; RET is the transmembrane signalling receptor.","caveats":"A gene-level GDNF -> RET row hides the co-receptor requirement. No affinity value in our evidence; all papers were read as abstracts except partial full text in [PMID:9182803].","key_references":[{"PMID":"8674117","why":"GDNF with GDNFR-alpha activates Ret"},{"PMID":"14514671","why":"RET ectodomain binds GDNF-GFRa1 complex only"},{"PMID":"9182803","why":"GFRA2 alternative co-receptor for Ret"}],"covers":["LR000712","LR004196"]},"LR002693":{"pair":"GDNF -> SDC3","headline":"Direct binding to syndecan-3 heparan sulfate chains reported, for matrix-immobilised GDNF.","interaction_type":"direct binding","direction_and_effect":"Immobilised GDNF binds syndecan-3 heparan sulfate chains with high affinity, mediating cell spreading and neurite outgrowth via Src kinase, and promoting cortical neuron migration in a syndecan-3-dependent manner [PMID:21200028].","molecular_requirements":"Syndecan-3 may directly transduce GFL signals or act as a coreceptor presenting GFLs to RET [PMID:21200028].","affinity_potency":[{"value":"Kd between 10 and 50 nM","assay":"surface plasmon resonance, GDNF/NRTN/ARTN binding to heparin/HS","system":"heparin or heparan sulfate, not syndecan-3 protein itself","cite":"PMID:21200028"}],"species_and_systems":"Cortical neurons and mice lacking syndecan-3 or GDNF; curators record human ligand and receptor. Mouse pair is ortholog-inferred [PMID:21200028].","localisation_and_range":"Matrix-bound (immobilised) GDNF acts at cell contact; syndecan-3 is a transmembrane proteoglycan [PMID:21200028]; GDNF is flagged secreted [flag].","caveats":"Affinity is for heparin/heparan sulfate, not the core protein. Soluble GDNF uses the GFRA/RET route instead [PMID:21200028]. Abstract plus full-text excerpts of one paper; no database support.","key_references":[{"PMID":"21200028","why":"GDNF binds syndecan-3 HS chains; cortical neuron migration"}],"covers":["LR002693","LR005958"]},"LR005186":{"pair":"GLG1 -> SELE","headline":"E-selectin binds ESL-1 (GLG1) with very low affinity in mouse SPR data; two confirmed rows share one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Monomeric E-selectin binds ESL-1 from mouse bone marrow cells by surface plasmon resonance, with Kd 62 uM and koff 4.6 s-1 [PMID:11404363]. Recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells gave Kd 66 uM [PMID:11404363]. Reactome has an E-selectin-ligand binding reaction [DB:Reactome].","molecular_requirements":"Fucosylation-linked: recombinant ESL-1 from fucosyltransferase IV CHO cells binds [PMID:11404363]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"Kd 62 microm","assay":"surface plasmon resonance","system":"mouse E-selectin and ESL-1 from mouse bone marrow cells","cite":"PMID:11404363"}],"species_and_systems":"Mouse proteins; the human pair is ortholog-inferred and the mouse pair is the experimental one [PMID:11404363].","localisation_and_range":"Receptor flagged transmembrane [flag]; ligand not secreted [flag]; adhesion between cells is implied by selectin rolling in curator notes.","caveats":"One paper, abstract only. Fast off-rate and very low affinity are consistent with transient adhesion rather than stable binding (curator interpretation).","key_references":[{"PMID":"11404363","why":"SPR kinetics of E-selectin binding ESL-1"}],"covers":["LR001831","LR005186"]},"LR010469":{"pair":"GLS:SLC1A1 -> GRIN1:GRIN2C","headline":"Protein-association records only; no paper confirms GLS:SLC1A1 -> GRIN1:GRIN2C as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010469"]},"LR005960":{"pair":"GP1BA -> ITGAM","headline":"Direct, mapped binding of GP Ibalpha to the alphaM I domain of Mac-1, with strong gain-of-function evidence (human).","interaction_type":"direct binding","direction_and_effect":"GP Ibalpha binding to Mac-1 (alphaM beta2) is mapped to the P201-K217 sequence of the alphaM I domain: swapping it for alphaL sequence abolished adhesion, and grafting it onto alphaL made alphaL beta2 bind GP Ibalpha [PMID:14530377]. Synthetic P201-K217 peptide bound GP Ibalpha directly and blocked alphaM beta2 adhesion [PMID:14530377]. Effect is adhesion; agonist/antagonist role not reported in our evidence.","molecular_requirements":"The alphaM I domain carries the binding site (recombinant alphaMI domains were tested). Intact Mac-1 is the alphaM beta2 heterodimer; whether beta2 is needed for binding is not reported in our evidence [PMID:14530377].","affinity_potency":[],"species_and_systems":"Human proteins; alphaM beta2-expressing 293 cells and THP-1 cells with soluble GP Ibalpha (full text) [PMID:14530377]. Mouse pair is ortholog-inferred.","localisation_and_range":"GP Ibalpha is the platelet counter receptor and Mac-1 is on leukocytes, so contact-dependent platelet-leukocyte adhesion [PMID:14530377]; both are annotated non-secreted [flag].","caveats":"One paper only, with an experimental-system claim from excerpts; no affinity reported in our evidence.","key_references":[{"PMID":"14530377","why":"Maps the GP Ibalpha binding site to alphaM P201-K217"}],"covers":["LR002695","LR005960"]},"LR009254":{"pair":"GPC3 -> LRP1","headline":"GPC3 binds LRP1 through its heparan sulfate chains, shown in one abstract-read paper; an IntAct co-IP record also lists the pair.","interaction_type":"direct binding","direction_and_effect":"GPC3 binds through its HS chains to LRP1, which mediates Hh-induced endocytosis of the GPC3-Hh complex and removes GPC3 from lipid rafts [PMID:22467855]. Effect on LRP1 signalling is not reported in our evidence.","molecular_requirements":"GPC3 heparan sulfate chains are required for binding [PMID:22467855]. LRP1 mediates endocytosis of the GPC3-Hh complex, and this endocytosis is needed for the Hh-inhibitory activity of GPC3 [PMID:22467855].","affinity_potency":[],"species_and_systems":"Species and cell system not reported in our evidence. IntAct lists anti-bait coimmunoprecipitation [DB:IntAct][PMID:39822733].","localisation_and_range":"GPC3 is a membrane-bound glypican, GPI-linked (paper) [PMID:22467855], annotated non-secreted [flag].","caveats":"Abstract only. The entry is classed 'Receptor-Receptor'. HS-mediated binding can be non-specific; the paper is not shown to measure protein-protein affinity. Other judged rows: 'review_only', 'abstract_insufficient', 'different_entity'.","key_references":[{"PMID":"22467855","why":"GPC3 binds LRP1 via HS chains; LRP1 mediates endocytosis"}],"covers":["LR009254"]},"LR008660":{"pair":"HGF -> SDC2","headline":"No curator-confirmed evidence; supported only by a BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the BioGRID record.","localisation_and_range":"SDC2 is annotated as a transmembrane receptor and HGF as secreted [flag].","caveats":"Four papers were judged abstract_insufficient and none confirmed the pair. The only support is a BioGRID reconstituted-complex record [DB:BioGRID][PMID:8157651].","key_references":[],"covers":["LR008660"]},"LR000749":{"pair":"HLA-A -> LILRB2","headline":"Direct binding shown by SPR in human recombinant proteins, with micromolar affinity; one of several class I ligands.","interaction_type":"direct binding","direction_and_effect":"LILRB2 (ILT4) binds classical HLA class I and HLA-G; ILT4 is described as inhibitory, delivering negative signals that can inhibit early signalling triggered by stimulatory receptors [PMID:9531263]. ILT2 and ILT4 compete with CD8 for MHC class I binding [PMID:12853576].","molecular_requirements":"Soluble D1D2 domains of LILRB2 were sufficient for binding by SPR [PMID:12853576][PMID:21559424]. Binding to >90 HLA class I alleles was assessed [PMID:21270408].","affinity_potency":[{"value":"Kd \u224814 to \u224845 \u03bcM","assay":"SPR, soluble ILT4 D1D2 over immobilised biotinylated HLA class I (HLA-A*1101, -B*3501, -Cw*0401, -Cw*0702)","system":"recombinant human proteins","cite":"PMID:12853576"},{"value":"9.74 \u00b5M","assay":"SPR, LILRB2 D1D2 over HLA-A*0201","system":"recombinant human proteins","cite":"PMID:21559424"}],"species_and_systems":"Human proteins and cells throughout [PMID:12853576][PMID:21559424][PMID:9531263]. The pair is not tied to one HLA-A allele: A*1101 and A*0201 were tested.","localisation_and_range":"Both partners are flagged transmembrane [flag]; contact-dependent.","caveats":"Affinity is low (micromolar). In the LILRA3 paper LILRB2/HLA-A*0201 serves as a benchmark rather than the main finding [PMID:21559424]. Several papers were read as abstracts only [PMID:21270408][PMID:9531263][PMID:21559424]. One judged row was a different entity.","key_references":[{"PMID":"12853576","why":"SPR affinities of ILT4 for classical HLA class I"},{"PMID":"21559424","why":"SPR of LILRB2 with HLA-A*0201 (9.74 \u00b5M)"},{"PMID":"9531263","why":"ILT4 binds classical class I and HLA-G; inhibitory"}],"covers":["LR000749"]},"LR001838":{"pair":"HLA-B -> KIR3DL2","headline":"Direct binding shown, mainly for HLA-B27 beta2m-free dimers and free heavy chains; three confirming papers.","interaction_type":"direct binding","direction_and_effect":"B27 homodimers bound KIR3DL1, KIR3DL2 and LILRB2 but not LILRB1 [PMID:17407096]. KIR3DL2 bound HLA-B27 dimers and free H chains more strongly than other HLA class I [PMID:23440420]. KIR3DL2 ligation by B27 dimers inhibits NK-cell and T-cell IFN-gamma production per the curator note [PMID:17407096].","molecular_requirements":"The relevant form is the beta2m-free HLA-B27 homodimer or free heavy chain, not only the classical heterotrimer; dimer binding is independent of bound peptide sequence [PMID:17407096]. B*27:05 forms more such ligands than B*27:09 [PMID:23804219].","affinity_potency":[],"species_and_systems":"Human proteins and cells: KIR3DL2-transfected Baf3 cells with B27 dimer tetramers and recombinant protein; KIR3DL2-CD3epsilon reporter T cells [PMID:23440420][PMID:23804219].","localisation_and_range":"Both partners are flagged transmembrane [flag]; contact-dependent.","caveats":"Evidence is specific to HLA-B27 forms. B27 dimer tetramers have more molecules than HLA-A3 tetramers, which may raise avidity; non-tetramerised dimer was also tested [PMID:23440420]. Two papers read as abstracts [PMID:17407096][PMID:23804219].","key_references":[{"PMID":"23440420","why":"KIR3DL2 binds B27 dimers and free H chains more strongly"},{"PMID":"17407096","why":"B27 homodimer binding to KIR3DL2 is peptide-independent"},{"PMID":"23804219","why":"B*27:05 forms more KIR3DL2 ligands than B*27:09"}],"covers":["LR001838"]},"LR000758":{"pair":"HLA-C -> LILRB1","headline":"Well-supported direct binding of folded HLA-C to inhibitory LILRB1, with micromolar affinity by SPR.","interaction_type":"direct binding","direction_and_effect":"LILRB1 (ILT2) binds HLA-C. It carries ITIMs that recruit phosphatases such as SHP-1 [PMID:12853576]. LIR-1-Fc bound cells expressing HLA-A, -B and -C, blocked by pan-class-I antibody W6/32 [PMID:9285411].","molecular_requirements":"LILRB1 exclusively bound folded beta2-microglobulin-associated class I, not free heavy chain [PMID:21270408]. The D1D2 domains were sufficient for SPR binding [PMID:12853576].","affinity_potency":[{"value":"Kd approx 6.5 uM (HLA-Cw4); approx 8.8 uM (HLA-B35)","assay":"surface plasmon resonance, soluble ILT2 D1D2 over immobilised HLA","system":"recombinant human proteins","cite":"PMID:12853576"}],"species_and_systems":"Human proteins and cells throughout (SPR, Fc-fusion binding, allele survey) [PMID:12853576][PMID:9285411][PMID:21270408].","localisation_and_range":"HLA-C is flagged transmembrane (not secreted) [flag]: trans interaction by cell contact.","caveats":"The SPR paper was read as a browser full text and its quote is marked unverified. The 1997 paper tests class I in general rather than HLA-C allotypes. One further judged row is still pending.","key_references":[{"PMID":"12853576","why":"SPR Kd of ILT2 D1D2 for HLA-Cw4"},{"PMID":"21270408","why":"Folded-only specificity across >90 HLA alleles"},{"PMID":"9285411","why":"LIR-1-Fc binds HLA-A/B/C on cells"}],"covers":["LR000758"]},"LR008336":{"pair":"HLA-DPA1 -> LAG3","headline":"No curator-verified paper; rests on database records saying LAG3 binds MHC class II.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records 'LAG3 (CD233) binds MHC II' [DB:Reactome R-HSA-8856157]; IntAct has an anti-tag coimmunoprecipitation record [DB:IntAct EBI-54690546]. Effect: not reported in our evidence.","molecular_requirements":"Which class II chain (alpha or beta) is needed: not reported in our evidence. The records are generic class II, not DPA1-specific.","affinity_potency":[],"species_and_systems":"Species of the experiments: not reported in our evidence (pair is human).","localisation_and_range":"Not reported in our evidence.","caveats":"Two papers were judged review-only and none verified. Specificity of DPA1 versus other class II alleles is unknown. Co-IP evidence does not prove direct binding.","key_references":[],"covers":["LR008336"]},"LR002729":{"pair":"HLA-E -> KLRC3","headline":"One abstract-level affinity study shows activating NKG2E/CD94 binding HLA-E with high affinity.","interaction_type":"direct binding","direction_and_effect":"Activating NKG2E/CD94 bound HLA-E with affinity indistinguishable from inhibitory NKG2A/CD94 and higher than NKG2C [PMID:15728498].","molecular_requirements":"Tested as NKG2E/CD94; KLRC3 alone not reported in our evidence. Peptide presented by HLA-E influenced affinity; allele did not [PMID:15728498].","affinity_potency":[],"species_and_systems":"Human; purified receptor/HLA-E complexes [PMID:15728498].","localisation_and_range":"KLRC3 and HLA-E flagged receptor/membrane and secreted+transmembrane respectively [flag].","caveats":"One paper, abstract only, no numeric affinity. No database records.","key_references":[{"PMID":"15728498","why":"NKG2E/CD94 binds HLA-E with high affinity"}],"covers":["LR002729"]},"LR000767":{"pair":"HLA-G -> LILRB2","headline":"Well-supported direct human HLA-G to LILRB2 (ILT4/LIR-2) binding, with a crystal structure; low-micromolar affinity.","interaction_type":"direct binding","direction_and_effect":"HLA-G binds the inhibitory receptor LILRB2 [PMID:9531263][PMID:10190906]. HLA-G tetramers bound ILT4 transfectants, and binding to monocytes was largely due to ILT4 [PMID:10190906]. A 2.5-A crystal structure of the LILRB2/HLA-G complex is reported [PMID:17056715]; PDB 2DYP is the corresponding record [DB:PDB 2DYP].","molecular_requirements":"LILRB2 mainly recognises the hydrophobic site of the HLA-G alpha3 domain, with a mode overlapping but distinct from LILRB1. Unlike LILRB1, it can recognise the beta2m-free form [PMID:17056715].","affinity_potency":[{"value":"Kd 2-45 microM (range across the MHC class I panel; ILT4 bound HLA-G with 3- to 4-fold higher affinity than classical MHCIs)","assay":"surface plasmon resonance","system":"soluble ILT4 (LILRB2) and MHC class I proteins","cite":"PMID:12853576"},{"value":"5.62 microM","assay":"SPR (BIAcore), LILRB2 D1D2 over immobilised HLA-G1","system":"recombinant human proteins; used as a positive control","cite":"PMID:21559424"}],"species_and_systems":"Human proteins and cells throughout (recombinant proteins, transfectants, blood monocytes) [PMID:17056715][PMID:10190906][PMID:21559424].","localisation_and_range":"HLA-G is flagged both secreted and transmembrane [flag]; the tetramer and monocyte data show contact-type binding to cell-surface receptor [PMID:10190906].","caveats":"Most papers were read as abstracts. PMID:15670976 shows HLA-G upregulating receptor expression and treats binding as background. PMID:21559424 mainly concerns LILRA3, with LILRB2 as comparator.","key_references":[{"PMID":"17056715","why":"Crystal structure of LILRB2/HLA-G"},{"PMID":"12853576","why":"SPR affinities of ILT4 for HLA-G"},{"PMID":"10190906","why":"HLA-G tetramers bind ILT4 and monocytes"}],"covers":["LR000767"]},"LR002738":{"pair":"HMGB1 -> LY96","headline":"Strong direct binding of disulfide HMGB1 to MD-2 (Kd 12 nM, SPR) that drives TLR4 signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"MD-2 binds the cytokine-inducing disulfide isoform of HMGB1 to the exclusion of other isoforms. MD-2-deficient mice and MD-2 silencing in macrophages show it is required for HMGB1-dependent TLR4 signalling. Peptide P5779 antagonises the MD-2-HMGB1 interaction without blocking LPS responses [PMID:25559892]. Reactome records HMGB1 binding TLR4:LY96 [DB:Reactome].","molecular_requirements":"Only the disulfide isoform binds; fully reduced, H2S-modified or sulfonyl HMGB1 had more than 1,000-fold reduced MD-2 binding, and cysteine 106 modification abolished binding. HMGB1 did not bind TLR4 directly without MD-2 [PMID:25559892].","affinity_potency":[{"value":"apparent Kd 12 nM","assay":"Biacore SPR","system":"disulfide HMGB1 with MD-2","cite":"PMID:25559892"}],"species_and_systems":"Recombinant proteins plus mouse macrophages (RAW 264.7) and MD-2-deficient mice [PMID:25559892]. Curated as human ligand with mouse receptor; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; MD-2 is an extracellular TLR4 adaptor [PMID:25559892].","caveats":"Isoform-specific, so total HMGB1 expression does not predict signalling. Single primary paper.","key_references":[{"PMID":"25559892","why":"Disulfide HMGB1 binds MD-2; P5779 antagonist"}],"covers":["LR002738","LR005986"]},"LR009065":{"pair":"HMGB1 -> THBD","headline":"Thrombomodulin binds HMGB1 via its D1 domain and sequesters it; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"TM, via D1, binds HMGB1, preventing in vitro leukocyte activation and reducing UV-induced cutaneous inflammation and LPS-induced lethality in vivo [PMID:15841214]. It acts as a decoy that sequesters HMGB1, preventing its interaction with cell-surface receptors [PMID:15841214]; UniProt also notes the anti-inflammatory function [DB:UniProt].","molecular_requirements":"The N-terminal lectin-like domain D1 is sufficient; this is separate from the anticoagulant cofactor function [PMID:15841214].","affinity_potency":[],"species_and_systems":"Curated as human protein with endothelium and purified domains; species is not stated in the abstract [PMID:15841214].","localisation_and_range":"HMGB1 is flagged secreted [flag]; TM is an endothelial membrane protein, with sequestration at the cell surface [PMID:15841214].","caveats":"Single abstract-only paper; no affinity. This is a scavenger, not a signalling, interaction.","key_references":[{"PMID":"15841214","why":"TM D1 binds and sequesters HMGB1"}],"covers":["LR009065"]},"LR009407":{"pair":"HSP90AA1 -> EGFR","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists 7 records (two-hybrid, affinity-capture-western) [DB:BioGRID]; IntAct lists 6 including ubiquitin-reconstruction associations [DB:IntAct]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; the judged row was different_entity.","key_references":[],"covers":["LR009407"]},"LR009056":{"pair":"HSP90AA1 -> FGFR3","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists 2 records (affinity-capture-MS and luminescence) [DB:BioGRID]; IntAct lists one affinity-chromatography association [DB:IntAct]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; the judged row was different_entity.","key_references":[],"covers":["LR009056"]},"LR000776":{"pair":"HSPG2 -> COL13A1","headline":"Human recombinant binding of the type XIII collagen ectodomain to perlecan, measured by SPR in the nanomolar range; adhesion partner, not a signalling pair.","interaction_type":"direct binding","direction_and_effect":"Recombinant COL13A1 ectodomain interacted with immobilised perlecan, fibronectin and nidogen-2 by surface plasmon resonance; no signalling was shown [PMID:11956183]. Curators note the usual direction is inverted, because COL13A1 is the transmembrane partner [PMID:11956183]. UniProt also records the interaction [DB:UniProt].","molecular_requirements":"Perlecan and nidogen-2 binding resides in the pepsin-sensitive portions of the ectodomain; the ectodomain forms 240-kDa trimers [PMID:11956183].","affinity_potency":[{"value":"K(D) in the nanomolar range","assay":"surface plasmon resonance, ectodomain vs immobilised perlecan","system":"recombinant COL13A1 ectodomain from insect cells","cite":"PMID:11956183"}],"species_and_systems":"Recombinant human proteins in vitro [PMID:11956183]. Mouse pair is ortholog-inferred.","localisation_and_range":"COL13A1 is flagged transmembrane and HSPG2 secreted [flag]; the ectodomain is shed in cell culture, and the paper links it to cell-adhesion sites [PMID:11956183]. This is a matrix or contact interaction.","caveats":"Abstract only; no exact K(D). Binding of a shed ectodomain to matrix does not show receptor signalling.","key_references":[{"PMID":"11956183","why":"SPR binding of COL13A1 ectodomain to perlecan, fibronectin and nidogen-2"}],"covers":["LR000776","LR004234"]},"LR002756":{"pair":"HSPG2 -> DAG1","headline":"Perlecan is a dystroglycan ligand at nodes of Ranvier (full text read), and Reactome records HSPG2 binding alpha-dystroglycan; no affinity.","interaction_type":"functional only","direction_and_effect":"Dystroglycan is required for perlecan to accumulate at peripheral nodes of Ranvier; perlecan then binds gliomedin and enhances clustering of node components [PMID:25646087]. Perlecan was absent from most nodes lacking dystroglycan (4% and 6% of nodes perlecan-positive vs 68% and 87% flanking paranodes in wild type) [PMID:25646087]. Reactome records HSPG2 binding alpha-dystroglycan [DB:Reactome R-HSA-2396395].","molecular_requirements":"Dystroglycan is an extracellular matrix receptor; Reactome lists a Dystroglycan:AGRN:HSPG2 complex [DB:Reactome R-HSA-2426244]. Which dystroglycan chain binds is not reported in our evidence in the paper excerpts.","affinity_potency":[],"species_and_systems":"In vivo mouse nerve (dystroglycan-deficient and perlecan-mutant mice) per excerpts; curators record human for both partners [PMID:25646087]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane [flag]; perlecan localises to the nodal gap matrix [PMID:25646087]. Matrix-bound, juxtacrine range.","caveats":"The paper shows dependence of perlecan localisation on dystroglycan, not a direct binding measurement; absence of perlecan alone did not impair Na+ channel clustering [PMID:25646087]. Direct binding rests on Reactome [DB:Reactome R-HSA-2396395].","key_references":[{"PMID":"25646087","why":"Dystroglycan needed for perlecan localisation at nodes of Ranvier"}],"covers":["LR002756","LR006003"]},"LR000785":{"pair":"ICAM1 -> ITGAM","headline":"ICAM-1 engages Mac-1 (ITGAM:ITGB2) in cell adhesion assays; evidence is functional and activation-dependent.","interaction_type":"functional only","direction_and_effect":"ICAM-1-expressing CHO cells adhered to immobilized purified Mac-1, and CDR-derived peptides blocked this at 10-100 muM [PMID:9488691]. An activating anti-alphaM antibody induced alphaMbeta2-transfected CHO cell adhesion to ICAM-1 [PMID:11073102]. UniProt says ITGAM/ITGB2 is also a receptor for ICAM1 [DB:UniProt].","molecular_requirements":"Requires the alphaM-beta2 integrin and an activated conformation; resting leukocyte beta2 integrins do not bind ligands [PMID:11073102].","affinity_potency":[],"species_and_systems":"Human proteins in transfected CHO cells and purified Mac-1 [PMID:9488691, PMID:11073102].","localisation_and_range":"ITGAM is not flagged secreted; cell-contact adhesion between cells [PMID:9488691].","caveats":"Both papers were abstract-only. The adhesion readout shows involvement, not affinity. One additional row was different_entity.","key_references":[{"PMID":"9488691","why":"ICAM-1 CHO cell adhesion to purified Mac-1"},{"PMID":"11073102","why":"Activation-dependent adhesion to ICAM-1"}],"covers":["LR000785","LR004243"]},"LR000794":{"pair":"ICAM3 -> ITGB2","headline":"Well supported direct, adhesive interaction of ICAM-3 with the LFA-1 integrin (alphaL/beta2); structure plus binding and functional data.","interaction_type":"direct binding","direction_and_effect":"ICAM-3 acts as a stimulatory adhesion ligand for LFA-1: purified ICAM-3 supported LFA-1-dependent adhesion and gave a costimulatory signal for resting T-cell proliferation [PMID:7905020]; curated as agonist [PMID:7822326].","molecular_requirements":"The evidence concerns the LFA-1 heterodimer (CD11a/CD18). A 1.65-A crystal structure used the alphaL inserted domain with ICAM-3 domain D1 [PMID:15728350]. N-terminal Ig domains 1-2 of ICAM-3 hold the binding site; Glu37, Leu66, Ser68 and Gln75 in domain 1 play a dominant role [PMID:7822326]. UniProt also lists ITGAD:ITGB2 as an ICAM3 receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins; ICAM-3-Fc mutants binding human LFA-1 on COS cells [PMID:7822326]; adhesion and T-cell assays in vitro [PMID:7905020].","localisation_and_range":"ICAM3 is flagged transmembrane, not secreted [flag]: membrane-bound, juxtacrine adhesion.","caveats":"Three papers were read as abstracts only (one further paper was abstract-insufficient). Evidence is for the alphaL/beta2 complex, not beta2 alone; affinity not reported in our evidence.","key_references":[{"PMID":"15728350","why":"Crystal structure of ICAM-3 D1 with the alphaLbeta2 inserted domain"},{"PMID":"7822326","why":"Mutational mapping of the LFA-1 binding site on ICAM-3"},{"PMID":"7905020","why":"ICAM-3 supports LFA-1 adhesion and T-cell costimulation"}],"covers":["LR000794"]},"LR001847":{"pair":"ICOSLG -> CD28","headline":"Direct binding of human B7-H2 to CD28, shown by receptor array, flow cytometry and SPR; not conserved in mouse.","interaction_type":"direct binding","direction_and_effect":"B7-H2 (ICOSLG) was identified as a ligand of CD28 in a receptor array; CD28Ig binding to B7-H2+ 293T cells was blocked by anti-CD28 mAb [PMID:21530327]. It costimulated human T cells (agonist) and induced Bcl-xL, lowered p27(kip1) and triggered ERK and AKT signalling [PMID:21530327].","molecular_requirements":"B7-H2 and B7-1/B7-2 bind CD28 through different interfaces and could bind simultaneously. B7-H2 residues Y51, Y53, L116 and F122 are needed for CD28 binding [PMID:21530327].","affinity_potency":[],"species_and_systems":"Human proteins; 293T transfectants, Ig fusions, SPR at 25 and 37 C, and purified human T cells [PMID:21530327]. Murine CD28Ig did not bind murine B7-H2.","localisation_and_range":"ICOSLG and CD28 are both flagged transmembrane, so contact-dependent [flag].","caveats":"Human-specific; not conserved in mouse [PMID:21530327]. B7-H2 binds weaker than B7-1/B7-2 [PMID:21530327]. Only one paper; no database records.","key_references":[{"PMID":"21530327","why":"Discovery and characterisation of B7-H2/CD28 binding and function"}],"covers":["LR001847"]},"LR008444":{"pair":"IFNA13 -> IFNAR2","headline":"Chain-level nanomolar binding of alpha-IFNs to IFNAR2, applied to IFNA13 by a class statement.","interaction_type":"direct binding","direction_and_effect":"IFNA13 is a stimulatory agonist at IFNAR2 [DB:GtoPdb]; binding to the isolated chain is reported for alpha-IFNs [PMID:21856167].","molecular_requirements":"Chain-only evidence [PMID:21856167].","affinity_potency":[{"value":"0.4-5 nM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated chains.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only; IFNA13 not named. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR008444","LR004264"]},"LR004259":{"pair":"Ifna15 -> Ifnar1","headline":"Mouse pair projected from human data; the two papers tested human IFNs on human receptor chains and do not name Ifna15.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs bind isolated IFNAR1 [PMID:21856167]; competitive 1:1 binding of IFNs to ifnar1-EC was seen [PMID:17174979].","molecular_requirements":"Chain-only evidence on IFNAR1 [PMID:21856167].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"binding to isolated receptor chain","system":"human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Both papers used human proteins, not mouse [PMID:21856167] [PMID:17174979]; the mouse pair is ortholog-inferred.","localisation_and_range":"Ifna15 flagged secreted [flag].","caveats":"No mouse experiment in our evidence; both papers are abstract only.","key_references":[{"PMID":"21856167","why":"Class-wide human affinities"},{"PMID":"17174979","why":"Human IFN receptor subunit binding"}],"covers":["LR004259"]},"LR007274":{"pair":"IFNA21 -> IFNAR1:IFNAR2","headline":"IFNA21 to the IFNAR1:IFNAR2 heterodimer rests on class-wide binding data for each chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM and IFNAR2 at 0.4-5 nM [PMID:21856167]. GtoPdb lists IFNA21 as an agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains are listed; each binds separately, IFNAR2 much more tightly [PMID:21856167]. Binding to the assembled heterodimer is not reported in our evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single verified paper, abstract only, class-wide values with no value for IFNA21; one further row was review only.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR007274"]},"LR004268":{"pair":"IFNA6 -> IFNAR2","headline":"IFNA6 binds IFNAR2 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000824","LR004268"]},"LR007283":{"pair":"IFNK -> IFNAR1:IFNAR2","headline":"IFN-kappa to the IFNAR1:IFNAR2 complex: database records only, no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNK-IFNAR1 and IFNK-IFNAR2 as Agonist [DB:GtoPdb]. The curated class is Ligand-Receptor with no stated modulatory effect.","molecular_requirements":"The receptor is a two-chain complex (IFNAR1, IFNAR2) [flag]. Whether both chains are required is not reported in our evidence for this row.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNK is flagged secreted and non-transmembrane; the complex is flagged transmembrane [flag].","caveats":"No papers were verified for this row (four abstract_insufficient and one review_only); support is database-only.","key_references":[],"covers":["LR007283"]},"LR001856":{"pair":"IFNL4 -> IL10RB","headline":"IFN-lambda4 to IL10RB: supported only by a database structure record of the ternary complex.","interaction_type":"database-asserted only","direction_and_effect":"No effect direction is stated in our evidence.","molecular_requirements":"PDB 9BPU (electron microscopy) shows the IFN-lambda4/IFN-lambdaR1/IL-10Rbeta complex; IL10RB is the shared second chain, and binding to IL10RB alone is not shown [DB:PDB 9BPU].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNL4 is flagged secreted [flag].","caveats":"No papers verified; database-only support.","key_references":[],"covers":["LR001856"]},"LR000839":{"pair":"IFNW1 -> IFNAR2","headline":"IFN-omega binds IFNAR2; crystal structures of the ternary complex and kinetic data support it.","interaction_type":"direct binding","direction_and_effect":"IFN-omega is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. Crystal structures of two human type I IFN ternary complexes (IFNalpha2 and IFNomega) show conserved heterotrimeric architectures, with ligand-specific tuning of binding affinities [PMID:21854986].","molecular_requirements":"IFNAR1 and IFNAR2 bind on opposing sides of the IFN ligand in a nearly orthogonal architecture [PMID:21854986]. The ifnar2-EC interaction is competitive 1:1 for all IFNs tested including IFNomega [PMID:17174979]; ISGF3 formation and antiviral activity correlated with ifnar2 affinity [PMID:17174979].","affinity_potency":[],"species_and_systems":"Human proteins, crystal structures and recombinant ectodomains [PMID:21854986, PMID:17174979].","localisation_and_range":"IFNW1 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract and excerpts only. No numeric affinity for IFN-omega with IFNAR2 is in our evidence.","key_references":[{"PMID":"21854986","why":"crystal structure of the IFN-omega ternary complex"},{"PMID":"17174979","why":"kinetics of IFNomega with ifnar2-EC"}],"covers":["LR000839"]},"LR002765":{"pair":"IGF1 -> ITGA6","headline":"Integrin alpha6beta4 directly binds IGF1 in one verified study; ITGA6 is the alpha chain of that integrin.","interaction_type":"direct binding","direction_and_effect":"Integrin alpha6beta4 directly bound IGF1, forming an alpha6beta4-IGF1-IGF1R ternary complex, and IGF1 signaling and survival depended on alpha6beta4 under low adhesion [PMID:22351760]. UniProt states ITGA6:ITGB4 binding is essential for IGF1 signaling [DB:UniProt].","molecular_requirements":"The heterodimer was tested, not ITGA6 alone. The beta4 sequence WPNSDP (residues 167-172) grafted onto beta1 enhanced IGF1 binding; the IGF1 R36E/R37E mutant did not bind or form the ternary complex [PMID:22351760].","affinity_potency":[],"species_and_systems":"Human proteins; assay details beyond a direct binding assay are not reported in our evidence [PMID:22351760].","localisation_and_range":"IGF1 is flagged secreted [flag]; the integrin acts at the cell surface in ternary complex with IGF1R [PMID:22351760].","caveats":"Abstract-only read. Evidence concerns the ITGA6:ITGB4 heterodimer, with the recognition determinant on beta4, so ITGA6 alone is not shown.","key_references":[{"PMID":"22351760","why":"Direct alpha6beta4 binding to IGF1 and ternary complex"}],"covers":["LR002765","LR006011"]},"LR007265":{"pair":"IGF1 -> ITGA6:ITGB4","headline":"Supported by a direct-binding study of integrin alpha6beta4 and IGF1 (via UniProt) plus a computational keloid study.","interaction_type":"direct binding","direction_and_effect":"UniProt states ITGA6:ITGB4 binds IGF1 and that this binding is essential for IGF1 signaling, and that IGF1 forms a ternary complex with IGF1R [DB:UniProt] [PMID:22351760]. The only verified paper is computational: single-cell communication analysis of keloid tissue ranked an IGF1-ITGA6+ITGB4 pathway among fibroblasts, epithelial and HSC CD34+ cells [PMID:41508965].","molecular_requirements":"Both integrin chains are listed together as the receptor complex [DB:UniProt]; subunit requirement was not separately tested in our evidence.","affinity_potency":[],"species_and_systems":"The keloid study is human transcriptomic data (GSE181316) [PMID:41508965]; the binding work is cited in UniProt but is not itself among the verified papers here.","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"The verified paper is computational inference, not a binding or functional assay, and was read as an abstract only [PMID:41508965]. Binding support comes only through UniProt annotations.","key_references":[{"PMID":"41508965","why":"Computational IGF1-ITGA6+ITGB4 communication in keloid"}],"covers":["LR007265"]},"LR010937":{"pair":"IGFBP1 -> IGF2","headline":"Database-supported IGFBP1-IGF2 binding with an inhibitory label; no curated paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory: IGFBP1 binds IGF forming IGF:IGFBP1 [DB:Reactome]; UniProt says IGFBP1 binds IGF1 and IGF2 equally well [DB:UniProt].","molecular_requirements":"Reconstituted complex of IGF2 and IGFBP1 [DB:BioGRID]; no subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; assays listed are reconstituted complex, anti-tag co-immunoprecipitation and bio-layer interferometry [DB:BioGRID][DB:IntAct].","localisation_and_range":"IGF2 is annotated as secreted [flag]; IGFBP1 has no localisation flag.","caveats":"No curator-verified paper (four candidates judged as a different entity). Evidence is database records only; no affinity reported.","key_references":[],"covers":["LR010937"]},"LR002774":{"pair":"IGFBP3 -> TMEM219","headline":"One abstract-level study reports TMEM219 as a membrane receptor binding IGFBP-3 and mediating caspase-8-dependent apoptosis.","interaction_type":"direct binding","direction_and_effect":"TMEM219 (IGFBP-3R) binds IGFBP-3 specifically but not other IGFBP species; it mediates IGFBP-3-induced caspase-8-dependent apoptosis, and knockdown attenuated while overexpression enhanced the effect [PMID:20353938]. Curator labels it antagonist-direction in effect; UniProt describes IGF-independent antiproliferative and apoptotic effects via TMEM219 [DB:UniProt].","molecular_requirements":"IGFBP-3R is a single-span membrane protein that physically interacts with and activates caspase-8 [PMID:20353938]. Co-receptors: not reported.","affinity_potency":[],"species_and_systems":"Human proteins; cancer cells in vitro and breast and prostate cancer xenografts in athymic nude mice [PMID:20353938]. The mouse pair is marked as projected from human evidence.","localisation_and_range":"IGFBP3 is annotated as secreted and TMEM219 as transmembrane [flag]; the paper calls the receptor a single-span membrane protein [PMID:20353938].","caveats":"Abstract-only read; the abstract is truncated in the dossier. IntAct and Reactome records trace to the same paper (co-immunoprecipitation, solid phase assay) [DB:IntAct][DB:Reactome], so they are not independent. No affinity reported.","key_references":[{"PMID":"20353938","why":"Identifies IGFBP-3R (TMEM219) as IGFBP-3-specific death receptor"}],"covers":["LR002774","LR006020"]},"LR010946":{"pair":"IGFBP4 -> IGF1","headline":"Database-supported IGFBP4-IGF1 binding with crystal structures; no curated paper, classed as ligand-ligand.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, class Ligand-Ligand; Reactome lists an IGF:IGFBP4 complex in the extracellular region [DB:Reactome].","molecular_requirements":"Structures with a chain of each protein are deposited [DB:PDB 1WQJ][DB:PDB 2DSP]; UniProt notes IGFBP4 binds IGF2 more than IGF1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human only; assays listed include reconstituted complex, X-ray crystallography and molecular sieving [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (five candidates judged as a different entity). Database records only; no affinity.","key_references":[],"covers":["LR010946"]},"LR004277":{"pair":"IGFBP4 -> LRP6","headline":"One abstract-level study: IGFBP-4 interacts with the Wnt co-receptor LRP6 and blocks Wnt3A binding.","interaction_type":"direct binding","direction_and_effect":"IGFBP-4 physically interacted with LRP6 and inhibited Wnt3A binding to it, inhibiting canonical Wnt signalling [PMID:18528331]. Curator effect: antagonist.","molecular_requirements":"Interaction reported with both Frizzled 8 and LRP6 as a Wnt receptor/co-receptor pair; whether LRP6 alone suffices is not reported in our evidence [PMID:18528331].","affinity_potency":[],"species_and_systems":"Mouse cardiogenesis model per curator note; IntAct lists anti-tag co-immunoprecipitation from the same paper [PMID:18528331][DB:IntAct]. The human pair is marked as projected from mouse.","localisation_and_range":"IGFBP4 is annotated as secreted; LRP6 as transmembrane [flag].","caveats":"Abstract-only read; co-immunoprecipitation evidence, no affinity. The IntAct record derives from the same paper, so it is not independent.","key_references":[{"PMID":"18528331","why":"IGFBP-4 binds LRP6 and Frizzled 8, blocks Wnt3A"}],"covers":["LR000845","LR004277"]},"LR000848":{"pair":"IHH -> BOC","headline":"Crystal structures and binding show all mammalian Hedgehog proteins, including IHH, bind BOC; abstract only.","interaction_type":"direct binding","direction_and_effect":"X-ray structures of Hh proteins alone and in complex with active domains of CDO and BOC show that all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Hh-BOC binding is a co-receptor-type interaction; the paper reports it as positively linked to Hh signalling only in the background of Ihog family relatives [PMID:20519495]. IntAct and UniProt cite the same paper [DB:IntAct] [DB:UniProt].","molecular_requirements":"BOC binds Hh via its active domain; PTCH and SMO are separate membrane components [PMID:20519495].","affinity_potency":[],"species_and_systems":"Recombinant proteins; Sonic, Indian and Desert Hh studied, so IHH is covered by the paper's general statement [PMID:20519495]. PDB 3N1M and 3N1P hold Q14623 (IHH) with Q9BWV1 (BOC) [DB:PDB 3N1M]. Mouse pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only; the abstract is truncated in the dossier and affinity for IHH-BOC is not reported. The paper says the Hh-CDO interaction is weakened at low pH.","key_references":[{"PMID":"20519495","why":"Structures of Hh proteins with CDO and BOC"}],"covers":["LR000848","LR004278"]},"LR007256":{"pair":"IHH -> CDON:PTCH1","headline":"Mouse joint genetics links IHH and CDON in apoptosis, but a direct IHH-CDON:PTCH1 complex is not shown.","interaction_type":"functional only","direction_and_effect":"In a mouse Ihh E95K brachydactyly model, IHH and its interacting partners CDON and GAS1 regulate apoptosis at the joint interzone; the model proposes CDON acts as a dependence receptor driving cavitation when IHH is low, and high IHH suppresses this [PMID:38472182]. In a Gli1-luciferase assay CDON showed no effect alone or with GAS1 on WT or mutant IHH signalling [PMID:38472182]. The effect is reported as IHH antagonising CDON-mediated apoptosis [PMID:38472182].","molecular_requirements":"CDON and PTCH1 are listed as one complex, but the paper tests CDON, not PTCH1 as a partner [PMID:38472182]. Structural IHH-CDON binding is in the single-chain pair [DB:PDB 3N1F].","affinity_potency":[],"species_and_systems":"Mouse genetics, chick neural tube electroporation and cell assays [PMID:38472182]. The curator recorded human species for ligand and receptor.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"The luciferase result shows no CDON effect on IHH signalling, while the mechanism is apoptosis rather than canonical signalling. No binding assay in this paper for the complex. Dossier cites the full text but the evidence sentence is from the abstract.","key_references":[{"PMID":"38472182","why":"IHH, CDON and GAS1 regulate joint-interzone apoptosis"}],"covers":["LR007256"]},"LR002783":{"pair":"IHH -> GPC3","headline":"One mouse liver abstract reports GPC3-Indian Hh binding changes; mechanism is competition with patched-1.","interaction_type":"direct binding","direction_and_effect":"The study tested the hypothesis that GPC3 down-regulates Hh signalling by competing with patched-1 for HH binding; GPC3-Indian HH binding fell at peak proliferation in mouse liver, followed by a rise in glioblastoma 1 protein [PMID:23665349]. Effect direction is not reported in our evidence beyond the hypothesis.","molecular_requirements":"Co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse liver regeneration [PMID:23665349]; the human pair is ortholog-inferred.","localisation_and_range":"GPC3 is flagged non-secreted [flag], consistent with a membrane-bound glypican; range from annotation only.","caveats":"Abstract only; the binding assay type is not stated in the dossier. Binding was measured as a change over time in tissue, not a purified-protein affinity. A single paper.","key_references":[{"PMID":"23665349","why":"GPC3-Indian Hh binding in regenerating mouse liver"}],"covers":["LR002783","LR006026"]},"LR007292":{"pair":"IL11 -> IL11RA:IL6ST","headline":"IL-11 signals through an IL11RA plus gp130 complex; the evidence is abstract-level and partly background.","interaction_type":"direct binding","direction_and_effect":"IL-11 is an agonist at the complex; GtoPdb lists IL11 as agonist for both IL11RA and IL6ST [DB:GtoPdb]. UniProt says binding to the receptor formed by IL6ST and IL11RA activates a signalling cascade promoting cell proliferation [DB:UniProt].","molecular_requirements":"Both chains are needed. Co-IP shows multiple copies of IL-11, IL-11R and gp130 in a complex, proposed as a hexamer of two of each [PMID:10948192]. gp130 is named as the shared transducing subunit of the high-affinity receptor [PMID:7670098]. A mutant (I171D) still binds IL-11Ralpha but fails to recruit gp130 [PMID:10504396]. Both IL11RA and IL6ST appear as chains in structures 8DPS, 8DPT and 8DPU [DB:PDB 8DPS].","affinity_potency":[],"species_and_systems":"Human IL-11 and receptor components; co-IP used differentially tagged soluble components [PMID:10948192]. Human receptor cloned from cDNA libraries, with an isoform lacking the cytoplasmic domain also found [PMID:7670098].","localisation_and_range":"IL6ST is flagged transmembrane and the complex as a receptor [flag]; soluble IL11RA can drive trans-signalling [DB:UniProt].","caveats":"All papers are abstract-only. For 10504396 and 7670098 the receptor usage is background rather than the paper's own result. No affinity value for the full complex is reported in our evidence. A review-only paper was excluded.","key_references":[{"PMID":"10948192","why":"hexameric IL-11/IL-11R/gp130 complex by co-IP"},{"PMID":"7670098","why":"cloning of human IL-11 receptor, gp130 as transducer"},{"PMID":"10504396","why":"epitopes for IL-11Ralpha and gp130 recruitment"}],"covers":["LR007292"]},"LR004286":{"pair":"IL11 -> IL6ST","headline":"IL-11 contacts gp130 directly within an IL-11R-containing complex; gp130 alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"IL-11 sites II and III are independent gp130-binding epitopes, both essential for gp130 dimerization [PMID:10948192]. GtoPdb lists IL11 as agonist at IL6ST [DB:GtoPdb].","molecular_requirements":"IL-11R is also required: a stable IL-11/IL-11R/gp130 complex forms, proposed as 2:2:2 [PMID:10948192]. High-affinity IL-11 binding appeared to require both NR1 (IL-11Ralpha) and gp130 [PMID:7957045]. Treat this as a complex-dependent pair, not a standalone IL11-IL6ST interaction.","affinity_potency":[{"value":"Kd = 300-800 pM","assay":"high-affinity IL-11 binding needing NR1 plus gp130","system":"mouse, Ba/F3 cells","cite":"PMID:7957045"}],"species_and_systems":"Co-IP and native PAGE used tagged ligand and soluble receptors [PMID:10948192]. Cloning and binding were in mouse Ba/F3 cells [PMID:7957045]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"IL6ST is flagged transmembrane, IL-11 secreted [flag].","caveats":"Both papers are abstract-only. The 7957045 evidence is about the NR1 plus gp130 requirement, not a direct IL-11 to gp130 contact, and the dossier labels the species as human although the paper is murine.","key_references":[{"PMID":"10948192","why":"IL-11 gp130-binding epitopes in a hexameric complex"},{"PMID":"7957045","why":"high-affinity binding needs gp130 with NR1"}],"covers":["LR000856","LR004286"]},"LR000857":{"pair":"IL12A -> IL12RB1","headline":"IL12A (p35) to IL12RB1 rests on IL-12 receptor literature that mainly concerns the heterodimeric cytokine; direct evidence for this chain pair is thin.","interaction_type":"database-asserted only","direction_and_effect":"IL-12 is an agonist; GtoPdb lists IL12A-IL12RB1 as agonist [DB:GtoPdb]. IL-12Rbeta2-deficient mice lost all detectable IL-12-induced functions [PMID:11086056].","molecular_requirements":"The curator note says IL-12 is the IL12A:IL12B heterodimer and the receptor needs IL12RB1 and IL12RB2 [PMID:11086056]. In mouse, IL-12Rbeta1 is the subunit primarily responsible for binding IL-12 [PMID:11086056]. IL12RB1 chain appears with a P42701 chain in structures 8XRP and 8YI7 [DB:PDB 8XRP].","affinity_potency":[],"species_and_systems":"The only paper used IL12RB2-knockout mouse splenocytes (T and NK cells); dossier tags it human. Ortholog-inferred for human, direct for mouse. IntAct records a FACS-based association [DB:IntAct].","localisation_and_range":"IL12A is flagged secreted [flag].","caveats":"The sole paper is abstract-only and tests IL12RB2, not IL12RB1 binding to p35. Reactome records are for 'Interleukin-12' as a whole [DB:Reactome]. No affinity is reported.","key_references":[{"PMID":"11086056","why":"IL12RB2 knockout; notes IL12RB1 primarily binds IL-12 in mouse"}],"covers":["LR000857","LR004287"]},"LR011729":{"pair":"IL13 -> IL13:IL13RA1:IL4R","headline":"Complex row in which IL13 sits on both sides; no judged papers, supported only by database records for IL13 with IL13RA1 and IL4R.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states IL13 acts through receptors comprising the IL4R chain and the IL13RA1 chain, activating JAK1 and TYK2 and then STAT6 [DB:UniProt]. GtoPdb lists IL13 with IL13RA1 and with IL4R as agonist [DB:GtoPdb].","molecular_requirements":"IL13RA1 and IL4R chains both needed per UniProt [DB:UniProt]. Structures of IL13 with IL13RA1 exist [DB:PDB 3BPO]; binding measured by isothermal titration calorimetry and surface plasmon resonance in IntAct [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human records only; no curated paper on this complex row in our evidence.","localisation_and_range":"IL13 flagged secreted, non-transmembrane [flag].","caveats":"No paper was judged for this row (two are pending). The receptor entity lists IL13 itself as a member, so it is a ligand-bound-complex representation rather than a plain receptor. Support rests on databases alone.","key_references":[],"covers":["LR011729"]},"LR010685":{"pair":"IL13 -> IL13RA2:IL4R","headline":"No evidence that IL13RA2 and IL4R form a receptor complex; the one verified paper says IL13RA2 is a separate decoy.","interaction_type":"conflicting","direction_and_effect":"One verified negative: IL-13Ralpha2 binds IL-13 with high affinity but lacks the cytoplasmic domain for signalling, and the receptor is IL-4Ralpha plus IL-13Ralpha1 [PMID:11003391]. UniProt describes IL13RA2 as a decoy [DB:UniProt].","molecular_requirements":"The signalling receptor comprises IL4R and IL13RA1 [DB:UniProt] [PMID:11003391]; IL13RA2 acts separately.","affinity_potency":[],"species_and_systems":"Mouse gene paper (abstract) [PMID:11003391]; human database records.","localisation_and_range":"Not reported in our evidence beyond annotation flags.","caveats":"Paper judged pair_absent for this combination; one review-only and one abstract-insufficient also excluded. Database records support IL13 binding IL13RA2 alone [DB:BioGRID] [DB:PDB 3LB6], not the IL13RA2:IL4R combination. This row likely reflects a pairing artefact.","key_references":[{"PMID":"11003391","why":"States IL13RA2 is separate from the IL4R:IL13RA1 receptor"}],"covers":["LR010685"]},"LR004295":{"pair":"IL15 -> IL15RA","headline":"IL15 binds IL15RA with high affinity, shown in mouse cloning and human soluble-receptor work; well supported.","interaction_type":"direct binding","direction_and_effect":"IL-15R alpha alone binds IL-15 with affinity equal to that of the heterotrimeric IL-2R for IL-2 [PMID:7641685]. Soluble full ectodomain sIL-15R alpha is a high-affinity IL-15 antagonist [PMID:15265897], while the recombinant sushi domain acts as an agonist through IL-15R beta/gamma [PMID:16284400].","molecular_requirements":"IL15RA is the private alpha chain; the IL15 high-affinity receptor combines it with IL-2R beta and gamma [PMID:15265897]. The sushi domain bears most of the binding affinity [PMID:16284400]. Sushi does not affect function of the tripartite membrane receptor [PMID:16284400].","affinity_potency":[],"species_and_systems":"Murine IL-15R alpha cloned and expressed [PMID:7641685]; human cell lines and COS-7 for shedding [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag]. Receptor shed as 42 kDa soluble form [PMID:15265897]; IL15 expressed with IL15RA on producer cells (trans-presentation) per UniProt [DB:UniProt].","caveats":"All abstracts only. Soluble forms can antagonize or agonize depending on domain used, which matters for shed-receptor interpretation. Numeric affinity not reported in our evidence.","key_references":[{"PMID":"7641685","why":"Cloning of murine IL-15R alpha; binding"},{"PMID":"15265897","why":"Soluble human sIL-15R alpha as antagonist"},{"PMID":"16284400","why":"Sushi domain as agonist"}],"covers":["LR000865","LR004295"]},"LR000866":{"pair":"IL15 -> IL2RB","headline":"IL15 uses IL2RB (with IL2RG) for binding and signalling; shown by transfection in 1994.","interaction_type":"direct binding","direction_and_effect":"IL-15 requires the IL-2R beta and gamma chains for binding and signaling in transfected cells [PMID:8026467]. GtoPdb lists agonist [DB:GtoPdb]. The soluble IL15RA acts as an IL-15 antagonist [PMID:15265897].","molecular_requirements":"Both beta and gamma chains are needed; the IL-2R alpha subunit is not involved in IL-15 binding [PMID:8026467]. High-affinity receptors share IL-2R beta and gamma with a private alpha chain [PMID:15265897].","affinity_potency":[],"species_and_systems":"Cells transfected with IL-2R subunits [PMID:8026467]; human cell lines [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag].","caveats":"Both abstracts only. An IL-15-specific additional component was implied but not identified in the 1994 paper [PMID:8026467]. Affinity not reported in our evidence.","key_references":[{"PMID":"8026467","why":"IL-15 binding and signalling need IL-2R beta and gamma"},{"PMID":"15265897","why":"Shared beta/gamma with private alpha chains"}],"covers":["LR000866","LR004296"]},"LR010766":{"pair":"IL16 -> GRIN2C","headline":"Database-asserted only: a single holdup-assay record links IL16 and GRIN2C; no papers support a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. IntAct EBI-66974126 reports a direct interaction by holdup assay [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Holdup assay (IntAct, PMID 36115835 per record) [DB:IntAct]; species of the assay is not reported in our evidence.","localisation_and_range":"IL16 is annotated as secreted [flag]; no localisation annotation for the partner in our evidence.","caveats":"No curated paper evidence; the partner was judged a different entity in our curation. A binding-assay hit between two proteins does not establish a ligand-receptor signalling relationship.","key_references":[],"covers":["LR010766"]},"LR000875":{"pair":"IL18 -> IL18RAP","headline":"IL-18 engages IL18RAP as the signalling second chain within a ternary complex; structural and functional evidence, but not direct binding on its own.","interaction_type":"direct binding","direction_and_effect":"IL-18 signals through IL-18R beta (IL18RAP) as agonist: both IL-1R-rp1 and AcPL were required for NF-kappaB and JNK activation in response to IL-18 [PMID:9792649]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL18RAP does not bind IL-18 alone: AcPL alone was unable to bind IL-18 with any appreciable affinity [PMID:9792649]. A crystal structure shows IL-18 with both receptor ectodomains; IL-18R beta D2 and D3 contact IL-18/IL-18R alpha while D1 does not [PMID:25500532]. UniProt agrees IL18RAP is not the binding chain [DB:UniProt]. IL18R1 is therefore needed.","affinity_potency":[],"species_and_systems":"Structure with human IL-18 and receptor ectodomains [PMID:25500532]; reporter assays with species unspecified [PMID:9792649]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers were read as abstracts (structure paper also has full-text excerpts). IL18RAP binds only as part of the ternary complex, so single-chain scoring in CCC tools may overstate a direct ligand-IL18RAP interaction.","key_references":[{"PMID":"25500532","why":"Crystal structure of the IL-18/IL-18R alpha/IL-18R beta complex"},{"PMID":"9792649","why":"IL18RAP required for IL-18 signalling"}],"covers":["LR000875","LR004305"]},"LR002792":{"pair":"IL1B -> ITGB3","headline":"IL-1beta binds integrin alphavbeta3 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alphaVbeta3); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGAV:ITGB3 binds to IL1B and this binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002792","LR006035"]},"LR000884":{"pair":"IL1F10 -> IL1R1","headline":"IL-1HY2 (IL1F10) protein binds soluble IL-1 receptor type I in one abstract-level report; effect not established.","interaction_type":"direct binding","direction_and_effect":"Purified recombinant IL-1HY2 bound soluble IL-1 receptor type I [PMID:11278614]. The paper notes 37% identity with the IL-1 receptor antagonist and a similar predicted fold, but the effect direction is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond soluble IL-1RI; no accessory chain was tested.","affinity_potency":[],"species_and_systems":"Purified recombinant human IL-1HY2 with soluble human receptor; the mouse pair is inferred [PMID:11278614].","localisation_and_range":"IL-1HY2 protein is secreted from mammalian cells [PMID:11278614].","caveats":"Abstract only; no affinity, no functional readout at IL1R1. Other papers judged for this pair were insufficient or about a different entity.","key_references":[{"PMID":"11278614","why":"Cloning of IL-1HY2 and binding to soluble IL-1RI"}],"covers":["LR000884","LR004314"]},"LR006815":{"pair":"IL1RN -> IL2RA","headline":"Only a GtoPdb antagonist record asserts this pair; no paper evidence, and judged papers named a different entity.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Antagonist [DB:GtoPdb]; no affinity is given.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experimental system in our evidence.","localisation_and_range":"IL1RN flagged secreted [flag].","caveats":"No verified papers; judged rows were different_entity. The pair rests on one database record and may be spurious.","key_references":[],"covers":["LR006815"]},"LR011738":{"pair":"IL2 -> IL2:IL2RA:IL2RB:IL2RG","headline":"IL-2 binds its receptor chains; a structural and database record set supports the IL-2 receptor assembly, but no paper is verified for this complex entry.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL2 with IL2RA, IL2RB and IL2RG each as Agonist [DB:GtoPdb]. UniProt says IL-2 binds the high-affinity trimeric IL-2R (IL2RA, IL2RB, IL2RG) or the low-affinity dimeric IL-2R (IL2RB and IL2RG) [DB:UniProt].","molecular_requirements":"High-affinity form needs IL2RA, IL2RB and IL2RG; IL2RB and IL2RG suffice for the dimeric form [DB:UniProt]. Crystal structures contain chains of IL2 (P60568) and IL2RG (P31785) [DB:PDB 2B5I] [DB:PDB 2ERJ]. Reactome lists IL2RA:IL2RB binding IL2RG [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human; recombinant crystal structures and BioGRID Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"IL-2 flagged secreted [flag].","caveats":"Two papers are pending, none verified. The entry is a complex that includes the ligand as a member, so it is a representation of the assembled receptor rather than a ligand to receptor pair. Database support only.","key_references":[],"covers":["LR011738"]},"LR000893":{"pair":"IL22 -> IL22RA1","headline":"IL-22 binds IL22RA1 directly, shown by a 1.9 A crystal structure and cross-linking; well supported in human.","interaction_type":"direct binding","direction_and_effect":"IL-22 binds IL-22R1 first and this dimer then recruits IL-10R2 [PMID:18675809]; IL22RA1 (CRF2-9) binds IL-TIF independently by cross-linking [PMID:11035029]. GtoPdb lists an agonist (pEC50) [DB:GtoPdb].","molecular_requirements":"IL22RA1 binds IL-22 alone; binding to the IL22RA1:IL10RB complex is greater than to IL22RA1 alone [PMID:11035029][DB:UniProt]. Site-directed mutagenesis confirmed key interface residues [PMID:18675809].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, crystal structure and transfected cells [PMID:18675809][PMID:11035029]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-22 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. Two other rows were judged different_entity.","key_references":[{"PMID":"18675809","why":"1.9 A crystal structure of IL-22/IL-22R1"},{"PMID":"11035029","why":"cross-linking of IL-22 to IL22RA1 chain"}],"covers":["LR000893","LR004323"]},"LR007319":{"pair":"IL26 -> IL10RB:IL20RA","headline":"IL-26 signals through an IL-20R1/IL-10R2 heterodimer; functional evidence from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"The active IL-26 receptor complex is a heterodimer of IL-20R1 and IL-10R2; signalling activates STAT1 and STAT3 and is blocked by neutralising antibodies to either subunit (agonist) [PMID:14764663].","molecular_requirements":"Both chains are required: blocking either subunit stopped signalling. IL-10R2 is broadly expressed while few tissues express IL-20R1, so responsiveness is restricted by IL-20R1 [PMID:14764663]. IL-10, IL-19, IL-20, IL-22 and IL-24 did not signal through this combination [PMID:14764663]. Reactome lists the same two receptor chains with JAK1 and TYK2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human; experiments with human proteins [PMID:14764663].","localisation_and_range":"IL-26 is flagged secreted; the complex is flagged transmembrane [flag].","caveats":"Single paper, read as abstract only; no direct binding measurement or affinity reported in our evidence [PMID:14764663].","key_references":[{"PMID":"14764663","why":"Deorphanisation of the IL-26 receptor; specific among five IL-10-family cytokines tested."}],"covers":["LR007319"]},"LR001865":{"pair":"IL36RN -> IL1RL2","headline":"IL-36Ra binds IL-36 receptor (IL1RL2) and is an antagonist; one binding paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Immobilized ectodomain screen: IL-36Ra bound only the IL-36 receptor among IL-1 receptor family members [PMID:22315422]. GtoPdb: Antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant ectodomains; human PBMC assays [PMID:22315422]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Abstract only. The paper is mainly about IL-38; IL-36Ra is a comparator. Dose-response was non-classical and both increased LPS-induced IL-6 twofold in dendritic cells [PMID:22315422]. No affinity.","key_references":[{"PMID":"22315422","why":"IL-36Ra and IL-38 bind only IL-36 receptor"}],"covers":["LR001865","LR005210"]},"LR007328":{"pair":"IL4 -> IL2RG:IL4R","headline":"IL4 forms a ternary complex with IL4R and the common gamma chain (type 1 receptor), shown by direct physical evidence.","interaction_type":"direct binding","direction_and_effect":"A ternary complex of IL-4 with soluble IL-4R and gamma c was shown in solution [PMID:7795521]; gamma c augments IL-4 binding and is needed for IL-4-driven IRS-1 phosphorylation [PMID:8266078]. GtoPdb lists both chains as agonist targets [DB:GtoPdb].","molecular_requirements":"Both chains are needed for the type 1 complex: IL4R dimerises with IL2RG [DB:UniProt]. The gamma c association with the stable IL-4/sIL-4R complex is described as in the millimolar range [PMID:7795521], i.e. weak.","affinity_potency":[],"species_and_systems":"Human soluble receptor domains by gel filtration and electrophoresis [PMID:7795521]; lymphoid cells for cross-linking [PMID:8266078].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Gamma c binds only weakly to the IL-4/IL-4R complex [PMID:7795521]. Abstracts only. The third confirmed paper does not address gamma c [PMID:7918378].","key_references":[{"PMID":"7795521","why":"Ternary complex IL-4/sIL-4R/gamma c isolated"},{"PMID":"8266078","why":"Cross-linking and signalling requirement of gamma c"}],"covers":["LR007328"]},"LR004349":{"pair":"IL9 -> IL2RG","headline":"IL9 signals through IL2RG (common gamma) together with IL9R; one functional human paper, abstract-level.","interaction_type":"functional only","direction_and_effect":"IL-9 acts through the IL-9R complex of IL-9Ralpha and gammac, activating JAK1/JAK3 and STAT-1/3/5 [PMID:9535918]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"gammac is needed with IL-9Ralpha; its membrane-proximal segment and IL-9Ralpha Tyr336 are crucial for signalling [PMID:9535918].","affinity_potency":[],"species_and_systems":"Human; mast cell and T cell lines [PMID:9535918]. Mouse pair ortholog-inferred.","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Chain-only row; gammac is a co-receptor and does not bind IL-9 alone in our evidence. Abstract only.","key_references":[{"PMID":"9535918","why":"IL-9Ralpha/gammac heteromerization and signalling requirements"}],"covers":["LR000926","LR004349"]},"LR007922":{"pair":"INHA -> ACVR1B:ACVR2B","headline":"INHA on ACVR1B plus ACVR2B: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; UniProt says the ACVR2B type 2 receptor binds inhibin-A/INHA-INHBA [DB:UniProt]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2B carries the database evidence; the type I chain is not specifically evidenced in our evidence.","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007922"]},"LR000929":{"pair":"INHA -> ACVR2B","headline":"Inhibin competes with BMPs for ACVR2B, facilitated by betaglycan; conflicting rows on one abstract.","interaction_type":"conflicting","direction_and_effect":"Inhibin competes with BMPs for type II activin receptors, facilitated by betaglycan [PMID:12493742]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"Betaglycan (TGFBR3) facilitates the competition [PMID:12493742].","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; abstract-level read. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag].","caveats":"A pair_absent judgement for the same PMID coexists with the confirmed one; the confirmed read is from the abstract only, and names ACVR2B only generically as type II receptors.","key_references":[{"PMID":"12493742","why":"Inhibin and betaglycan versus activin/BMP at type II receptors"}],"covers":["LR000929","LR004352"]},"LR007931":{"pair":"INHA:INHBB -> ACVR1:ACVR2A","headline":"Inhibin A:activin B to ACVR1:ACVR2A rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records ACVR2A with INHBB and INHA (Reconstituted Complex, Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I (ACVR1) plus type II (ACVR2A) pair; whether this heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007931"]},"LR008255":{"pair":"INHBA -> ACVR1B:ACVR2B","headline":"Activin binds ACVR2B directly and recruits ACVR1B; one verified abstract-level paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Activin binds directly to ActR-IIB, and this complex associates with ActR-IB, which does not bind ligand on its own; ActR-IB becomes hyperphosphorylated in the complex, requiring ActR-IIB kinase activity [PMID:8622651]. Agonist effect; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Both chains act in sequence: ACVR2B is the primary receptor and ACVR1B a downstream transducer, so ACVR1B alone does not bind ligand [PMID:8622651]. UniProt states the same for type-2 receptors [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in transfected cells [PMID:8622651]; structure PDB 7OLY with ActRIIB-Alk4 fusion [DB:PDB 7OLY].","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"Paper read as abstract only; the abstract does not say which activin form was used, so the INHBA-specific link is not shown. Affinity not reported.","key_references":[{"PMID":"8622651","why":"Activin binds ActR-IIB, which recruits and phosphorylates ActR-IB."}],"covers":["LR008255"]},"LR004358":{"pair":"INHBA -> ENG","headline":"Activin A interacts with endoglin only when type II activin receptors are coexpressed; verified abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Endoglin interacts with activin-A but requires coexpression of the ligand-binding kinase receptor; it does not bind ligands on its own [PMID:9872992].","molecular_requirements":"Association with activin-A is via activin type II receptors ActRII and ActRIIB, regardless of the type I partner [PMID:9872992]. Endoglin acts as an accessory protein, a co-receptor role [PMID:9872992].","affinity_potency":[],"species_and_systems":"Human endothelial and leukaemic cells, affinity labelling [PMID:9872992]; mouse pair projected.","localisation_and_range":"Ligand secreted flag [flag]; endoglin is described as a transmembrane glycoprotein [PMID:9872992].","caveats":"Not independent direct binding; needs type II receptors. Abstract only; both confirmed rows may share this evidence.","key_references":[{"PMID":"9872992","why":"Endoglin interacts with activin-A through ActRII/ActRIIB."}],"covers":["LR000935","LR004358"]},"LR000938":{"pair":"INHBB -> ACVR1B","headline":"Activin B activates ACVR1B (ALK4) with ActRIIA in vitro; one abstract-level paper, plus database records.","interaction_type":"functional only","direction_and_effect":"Activin B, like all activins, activated an ActRIIA plus ALK4 combination with varying potency; effect is agonist [PMID:15196700]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Signalling used the ActRIIA/ALK4 receptor combination, so ACVR1B alone may not suffice [PMID:15196700]. The same paper says activin B prefers ActRIIA/ALK7 [PMID:15196700].","affinity_potency":[],"species_and_systems":"Curator fields list human ligand and receptor [PMID:15196700]; the pair's mouse entry is ortholog-inferred. Beta-cell line MIN6 is named in the abstract [PMID:15196700].","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine. Receptor transmembrane flag is not set.","caveats":"Evidence is abstract only [PMID:15196700]; potency differences are not given numerically. Binding is supported by BioGRID records for INHBB with ACVR2A, not ACVR1B [PMID:9202237].","key_references":[{"PMID":"15196700","why":"Activin isoforms and type I receptor usage (ALK4, ALK7)"}],"covers":["LR000938","LR004361"]},"LR010982":{"pair":"INHBC -> ACVR1C:ACVR2A","headline":"INHBC to ACVR1C:ACVR2A rests on one abstract-level paper that supports ALK7 only.","interaction_type":"functional only","direction_and_effect":"Recombinant activin C activated SMAD2/3 signalling via ALK7 and suppressed lipolysis in human adipocytes [PMID:39283655].","molecular_requirements":"ALK7 is implicated; ACVR2A is not addressed in our evidence [PMID:39283655].","affinity_potency":[],"species_and_systems":"Human immortalized adipocytes [PMID:39283655].","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Abstract only; the type II chain has no direct support here, and no database records are held.","key_references":[{"PMID":"39283655","why":"Activin C acts via ALK7 in adipocytes"}],"covers":["LR010982"]},"LR010991":{"pair":"INHBE -> ACVR1C:ACVR2A","headline":"Activin E to ACVR1C:ACVR2A complex rests on UniProt text only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records that INHBE signals via ACVR1C to activate SMAD2/3 signalling and suppress PPARG target genes [DB:UniProt]. UniProt also lists ACVR1C as a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt].","molecular_requirements":"The type II partner in this complex is not addressed by the UniProt text in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"No papers were judged for this complex (two rows pending). Support is database annotation only, and covers ACVR1C rather than the complex.","key_references":[],"covers":["LR010991"]},"LR000947":{"pair":"INSL3 -> RXFP2","headline":"INSL3 is the established ligand of RXFP2 (LGR8), with binding, cAMP signalling and structure-function data.","interaction_type":"direct binding","direction_and_effect":"INSL3 stimulated cAMP production in LGR8-expressing cells but not LGR7, and ligand-receptor cross-linking showed their interaction [PMID:12114498]. INSL3 behaved as a partial agonist at RXFP2, with low maximal cAMP response but high binding potency [PMID:15649866]. INSL3 can only bind and activate RXFP2 [PMID:22973049]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Binding is mainly via the INSL3 B-chain, while A-chain elements, including its N terminus, are needed for activation [PMID:20560146] [PMID:18434306]. The RXFP2 ectodomain holds the primary high-affinity site and a secondary lower-affinity site lies in the transmembrane region [PMID:15649866].","affinity_potency":[{"value":"pKi 9.34000015258789 to 9.699999809265137","assay":"GtoPdb affinity range, full agonist","system":"RXFP2","cite":"PMID:15649866"}],"species_and_systems":"Recombinant receptor-expressing cells; cultured gubernacular cells responded to INSL3 [PMID:12114498]. Curators recorded human experiments for most papers. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]. Gubernaculum expression of LGR8 is reported at transcript level [PMID:12114498].","caveats":"All shown papers were read as abstracts. Eight confirmed rows exist, four shown. The antagonist reading in [PMID:20560146] concerns a synthetic B-chain dimer, not INSL3.","key_references":[{"PMID":"12114498","why":"INSL3 identified as LGR8 ligand by cAMP and cross-linking"},{"PMID":"15649866","why":"Two-site pharmacology of RXFP1/RXFP2 with chimeras; INSL3 partial agonist"},{"PMID":"22973049","why":"INSL3 binds and activates RXFP2 only; ECD binding site"}],"covers":["LR000947","LR004370"]},"LR002819":{"pair":"INSL3 -> RXFP3","headline":"INSL3 shows weak, nonselective activity at RXFP3 in cell signalling assays; not a defined ligand.","interaction_type":"functional only","direction_and_effect":"In RXFP3-expressing cells, INSL3 gave weaker inhibition of forskolin-stimulated cAMP, ERK1/2 and NF-kappaB reporter responses than H3 relaxin [PMID:20159943].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"CHO-K1 and HEK-293 cells expressing RXFP3 and murine septal neuron SN56 cells [PMID:20159943]; receptor species not stated in the abstract.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Single abstract-only paper; INSL3 is one of several relaxin-family peptides with weak activity. Two other rows were judged a different entity and one abstract-insufficient.","key_references":[{"PMID":"20159943","why":"RXFP3 signalling by relaxin-family peptides including INSL3"}],"covers":["LR002819"]},"LR006059":{"pair":"INSL5 -> GPR142","headline":"INSL5 binds and activates the receptor named GPCR142 with nanomolar potency, but the receptor entity in this pair may be mismatched.","interaction_type":"direct binding","direction_and_effect":"Human INSL5 is a specific agonist of GPCR142: it displaces 125I-relaxin-3 with high affinity, binds in saturation assays and activates GTPgammaS and cAMP assays [PMID:15525639].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 1.5 nM","assay":"125I-relaxin-3 displacement","system":"GPCR142","cite":"PMID:15525639"},{"value":"Kd 2.5 nM","assay":"125I-INSL5 saturation binding","system":"GPCR142","cite":"PMID:15525639"},{"value":"EC50 1.3 nM and 1.2 nM","assay":"GTPgammaS and cAMP assays","system":"GPCR142","cite":"PMID:15525639"}],"species_and_systems":"Receptor-expressing cells including HEK293 with Galpha16; human INSL5 [PMID:15525639]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Abstract only. Two confirmed rows exist, one shown. INSL5 did not activate GPCR135 or LGR7 in that paper.","key_references":[{"PMID":"15525639","why":"INSL5 binds and activates GPCR142 with nanomolar affinity"}],"covers":["LR002820","LR006059"]},"LR008552":{"pair":"ITGA4:ITGB1 -> VCAM1","headline":"Integrin alpha4beta1 binding to VCAM1 rests on database records only; no paper has been judged.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which VCAM1 binds integrin alpha4beta1 [DB:Reactome]. UniProt states alpha-4/beta-1 is a receptor for VCAM1 [DB:UniProt].","molecular_requirements":"Both ITGA4 and ITGB1 are in the complex [DB:Reactome]. BioGRID has ITGA4-VCAM1 affinity capture-MS and IntAct has cross-linking associations [DB:BioGRID][DB:IntAct].","affinity_potency":[],"species_and_systems":"No experimental paper judged for this pair; species is human per the record.","localisation_and_range":"Both partners carry receptor flags and VCAM1 is flagged transmembrane [flag]; contact-mediated adhesion is implied by the plasma membrane complexes listed [DB:Reactome].","caveats":"Support is from databases alone; one pending paper not yet judged. Direction is nominal because VCAM1 is the adhesion counter-receptor. The Reactome examples also include an alpha9beta1 complex.","key_references":[],"covers":["LR008552"]},"LR002828":{"pair":"ITGB2 -> CD209","headline":"Mac-1 on neutrophils is reported to bind DC-SIGN; ITGB2 evidence is background statement only.","interaction_type":"functional only","direction_and_effect":"DC-neutrophil interaction needs DC-SIGN binding to Mac-1 [PMID:16246332].","molecular_requirements":"Evidence is for the Mac-1 heterodimer; CEACAM1 is also required [PMID:16246332].","affinity_potency":[],"species_and_systems":"Human neutrophils and dendritic cells [PMID:16246332].","localisation_and_range":"Cell-contact interaction [PMID:16246332].","caveats":"Background statement in an abstract; chain-only attribution to ITGB2.","key_references":[{"PMID":"16246332","why":"DC-SIGN engages Mac-1 and CEACAM1"}],"covers":["LR002828"]},"LR006068":{"pair":"IZUMO1 -> IZUMO1R","headline":"IZUMO1 binds JUNO (IZUMO1R) in the sperm-egg interaction; crystal structure and human oocyte antibody blocking.","interaction_type":"direct binding","direction_and_effect":"The IZUMO1-JUNO interaction is needed for sperm-oocyte interaction [PMID:27309808]. An anti-human-JUNO antibody completely blocked gamete fusion [PMID:30517645]; UniProt calls the interaction necessary adhesion but not sufficient for fusion [DB:UniProt].","molecular_requirements":"1:1 complex [DB:UniProt]. The central beta-hairpin of IZUMO1 is the main JUNO-binding platform [PMID:27309808]. UniProt notes FCRL3/MAIA replaces JUNO after adhesion [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins crystallised [PMID:27309808]; human zona-free oocytes with sperm [PMID:30517645]. Mouse pair orthology-projected.","localisation_and_range":"Both membrane-bound; juxtacrine gamete contact [PMID:27309808].","caveats":"Abstracts only. No affinity in the dossier. IZUMO1 not flagged as receptor.","key_references":[{"PMID":"27309808","why":"Crystal structure of IZUMO1-JUNO complex"},{"PMID":"30517645","why":"Anti-JUNO antibody blocks human gamete fusion"}],"covers":["LR002831","LR006068"]},"LR004376":{"pair":"JAG1 -> NOTCH2","headline":"Jagged1 binds and activates Notch2 with measured nanomolar affinity in mouse systems; also human cell-based activation.","interaction_type":"direct binding","direction_and_effect":"Mouse Jagged1 bound mouse Notch2 on cells and as a soluble ectodomain, Ca2+-dependent [PMID:10551863]. Jagged1 bound endogenous Notch2 on BaF3 cells and induced Notch2 cleavage within 15 min, nuclear translocation, hyperphosphorylation and RBP-Jkappa reporter activation (agonist) [PMID:10958687]. In human cell-based assays, ligands other than DLL4 activated NOTCH2 similarly or slightly more than NOTCH1, and MFNG inhibited NOTCH2 activation by JAG1 [PMID:32820046].","molecular_requirements":"The DSL domain of Jagged1 is the minimal binding unit and is indispensable; EGF-like repeats 1 and 2 modulate affinity [PMID:10551863]. Fringe modification affects the response [PMID:32820046].","affinity_potency":[{"value":"Kd 0.4 nM","assay":"Scatchard analysis of mJagged1 binding","system":"BaF3 cells","cite":"PMID:10551863"},{"value":"Kd 0.7 nM","assay":"Scatchard analysis of mJagged1 binding","system":"soluble Notch2 protein","cite":"PMID:10551863"}],"species_and_systems":"Binding and signalling papers used mouse proteins [PMID:10551863][PMID:10958687]; the cell-based activation paper used human proteins [PMID:32820046]. The human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag].","caveats":"All papers read as abstracts only. The kinetic data are from mouse, not human, proteins. Database records (BioGRID, Reactome) add support [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"10551863","why":"Scatchard Kd values for Jagged1-Notch2"},{"PMID":"10958687","why":"Binding and downstream cleavage and reporter activation"},{"PMID":"32820046","why":"Human cell-based activation and Fringe effects"}],"covers":["LR000953","LR004376"]},"LR000956":{"pair":"JAG2 -> NOTCH1","headline":"Jagged2 binds Notch1 directly in vitro; database records are extensive but only one paper is detailed.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch1 bound Jagged2 on cells and in solid-phase assays, Ca2+-dependent [PMID:11006133]. GtoPdb lists it as agonist [DB:GtoPdb]. Annotation: stimulatory.","molecular_requirements":"Ca2+ required [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human proteins in the one paper [PMID:11006133]. The human pair is ortholog-inferred; a mouse record exists.","localisation_and_range":"JAG2 is flagged as not secreted [flag].","caveats":"Abstract-only; affinities not given in our evidence. BioGRID, GtoPdb and Reactome records support it [DB:BioGRID][DB:GtoPdb][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding of Jagged2 to Notch1"}],"covers":["LR000956","LR004379"]},"LR002837":{"pair":"KIR2DL5A -> PVR","headline":"KIR2DL5 binds PVR directly and inhibits human NK cells; supported by one 2022 paper and IntAct records.","interaction_type":"direct binding","direction_and_effect":"KIR2DL5 engagement of PVR induced inhibitory synapse formation; blocking antibodies augmented NK cytotoxicity against PVR+ human tumours, and KIR2DL5 blockade reduced tumour growth and improved survival in humanized tumour models [PMID:36377656]. Both ITIM and ITSM of KIR2DL5 were phosphorylated and recruited SHP-1 and/or SHP-2 [PMID:36377656].","molecular_requirements":"Binding needs both the D0 and D2 domains of KIR2DL5; PVR bound KIR2DL5 but not its homolog KIR2DL4 or CD112 [PMID:36377656]. Binding depended on allele: solid for 2DL5A*001, weak for 2DL5B*00602, none for 2DL5A*005 or 2DL5B*003 [PMID:36377656]. DNAM-1, TIGIT and CD96 did not block the interaction [PMID:36377656].","affinity_potency":[{"value":"EC50 = 0.095 \u03bcM","assay":"anti-KIR2DL5 mAb F8B30 blocking KIR2DL5-PVR binding (not the ligand's own affinity)","system":"cell-based binding assay","cite":"PMID:36377656"}],"species_and_systems":"Human NK cells, 3T3 cells expressing KIR2DL5 or PVR, PVR-Ig fusion protein, humanized mouse tumour models [PMID:36377656].","localisation_and_range":"KIR2DL5 is a membrane receptor on NK cells and PVR on target cells, so contact-dependent [PMID:36377656]. Entity flags mark PVR as secreted and transmembrane [flag].","caveats":"Single paper, read as abstract plus excerpts. IntAct lists surface plasmon resonance and solid phase assay records [DB:IntAct]. The pair is written KIR2DL5A here but the paper studies several KIR2DL5 alleles with different binding, so allele matters.","key_references":[{"PMID":"36377656","why":"KIR2DL5 binds PVR and inhibits NK cells; mapping and blockade"}],"covers":["LR002837"]},"LR006077":{"pair":"KLRG1 -> CDH2","headline":"KLRG1 binds N-cadherin per one abstract-level statement; direct binding, no detail on N-cadherin.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor and binds N-cadherin; inhibition of killing was shown for E-cadherin, not N-cadherin [PMID:16461340].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Identified by expression cloning with a mouse KLRG1 tetramer; the paper's mouse-specific finding is for E-cadherin, so N-cadherin binding is not resolved to mouse [PMID:16461340]. Human pair is ortholog-inferred [flag].","localisation_and_range":"Both membrane proteins [flag].","caveats":"One paper; the N-cadherin statement is a single sentence and the functional effect is shown only for E-cadherin. Two further papers were abstract_insufficient. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds E-, N- and R-cadherins"}],"covers":["LR002842","LR006077"]},"LR004385":{"pair":"KNG1 -> BDKRB2","headline":"Kininogen-derived bradykinin and kallidin activate B2R, shown by several structures; the active ligand is a kinin peptide.","interaction_type":"direct binding","direction_and_effect":"Bradykinin and kallidin are endogenous peptide agonists of B2R, acting as vasodilators [PMID:35132089]. Complex structures of human B2R with bradykinin are reported [PMID:34518695]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The acting ligands are kinins derived from KNG1; B2R is coupled to Gq in the structures [PMID:35132089]. Intact KNG1 as ligand is not tested in our evidence.","affinity_potency":[{"value":"pIC50 7.0-9.3","assay":"GtoPdb full agonist record","system":"not specified in dossier","cite":"PMID:8302267"}],"species_and_systems":"Human B2R-Gq cryo-EM structures at 3.0 and 2.9 angstrom resolution, expressed in insect cells [PMID:35132089]; human structures also in [PMID:34518695]. PDB 7F2O, 7F6H, 7F6I [DB:PDB 7F2O].","localisation_and_range":"KNG1 is secreted [flag]; endocrine or paracrine kinin action at a membrane GPCR.","caveats":"The second paper's abstract is truncated at source. Three papers were abstract_insufficient and one pending. The precursor-versus-kinin distinction matters for expression-based scoring.","key_references":[{"PMID":"34518695","why":"B1R and B2R structures"},{"PMID":"35132089","why":"Cryo-EM B2R-Gq with bradykinin and kallidin"}],"covers":["LR000963","LR004385"]},"LR009263":{"pair":"KNG1 -> CD93","headline":"No curated paper support; one BioGRID reconstituted-complex record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex from PMID 8710908; species not reported in our evidence [DB:BioGRID].","localisation_and_range":"Not reported in our evidence.","caveats":"Curators judged two papers as different_entity and one as unresolvable, so no paper supports this pair as written. Treat as weak.","key_references":[],"covers":["LR009263"]},"LR000965":{"pair":"KNG1 -> ITGAM","headline":"Cleaved kininogen (HKa) binds the Mac-1 integrin with nanomolar affinity; the evidence is for the ITGAM:ITGB2 heterodimer.","interaction_type":"direct binding","direction_and_effect":"HKa blocked adhesion of Mac-1-transfected cells to fibrinogen and ICAM-1 in a dose-dependent manner, an inhibitory effect [PMID:10845911].","molecular_requirements":"The evidence is for the Mac-1 heterodimer (CD11b/CD18, ITGAM:ITGB2), and the ligand form tested is cleaved high-molecular-weight kininogen (HKa), not intact KNG1 [PMID:10845911].","affinity_potency":[{"value":"Kd 3.2 nM","assay":"IAsys resonant mirror optical biosensor, purified Mac-1","system":"cell-free","cite":"PMID:10845911"},{"value":"Kd 62 nM","assay":"FITC-labelled HKa cell binding","system":"Mac-1-transfected HEK 293 cells","cite":"PMID:10845911"}],"species_and_systems":"Human Mac-1 in transfected HEK 293 cells and purified protein [PMID:10845911].","localisation_and_range":"KNG1 is secreted [flag]; binds a leukocyte surface integrin.","caveats":"Abstract only. One chain alone is not shown to bind; one abstract_insufficient paper also exists for ITGAM.","key_references":[{"PMID":"10845911","why":"HKa-Mac-1 binding and adhesion block"}],"covers":["LR000965","LR004387"]},"LR001874":{"pair":"L1CAM -> ALCAM","headline":"Functional adhesion evidence only: ALCAM or L1 itself identified as endothelial binding partner for L1-CAM-high breast cancer cells.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies and recombinant-protein-coated flow channels identified ALCAM or L1 itself, but not ICAM-1, as potential binding partners on endothelial cells; L1-CAM on cancer cells promotes adherence to activated endothelium [PMID:22983139]. Direction is cancer-cell L1-CAM to endothelial ALCAM.","molecular_requirements":"Not reported in our evidence beyond a Reactome L1:ALCAM complex record [DB:Reactome R-HSA-443658].","affinity_potency":[],"species_and_systems":"Human breast cancer cells (MDA-MB231-Fra2) and human pulmonary microvascular endothelial cells; only the abstract was read [PMID:22983139]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-to-membrane adhesion between cells (juxtacrine), as implied by the cell adhesion assays [PMID:22983139]; flags list both as secreted and transmembrane [flag].","caveats":"Only one paper, abstract only; the paper says 'potential binding partners' and does not show direct binding. The ALCAM-or-L1 result is not resolved between the two.","key_references":[{"PMID":"22983139","why":"Blocking and adhesion assays implicate ALCAM"}],"covers":["LR001874","LR005216"]},"LR004394":{"pair":"L1CAM -> ERBB3","headline":"Strongest of the erbB set: reciprocal co-IP, endogenous brain co-IP and in situ proximity ligation support L1CAM-erbB3.","interaction_type":"direct binding","direction_and_effect":"Reciprocal co-IP in HEK293 cells, a proximity ligation assay, and co-IP of endogenous proteins from rat brain support physical L1CAM-erbB3 interaction [PMID:22815787]. Binding enhances the response to neuregulins [PMID:22815787].","molecular_requirements":"The Ig-like domains of L1CAM support the interaction; a DeltaIg construct was tested [PMID:22815787]. The PLA signal appeared in cells not in contact, so the interaction occurs in cis [PMID:22815787].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293; rat P2 brain and mouse E14 brain for endogenous evidence [PMID:22815787]. Mouse pair is ortholog-inferred. BioGRID lists Affinity Capture-Western and Co-localization [DB:BioGRID].","localisation_and_range":"Cis interaction at the cell surface in growing axons [PMID:22815787].","caveats":"One paper only; no affinity; co-IP and PLA show proximity, not necessarily direct contact.","key_references":[{"PMID":"22815787","why":"Co-IP, PLA and brain evidence for L1CAM-erbB3"}],"covers":["LR000972","LR004394"]},"LR007049":{"pair":"L1CAM -> ITGA5:ITGB1","headline":"One abstract-level paper shows RGD-dependent L1-Ig6 adhesion via alpha5beta1.","interaction_type":"direct binding","direction_and_effect":"L1-Ig6 is a heterophilic ligand for alpha5beta1 and supports adhesion via it as an immobilised ligand [PMID:9396761].","molecular_requirements":"RGD-dependent; alpha5beta1 binding was seen only in Mn2+ and inhibited by Ca2+ [PMID:9396761]. Both chains are required as the heterodimer.","affinity_potency":[],"species_and_systems":"Human L1-Ig6, adhesion assay [PMID:9396761].","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Single paper, abstract only; weakest in the stated integrin hierarchy; one other judged paper was a different entity.","key_references":[{"PMID":"9396761","why":"L1-Ig6 supports alpha5beta1 adhesion"}],"covers":["LR007049"]},"LR002846":{"pair":"L1CAM -> ITGA9","headline":"Co-IP and colocalisation suggest alpha9beta1 associates with L1 in melanoma cells; alpha9 not directly detected.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 colocalized with L1 and beta1 coprecipitated with L1 in human M21 melanoma cells at cell-cell contact [PMID:10871287].","molecular_requirements":"The alpha9 subunit could not be detected by Western blot, so beta1 coprecipitation is only likely due to alpha9 [PMID:10871287]. The partner is alpha9beta1; ITGB1 required.","affinity_potency":[],"species_and_systems":"Human M21 and M21-L melanoma cells; mouse pair is ortholog-inferred [PMID:10871287].","localisation_and_range":"Colocalised at cell-cell contact sites [PMID:10871287].","caveats":"Authors state they cannot definitively claim alpha9beta1 coprecipitation; association not direct binding evidence.","key_references":[{"PMID":"10871287","why":"Colocalisation and co-IP of alpha9beta1 with L1"}],"covers":["LR002846","LR006081"]},"LR000974":{"pair":"L1CAM -> ITGAV","headline":"Direct L1-alphavbeta3 binding (ELISA, FN3) and L1-Ig6 RGD adhesion; alphav acts within alphavbeta3 or beta1 heterodimers.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta3 bound L1 FN3 directly [PMID:10871287]; L1-Ig6 is a heterophilic ligand for alphavbeta3 and alphavbeta1, supporting endothelial cell adhesion; agonist-like [PMID:9396761].","molecular_requirements":"Two sites: RGD-independent FN3 [PMID:10871287] and RGD-dependent Ig6; beta3 binding in Ca2+, Mg2+ or Mn2+ [PMID:9396761]. Evidence is on heterodimers; ITGAV alone is chain-level.","affinity_potency":[],"species_and_systems":"Human proteins, purified in ELISA, CHO cells and HUVEC adhesion [PMID:10871287][PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Alphavbeta3 ranked highest in the integrin hierarchy [PMID:9396761]; no affinity; ELISA-based, two papers.","key_references":[{"PMID":"10871287","why":"ELISA binding of alphavbeta3 to FN3"},{"PMID":"9396761","why":"L1-Ig6 RGD-dependent alphav integrin binding"}],"covers":["LR000974","LR004396"]},"LR006086":{"pair":"LAMA1 -> DAG1","headline":"Laminin-1 binds alpha-dystroglycan in an overlay assay in bovine cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Biotin-laminin-1 bound alphaDG on membrane blots, soluble alphaDG blocked endothelial cell adhesion to laminin-1, and glycosaminoglycans inhibited the binding [PMID:10207021]. The interaction record is flagged Stimulatory [flag].","molecular_requirements":"Not reported in our evidence; the ligand tested was laminin-1 as a whole, and a laminin alpha5 globular fragment also bound alphaDG [PMID:10207021].","affinity_potency":[],"species_and_systems":"Bovine aortic endothelial cells and membrane proteins; human and mouse pairs are ortholog-inferred [PMID:10207021].","localisation_and_range":"Ligand flagged secreted; DAG1 flagged transmembrane receptor [flag]. Cell adhesion experiment is to a substrate-coated laminin [PMID:10207021].","caveats":"Abstract only (re-read via protein names), and the ligand is laminin-1, not LAMA1 alone. The abstract is cut off. No affinity reported.","key_references":[{"PMID":"10207021","why":"Laminin-1 overlay shows binding to alphaDG"}],"covers":["LR002852","LR006086"]},"LR011378":{"pair":"LAMA3 -> ITGA3:ITGB1","headline":"No verified paper; only database records, one of which concerns a different complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states integrin alpha-3/beta-1 is a receptor for epiligrin, laminin and other ligands [DB:UniProt P26006]; effect not reported.","molecular_requirements":"Complex of ITGA3 and ITGB1 [DB:UniProt P26006].","affinity_potency":[],"species_and_systems":"UniProt functional statements citing PMID 10455171 [DB:UniProt]. Reactome record is for integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Two papers were abstract_insufficient. The Reactome record names alpha2beta1, not alpha3beta1. The UniProt statements name laminin and epiligrin generally, not LAMA3 specifically.","key_references":[],"covers":["LR011378"]},"LR002855":{"pair":"LAMA3 -> ITGA6","headline":"Direct binding of laminin-332 (carrying LAMA3) to recombinant integrin alpha6beta1; one full-text study, assembled trimer only.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant integrin alpha6beta1 in solid-phase saturation binding; the integrin is the receptor, laminin the ligand [PMID:16413178].","molecular_requirements":"LAMA3 is one chain of laminin-332 (alpha3beta3gamma2); the paper never tests single chains, and the receptor tested was the alpha6beta1 heterodimer, so ITGA6 alone is not shown to suffice [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha6beta1 ectodomain","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified human laminin; mouse pair is ortholog-inferred only [PMID:16413178].","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Assembled heterotrimer evidence only; no cellular or in vivo data in our evidence. Two further papers were judged abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd table of recombinant integrins vs laminin isoforms"}],"covers":["LR002855","LR006089"]},"LR010838":{"pair":"LAMA4 -> ITGA9:ITGB1","headline":"Only LAMA4-ITGB1 co-localisation in mouse brain; alpha9 not examined.","interaction_type":"functional only","direction_and_effect":"LAMA4 and ITGB1 overlapped by immunofluorescence in E14.5 mouse brain, reported as experimental confirmation [PMID:31677479].","molecular_requirements":"Only ITGB1 was tested; ITGA9 is not mentioned [PMID:31677479].","affinity_potency":[],"species_and_systems":"Mouse E14.5 brain [PMID:31677479].","localisation_and_range":"LAMA4 flagged secreted [flag].","caveats":"Co-localisation is not binding; alpha9 subunit unsupported.","key_references":[{"PMID":"31677479","why":"LAMA4-ITGB1 overlap"}],"covers":["LR010838"]},"LR000992":{"pair":"LAMA4 -> ITGAV","headline":"Recombinant laminin alpha4 G domain binds integrin alphavbeta3 with high affinity; abstract-level read.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 integrin bound with high affinity to recombinant G(919-1207) of laminin alpha4, and anti-alphavbeta3 antibodies inhibited endothelial attachment to it [PMID:12454288]. Stimulatory per interaction record [flag].","molecular_requirements":"Receptor tested is the alphavbeta3 heterodimer; ligand is a G-domain fragment [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein; mouse-human chimeric angiogenesis model mentioned for the antibody [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted [flag]; vessel basement membrane component [PMID:12454288].","caveats":"Abstract only; no binding Kd given. One further paper was review-only.","key_references":[{"PMID":"12454288","why":"alphavbeta3 binds alpha4 G domain"}],"covers":["LR000992","LR004411"]},"LR006095":{"pair":"LAMA5 -> CD44","headline":"A synthetic laminin alpha5 G-domain peptide pulls down CD44 from mouse melanoma cells; peptide-level evidence only.","interaction_type":"direct binding","direction_and_effect":"Peptide A5G27 (RLVSYNGIIFFLK, residues 2892-2904) from the alpha5 G domain bound a CD44-reactive band by affinity chromatography, and CD44 GAGs mediated attachment to it [PMID:15256450]. Stimulatory per interaction record [flag].","molecular_requirements":"Binding site is a peptide, not intact laminin alpha5; GAG chains of CD44 are implicated [PMID:15256450].","affinity_potency":[],"species_and_systems":"Mouse B16-F10 melanoma cells; human pair is ortholog-inferred [PMID:15256450].","localisation_and_range":"LAMA5 flagged secreted; CD44 flagged transmembrane [flag].","caveats":"Abstract only; peptide, not full chain; no affinity value. Other peptides did not bind a surface protein.","key_references":[{"PMID":"15256450","why":"A5G27 peptide identifies CD44 as receptor"}],"covers":["LR002861","LR006095"]},"LR002864":{"pair":"LAMB1 -> DAG1","headline":"Laminin beta1 chain (in laminin-10/11, laminin A/B1/B2) binds alpha-dystroglycan in brain and nerve; chain-level, abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal-muscle alpha-dystroglycan [PMID:16709410]. Peripheral-nerve alpha-dystroglycan binds laminin (A/B1/B2) and merosin (M/B1/B2) [PMID:7925941]. Annotated stimulatory.","molecular_requirements":"Binding to the alpha-dystroglycan form depends on tissue glycosylation (brain-specific glycoepitope) [PMID:16709410]; in nerve it is Ca2+-dependent and heparin-inhibitable [PMID:7925941]. LAMB1 was not tested alone.","affinity_potency":[],"species_and_systems":"Mammalian brain and peripheral nerve extracts; species not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and DAG1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers were read as abstracts only and tested whole laminins, so LAMB1 is inferred. An IntAct record from a cross-linking study lists Q14118-P07942 [DB:IntAct] [PMID:30914516]; no affinity values reported.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan preferentially"},{"PMID":"7925941","why":"Nerve alpha-dystroglycan binds laminin and merosin"}],"covers":["LR002864","LR006098"]},"LR011387":{"pair":"LAMC1 -> ITGA6:ITGB1","headline":"LAMC1 with ITGA6:ITGB1 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P23229 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Four papers were abstract_insufficient and two different_entity. The PDB entry lists no ITGB1 chain.","key_references":[],"covers":["LR011387"]},"LR008822":{"pair":"LAMC2 -> ITGA2","headline":"Supported only by a Reactome record that integrin alpha2beta1 binds laminin-332; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records a binding reaction: integrin alpha2beta1 binds laminin-332 [DB:Reactome R-HSA-349626]. Recorded effect: stimulatory [flag].","molecular_requirements":"The record concerns the alpha2beta1 heterodimer and laminin-332, not LAMC2 or ITGA2 alone [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"No paper verified this pair; other papers were judged review-only or abstract-insufficient. Chain-level assignment is inferred from a complex-level record.","key_references":[],"covers":["LR008822"]},"LR011396":{"pair":"LAMC2 -> ITGA7:ITGB1","headline":"Weak support: LAMC2-ITGB1 proximity in tissue and a Reactome record about alpha2beta1; alpha7 not addressed.","interaction_type":"database-asserted only","direction_and_effect":"A Duolink proximity assay showed increased LAMC2-ITGB1 signals in alcohol-exposed colorectal cancer rats and patients [PMID:36188720]. Reactome lists alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"Only ITGB1 was assayed; ITGA7 is not addressed [PMID:36188720]. The Reactome record names alpha2beta1, not alpha7beta1 [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Rat model and clinical colorectal samples [PMID:36188720].","localisation_and_range":"Not reported in our evidence.","caveats":"Support is indirect: neither the tissue proximity paper nor the Reactome record addresses the alpha7 chain. Curated from the abstract only.","key_references":[{"PMID":"36188720","why":"LAMC2-ITGB1 proximity in CRC tissue"}],"covers":["LR011396"]},"LR002873":{"pair":"LCN2 -> MC4R","headline":"In mice, bone-derived LCN2 binds MC4R in hypothalamic neurons and suppresses appetite in an MC4R-dependent manner.","interaction_type":"functional only","direction_and_effect":"LCN2 crosses the blood-brain barrier, binds MC4R in paraventricular and ventromedial hypothalamic neurons and activates an MC4R-dependent anorexigenic pathway; curated as agonist [PMID:28273060].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments in vivo, both ligand and receptor [PMID:28273060]. Human pair is also listed.","localisation_and_range":"LCN2 is a secreted osteoblast-enriched hormone acting endocrine on the brain [PMID:28273060]; MC4R flagged transmembrane [flag].","caveats":"Curated from the abstract; the dossier shows no excerpt of a direct binding assay, so the binding claim rests on the abstract statement.","key_references":[{"PMID":"28273060","why":"LCN2 binds MC4R and suppresses appetite in mice"}],"covers":["LR002873","LR006107"]},"LR004439":{"pair":"LEP -> LEPR","headline":"Well-supported direct leptin-LEPR binding with cryo-EM structure and mapped binding domain; leptin activates LEPR.","interaction_type":"direct binding","direction_and_effect":"Agonist: a cryo-EM structure shows one leptin inducing LepR dimerisation through two distinct receptor sites, and a single leptin is sufficient to dimerise two LepR chains and activate STAT3 signalling [PMID:37002197]. Leptin binding to LEPR activates several signalling pathways [DB:UniProt]; Reactome lists LEP:LEPR:JAK2 [DB:Reactome].","molecular_requirements":"Two LepR chains per leptin; the high-affinity site 2 involves the LepR hinge of domains D4-D5 and the lower-affinity site 3 involves the Ig domain D3 [PMID:37002197]. Binding localised to residues 323-640 of LEPR [PMID:9463481]. Coexpressing an inactive LEPR mutant suppressed OB-Rb activity [PMID:9463481].","affinity_potency":[],"species_and_systems":"The cryo-EM full text describes mouse leptin and mouse LepR complexes; signalling used HEK-293T cells [PMID:37002197]. Curators list human for both papers. Structures with both chains are in PDB (e.g. 7Z3Q, 8AVE) [DB:PDB 7Z3Q].","localisation_and_range":"Leptin flagged secreted; LEPR transmembrane [flag]. Circulating hormone acting on LepR in hypothalamic neurons [PMID:37002197].","caveats":"Both papers were read from the abstract only by the curators (cryo-EM paper has full text). Peripheral clearance of leptin can occur by other receptors, see LEP -> LRP2.","key_references":[{"PMID":"37002197","why":"Cryo-EM leptin-LepR complex, asymmetric 1:2 architecture"},{"PMID":"9463481","why":"Maps leptin binding domain to LEPR residues 323-640"}],"covers":["LR001021","LR004439"]},"LR002882":{"pair":"LGALS3 -> IL13RA2","headline":"Galectin-3 physically interacts with IL-13Ralpha2 and displaces TMEM219 from it, shown in Hermansky-Pudlak lung work.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 physically interacted with IL-13Ralpha2 and CHI3L1 and competed with TMEM219 for IL-13Ralpha2 binding; recombinant galectin-3 diminished TMEM219 binding to IL-13Ralpha2, abrogating the chitosome complex and its antiapoptotic signalling [PMID:29427412]. Effect is antagonist for epithelial apoptosis protection, but augmented macrophage Wnt/beta-catenin signalling [PMID:29427412].","molecular_requirements":"Competes with TMEM219 for IL-13Ralpha2, so the IL-13Ralpha2/TMEM219 complex is the relevant context [PMID:29427412]. IntAct lists anti-bait coimmunoprecipitation [DB:IntAct].","affinity_potency":[],"species_and_systems":"HPS bronchoalveolar lavage fluid, lung fibroblasts and macrophages, with recombinant human galectin-3; curators list human [PMID:29427412]. Human pair ortholog-inferred, mouse not.","localisation_and_range":"Galectin-3 flagged secreted; extracellular galectin-3 drives epithelial apoptosis [PMID:29427412].","caveats":"Affinity not reported in our excerpts. Read depth is abstract only although the excerpts quote full text; IL-13Ralpha2 is also a decoy for other ligands.","key_references":[{"PMID":"29427412","why":"Gal-3 binds IL-13Ralpha2 and competes with TMEM219"}],"covers":["LR002882","LR006116"]},"LR002891":{"pair":"LGALS3BP -> SIGLEC10","headline":"LGALS3BP was identified by affinity chromatography as a sialic-acid-dependent ligand of SIGLEC10 and inhibits neutrophil activation; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"LGALS3BP is a sialic acid-dependent ligand for human Siglec-9, Siglec-5 and Siglec-10, and inhibited neutrophil activation in a sialic acid- and Siglec-dependent manner (immunoinhibitory) [PMID:25320078].","molecular_requirements":"Sialic acid on LGALS3BP is required; the paper does not say whether other chains are needed [PMID:25320078].","affinity_potency":[],"species_and_systems":"Human tumour cell extracts; neutrophil assay system is not specified in the abstract. The mouse homolog Siglec-E binds murine LGALS3BP with lower affinity [PMID:25320078].","localisation_and_range":"LGALS3BP is a heavily glycosylated secreted molecule, up-regulated in the extracellular matrix of colorectal and prostate cancer [PMID:25320078].","caveats":"Abstract only. The inhibition of neutrophil activation was shown for Siglecs collectively, not necessarily SIGLEC10 specifically. Same paper supports three Siglec partners. BioGRID lists a Reconstituted Complex record [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"25320078","why":"LGALS3BP identified as a sialic acid-dependent ligand for CD33-related Siglecs"}],"covers":["LR002891"]},"LR002909":{"pair":"LGALS9 -> TLR4","headline":"Galectin-9 binds TLR4 on mouse B-1 cells in a bead pulldown; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Gal9 binds TLR4 and CD180 on B-1 cells, and less on B-2 cells, by recombinant Gal9-coated bead pulldown of mouse B cell lysates and flow cytometry [PMID:34369876]. The paper concludes Gal9 directly regulates distinct TLRs, dampening signal transduction by altering nano-scale co-distribution [PMID:34369876].","molecular_requirements":"Gal9 also binds CD180, IgM-BCR and CD5; whether TLR4 requires other chains is not reported in our evidence [PMID:34369876].","affinity_potency":[],"species_and_systems":"Mouse primary B-1 and B-2 cells; the human pair is ortholog-inferred [PMID:34369876].","localisation_and_range":"Galectin-9 flagged secreted [flag]; acts at the B-cell surface [PMID:34369876].","caveats":"Single paper; a pulldown does not show a direct purified-protein interaction or the glycan dependence. Two other rows were abstract_insufficient.","key_references":[{"PMID":"34369876","why":"Gal9 pulldown binds TLR4 and CD180 on B-1 cells"}],"covers":["LR002909","LR006136"]},"LR001883":{"pair":"LGI1 -> ADAM11","headline":"LGI1 binds ADAM11 with significant ability in one study, secondary to ADAM22; Reactome also lists it.","interaction_type":"direct binding","direction_and_effect":"ADAM11 had a significant binding ability to LGI1 or LGI4, so ADAM22 is not the sole receptor [PMID:18974846]. Reactome lists LGI1 binds ADAM11 and an LGI1 dimer:ADAM11 complex [DB:Reactome]. Effect direction not reported in our evidence.","molecular_requirements":"Reactome describes an LGI1 dimer:ADAM11 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curator labels both partners human; excerpts describe mouse brain and mouse HA-tagged LGI1 in cell-based ELISA [PMID:18974846]. Human pair is ortholog-inferred.","localisation_and_range":"LGI1 is a secreted protein and the ADAM binds on the cell surface [PMID:18974846]; ADAM11 flagged non-secreted receptor [flag].","caveats":"The abstract does not say whether the ADAM11 binding was to LGI1 or LGI4 ('LGI1 or LGI4'), and no affinity is given; read as abstract only [PMID:18974846]. The excerpts focus on ADAM22.","key_references":[{"PMID":"18974846","why":"LGI-ADAM binding specificity incl. ADAM11"}],"covers":["LR001883","LR005225"]},"LR001892":{"pair":"LGI4 -> ADAM22","headline":"LGI4 binds ADAM22 directly and strongly, and acts on axonal Adam22 to drive Schwann cell differentiation.","interaction_type":"direct binding","direction_and_effect":"Schwann-cell Lgi4 signals in a paracrine manner to axonal Adam22 to drive Schwann cell differentiation in peripheral nerve myelination; agonist [PMID:20220021]. In cell-ELISA LGI4 bound ADAM22 most strongly of the ADAMs tested [PMID:18974846].","molecular_requirements":"Lgi4 binds Adam22 directly without a requirement for additional membrane-associated factors [PMID:20220021]. Adam22 is required on axons, Lgi4 comes from Schwann cells [PMID:20220021]. ADAM22 is not the sole LGI4 receptor; ADAM11 and ADAM23 also bind [PMID:18974846].","affinity_potency":[],"species_and_systems":"Mouse: cell-ELISA with mouse LGI4 and ADAM22 [PMID:18974846]; Schwann cell-sensory neuron cocultures and cell-type-specific knockout in mice [PMID:20220021].","localisation_and_range":"Paracrine: Lgi4 is secreted by Schwann cells and acts on axonal Adam22 [PMID:20220021]. LGI4 is flagged secreted [flag].","caveats":"Both papers are abstract-based for this pair or read via excerpts; no affinity value is reported. Promiscuous ADAM binding means receptor choice depends on expression [PMID:18974846]. The dossier labels 18974846 species as human although its text concerns mouse proteins.","key_references":[{"PMID":"20220021","why":"Direct Lgi4-Adam22 binding and paracrine signalling in vivo"},{"PMID":"18974846","why":"Cell-ELISA, LGI4 strongest with ADAM22"}],"covers":["LR001892","LR005234"]},"LR004448":{"pair":"LPL -> VLDLR","headline":"LPL binds purified VLDLR with high affinity and is internalised by VLDLR-expressing cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"LpL bound with high affinity to purified VLDL receptor in vitro [PMID:7592875]. Fibroblasts lacking VLDLR and LRP that were given VLDLR by adenovirus internalised and degraded 125I-LpL, whereas uninfected or lacZ-infected cells did not [PMID:7592875]. VLDLR acts as an endocytic clearance receptor here.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in vitro; murine embryonic fibroblasts used for the internalisation assay [PMID:7592875].","localisation_and_range":"LPL is annotated secreted and VLDLR transmembrane [flag].","caveats":"Single paper read as abstract only; numeric affinity not stated in the abstract. BioGRID lists a reconstituted complex record from the same paper [DB:BioGRID].","key_references":[{"PMID":"7592875","why":"LpL binds purified VLDLR and is internalised via VLDLR in fibroblasts"}],"covers":["LR001034","LR004448"]},"LR002918":{"pair":"LRFN5 -> PTPRF","headline":"LRFN5 (SALM5) binds LAR (PTPRF) via its Ig domains with Kd 8.96 nM; one paper, direct measurement.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells, LAR-Ecto-Fc","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity measured directly for LAR. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002918","LR006143"]},"LR006149":{"pair":"LRPAP1 -> IFNAR1","headline":"Secreted LRPAP1 binds IFNAR1 and drives its degradation, helping viruses evade interferon signalling; one 2023 paper plus BioGRID records.","interaction_type":"direct binding","direction_and_effect":"The N-terminus of secreted LRPAP1 binds the IFNAR1 extracellular domain and triggers IFNAR1 ubiquitination and degradation, promoting virus infection in vitro, ex vivo in mouse brain and in newborn mice [PMID:37743411]. Curators label the effect antagonist [PMID:37743411]. Recombinant LRPAP1 reduced cell-surface IFNAR1 [PMID:37743411].","molecular_requirements":"A small peptide from the LRPAP1 N-terminus binds and degrades IFNAR1 [PMID:37743411]. Binding to the IFNAR1 ECD was tested by pull-down and microscale thermophoresis; the MST values are not reported in our excerpts [PMID:37743411].","affinity_potency":[],"species_and_systems":"Human HEK-293T, RD and mouse 4T1 cells, C57BL/6 mouse cerebrum and newborn mice [PMID:37743411]. BioGRID lists affinity capture-Western and reconstituted complex [DB:BioGRID]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted, non-transmembrane [flag]. The paper presents secreted LRPAP1 acting extracellularly on membrane IFNAR1 [PMID:37743411].","caveats":"LRPAP1 is also known as an LDL-receptor-family chaperone; this paper's IFNAR1 effect is virus-induced upregulation, and it is a single paper. Alpha2M as an inhibitor stabilising IFNAR1 is reported in the abstract only [PMID:37743411].","key_references":[{"PMID":"37743411","why":"Secreted LRPAP1 binds IFNAR1 ECD and triggers its degradation"}],"covers":["LR002924","LR006149"]},"LR002927":{"pair":"LRRTM1 -> NRXN1","headline":"LRRTM1 binds neurexin-1 lacking the splice site 4 insert; binding code shown in vitro and by LRRTM2 structure, with LRRTM1 data from abstracts.","interaction_type":"direct binding","direction_and_effect":"LRRTM1 and LRRTM2 bind the Nrxn splice variant lacking an insert at splice site 4 (S4) [PMID:30262834]. The binding code first characterised for LRRTM2 is conserved in LRRTM1 and is functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Binding requires neurexin lacking the S4 insert [PMID:30262834, PMID:20519524]. The crystal structure was of Nrxn1beta with LRRTM2, not LRRTM1; the excerpts say LRRTM2 key residues Glu348, Asp352 and Phe357 are completely conserved in LRRTM1 [PMID:30262834].","affinity_potency":[],"species_and_systems":"The structure paper used human proteins per the curator fields [PMID:30262834]; the 2010 paper does not specify species in our evidence [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; the papers describe postsynaptic LRRTMs binding presynaptic neurexins in trans [PMID:30262834].","caveats":"The direct structure is for LRRTM2, so LRRTM1 binding rests on conservation and an abstract-level statement. Both papers were read as abstracts (the structure paper also has excerpts). Affinity for LRRTM1 not reported in our evidence.","key_references":[{"PMID":"20519524","why":"shows LRRTM2 neurexin code is conserved in LRRTM1"},{"PMID":"30262834","why":"Nrxn1beta-LRRTM2 structure; S4-lacking selectivity"}],"covers":["LR002927","LR006152"]},"LR006158":{"pair":"Lrrtm3 -> Nrxn1","headline":"Mouse LRRTM3 interacts with neurexin-1beta in vitro by pull-down; one paper, with the interaction described as limited to in vitro.","interaction_type":"direct binding","direction_and_effect":"Pull-down assays with Ig-neurexin-1b fusion proteins lacking an insert at splice site 4 showed that LRRTM3 interacted with neurexin-1b, at least in vitro [PMID:26776509]. LRRTM3 required only specific neurexins for its synaptogenic activity per the abstract [PMID:26776509].","molecular_requirements":"Neurexin-1b lacking the SS4 insert was used [PMID:26776509].","affinity_potency":[],"species_and_systems":"Mouse proteins; Lrrtm3-knockout mice and neuron work in the same paper [PMID:26776509]. No database records.","localisation_and_range":"Postsynaptic adhesion molecule at excitatory synapses [PMID:26776509]; Lrrtm3 is not flagged transmembrane here (annotation flags only list is_receptor) [flag].","caveats":"The binding result is a supplementary-figure pull-down and the paper itself says 'at least in vitro'. Neurexin-1 is the beta form only. No affinity reported.","key_references":[{"PMID":"26776509","why":"LRRTM3 pull-down with Ig-neurexin-1b; mouse KO study"}],"covers":["LR006158"]},"LR002936":{"pair":"LRRTM4 -> GPC4","headline":"LRRTM4 binds GPC4 in a heparan sulfate-dependent trans-synaptic manner; one paper with reciprocal affinity chromatography.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103]. Reciprocal affinity chromatography with GPC4-Fc identified LRRTM3 and LRRTM4 but not LRRTM1 or LRRTM2 [PMID:23911103]. LRRTM4 triggers GPC4 clustering in contacting axons and GPC4 induces LRRTM4 clustering in contacting dendrites, HS-dependently; LRRTM4 synaptogenic activity requires neuronal-surface HS [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC4 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. Evidence is specific to GPC4 in the abstract. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002936","LR006161"]},"LR006833":{"pair":"LTA -> TNFRSF19","headline":"No verified paper; the pair rests on a GtoPdb record with no stated type or action.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; direction and effect not reported in our evidence. GtoPdb lists the interaction with Type=None, Action=None and no affinity units [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LT alpha flagged secreted [flag]; receptor localisation not reported.","caveats":"Four judged papers were abstract_insufficient, so nothing confirms binding. Treat as unverified.","key_references":[],"covers":["LR006833"]},"LR004457":{"pair":"LTB -> LTBR","headline":"LTBR is a receptor specific for LT-beta containing complexes; two early papers, abstract-read, human.","interaction_type":"direct binding","direction_and_effect":"The predominant surface lymphotoxin form, LT-alpha1/beta2, is recognised by the LT-beta receptor [PMID:7995952]. A receptor specific for human LT-beta was identified [PMID:8171323]. Curator labels agonist; UniProt calls LTBR the receptor for heterotrimeric LTA/LTB [DB:UniProt].","molecular_requirements":"LT-beta acts as part of a complex with LT-alpha; the 60 and 80 kDa TNF receptors do not recognise the major cell surface LT-alpha-LT-beta complex [PMID:8171323]. LT-beta alone as a ligand is not shown. A structure includes chains of LTB and LTBR [DB:PDB 4MXW].","affinity_potency":[],"species_and_systems":"Human systems: PMA-activated II-23 T cell hybridoma [PMID:7995952]; species details of the 1994 study not in the abstract [PMID:8171323].","localisation_and_range":"LT-beta is a type II transmembrane protein, with surface complexes not secreted [PMID:8171323][PMID:7995952]; contact-dependent signalling.","caveats":"Both papers abstract-only; no affinity. One row was a different entity and one abstract_insufficient (not shown).","key_references":[{"PMID":"8171323","why":"Identifies a receptor specific for LT-beta"},{"PMID":"7995952","why":"LT-alpha1/beta2 recognised by LTBR"}],"covers":["LR001044","LR004457"]},"LR006167":{"pair":"LTF -> LRP2","headline":"Lactoferrin binds LRP2/gp330 on blots; one 1992 paper plus UniProt, no signalling evidence.","interaction_type":"direct binding","direction_and_effect":"gp330 from rat kidney membranes bound bovine lactoferrin on nitrocellulose blots; lactoferrin is known to inhibit hepatic clearance of chylomicron remnants [PMID:1464627]. Curator labels antagonist, but the cell-based blocking assay in the abstract was for LRP (LRP1), not gp330 [PMID:1464627].","molecular_requirements":"The 39-kDa RAP protein inhibits binding of all ligands to both LRP and gp330 [PMID:1464627]. UniProt lists lactoferrin among ligands bound by LRP2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Bovine lactoferrin with rat kidney gp330 [PMID:1464627]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"Lactoferrin flagged secreted [flag]; receptor-mediated uptake not studied here.","caveats":"Single abstract-only paper; no affinity or signalling reported; antagonist effect belongs to LRP1 experiments.","key_references":[{"PMID":"1464627","why":"gp330 and LRP bind bovine lactoferrin"}],"covers":["LR002942","LR006167"]},"LR002945":{"pair":"MAG -> RTN4R","headline":"MAG binds NgR1 (RTN4R) and its inhibition of neurite outgrowth depends on it, shown in mouse; one confirmed paper concerns NgR2 instead.","interaction_type":"direct binding","direction_and_effect":"MAG interacts with NgR1 to inhibit neurite outgrowth (agonist). MAG precipitates NgR from NgR-expressing cells, DRG and cerebellar neurons; soluble NgR, NgR antibody or dominant-negative NgR each block MAG inhibition; MAG and Nogo66 compete for NgR [PMID:12160746]. NgR1 also supports MAG binding in neurons in a sialic acid-dependent manner [PMID:15673660].","molecular_requirements":"NgR is GPI-linked with no transmembrane domain and needs a signalling partner [PMID:12160746]. Binding to NgR-expressing cells was sialic acid independent in one study [PMID:12160746] but sialic acid dependent in neurons in another [PMID:15673660].","affinity_potency":[{"value":"IC50 120 nM","assay":"Nogo66-AP competition for MAG-Fc binding (not a MAG-NgR Kd)","system":"neurons on immobilized MAG-Fc","cite":"PMID:12160746"}],"species_and_systems":"Mouse cells and neurons [PMID:12160746]; PMID:15673660 is labelled human but is abstract-only. Mouse pair of this dossier is ortholog-inferred.","localisation_and_range":"MAG is flagged secreted; RTN4R is flagged transmembrane [flag], whereas the paper describes NgR as GPI-linked without a transmembrane domain [PMID:12160746]. Contact/paracrine myelin-to-axon signalling is not stated explicitly.","caveats":"PMID:15673660 mainly shows NgR2 binds MAG with greater affinity than NgR1; no NgR1 affinity is given. Sialic acid dependence differs between the two papers. UniProt lists RTN4R as receptor for MAG [DB:UniProt].","key_references":[{"PMID":"12160746","why":"reciprocal binding, co-precipitation and loss-of-function of MAG-NgR"},{"PMID":"15673660","why":"NgR1 vs NgR2 as MAG receptors"}],"covers":["LR002945","LR006170"]},"LR004475":{"pair":"MDK -> SDC3","headline":"Syndecan-3 from fetal rat bound midkine strongly; one abstract-only paper plus UniProt statements.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 isolated from 16-day rat fetus bound midkine strongly, and is considered involved in midkine interaction in later CNS development [PMID:9089390]. UniProt states midkine binds SDC3 or GPC2 and mediates neurite outgrowth and cell adhesion [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond binding of isolated syndecan-3.","affinity_potency":[],"species_and_systems":"Rat fetal tissue syndecan-3 [PMID:9089390]; curator fields list human, which the abstract does not support. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence; midkine flagged secreted [flag].","caveats":"One abstract-only paper; no affinity, no assay detail beyond 'bound'. The other UniProt-cited papers (PMID 12084985, 1768439) were not judged in our dossier.","key_references":[{"PMID":"9089390","why":"Isolated rat syndecan-3 binds midkine strongly"}],"covers":["LR001062","LR004475"]},"LR006176":{"pair":"MFGE8 -> ITGA8","headline":"Human ITGA8-transfected cells adhere to MFGE8 in an antibody-blockable way; mouse in vivo role also reported; full text.","interaction_type":"direct binding","direction_and_effect":"alpha8-transfected human SW480 cells adhered to Mfge8, and adhesion was blocked by an alpha8 blocking antibody (YZ3) [PMID:27092791]. Ligation of alpha8beta1 by Mfge8 reduced antral smooth muscle contractile force by preventing RhoA activation via PTEN [PMID:27092791].","molecular_requirements":"alpha8 acts with beta1 as alpha8beta1; adhesion was assayed with anti-beta5 ALULA present to block endogenous receptors [PMID:27092791].","affinity_potency":[],"species_and_systems":"Human SW480 cell adhesion with solid-phase binding; mouse smooth muscle deletion and antibody blockade in vivo [PMID:27092791]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"Mfge8 is flagged secreted [flag]; the paper calls it a milk protein [PMID:27092791].","caveats":"Binding rests on cell adhesion and solid-phase assay, with no affinity. The excerpt cites earlier work for the YZ3 antibody [PMID:27092791].","key_references":[{"PMID":"27092791","why":"alpha8beta1-Mfge8 adhesion and PTEN/RhoA mechanism"}],"covers":["LR002951","LR006176"]},"LR002954":{"pair":"MIA -> ITGA4","headline":"MIA binds integrin alpha4 (as alpha4beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605].","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002954","LR006179"]},"LR004484":{"pair":"MMP12 -> PLAUR","headline":"This appears to be enzyme-substrate: MMP-12 cleaves uPAR rather than binding it as a ligand.","interaction_type":"functional only","direction_and_effect":"MMP-12 and other MMPs cleave uPAR at Thr86-Tyr87 in the D1-D2 linker, releasing domain 1, which prevents uPA and vitronectin binding. Murine uPAR is cleaved at Pro89-Gln90 [PMID:12195704].","molecular_requirements":"Not reported in our evidence as a ligand-receptor requirement.","affinity_potency":[],"species_and_systems":"Human uPAR cleavage by MMP-12 and other MMPs, with murine uPAR also cleaved; abstract only [PMID:12195704].","localisation_and_range":"MMP-12 carries a secreted flag; PLAUR carries secreted, receptor and transmembrane flags [flag].","caveats":"Evidence is proteolysis, not receptor engagement; no binding or affinity data. Single paper read as abstract [PMID:12195704].","key_references":[{"PMID":"12195704","why":"MMP-12 cleaves uPAR in the linker region"}],"covers":["LR001072","LR004484"]},"LR006185":{"pair":"MMP14 -> FLT1","headline":"Protease-substrate binding: MMP14 binds and cleaves VEGFR1 (FLT1); two papers disagree on net pro- versus anti-angiogenic effect.","interaction_type":"conflicting","direction_and_effect":"Two papers report direct binding and cleavage but opposite functional readouts. In mouse, the 59.8-kDa N-terminal VEGFR1 cleavage fragment binds VEGF-A165 and inhibits VEGF-induced endothelial mitogenesis, acting as a VEGF trap (antagonist) [PMID:26284550]. In human, MMP14 increased VEGFA-induced ERK phosphorylation, and loss of vascular MMP14 in mice reduced VEGFA-induced corneal angiogenesis (agonist) [PMID:27327585].","molecular_requirements":"MMP14 acts on FLT1 as a protease; the catalytic domain alone was enough for cleavage, and GM6001 blocked it [PMID:27327585]. MMP14 did not bind or cleave VEGFR2 or VEGFR3 [PMID:27327585]. Cleavage products were about 70, 59.8 and 21 kDa [PMID:27327585].","affinity_potency":[{"value":"KD 2.59 \u00d7 10\u22129 M","assay":"surface plasmon resonance, MMP14 over immobilised rhVEGFR1","system":"recombinant human proteins","cite":"PMID:27327585"}],"species_and_systems":"Mouse recombinant VEGFR1 with recombinant MMP14 and cell proliferation assays [PMID:26284550]. Human recombinant proteins, HUVEC co-immunoprecipitation, and conditional vascular MMP14-deletion mice (aortic ring and corneal micropocket) [PMID:27327585].","localisation_and_range":"MMP14 is not annotated as secreted in the entity flags [flag]. The interaction is proteolytic, so membrane-proximal contact is implied; this is not a classical signalling ligand.","caveats":"This is a protease-substrate relationship, not a signalling ligand-receptor pair. The two papers draw opposite conclusions on net effect. The 2015 paper was read as abstract only [PMID:26284550]; the 2016 curator row was also read as abstract only, but full-text excerpts are available [PMID:27327585].","key_references":[{"PMID":"27327585","why":"Human proteins: selective binding (SPR, co-IP), cleavage, pro-angiogenic effect"},{"PMID":"26284550","why":"Mouse VEGFR1 cleavage fragment acts as VEGF trap"}],"covers":["LR002960","LR006185"]},"LR002963":{"pair":"MMP9 -> IFNAR1","headline":"One abstract reports MMP-9 binding IFNAR1 and driving its degradation in HBV infection; no assay detail beyond the abstract.","interaction_type":"direct binding","direction_and_effect":"MMP-9 binds IFNAR1 and promotes IFNAR1 phosphorylation, ubiquitination, redistribution and degradation, interfering with IFNAR1 binding to IFN-\u03b1; this represses IFN/JAK/STAT signalling (antagonist-like) [PMID:28122987].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PBMCs and macrophages from HBV-infected patients and healthy donors [PMID:28122987]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMP9 is flagged as secreted [flag]. Where MMP-9 meets IFNAR1 is not reported in our evidence.","caveats":"Single paper, abstract only; the binding method is not stated in our evidence. The effect is on receptor degradation, not agonism or classical antagonism.","key_references":[{"PMID":"28122987","why":"MMP-9 binds IFNAR1 and promotes its degradation in HBV infection"}],"covers":["LR002963","LR006188"]},"LR005249":{"pair":"MMRN2 -> CLEC14A","headline":"MMRN2 binds CLEC14A directly; supported by one full-text paper with binding mapping.","interaction_type":"direct binding","direction_and_effect":"CLEC14A directly binds MMRN2; recorded as agonist, and an MMRN2 peptide spanning the binding region blocks CLEC14A extracellular domain binding to endothelial cells [PMID:28671670].","molecular_requirements":"The CLEC14A C-type lectin domain is required; chimeras lacking it failed to bind. CLEC14A and CD93 bind the same non-glycosylated coiled-coil region of MMRN2, while CD248 binds a distinct region [PMID:28671670].","affinity_potency":[],"species_and_systems":"Human proteins and cells (HUVEC, HEK293T); mouse CLEC14A-ECD-Fc also bound the corresponding mouse MMRN2 region by far western [PMID:28671670].","localisation_and_range":"MMRN2 is an endothelial extracellular matrix protein and carries a secreted flag [flag]; CLEC14A is a membrane receptor, so signalling is by matrix contact.","caveats":"Single paper. Full-length MMRN2 behaved inconsistently in far western under some conditions. No affinity reported in our evidence.","key_references":[{"PMID":"28671670","why":"Direct binding, domain mapping, blocking peptide"}],"covers":["LR001909","LR005249"]},"LR007247":{"pair":"MSTN -> ACVR1B:ACVR2B","headline":"Myostatin binds ACVR2B; the ACVR1B chain is not evidenced.","interaction_type":"direct binding","direction_and_effect":"Purified C-terminal myostatin dimer bound activin type II receptors, ActRIIB preferentially [PMID:11459935]; BioGRID lists an Affinity Capture-Western record [DB:BioGRID 297250].","molecular_requirements":"Type II chain ACVR2B is evidenced; ACVR1B (ALK4) is not named in the abstract [PMID:11459935]. Binding was inhibited by follistatin and, at higher concentrations, by the myostatin propeptide [PMID:11459935].","affinity_potency":[],"species_and_systems":"Purified recombinant proteins and transgenic mice [PMID:11459935]; IntAct SPR records exist [DB:IntAct].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"Abstract only; support is for ACVR2B alone, not the complex.","key_references":[{"PMID":"11459935","why":"Myostatin binds ActRIIB"}],"covers":["LR007247"]},"LR006194":{"pair":"MSTN -> ACVR2A","headline":"Myostatin binds ACVR2A more weakly than ACVR2B; one binding paper plus one functional paper.","interaction_type":"direct binding","direction_and_effect":"The purified C-terminal myostatin dimer bound ActRIIB and, to a lesser extent, ActRIIA [PMID:11459935]. In human granulosa cells GDF8 suppressed PTX3 with SMAD2/3 phosphorylation; ACVR2A/ACVR2B knockdown reversed the effect [PMID:25641196].","molecular_requirements":"Type I partner ALK5 also needed in granulosa cells (knockdown reversed the effect) [PMID:25641196].","affinity_potency":[],"species_and_systems":"Purified proteins, species unspecified [PMID:11459935]; human granulosa cell lines and primary cells [PMID:25641196]; mouse pair ortholog-inferred.","localisation_and_range":"Myostatin is secreted [flag]; autocrine in follicular fluid at an average of 3 ng/ml [PMID:25641196].","caveats":"Both abstracts only. ACVR2A binding is weaker than ACVR2B; knockdown was combined for ACVR2A/ACVR2B so ACVR2A alone is not isolated.","key_references":[{"PMID":"11459935","why":"Binding to ActRIIA and ActRIIB"},{"PMID":"25641196","why":"ACVR2A/2B knockdown in granulosa cells"}],"covers":["LR002969","LR006194"]},"LR002972":{"pair":"MYL12A -> CD69","headline":"Myl9/12 reported as functional CD69 ligands in mouse asthma models; abstract-only and not isoform-specific.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are described as new functional ligands for CD69; blocking CD69-Myl9/12 interaction ameliorated allergic airway inflammation [PMID:28783682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ovalbumin- and house dust mite-induced asthma models, plus human nasal polyp tissue staining [PMID:28783682].","localisation_and_range":"Ligand is flagged secreted [flag]; platelet-derived Myl9/12 localised to blood vessel luminal surfaces and net-like intravascular structures [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682]. Myl9/12 are reported jointly; the abstract does not separate Myl12a from Myl12b.","key_references":[{"PMID":"28783682","why":"Myl9/12 identified as functional CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR002972","LR006197"]},"LR004493":{"pair":"MYOC -> FZD1","headline":"Myocilin-AP fusion bound FZD1 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD1 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001082","LR004493"]},"LR007346":{"pair":"NCAM1 -> AGRN","headline":"Not supported by the one judged paper; only Reactome complexes assert it.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Reactome lists NCAM-1:Agrin and AGRN:NCAM1/PTPRS complexes [DB:Reactome R-HSA-375096, R-HSA-2467657].","affinity_potency":[],"species_and_systems":"Human; no experimental system reported in our evidence beyond the Reactome record.","localisation_and_range":"Both partners are flagged secreted and transmembrane in places [flag]; agrin is flagged non-receptor [flag].","caveats":"The one paper judged is a mouse migraine snRNA-seq CellChat study, which listed Agrn-Dag1, Ncam1-Ncam2 and Ncam1-L1cam, never Ncam1-Agrn, and was judged pair_absent [PMID:41254485]. Abstract-only read. Support is therefore database-only [DB:Reactome R-HSA-375096].","key_references":[],"covers":["LR007346"]},"LR002981":{"pair":"NCAN -> NCAM1","headline":"Neurocan binds NCAM1 directly in two full-text-supported papers, with a Kd of approximately 1 nM; the interaction is glycosaminoglycan-dependent.","interaction_type":"direct binding","direction_and_effect":"Neurocan binds NCAM and inhibits NCAM/EphA3 association and ephrin-A5-induced growth cone collapse [PMID:29670169]. Neurocan also inhibits neuronal adhesion and neurite outgrowth via NCAM-family binding [PMID:7513709].","molecular_requirements":"Neurocan binds the NCAM Ig2 domain, and binding is chondroitin-sulfate/GAG-dependent, though the core glycoprotein also has binding activity [PMID:29670169][PMID:7513709]. Polysialylated NCAM bound less efficiently than non-polysialylated NCAM [PMID:29670169].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"solid-phase 125I-neurocan binding, Scatchard analysis","system":"soluble neurocan on coated N-CAM microwells","cite":"PMID:7513709"}],"species_and_systems":"Recombinant human neurocan and NCAM-Fc pulldowns, mouse brain co-IP and HEK293T cells [PMID:29670169]. The 1994 binding assay used purified proteins; the species of the proteins is not reported in our evidence (the paper stains rat cerebellum) [PMID:7513709].","localisation_and_range":"Both entities carry a secreted flag [flag]; neurocan is a proteoglycan of the perineuronal net and neuronal surface, so it likely acts in the extracellular matrix near neurons [PMID:29670169].","caveats":"PMID:7513709 was read as abstract/excerpts only. BioGRID and Reactome also list this pair [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"29670169","why":"Full-text pulldowns with purified proteins, Ig2 domain mapping"},{"PMID":"7513709","why":"Scatchard affinity, GAG dependence"}],"covers":["LR002981","LR006206"]},"LR001919":{"pair":"NECTIN1 -> NECTIN4","headline":"Nectin-1 binds nectin-4 in trans with a KD of 100 nM; two papers show direct binding.","interaction_type":"direct binding","direction_and_effect":"Nectin4-Fc trans-interacts with nectin1-expressing cells but not cells expressing nectin2, nectin3 or PVR; nectin1-Fc precipitates nectin4 [PMID:11544254]. Reactome lists a trans heterodimer [DB:Reactome].","molecular_requirements":"The trans-interaction is V-to-V domain, with C domains raising affinity; nectin3 and nectin4 share a binding region in the nectin1 V domain [PMID:12011057][PMID:11544254].","affinity_potency":[{"value":"KD 100 nM","assay":"trans-interaction affinity","system":"nectin1 with nectin4, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins; the mouse row is ortholog-inferred [PMID:12011057].","localisation_and_range":"Membrane adhesion molecules acting in trans at cell-cell junctions [PMID:12011057].","caveats":"Both papers abstract only. The ligand and receptor roles are arbitrary; the pair is symmetric.","key_references":[{"PMID":"11544254","why":"Nectin1-nectin4 trans-interaction"},{"PMID":"12011057","why":"KD measurement and V domain mapping"}],"covers":["LR001919","LR005258"]},"LR005258":{"pair":"NECTIN1 -> NECTIN4","headline":"Nectin-1 binds nectin-4 in trans with a KD of 100 nM; two papers show direct binding.","interaction_type":"direct binding","direction_and_effect":"Nectin4-Fc trans-interacts with nectin1-expressing cells but not cells expressing nectin2, nectin3 or PVR; nectin1-Fc precipitates nectin4 [PMID:11544254]. Reactome lists a trans heterodimer [DB:Reactome].","molecular_requirements":"The trans-interaction is V-to-V domain, with C domains raising affinity; nectin3 and nectin4 share a binding region in the nectin1 V domain [PMID:12011057][PMID:11544254].","affinity_potency":[{"value":"KD 100 nM","assay":"trans-interaction affinity","system":"nectin1 with nectin4, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins; the mouse row is ortholog-inferred [PMID:12011057].","localisation_and_range":"Membrane adhesion molecules acting in trans at cell-cell junctions [PMID:12011057].","caveats":"Both papers abstract only. The ligand and receptor roles are arbitrary; the pair is symmetric.","key_references":[{"PMID":"11544254","why":"Nectin1-nectin4 trans-interaction"},{"PMID":"12011057","why":"KD measurement and V domain mapping"}],"covers":["LR001919","LR005258"]},"LR007058":{"pair":"NECTIN2 -> NECTIN3","headline":"Heterophilic nectin-nectin trans-interaction supported by databases only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No papers were verified for this pair, so direction and effect are not reported in our evidence. UniProt describes NECTIN3 as promoting adhesion through trans-interaction with NECTIN2 at Sertoli-spermatid junctions [DB:UniProt]; Reactome lists a Nectin-2:Nectin 3 trans heterodimer interaction [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human records; experimental systems are not described beyond assay names (protein array, surface plasmon resonance, solid phase assay, anti-tag coimmunoprecipitation) [DB:IntAct].","localisation_and_range":"Membrane-bound adhesion molecules (transmembrane flags) [flag]; Reactome places the heterodimer at the cell junction [DB:Reactome]. Juxtacrine.","caveats":"Rests on databases alone. Curators judged two candidate papers as concerning a different entity, so none support the pair. Interaction class is Adhesion-Adhesion rather than a classic signalling pair.","key_references":[],"covers":["LR007058"]},"LR002990":{"pair":"NID1 -> NCR2","headline":"NKp44 binds Nidogen-1 by immunoprecipitation, western blot and ELISA, but its effect on NK cells is modulatory only.","interaction_type":"direct binding","direction_and_effect":"NID1 is a ligand of NKp44, an activating NK receptor; as a soluble molecule it modulates NKp44-induced IFN-gamma production or cytotoxicity, and also modulates PDGF-DD-induced IFN-gamma production [PMID:30228939].","molecular_requirements":"Not reported in our evidence beyond NKp44Fc binding.","affinity_potency":[],"species_and_systems":"Human NK cells and HEK293T supernatant; NKp44Fc immunoprecipitated NID1, but not NKp30Fc or DNAM-1Fc controls, and recognised recombinant NID1 by western blot and ELISA [PMID:30228939].","localisation_and_range":"Soluble NID1 acts; surface-bound or solid-supported NID1 fails to induce cytotoxicity or cytokine release but alters the proteomic profile [PMID:30228939].","caveats":"Single paper; no database records. NID1 effect is modulatory and context-dependent, not simply activating, and affinity is not reported in our evidence.","key_references":[{"PMID":"30228939","why":"Identifies NID1 as a ligand of NKp44 with binding controls"}],"covers":["LR002990"]},"LR004529":{"pair":"NODAL -> ACVR1C","headline":"Functional support for ALK7 (ACVR1C) as a Nodal type I receptor, mainly from mouse Nodal and Xenopus experiments.","interaction_type":"functional only","direction_and_effect":"ALK7 acts as a receptor for mouse Nodal and Xenopus Xnr1; constitutively active ALK7 mimics Xnr1 and dominant-negative ALK7 specifically blocks Nodal and Xnr1 [PMID:11485994]. UniProt: upon NODAL binding, activation suppresses AKT and activates Smad2 signalling [DB:UniProt].","molecular_requirements":"ALK7 collaborates with ActRIIB; both receptors can independently bind Xnr1; Cripto interacts with Xnr1 and ALK7 and greatly enhances response [PMID:11485994].","affinity_potency":[],"species_and_systems":"Mouse Nodal and Xenopus Xnr1 in Xenopus embryos and reconstitution [PMID:11485994]. The human pair is direct; mouse likewise.","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"Abstract only; two further papers abstract-insufficient.","key_references":[{"PMID":"11485994","why":"Biochemical and functional evidence that ALK7 is a Nodal receptor"}],"covers":["LR001118","LR004529"]},"LR008516":{"pair":"NOG -> BMP4","headline":"Noggin to BMP4 is annotated inhibitory; only a Reactome complex record supports it in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Interaction is annotated Inhibitory [flag]; Reactome records a BMP4:NOG complex in the extracellular region [DB:Reactome R-HSA-9794043, PMID:24243840].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"BMP4 flagged secreted [flag]; Reactome places the complex extracellularly [DB:Reactome R-HSA-9794043].","caveats":"No curated paper confirms it: three papers were judged as a different entity and five had insufficient abstracts. Database assertion only.","key_references":[{"PMID":"24243840","why":"Reactome source for the BMP4:NOG complex (database only)"}],"covers":["LR008516"]},"LR008534":{"pair":"NOTCH1 -> DLK2","headline":"Only a co-immunoprecipitation record supports NOTCH1-DLK2; no judged evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists association by anti tag coimmunoprecipitation [DB:IntAct, PMID:33961781]; species and system not reported.","localisation_and_range":"NOTCH1 is flagged transmembrane receptor and DLK2 non-secreted [flag], suggesting a contact-dependent setting.","caveats":"Three papers are still pending, none judged. A single co-IP record does not show a direct ligand-receptor interaction.","key_references":[{"PMID":"33961781","why":"IntAct co-IP record (database only)"}],"covers":["LR008534"]},"LR004538":{"pair":"NPPA -> NPR1","headline":"ANP is an established agonist of NPR1 (GC-A) with structural, database and functional support.","interaction_type":"direct binding","direction_and_effect":"ANP stimulates NPR1 to produce cGMP [DB:UniProt]; GtoPdb lists agonist [DB:GtoPdb]. In H295R cells ANP and a selective analogue raised cGMP and lowered forskolin- and angiotensin II-induced aldosterone and pregnenolone production [PMID:8700153].","molecular_requirements":"NPR1 is a dimer; ANP stabilises a dimeric NPRA by contacting both subunits, and a W74C covalent dimer could neither bind nor be activated by ANP until disulfides were opened [PMID:12547834]. Reactome lists NPPA(124-151):NPR1 dimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human receptor and ligand in recombinant or cell systems [PMID:12547834][PMID:8700153]. Mouse pair is projected. PDB structures exist of the ANP-NPR1 complex [DB:PDB 8TG9].","localisation_and_range":"ANP is annotated secreted and NPR1 transmembrane [flag].","caveats":"Both papers were abstract-only. PMID:12547834 is a mutant-receptor study, and its evidence sentence is background from an earlier paper. The ligand is annotated as 'mutant ANP' [flag].","key_references":[{"PMID":"8700153","why":"Functional cGMP and steroidogenesis response to ANP via NPR-A"},{"PMID":"12547834","why":"Dimer requirements for ANP binding to NPRA"}],"covers":["LR001128","LR004538"]},"LR001928":{"pair":"NPPA -> NPR2","headline":"ANP activates NPR2 (GC-B) but with lower potency than CNP; one abstract-level paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Via GC-B, rank order of cGMP production potency was CNP greater than ANP greater than or equal to BNP, so ANP is a secondary agonist [PMID:1309330].","molecular_requirements":"Receptor-only; subunit or co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, bovine and rat receptor preparations and homologous assays; the dossier gives human as experiment species [PMID:1309330]. Mouse pair is projected.","localisation_and_range":"ANP is annotated secreted [flag].","caveats":"Single abstract-only paper, with a functional (cGMP) readout rather than a direct binding measurement for this pair, despite the direct_binding label. The paper notes marked species differences in selectivity [PMID:1309330]. BioGRID reconstituted-complex records only [DB:BioGRID].","key_references":[{"PMID":"1309330","why":"Rank order of natriuretic peptide potency at GC-B"}],"covers":["LR001928","LR005267"]},"LR005267":{"pair":"NPPA -> NPR2","headline":"ANP activates NPR2 (GC-B) but with lower potency than CNP; one abstract-level paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Via GC-B, rank order of cGMP production potency was CNP greater than ANP greater than or equal to BNP, so ANP is a secondary agonist [PMID:1309330].","molecular_requirements":"Receptor-only; subunit or co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, bovine and rat receptor preparations and homologous assays; the dossier gives human as experiment species [PMID:1309330]. Mouse pair is projected.","localisation_and_range":"ANP is annotated secreted [flag].","caveats":"Single abstract-only paper, with a functional (cGMP) readout rather than a direct binding measurement for this pair, despite the direct_binding label. The paper notes marked species differences in selectivity [PMID:1309330]. BioGRID reconstituted-complex records only [DB:BioGRID].","key_references":[{"PMID":"1309330","why":"Rank order of natriuretic peptide potency at GC-B"}],"covers":["LR001928","LR005267"]},"LR004547":{"pair":"NPVF -> NPFFR2","headline":"NPVF peptides bind human NPFFR2 with nanomolar affinity, but with slight preference for NPFFR1; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Pro-NPFF(B)-derived peptides are recognised by NPFF2 with nanomolar affinity; the paper reports a slight preference of these peptides for NPFF1 [PMID:12242085]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NPFF receptors expressed in CHO cells [PMID:12242085]. Mouse pair is projected from human.","localisation_and_range":"NPVF is flagged secreted and NPFFR2 transmembrane [flag].","caveats":"Single paper, read as abstract only [PMID:12242085]. The abstract gives no peptide-specific values for NPFF2, and GtoPdb lists pKi without values in the dossier [DB:GtoPdb]. Mainly a database plus one abstract.","key_references":[{"PMID":"12242085","why":"Human NPFF1/NPFF2 binding and cAMP in CHO cells"}],"covers":["LR001137","LR004547"]},"LR004556":{"pair":"NRG1 -> ERBB3","headline":"NRG1 binds ERBB3 directly with nanomolar affinity and activates it, usually with ERBB2 as partner; well supported.","interaction_type":"direct binding","direction_and_effect":"Agonist: heregulin activates ERBB3 signalling in cells, and in breast cancer cells HRG stimulation led MTK1 to associate with activated HER3 [PMID:24036211]. ERBB3 alone gives little or no phosphorylation response; co-expression with erbB2 gave higher-affinity binding and signalling [PMID:7514177].","molecular_requirements":"Ligand binds the ERBB3 extracellular domain I-II [PMID:11555649]. ERBB3 needs a partner for signalling: ErbB-1 or ErbB-2 transactivate it, and neither NDF isoform was active on ErbB-3 alone [PMID:8702572]. Ligand bivalence: a high-affinity site binds ErbB-3 and a low-affinity site binds ErbB-2 [PMID:9305636]. Full-length NDF beta 2 bound sHer3 roughly 1000-fold more tightly than sHer2 [PMID:7592681].","affinity_potency":[{"value":"Kd 26 +/- 9 nM","assay":"native gels, light scattering, sedimentation equilibrium","system":"NDF beta 2 with soluble Her3 extracellular domain","cite":"PMID:7592681"},{"value":"68 nM","assay":"HER3-ECD(I-II) binding to hrg","system":"recombinant HER3 domains I-II","cite":"PMID:11555649"},{"value":"pKd 8.89","assay":"heterodimer-formation binding assay (database value)","system":"NDF/neuregulin","cite":"PMID:9305636"},{"value":"pIC50 9.26","assay":"soluble receptor-ligand binding","system":"egf domains on ErbB receptors","cite":"PMID:10214951"}],"species_and_systems":"Human ligand and receptor; recombinant soluble domains, transfected cells, MCF-7 and other breast cancer cells. The mouse pair is projected from human evidence.","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag]; single-molecule work on live MCF-7 cell surfaces showed heregulin binding at the cell surface [PMID:22891299].","caveats":"Most papers were abstract only. Single-molecule data show negative cooperativity and apparent low- and high-affinity sites [PMID:22891299]. PMID 10995872 and 24036211 are functional readouts that do not isolate ERBB3 binding. PMID 10348342 was browser-read with spot-check pending. Quoted pKd and pIC50 values come from the curated records.","key_references":[{"PMID":"7592681","why":"Kd 26 nM NDF-sHer3, weak sHer2 binding"},{"PMID":"7514177","why":"erbB2 co-expression reconstitutes high-affinity receptor"},{"PMID":"11555649","why":"HER3 domains I-II bind hrg, 68 nM"}],"covers":["LR001147","LR004556"]},"LR008237":{"pair":"NRTN -> GFRA1:RET","headline":"NRTN activates the GFRA1:RET receptor complex; Ret phosphorylation needs GDNFRalpha.","interaction_type":"functional only","direction_and_effect":"NTN causes Ret phosphorylation in fibroblasts stably expressing Ret and GDNFRalpha, but not in cells expressing Ret alone [PMID:9192684]. TrnR1-Ret cells respond equivalently to both NTN and GDNF [PMID:9182803].","molecular_requirements":"Both GFRA1 (GPI-linked GDNFRalpha) and RET are needed; Ret alone does not respond [PMID:9192684]. BioGRID records RET-NRTN capture [DB:BioGRID]; PDB entries contain chains of NRTN and RET [DB:PDB 6GL7].","affinity_potency":[],"species_and_systems":"Primary rat superior cervical ganglion neurons and transfected fibroblasts [PMID:9192684]; human receptors in fibroblasts [PMID:9182803].","localisation_and_range":"NRTN is secreted and not transmembrane [flag]; GDNFRalpha is GPI-linked, as PI-PLC treatment reduced NTN signalling [PMID:9192684].","caveats":"Both papers abstract only for this row; evidence sentences are background statements about the GDNF receptor. No affinity numbers.","key_references":[{"PMID":"9192684","why":"NTN induces Ret phosphorylation via Ret and GDNFRalpha"},{"PMID":"9182803","why":"TrnR1-Ret mediates NTN and GDNF signalling"}],"covers":["LR008237"]},"LR006239":{"pair":"NRXN1 -> CBLN1","headline":"Indirect: Cbln1 bridges presynaptic neurexins and postsynaptic GluRdelta2; support rests on one abstract-read paper.","interaction_type":"functional only","direction_and_effect":"Cbln1 links the GluRdelta2 N-terminal domain to presynaptic neurexins to drive synapse formation; synaptogenic activity was abolished in Cbln1 knockout cultures and restored by recombinant Cbln1 [PMID:20537373]. Soluble NRXN1beta extracellular domain suppressed Cbln1 synaptogenic activity in culture and in vivo [PMID:20537373].","molecular_requirements":"A tripartite GluRdelta2-Cbln1-NRXN complex is described; knockdown of NRXNs in granule cells also impaired GluRdelta2 synaptogenic activity [PMID:20537373]. Whether NRXN1 binds Cbln1 directly is not shown in our abstract-only evidence.","affinity_potency":[],"species_and_systems":"Mouse cerebellar primary cultures and in vivo; curation lists human. Human pair is ortholog-inferred.","localisation_and_range":"CBLN1 is flagged secreted [flag]; NRXN1 is transmembrane presynaptic [flag]; the complex is trans-synaptic [PMID:20537373].","caveats":"Read as abstract only. The assay_class direct_binding is not clearly supported by the abstract, which reports functional bridging and competition rather than a binding measurement. CBLN1 is a bridging ligand, not a conventional receptor.","key_references":[{"PMID":"20537373","why":"Cbln1 bridges GluRdelta2 NTD and neurexins in cerebellar synapse formation"}],"covers":["LR003015","LR006239"]},"LR006248":{"pair":"NRXN1 -> NLGN3","headline":"Direct binding of NLGN3 and beta-neurexin supported, but the second paper's evidence concerns PTPdelta and competition.","interaction_type":"direct binding","direction_and_effect":"Neuroligins were tested against beta-neurexin-1 by SPR [PMID:17042500]. NLGN3 and neurexins form a canonical transsynaptic pair, and NLGN3 binds PTPdelta splice variants in competition with NRXN binding [PMID:33758193].","molecular_requirements":"Competition: PTPdelta splice variants compete with NRXNs for NLGN3; a NLGN3 mutation selectively impairing the NRXN interaction increased sociability in mice [PMID:33758193].","affinity_potency":[],"species_and_systems":"17042500: recombinant protein, unspecified species; 33758193 used mouse assays. Mouse pair is the non-inferred one in curation.","localisation_and_range":"Both transmembrane [flag].","caveats":"The NRXN1 identity is not stated in the 33758193 abstract (NRXNs generally). No NLGN3 affinity in our evidence. BioGRID lists reconstituted complex and affinity capture-western [DB:BioGRID].","key_references":[{"PMID":"17042500","why":"SPR of neuroligins with beta-neurexin-1"},{"PMID":"33758193","why":"NLGN3 canonical NRXN pair and competition with PTPdelta"}],"covers":["LR003024","LR006248"]},"LR004565":{"pair":"NTF3 -> NGFR","headline":"Mature NT-3 binding to p75NTR is only indirectly supported; the confirmed paper concerns proNT-3 requiring p75NTR.","interaction_type":"functional only","direction_and_effect":"ProNT-3 required p75NTR to promote cell cycle exit of cerebellar granule progenitors; in cells lacking p75NTR it could not reduce Shh-induced BrdU incorporation [PMID:27434667]. Mature NT3 (100 ng/ml) had no effect on proliferation [PMID:27434667]. UniProt describes NGFR as a low affinity receptor binding NGF, BDNF, NTF3 and NTF4 [DB:UniProt].","molecular_requirements":"SorCS2 was the sortilin family co-receptor detected in the EGL; UniProt describes a heterodimer with SORCS2 binding precursor NTF3 with high affinity [PMID:27434667][DB:UniProt].","affinity_potency":[],"species_and_systems":"Cultured rat/mouse cerebellar granule progenitors, WT versus Ngfr-/- [PMID:27434667]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"NTF3 flagged secreted, NGFR transmembrane [flag]: secreted ligand acting on a cell-surface receptor.","caveats":"No direct binding assay in this paper; the effect is of the precursor, not mature NT-3. BioGRID reports affinity capture-western [DB:BioGRID]; GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"27434667","why":"proNT-3 acts via p75NTR on granule progenitors"}],"covers":["LR001156","LR004565"]},"LR006257":{"pair":"NTN1 -> APP","headline":"Netrin-1 binds APP in co-IP and cell-recruitment assays and modulates APP signalling; mainly one lab's work.","interaction_type":"direct binding","direction_and_effect":"APP binds netrin-1; netrin-1 binding triggers AICD-dependent gene transcription and suppresses Abeta production in brain slices from Alzheimer model transgenic mice [PMID:19148186]. During commissural axon guidance, APP is part of the DCC receptor complex mediating netrin-1 dependent guidance [PMID:22782894].","molecular_requirements":"APP interacts with DCC in the presence of netrin-1 [PMID:22782894]. Netrin-1 did not interact with p75NTR in cortex co-IP [PMID:19148186].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293T cells, B103 cells and mouse E16.5 cortical neurons and developing cortex [PMID:19148186]. Human pair is ortholog-inferred; mouse pair is direct. IntAct lists an ELISA record [DB:IntAct].","localisation_and_range":"NTN1 secreted, APP transmembrane [flag].","caveats":"Abstracts only (one paper has excerpts of its results); the 2012 paper's evidence sentence is background to the earlier work [PMID:22782894].","key_references":[{"PMID":"19148186","why":"Netrin-1 binds APP; modulates Abeta and AICD"},{"PMID":"22782894","why":"APP in DCC complex for axon guidance"}],"covers":["LR003033","LR006257"]},"LR004574":{"pair":"NTN1 -> UNC5A","headline":"Netrin-1 binds UNC5A: netrin-binding evidence from 1997 and a functional stroke paper, both read as abstracts.","interaction_type":"direct binding","direction_and_effect":"UNC5 homologues were shown to be netrin-binding proteins, supporting a netrin receptor role [PMID:9126742]. In stroke models, netrin-1 signalling in microglia ran mainly via UNC5a and shifted microglia towards an anti-inflammatory M2-like state [PMID:37388740].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The 1997 work used cloned vertebrate UNC-5 homologues [PMID:9126742]; the stroke work used human patients, rat and mouse models [PMID:37388740]. A BioGRID reconstituted complex and Reactome binding reactions are also recorded [DB:BioGRID][DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5A is not secreted [flag].","caveats":"The 1997 abstract refers to two UNC-5 homologues and does not name UNC5A specifically. Both papers read as abstracts only. The stroke abstract is truncated and mostly functional.","key_references":[{"PMID":"9126742","why":"UNC-5 homologues are netrin-binding proteins"},{"PMID":"37388740","why":"UNC5a-mediated netrin-1 signalling in microglia in stroke"}],"covers":["LR001165","LR004574"]},"LR004583":{"pair":"NTS -> NTSR1","headline":"Neurotensin is a well-established agonist of NTSR1 with nM-range binding and many confirming papers; large NTS forms are also active.","interaction_type":"direct binding","direction_and_effect":"Neurotensin binds and activates NTSR1 as an agonist: phosphoinositide hydrolysis in CHO cells with rat receptor, pertussis-toxin-insensitive [PMID:1331689]; activation of the yeast pheromone pathway by human NTR1 [PMID:11559354]. Neurotensin binding triggers receptor internalisation [PMID:11801734]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain, a seven-transmembrane GPCR [PMID:1694443]. The third outer loop is the binding site for neurotensin and analogs, and one residue (hTyr339 vs rPhe344) sets species selectivity for an analog [PMID:10930533]. Large NT and large neuromedin N bind and activate human NTS1 with potencies about 10 times lower than the small peptides but are far less sensitive to degradation [PMID:11811984]. An arginylated NT (porcine) acts as agonist on NTR1 [PMID:16087676].","affinity_potency":[{"value":"Kd 3.2 nM","assay":"[125I-Tyr3]NT binding","system":"human NTR1 in yeast","cite":"PMID:11559354"},{"value":"Kd 0.45 nM","assay":"Scatchard, [3H]neurotensin binding","system":"rat NTR1 in CHO cells","cite":"PMID:1331689"},{"value":"pIC50 7.4","assay":"binding/pharmacology of large NT","system":"human NTS1 (COS cells / HT29)","cite":"PMID:11811984"}],"species_and_systems":"Experiments span human (yeast, COS, HT29), rat (CHO, oocytes) and mouse/human/rat receptors [PMID:11559354][PMID:1331689][PMID:11801734]; the mouse pair is ortholog-inferred. Mostly recombinant cells. GtoPdb lists pKi 8.3 to 9.7 [DB:GtoPdb]. Structures exist (PDB 2LYW, 6UP7) [DB:PDB 2LYW][DB:PDB 6UP7].","localisation_and_range":"Neuropeptide flagged secreted [flag], so paracrine or endocrine action on a membrane GPCR.","caveats":"All papers were abstract-only reads. Some confirmed papers are indirect for this pair: PMID:11801734 is about receptor recycling (the NTR2 recycles, human NTR2 and rat NTR1 do not) and PMID:1694443 is the receptor cloning paper without a stated affinity. PMID:16087676 tested a modified peptide.","key_references":[{"PMID":"1331689","why":"Rat NTR1 binding Kd and phospholipase C activation"},{"PMID":"11559354","why":"Human NTR1 binding Kd and agonist signalling in yeast"},{"PMID":"11811984","why":"Large NTS forms bind and activate human NTS1"}],"covers":["LR001174","LR004583"]},"LR007364":{"pair":"NTS -> SORT1","headline":"Neurotensin binds sortilin (NTR3) directly, with in vivo primate support for function; sortilin is largely intracellular.","interaction_type":"direct binding","direction_and_effect":"Sortilin is the 100-kDa neurotensin receptor purified by neurotensin affinity chromatography and cloned; it is not a GPCR [PMID:9756851]. In macaque, a SORT1-selective antagonist (AF38469) reduced theca-cell migration and, with SORT1 antagonist or siRNA, abrogated NTS-stimulated endothelial migration and permeability changes, indicating an agonist role [PMID:41014186][PMID:40037635].","molecular_requirements":"Furin cotransfection converts the 110-kDa form into a higher-affinity mature 100-kDa receptor [PMID:9756851]. In macaque cells both NTSR1 and SORT1 were needed for NTS-stimulated migration, and the two receptors may form a complex [PMID:41014186].","affinity_potency":[{"value":"affinity of 10-15 nM","assay":"[125I]NT binding to solubilised extracts","system":"human NT3/sortilin in COS-7","cite":"PMID:9756851"},{"value":"Kd = 0.3 nM","assay":"binding after furin cotransfection","system":"human, COS-7","cite":"PMID:9756851"},{"value":"IC50 21 nm","assay":"competition binding, neurotensin","system":"soluble NTR3","cite":"PMID:16087676"}],"species_and_systems":"Human receptor in COS-7 cells and brain extracts [PMID:9756851]; cynomolgus/macaque follicles and primary cells [PMID:41014186][PMID:40037635]. Structures PDB 3F6K and 4PO7 [DB:PDB 3F6K][DB:PDB 4PO7]; SPR records in IntAct [DB:IntAct].","localisation_and_range":"NTS is flagged secreted [flag]. Sortilin localises to intracellular vesicles [PMID:9756851], and a cell-surface role is described in macaque theca cells [PMID:41014186].","caveats":"The macaque papers were read as abstracts or partial text; antagonist selectivity is assumed, and knockdown results concern migration, not binding. PMID:16087676 quote is browser-read with spot-check pending. One paper is classed unresolvable and one abstract-insufficient [outcome counts].","key_references":[{"PMID":"9756851","why":"Cloning of sortilin as the NT3 receptor, with affinities"},{"PMID":"40037635","why":"Macaque ovulation: SORT1 antagonist and siRNA"},{"PMID":"41014186","why":"Macaque theca-cell migration via NTSR1 and SORT1"}],"covers":["LR007364"]},"LR004592":{"pair":"OMG -> RTN4R","headline":"OMG is a well-supported ligand of RTN4R (NgR); binding and function shown, plus database support.","interaction_type":"direct binding","direction_and_effect":"OMgp was identified as a high-affinity NgR-binding protein from an expression library screen; removing NgR makes axons insensitive to OMgp and adding NgR confers responsiveness, so OMgp acts as an agonist and the output is inhibition of neurite outgrowth [PMID:12068310]. Binding of OMgp to NgR-expressing cells is also reported, with selectivity for NgR over NgR2 and NgR3 [PMID:12839991]. UniProt lists RTN4R as receptor for OMG [DB:UniProt].","molecular_requirements":"NgR is GPI-anchored and signals through a co-receptor complex (p75/LINGO-1) rather than autonomously, per curator notes [PMID:12068310]. The abstract of [PMID:12839991] states ligand binding needs the whole LRR region of NgR.","affinity_potency":[{"value":"high-affinity (no value given)","assay":"expression library screen binding","system":"human","cite":"PMID:12068310"}],"species_and_systems":"Curator-labelled human ligand and receptor; both read as abstracts only [PMID:12068310][PMID:12839991]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"OMG is flagged non-secreted and RTN4R transmembrane [flag]; OMgp is described as a GPI-anchored myelin protein, so action is by cell contact [PMID:12068310].","caveats":"Both papers read only as abstracts; the second was browser-read with an unverified quote. No numeric affinity reported. NgR2 and NgR3 do not bind OMgp [PMID:12839991]. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"12068310","why":"Identifies NgR as OMgp receptor, necessity and sufficiency"},{"PMID":"12839991","why":"Ligand-binding region and NgR selectivity"}],"covers":["LR001183","LR004592"]},"LR007382":{"pair":"OSM -> IL6ST:OSMR","headline":"OSM signals through gp130:OSMRbeta (type II OSM receptor), supported by reconstitution, structure and databases.","interaction_type":"functional only","direction_and_effect":"OSM-induced responses are mediated by two heterodimers; gp130.OSMRbeta is activated by OSM but not by LIF [PMID:8999038]. Expression of OSMRbeta in rat hepatoma cells gave strongest STAT5 and ERK activation [PMID:10854424]. OSM structure maps receptor-binding epitopes [PMID:10997905]. UniProt names the type II OSM receptor as OSMR plus IL6ST [DB:UniProt]. GtoPdb lists agonist records for both chains [DB:GtoPdb].","molecular_requirements":"Both chains are involved: gp130 and OSMRbeta [PMID:8999038]. OSMR is also shared with IL-31 signalling in another complex [PMID:25054142].","affinity_potency":[],"species_and_systems":"Human cells for [PMID:8999038]; rat hepatoma cells expressing human or mouse OSMRbeta [PMID:10854424]; human genetics [PMID:25054142]. Mouse pair not listed for this complex.","localisation_and_range":"OSM is flagged secreted [flag]; complex is a flagged transmembrane receptor [flag].","caveats":"All papers read as abstracts only. Direct binding of OSM to the complex is not itself shown in the abstracts; evidence is signalling and mapping. [PMID:25054142] is a disease-mutation study, supporting that OSM is a ligand of OSMR only indirectly. Review-only and abstract-insufficient rows not shown.","key_references":[{"PMID":"8999038","why":"OSM acts via gp130 plus OSMRbeta"},{"PMID":"10854424","why":"Reconstitution of OSMRbeta signalling in rat hepatoma cells"},{"PMID":"10997905","why":"OSM crystal structure and receptor epitopes"}],"covers":["LR007382"]},"LR009326":{"pair":"PDGFA -> PDGFRB","headline":"No curated paper confirms PDGF-A binding to PDGFRB; support is from database records only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt lists PDGFRB as binding homodimeric PDGFB and PDGFD and as a heterodimer partner, without a PDGFA-specific verified paper here [DB:UniProt]; Reactome gives generic PDGF:PDGF receptor dimer complexes [DB:Reactome]. IntAct includes ELISA and competition binding records [DB:IntAct]. Curated effect is Stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No verified experiments; species not stated.","localisation_and_range":"PDGFA annotated secreted [flag].","caveats":"Only review_only outcomes; database text does not clearly state PDGFA binds PDGFRB directly, and generic PDGF complexes may not apply to the A chain.","key_references":[],"covers":["LR009326"]},"LR001199":{"pair":"PDGFC -> PDGFRB","headline":"PDGFC -> PDGFRB is supported only by database records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PDGFC interacts with PDGFRA homodimers and with PDGFRA:PDGFRB heterodimers, not PDGFRB homodimers [DB:UniProt]. An IntAct cross-linking record exists for PDGFC and PDGFRB [DB:IntAct].","molecular_requirements":"Evidence points to the PDGFRA:PDGFRB heterodimer rather than PDGFRB alone [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database records.","localisation_and_range":"PDGFC flagged secreted and transmembrane; PDGFRB transmembrane [flag].","caveats":"No verified papers (two abstract-insufficient, one review-only). A standalone PDGFRB homodimer interaction is not supported by the UniProt record. Mouse pair is ortholog-inferred.","key_references":[],"covers":["LR001199","LR004608"]},"LR003089":{"pair":"PDYN -> ACKR3","headline":"Dynorphin peptides activate ACKR3 as a scavenger receptor, shown with quantitative potency in one paper.","interaction_type":"functional only","direction_and_effect":"ACKR3 is a scavenger of opioid peptides, especially enkephalins and dynorphins, reducing their availability to classical opioid receptors [PMID:32561830]. It recruits beta-arrestin but did not show G-protein signalling in response to opioid peptides [PMID:32561830].","molecular_requirements":"Active peptides include dynorphin A, dynorphin A 1-13, dynorphin B, big dynorphin and leumorphin (PDYN-derived fragments), with different potencies [PMID:32561830].","affinity_potency":[{"value":"EC50 110 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, dynorphin A","cite":"PMID:32561830"},{"value":"EC50 61.9 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, dynorphin A 1-13","cite":"PMID:32561830"},{"value":"EC50 108 nM","assay":"beta-arrestin-1 recruitment","system":"ACKR3, U87 cells, big dynorphin","cite":"PMID:32561830"}],"species_and_systems":"Cell-based assays in U87 cells; rat brain used for a competitor peptide experiment [PMID:32561830]. Species of ACKR3 construct not stated in our excerpts.","localisation_and_range":"PDYN-derived peptides are secreted [flag]; ACKR3 is a transmembrane receptor [flag]; paracrine in brain per the paper's setting.","caveats":"Decoy or scavenger rather than classical agonist. Evidence is beta-arrestin recruitment, not binding. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"32561830","why":"ACKR3 scavenges opioid peptides including dynorphins"}],"covers":["LR003089","LR006312"]},"LR008723":{"pair":"PECAM1 -> EFNB2","headline":"Only one abstract reports that ephrinB2 co-localises and co-immunoprecipitates with CD31; direction and function unclear.","interaction_type":"functional only","direction_and_effect":"Junctional ephrinB2 colocalises and coimmunoprecipitates with CD31 in endothelial cells [PMID:16357318]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cells (aortic and saphenous vein) in culture; abstract only [PMID:16357318].","localisation_and_range":"Both are transmembrane [flag]; the association is at interendothelial junctions [PMID:16357318]; the pair is annotated Receptor-Receptor.","caveats":"Co-immunoprecipitation does not establish direct binding; the association is context dependent; the paper is mainly about ephrinB2 regulation. The ligand/receptor direction is arbitrary.","key_references":[{"PMID":"16357318","why":"ephrinB2 co-IP with CD31 at endothelial junctions"}],"covers":["LR008723"]},"LR004619":{"pair":"PGF -> NRP1","headline":"PlGF-2 (heparin-binding isoform) binds NRP1 b1b2 domain, heparin-dependent; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"125I-PlGF-2 co-precipitated with the NRP1 b1b2 domain, competed by VEGF165 [PMID:11986311]. A title states neuropilin-1 is a PlGF-2 receptor [PMID:9712843].","molecular_requirements":"b1b2 domain needed; heparin enhanced PlGF-2 binding 4-fold [PMID:11986311]. Binding in cells was heparin dependent [PMID:9712843].","affinity_potency":[],"species_and_systems":"Soluble Myc-tagged NRP1 domains from mammalian cells [PMID:11986311]; endothelial cross-linking, species unspecified [PMID:9712843]. Pair is ortholog-inferred.","localisation_and_range":"PGF flagged secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Isoform specific to PlGF-2; PlGF-1 marginal [PMID:9712843]. Both abstract only. UniProt agrees [DB:UniProt]; BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11986311","why":"NRP1 b1b2 binds PlGF-2"},{"PMID":"9712843","why":"PlGF-2 binds neuropilin-1"}],"covers":["LR001216","LR004619"]},"LR003098":{"pair":"PGLYRP1 -> CXCR3","headline":"No verified paper; only a UniProt annotation of the Tag7-Mts1 complex as CXCR3 ligand.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the PGLYRP1 complex acts as a ligand of CCR5 and CXCR3 [DB:UniProt].","molecular_requirements":"The ligand is a complex with S100A4/Mts1 per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Both judged rows were abstract_insufficient. A companion paper rules out PGLYRP1 alone binding CCR5, so chain-level support is doubtful [DB:UniProt].","key_references":[],"covers":["LR003098","LR006320"]},"LR001937":{"pair":"PGLYRP1 -> TREM1","headline":"PGLYRP1-peptidoglycan complexes bind and activate TREM-1; one abstract-only paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"PGLYRP1 with peptidoglycan forms a potent TREM-1 ligand inducing known TREM-1 functions; multimerized PGLYRP1 alone also activates [PMID:25595774]. UniProt cites the interaction [DB:UniProt].","molecular_requirements":"The ligand is normally a PGLYRP1-peptidoglycan complex; multimerization bypasses the peptidoglycan need [PMID:25595774].","affinity_potency":[],"species_and_systems":"Human and mouse recorded in the pair; the abstract does not name the experimental systems [PMID:25595774].","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Abstract only; adaptor TYROBP/DAP12 is part of TREM1 signalling per UniProt [DB:UniProt]. No affinities reported in our evidence.","key_references":[{"PMID":"25595774","why":"PGLYRP1-peptidoglycan complexes bind TREM-1"}],"covers":["LR001937","LR005274"]},"LR005276":{"pair":"PLA2G2A -> ITGA5","headline":"sPLA2-IIA activates integrin alpha5beta1 through site 2; abstract-level evidence from a single paper.","interaction_type":"functional only","direction_and_effect":"sPLA2-IIA activated integrins alpha4beta1 and alpha5beta1 in a site 2-mediated manner [PMID:25398877]. The curator detail reports activation of purified soluble and cell-surface alpha5beta1, independent of catalytic activity or M-type receptor [PMID:25398877]. Curated effect: agonist.","molecular_requirements":"The alpha5beta1 heterodimer is the unit; a site 2 peptide from integrin beta1 suppressed sPLA2-IIA effects [PMID:25398877]. UniProt lists ITGA5:ITGB1 binding PLA2G2A [DB:UniProt P05556].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract only. The docking prediction and direct site 2 binding in the abstract concern alphavbeta3; alpha5beta1 is covered by one sentence [PMID:25398877]. Alpha5 alone is not the binding unit.","key_references":[{"PMID":"25398877","why":"sPLA2-IIA site 2 activation of alphavbeta3, alpha4beta1, alpha5beta1"}],"covers":["LR001939","LR005276"]},"LR004628":{"pair":"PLAU -> PLAUR","headline":"Well-supported direct binding: uPA (amino-terminal fragment) binds uPAR, with a crystal structure, binding assays and several database records.","interaction_type":"direct binding","direction_and_effect":"uPA binds uPAR; the receptor-binding region lies in the uPA amino-terminal fragment, which inserts into a cavity formed by the three uPAR domains [PMID:16456079]. A peptide from uPA residues 12-32 inhibited receptor binding of labelled ATF, 50% at 100 nM; the paper was read as abstract only [PMID:3031025]. Effect on signalling not reported in our evidence.","molecular_requirements":"The amino-terminal fragment suffices for binding in the structure [PMID:16456079]. Binding sites on uPAR span domains I-III [PMID:11501527]. Single-chain pro-uPA binds without prior conversion to two-chain uPA [PMID:3023326].","affinity_potency":[{"value":"Kd 0.5 nM","assay":"pro-uPA binding to cells","system":"human U937 monocyte-like cells","cite":"PMID:3023326"}],"species_and_systems":"Human experiments throughout (crystal structure, phage display and peptide array, U937 cells) [PMID:16456079][PMID:11501527][PMID:3023326]. Mouse pair is projected from human evidence. PDB structures exist [DB:PDB 2FD6].","localisation_and_range":"Ligand flagged secreted; the receptor carries both secreted and transmembrane flags [flag]. A pro-uPA study indicates secreted pro-uPA reaches the cell-surface receptor [PMID:3023326].","caveats":"All four verified papers were read as abstracts only. UniProt notes that PLAUR can be cleaved and inactivated by its ligand [DB:UniProt].","key_references":[{"PMID":"16456079","why":"1.9 A crystal structure of uPAR with uPA amino-terminal fragment"},{"PMID":"3023326","why":"Kd 0.5 nM pro-uPA binding"},{"PMID":"11501527","why":"maps four uPA-binding regions across uPAR"}],"covers":["LR001225","LR004628"]},"LR006329":{"pair":"PLAUR -> FPR2","headline":"Functional evidence only, for a cleaved uPAR peptide (84-95) acting on FPRL1/FPR2; weak for full-length PLAUR.","interaction_type":"functional only","direction_and_effect":"The uPAR-derived peptide 84-95 induced human basophil chemotaxis, and uPA and its amino-terminal fragment were chemoattractants [PMID:15494526]. Desensitisation data point to FPRL2 as the main receptor, with FPRL1 (FPR2) contributing secondarily [PMID:15494526].","molecular_requirements":"The active ligand is the exposed epitope uPAR84-95, a cleaved form, not intact uPAR [PMID:15494526].","affinity_potency":[],"species_and_systems":"Human basophils; no binding measurement. Abstract only [PMID:15494526].","localisation_and_range":"Receptor is transmembrane [flag]; ligand flagged secreted [flag]. Range not otherwise reported.","caveats":"The row generalises a peptide to whole PLAUR, and FPR2 is not the primary receptor in this study. Mouse pair is projected.","key_references":[{"PMID":"15494526","why":"uPAR84-95 peptide chemoattracts basophils via FPRL1/FPRL2"}],"covers":["LR003108","LR006329"]},"LR008570":{"pair":"PLXNA4 -> SEMA6A","headline":"No verified evidence for this orientation; only a Reactome complex record and abstract-insufficient papers.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a SEMA6A:PLXNA2,PLXNA4 complex at the plasma membrane [DB:Reactome R-HSA-416728].","molecular_requirements":"Complex includes both PLXNA2 and PLXNA4 per Reactome [DB:Reactome R-HSA-416728].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Both partners flagged membrane-associated [flag].","caveats":"Four papers judged abstract-insufficient and one different-entity; no confirmed paper. Row is classed Receptor-Receptor.","key_references":[],"covers":["LR008570"]},"LR004637":{"pair":"PMCH -> MCHR1","headline":"MCH binds and activates MCHR1 with sub-nanomolar affinity in human recombinant cells; well supported, but MCH is also non-selective for MCHR2.","interaction_type":"direct binding","direction_and_effect":"PMCH-derived MCH is a full agonist at MCHR1: it binds SLC-1 (renamed MCHR1) on HEK293 cells, mobilises intracellular Ca2+ and reduces forskolin-elevated cAMP [PMID:10421367]. Signalling via Galphai and/or Galphaq is reported [PMID:10421368]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"A single receptor chain (MCHR1) is sufficient in the reported assays; no co-receptor is described in our evidence. Truncated analogues show a disulfide-cyclic core plus N-terminal Arg is enough for full activation of MCH-1R or MCH-2R [PMID:11478907]. Five PDB complex structures are listed (PDB 8WSS and others) [DB:PDB 8WSS].","affinity_potency":[{"value":"sub-nanomolar affinity","assay":"binding to SLC-1/MCHR1","system":"HEK293 cells, human receptor","cite":"PMID:10421367"},{"value":"pKi 9.7-10.5","assay":"GtoPdb curated affinity","system":"not stated","cite":"PMID:10421367"}],"species_and_systems":"Human receptor and ligand in recombinant HEK293/CHO cells [PMID:10421367][PMID:11478907]; the mouse pair is projected from human evidence (ortholog-inferred), no mouse experiment in our evidence.","localisation_and_range":"Ligand flagged secreted and receptor flagged transmembrane [flag], so paracrine or endocrine signalling to a cell-surface receptor.","caveats":"MCH is a potent but non-selective agonist at MCHR1 and MCHR2 [PMID:11478907][PMID:11839762]. Several papers report data for synthetic analogues rather than native MCH [PMID:11375253][PMID:11839762]. All papers were read as abstracts only.","key_references":[{"PMID":"10421367","why":"MCH binds human MCHR1 with sub-nanomolar affinity and activates it"},{"PMID":"10421368","why":"companion paper, MCH activates SLC-1 signalling"},{"PMID":"11478907","why":"active core of MCH; non-selective at MCHR1/MCHR2"}],"covers":["LR001234","LR004637"]},"LR004646":{"pair":"POMC -> OPRD1","headline":"One in vivo rat study implicates delta opioid receptor in beta-endorphin action; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"In rats, intra-NAc beta-endorphin lowers cue-induced cocaine seeking, and the delta opioid antagonist naltrindole raises it and blocks beta-endorphin's effect; the mu antagonist CTAP had no effect [PMID:23800967]. GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat in vivo behaviour with intra-accumbens infusion; read as abstract only [PMID:23800967]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRD1 transmembrane [flag]; the paper infuses beta-endorphin locally into nucleus accumbens [PMID:23800967].","caveats":"Evidence is antagonist pharmacology in behaviour, not binding. The active ligand is beta-endorphin, not full-length POMC. Only one paper; GtoPdb row has no affinity values given.","key_references":[{"PMID":"23800967","why":"Rat in vivo: naltrindole reverses beta-endorphin effect"}],"covers":["LR001244","LR004646"]},"LR010757":{"pair":"PON2 -> HTR2A","headline":"Only an IntAct two-hybrid record; the curator judged the paper a different entity, so there is no verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"A yeast two-hybrid interaction between P28223 and Q15165 is recorded [DB:IntAct]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No papers shown; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database-only support from a two-hybrid screen; the one judged paper was a different_entity. A secreted esterase with a serotonin receptor is not a validated ligand-receptor pair on this evidence.","key_references":[],"covers":["LR010757"]},"LR006347":{"pair":"POSTN -> ITGB5","headline":"Periostin-dependent cell adhesion is blocked by anti-alpha(V)beta(5) antibody, supporting ITGB5 as a periostin receptor; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Purified recombinant periostin supports adhesion of ovarian epithelial cells, inhibited by monoclonal antibodies against alpha(V)beta(3) or alpha(V)beta(5), but not by anti-beta(1) antibody [PMID:12235007]. The curator notes alphaVbeta3 colocalises to focal adhesions on periostin [PMID:12235007].","molecular_requirements":"The evidence concerns the alphaV-beta heterodimers, so alphaV with ITGB5 is needed; ITGB5 alone is not tested [PMID:12235007].","affinity_potency":[],"species_and_systems":"Human ovarian epithelial cells, recombinant periostin; read as abstract only [PMID:12235007]. The mouse pair is ortholog-inferred.","localisation_and_range":"Periostin is flagged secreted [flag]; adhesion to purified protein suggests matrix-bound action, which is an inference.","caveats":"Antibody blocking is indirect; the abstract does not report binding or affinity. The same antibody result covers both beta chains and does not separate them. Only one paper confirmed in the shown dossier.","key_references":[{"PMID":"12235007","why":"Antibody-blocked adhesion to periostin via alphaV integrins"}],"covers":["LR003126","LR006347"]},"LR004655":{"pair":"PRL -> PRLR","headline":"Well-established prolactin receptor pair: NMR structure, 2:1 complex, Kd 4x10(-10) M in transfected cells, many PDB entries.","interaction_type":"direct binding","direction_and_effect":"Prolactin activates PRLR in a 2:1 complex; hormone binding switches the WSXWS motif from a T-stack to a Trp/Arg-ladder and influences receptor dimerisation [PMID:22325776]. Tagged PRLR bound PRL and stimulated transcription of a beta-casein gene [PMID:9175708].","molecular_requirements":"Two receptor chains per hormone (2:1 complex) with receptor-receptor dimerisation at site 3 [PMID:22325776].","affinity_potency":[{"value":"Kd = 4x10(-10) M","assay":"PRL binding to Flag-tagged receptor","system":"transfected cells, rat PRLR","cite":"PMID:9175708"}],"species_and_systems":"NMR work on the human PRLR membrane-proximal domain [PMID:22325776]; the affinity study used rat PRLR cDNAs in transfected cells and does not state the PRL species [PMID:9175708]. Structures exist [DB:PDB 3D48].","localisation_and_range":"PRL is flagged secreted and PRLR transmembrane [flag].","caveats":"Both papers were abstract-only. Four further papers were pending and four abstract_insufficient. IntAct and PDB records also report the complex [DB:IntAct].","key_references":[{"PMID":"22325776","why":"NMR structure, hormone-dependent WSXWS switch, 2:1 complex"},{"PMID":"9175708","why":"PRL binds tagged PRLR, Kd 4x10(-10) M"}],"covers":["LR001254","LR004655"]},"LR006356":{"pair":"PRNP -> NRP1","headline":"Direct binding of normal PrP to immobilised neuropilin-1 in a biosensor assay, among many heparin-binding proteins; one paper.","interaction_type":"direct binding","direction_and_effect":"Normal protease-sensitive prion protein interacted with Npn-1 immobilised on an optical biosensor [PMID:15695515]. Functional effect on neuropilin-1 is not reported in our evidence.","molecular_requirements":"Interactions with heparin-binding proteins are ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Biosensor assay with purified proteins; curator labels species human [PMID:15695515].","localisation_and_range":"PRNP is flagged non-secreted, NRP1 secreted and transmembrane [flag].","caveats":"PrP is one of many proteins listed as binding Npn-1, and the 'strong binding' sentence the curator quoted refers to four FGFs, not PrP [PMID:15695515]. No affinity for PrP. Specificity is uncertain.","key_references":[{"PMID":"15695515","why":"Biosensor screen of heparin-binding proteins binding Npn-1"}],"covers":["LR003135","LR006356"]},"LR001946":{"pair":"PROS1 -> MERTK","headline":"PROS1 activates MER in a reporter-cell system, with context-dependent activation; one abstract-only paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Each TAM receptor showed a unique pattern of interaction with and activation by GAS6 and PROS1 in chimeric reporter cells; agonist action, modulated by apoptotic cells, phosphatidylserine vesicles and enveloped virus [PMID:25074926]. Reactome describes MERTK binding Gas6 or Protein S [DB:Reactome R-HSA-202710].","molecular_requirements":"Gamma-carboxylation of the ligands is essential for full TAM activation; soluble immunoglobulin-like TAM domains act as specific ligand antagonists [PMID:25074926].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in chimeric-receptor reporter cell lines [PMID:25074926]; mouse pair is ortholog-inferred.","localisation_and_range":"PROS1 annotated secreted and MERTK transmembrane [flag]; activation depends on phosphatidylserine presentation (soluble, apoptotic cell or viral envelope) [PMID:25074926].","caveats":"Single abstract-only paper that covers all three TAM receptors; MER-specific numbers are not reported in our evidence. One further row was review-only.","key_references":[{"PMID":"25074926","why":"Chimeric TAM reporter study of GAS6/PROS1 activation patterns."}],"covers":["LR001946","LR005282"]},"LR004664":{"pair":"PSAP -> GPR37L1","headline":"Prosaptide binds and activates GPR37L1 (pEC50 8.3); full-length prosaposin also stimulates; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Prosaptide promoted endocytosis of GPR37L1, bound it and activated GPR37L1-dependent signalling, with ERK phosphorylation, 35S-GTPgammaS binding and cAMP inhibition [PMID:23690594]. UniProt says GPR37L1 binds prosaposin, causing endocytosis and an ERK cascade [DB:UniProt]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Prosaptide is the active fragment; full-length prosaposin also stimulates GPR37L1 signalling [PMID:23690594].","affinity_potency":[{"value":"pEC50 8.3","assay":"prosaptide agonist activity","system":"human prosaptide at human GPR37L1","cite":"PMID:23690594"}],"species_and_systems":"Human proteins in cells; primary astrocytes were protected from oxidative stress, attenuated by siRNA knockdown [PMID:23690594]. Mouse pair is ortholog-inferred.","localisation_and_range":"PSAP flagged secreted and GPR37L1 transmembrane [flag]; paracrine.","caveats":"One paper, abstract-only; one further row pending. Astrocyte knockdown covered GPR37 and GPR37L1 together [PMID:23690594].","key_references":[{"PMID":"23690594","why":"Deorphanisation of GPR37L1 by prosaptide and prosaposin."}],"covers":["LR001264","LR004664"]},"LR004673":{"pair":"PTH -> PTH1R","headline":"PTH binds and activates PTH1R; well supported by crosslinking, binding and structural records.","interaction_type":"direct binding","direction_and_effect":"PTH is an agonist at PTH1R [PMID:31594997]. UniProt says PTH activates PTH1R, engaging Gs-cAMP/PKA and Gq-PLC/PKC signalling [DB:UniProt].","molecular_requirements":"Binding involves the receptor extracellular domain and orthosteric pocket [PMID:31594997]; a PTH analogue contacts receptor residues 173-189 [PMID:9108031].","affinity_potency":[{"value":"KD 4 uM","assay":"ITC, PTH1R ECD titrated into PTH (1-34)","system":"purified proteins","cite":"PMID:31594997"},{"value":"KD 3.8 uM","assay":"ITC, PTH (1-34) titrated into PTH1R ECD","system":"purified proteins","cite":"PMID:31594997"}],"species_and_systems":"Human receptor in HEK-293 cells for a photoreactive PTH agonist [PMID:9108031]; human ligand and receptor in COS-7 cells with PTHrP/PTH analogues [PMID:12947048].","localisation_and_range":"Secreted ligand and transmembrane receptor [flag].","caveats":"Many verified papers are abstract-only. Crosslinking papers used analogues, not native PTH. One pending paper not shown.","key_references":[{"PMID":"9108031","why":"Photocrosslinking maps PTH agonist contact to receptor 173-189."},{"PMID":"12947048","why":"Crosslinking localises position 19 contact to Leu232-Lys240."},{"PMID":"31594997","why":"Native binding and ITC of PTH (1-34) to PTH1R ECD."}],"covers":["LR001273","LR004673"]},"LR006365":{"pair":"PTK7 -> ADGRD1","headline":"PTK7 binds the ADGRD1 (GPR133) N-terminal fragment and raises its signalling in trans in glioblastoma models; direct binding is supported.","interaction_type":"direct binding","direction_and_effect":"PTK7 is a positive allosteric modulator of GPR133: expressed in trans in neighbouring cells it increased cAMP, additive with the orthosteric Stachel-mimicking peptide [PMID:37354459]. No cAMP increase was seen when both were co-expressed in the same cells [PMID:37354459].","molecular_requirements":"PTK7 binds the autoproteolytically generated N-terminal fragment; the effect requires GPR133 intramolecular cleavage and PTK7 plasma-membrane anchoring, and a secreted PTK7 NTF did not work [PMID:37354459]. The PTX domain is not needed for binding [PMID:37354459].","affinity_potency":[],"species_and_systems":"Human proteins; affinity proteomics in patient-derived glioblastoma cells, validation in HEK293T cells [PMID:37354459]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound PTK7 acting on neighbouring cells (juxtacrine) [PMID:37354459]. The ligand is flagged as secreted [flag], but the paper found the secreted form inactive.","caveats":"Single paper; no affinity reported. Mechanism is allosteric modulation rather than classical agonism. A secreted-flag annotation on PTK7 conflicts with the paper's anchoring requirement.","key_references":[{"PMID":"37354459","why":"Identifies PTK7 as GPR133 binder and positive allosteric modulator"}],"covers":["LR003144","LR006365"]},"LR010649":{"pair":"PTMA -> VIPR1","headline":"Thymosin alpha 1, derived from PTMA, displaces VIP at VPAC1-type sites in rodent cells; the PTMA precursor itself was not tested.","interaction_type":"direct binding","direction_and_effect":"Thymosin alpha 1 inhibits 125I-VIP binding over a 10^-11 to 10^-6 M range, so it engages the VIP receptor site, classed as antagonist-like [PMID:8886855].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human thymosin alpha 1 tested on rat and mouse peritoneal macrophages and on rat lymphocytes (native cells, not recombinant) [PMID:8886855]. The paper speaks of the VIP receptor system, not specifically VPAC1.","localisation_and_range":"Not reported in our evidence; PTMA has no secreted flag in the dossier.","caveats":"Abstract only. The ligand entity PTMA is the precursor; the active peptide tested was the fragment thymosin alpha 1 [PMID:8886855]. Rodent cells were used and receptor subtype assignment to VIPR1 is not shown. No database support.","key_references":[{"PMID":"8886855","why":"Thymosin alpha 1 competes with VIP binding in rodent immune cells"}],"covers":["LR010649"]},"LR006374":{"pair":"PTN -> ROR1","headline":"One SPR study shows human PTN binding the ROR1 ectodomain; no functional data.","interaction_type":"direct binding","direction_and_effect":"Human PTN as analyte bound the ROR1 ectodomain by surface plasmon resonance, validating a CRISPRa screen hit; the comparator MDK showed no binding [PMID:36178190]. Functional effect not reported in our evidence.","molecular_requirements":"Receptor ectodomain only; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant ectodomains, SPR [PMID:36178190].","localisation_and_range":"ROR1 is flagged transmembrane and PTN secreted [flag].","caveats":"Single paper, in vitro; no affinity value in our evidence; the paper also reports a 'steady-state curve' but no number is given here.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to ROR1-ECD"}],"covers":["LR003153","LR006374"]},"LR006383":{"pair":"PTPRD -> SLITRK3","headline":"Cell-aggregation evidence in mouse for PTPRD and SLITRK3; single paper, human and mouse pairs both inferred.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing L cells specifically aggregated with PTP-delta-expressing L cells [PMID:23345436]. Effect direction on either partner is not reported in our evidence.","molecular_requirements":"Not reported in our evidence; the paper says Slitrks need distinct LAR-RPTP members for synapse formation, with PTP-delta needed for inhibitory synapse differentiation [PMID:23345436].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells [PMID:23345436]. Both human and mouse pairs are ortholog-inferred, so no direct human data are shown.","localisation_and_range":"Both flagged transmembrane [flag]; cell-cell aggregation suggests contact-dependent action [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. No database record supports this pair.","key_references":[{"PMID":"23345436","why":"Cell-aggregation assay Slitrk3 with PTP-delta cells"}],"covers":["LR003162","LR006383"]},"LR005285":{"pair":"PTPRK -> PTPRK","headline":"PTPRK is a homophilic adhesion receptor: self-binding shown by aggregation in 1994 and stabilisation at cell contacts in 2019.","interaction_type":"direct binding","direction_and_effect":"R-PTP-kappa mediates homophilic intercellular interaction; its extracellular domain functions as an adhesion substrate and induces aggregation of coated beads [PMID:8264577]. In epithelial cells PTPRK is stabilised at cell-cell contacts, and it dephosphorylates at least five substrates (Afadin, PARD3, delta-catenin family members) [PMID:30924770]. Curated effect: agonist.","molecular_requirements":"Extracellular domain alone suffices for adhesion; adhesion needs no PTPase activity or proteolytic cleavage and is calcium independent [PMID:8264577]. A recombinant PTPRK ECD screened against a secreted-protein microarray found no additional ligands [PMID:30924770].","affinity_potency":[],"species_and_systems":"Human proteins; heterologous cells and beads in 1994 [PMID:8264577]; epithelial cells (MCF10A, Hs27 lysates) in 2019 [PMID:30924770]. Human and mouse pairs listed, neither projected.","localisation_and_range":"Membrane-bound, trans homophilic interaction at cell-cell contacts [PMID:30924770] [PMID:8264577].","caveats":"Self-pair: the ligand and receptor are the same protein, so scoring needs a single-subunit expression rule. The 2019 paper's homophilic claim rests on contact stabilisation and its text excerpts, and its main findings concern substrates; the 1994 paper was read as abstract only. IntAct reports a dimerization assay [DB:IntAct].","key_references":[{"PMID":"8264577","why":"Homophilic binding of R-PTP-kappa"},{"PMID":"30924770","why":"PTPRK stabilised at cell contacts; substrates"}],"covers":["LR001949","LR005285"]},"LR006392":{"pair":"PTPRS -> SLITRK2","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK2 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk2-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported.","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Human pair is direct; mouse pair is ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check.","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003171","LR006392"]},"LR004682":{"pair":"PYY -> NPY4R","headline":"PYY binds human NPY4R (Y4) with nanomolar affinity, but pancreatic polypeptide is the preferred ligand.","interaction_type":"direct binding","direction_and_effect":"PYY acts as a full agonist at Y4 [DB:GtoPdb]; both papers show human Y4 binds PYY with lower affinity than PP [PMID:7592911][PMID:7493937].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 9.89","assay":"125I-PYY saturation binding","system":"human Y4, transient expression","cite":"PMID:7592911"},{"value":"pKi 9.06","assay":"displacement of 125I-PYY","system":"human Y4, transient expression","cite":"PMID:7592911"},{"value":"Ki 1.44 nM","assay":"radioligand binding","system":"CHO cells, human Y4","cite":"PMID:7493937"}],"species_and_systems":"Human receptor in transfected cells (human placental genomic clone; CHO) [PMID:7592911][PMID:7493937]. Mouse pair is projected.","localisation_and_range":"PYY is flagged secreted [flag]; Y4 is a transmembrane GPCR.","caveats":"Both papers read as abstract. In both, PP binds better (PP pKi = 10.25; Ki 13.8 pM), so Y4 is primarily a PP receptor [PMID:7592911][PMID:7493937]. One additional paper was judged a different entity.","key_references":[{"PMID":"7592911","why":"Y4 cloning with PYY binding, pKi 9.06"},{"PMID":"7493937","why":"Y4 cloning with PYY Ki 1.44 nM; GtoPdb source"}],"covers":["LR001282","LR004682"]},"LR003179":{"pair":"RAE1 -> KLRK1","headline":"RAE-1 proteins bind NKG2D (KLRK1) in the original mouse study; a BioGRID record supports the pair.","interaction_type":"direct binding","direction_and_effect":"RAE-1 alpha, beta, gamma and delta and H60 were stained by mNKG2D-Ig fusion protein, and RAE-1 and H60 rendered cells susceptible to NK cytotoxicity [PMID:10894171]. Activating receptor, ligand on target cell.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse NKG2D-Ig and mouse cell lines (Ba/F3 transductants, F9, LL/2) [PMID:10894171]. BioGRID lists a reconstituted complex [DB:BioGRID]. The human pair is projected from mouse (ortholog inferred).","localisation_and_range":"RAE-1 is described as GPI-anchored membrane protein [PMID:10894171]; ligand is flagged not secreted [flag]. Contact-dependent.","caveats":"The dossier marks the experiment species as human, but the paper used mouse NKG2D and mouse RAE-1. No affinity reported. Pair is projected to human.","key_references":[{"PMID":"10894171","why":"RAE-1 family identified as mNKG2D ligands"}],"covers":["LR003179","LR006399"]},"LR001955":{"pair":"RAET1G -> KLRK1","headline":"RAET1G is a genuine but weak human NKG2D (KLRK1) ligand; one abstract-only binding paper plus IntAct records.","interaction_type":"direct binding","direction_and_effect":"RAET1G only weakly interacts with NKG2D, which gives less-efficient NKG2D down-regulation and NK degranulation than its paralogue ULBP2; curators label it an agonist [PMID:19424970].","molecular_requirements":"Not reported in our evidence beyond NKG2D itself; a single alpha2-domain amino-acid substitution in RAET1G is described as the main reason for the weaker binding [PMID:19424970].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor per curator fields; the abstract does not specify the assay system (not reported in our evidence). IntAct lists five records using FACS and ELISA [DB:IntAct].","localisation_and_range":"RAET1G is flagged both secreted and transmembrane [flag]; the paper notes an extended cytoplasmic domain, and the contact vs soluble mode is not resolved in our evidence [PMID:19424970].","caveats":"Only one paper, read as abstract only; no affinity value reported. Binding is weak relative to ULBP2, so low-expression contexts may give little signal.","key_references":[{"PMID":"19424970","why":"RAET1G binds NKG2D weakly vs ULBP2; single alpha2 substitution"}],"covers":["LR001955"]},"LR001289":{"pair":"RBP4 -> STRA6","headline":"RBP4 and STRA6 coordinate retinol transport in adipocyte precursors; evidence here is functional plus Reactome and UniProt records.","interaction_type":"functional only","direction_and_effect":"STRA6, depending on apo- or holo-RBP4, mediates bidirectional retinol transport: retinol-loaded holo-RBP4 blocked adipocyte differentiation via RARalpha, while retinol-free apo-RBP4 triggered retinol efflux and enhanced adipogenesis [PMID:23959802]. UniProt says RBP4 transfers retinol to STRA6 [DB:UniProt].","molecular_requirements":"The effect depends on RBP4 loading state; Reactome lists complexes TTR:RBP4:STRA6 and TTR:RBP4:atROL:STRA6 [DB:Reactome R-HSA-2453850]. Ectopic STRA6 acted synergistically with apo-RBP4 [PMID:23959802].","affinity_potency":[],"species_and_systems":"Curators record human/human, but the abstract describes mouse in vivo retinoid mobilization and cultured precursor cells [PMID:23959802].","localisation_and_range":"RBP4 is flagged secreted; STRA6 is a membrane receptor [flag].","caveats":"Paper read as abstract only; no binding affinity in our evidence. The paper concerns retinol transport rather than classical signaling, and opposite outcomes arise from apo vs holo forms. The human pair is ortholog-inferred; mouse evidence is the direct data.","key_references":[{"PMID":"23959802","why":"STRA6 bidirectional retinol transport by apo/holo-RBP4"}],"covers":["LR001289","LR004688"]},"LR004691":{"pair":"RELN -> LRP8","headline":"Reelin is a well-supported direct ligand of ApoER2 (LRP8), with nM-range affinity and genetic necessity evidence.","interaction_type":"direct binding","direction_and_effect":"Reelin binds ApoER2 directly and calcium-dependently [PMID:10571240]. Purified Reelin associated more readily with ApoER2 than VLDLR, with agonist-type signalling (Dab1 tyrosine phosphorylation) [PMID:12670700]. Reelin enhanced LTP in hippocampal slices and this was abolished in ApoER2 knockouts [PMID:12167620]. UniProt lists LRP8 as a cell surface receptor for Reelin [DB:UniProt].","molecular_requirements":"Acidic residues in apoER2 complement-type repeats 1 and 3 are required; Reelin appears to engage two or more apoER2 molecules for high-affinity signalling [PMID:12899622]. Both ApoER2 and VLDLR were needed for complete Dab1 phosphorylation [PMID:12670700] and for LTP enhancement [PMID:12167620]. Binding is inhibited by apoE [PMID:10571240].","affinity_potency":[{"value":"KD 0.2 nM","assay":"surface plasmon resonance","system":"Reelin and apoER2, human","cite":"PMID:12899622"}],"species_and_systems":"Mixed: mouse/human Reelin with human receptor [PMID:10571240]; purified human Reelin with mouse neurons [PMID:12670700]; SPR with human proteins [PMID:12899622]; mouse hippocampal slices [PMID:12167620].","localisation_and_range":"RELN is flagged secreted [flag]. LRP8 is flagged transmembrane [flag].","caveats":"Four papers shown were all read as abstracts only. One abstract is truncated. BioGRID also lists reconstituted-complex and affinity-capture records [DB:BioGRID].","key_references":[{"PMID":"12899622","why":"SPR affinity of Reelin for apoER2"},{"PMID":"10571240","why":"Direct binding of Reelin to VLDLR and ApoER2"},{"PMID":"12670700","why":"Purified Reelin prefers ApoER2; Dab1 phosphorylation"}],"covers":["LR001292","LR004691"]},"LR003188":{"pair":"RGMB -> PDCD1LG2","headline":"PD-L2 binds RGMb at a site distinct from BMP; one paper, mouse respiratory tolerance model.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds RGMb and the two bind distinct sites from BMP-2/4; blocking the RGMb-PD-L2 interaction impaired respiratory tolerance by reducing initial T-cell expansion [PMID:24752301].","molecular_requirements":"PD-L2 and BMP-2/4 bind non-overlapping sites on RGMb [PMID:24752301].","affinity_potency":[],"species_and_systems":"Lung tissue and mouse tolerance model; curator lists human; the human pair is ortholog-inferred, the mouse pair is not [PMID:24752301].","localisation_and_range":"RGMb is not flagged secreted and PDCD1LG2 is transmembrane [flag].","caveats":"Abstract-only; no affinity; the paper frames PD-L2 as ligand and RGMb as receptor, opposite to the pair's written direction.","key_references":[{"PMID":"24752301","why":"PD-L2 binds RGMb; role in respiratory tolerance"}],"covers":["LR003188","LR006408"]},"LR001298":{"pair":"RLN2 -> RXFP1","headline":"Relaxin-2 acting as an agonist at RXFP1, supported by binding and cAMP studies plus database records; most papers read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"H2 relaxin (RLN2) is the established agonist of RXFP1 (LGR7) [PMID:15649866], acting through a cAMP-dependent pathway [PMID:11809971]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Two binding sites were described on RXFP1/RXFP2: a primary high-affinity site in the ectodomain and a secondary lower-affinity site in the transmembrane region; the primary site dictates binding [PMID:15649866]. Whether other subunits are needed is not reported in our evidence.","affinity_potency":[{"value":"pKi 9.239999771118164 to 10.199999809265137","assay":"GtoPdb affinity range (pKi)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in all curated papers; recombinant or cell-based systems. A soluble LGR7 ligand-binding region delayed parturition in antepartum mice [PMID:11809971].","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag], so endocrine or paracrine signalling to a membrane receptor.","caveats":"All four confirmed papers were read as abstracts only. PMID:12506116 states the RLN2/LGR7 pairing only as background; its new data concern H3 relaxin.","key_references":[{"PMID":"11809971","why":"Deorphanisation of LGR7/LGR8 as relaxin receptors via cAMP"},{"PMID":"15649866","why":"Two-site binding model for relaxin peptides at RXFP1/RXFP2"},{"PMID":"22973049","why":"Relaxin binds and activates RXFP1 and RXFP2 (chimeric ECD study)"}],"covers":["LR001298"]},"LR012359":{"pair":"RNF43 -> FZD1:LRP6","headline":"RNF43 -> FZD1:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: different_entity 2, abstract_insufficient 2). Some judged rows were a different entity.","key_references":[],"covers":["LR012359"]},"LR012395":{"pair":"RNF43 -> FZD9:LRP6","headline":"RNF43 -> FZD9:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 3). ","key_references":[],"covers":["LR012395"]},"LR007391":{"pair":"RSPO1 -> FZD8:LRP6","headline":"RSPO1 -> FZD8:LRP6 complex is supported only by UniProt annotations.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states RSPO1 acts as a ligand for FZD8 and LRP6 and interacts with their extracellular domains [DB:UniProt].","molecular_requirements":"Complex of FZD8 and LRP6; whether both subunits are needed together is not reported in our evidence.","affinity_potency":[],"species_and_systems":"UniProt cites PMIDs 16109882 and 17804805; species not stated [DB:UniProt].","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"No papers judged (2 pending); support is two UniProt statements only [DB:UniProt]. A complex-level interaction is not shown in our evidence.","key_references":[],"covers":["LR007391"]},"LR004709":{"pair":"RSPO2 -> LGR4","headline":"RSPO2 binds and activates LGR4, with binding, functional and genetic evidence.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 [PMID:21693646]. Human RSPO2 mutants show impaired binding to LGR4/5/6 and to RNF43/ZNRF3 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp complex [PMID:21727895]. RSPO2 limb function was independent of LGR4/5/6 and ran through RNF43/ZNRF3 [PMID:29769720].","affinity_potency":[{"value":"pEC50 12.52","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins in intestinal crypts and reporter assays [PMID:21693646]; human tetra-amelia mutations [PMID:29769720]; mouse gut deletion [PMID:21727895].","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"All three papers abstract only. The PMID 21727895 evidence sentence concerns Lgr5/Lgr4 co-expression, not RSPO2 binding. One review-only row exists.","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands, pEC50"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"},{"PMID":"21727895","why":"LGR4/5 mediate R-spondin signalling"}],"covers":["LR001312","LR004709"]},"LR003197":{"pair":"RTN2 -> RTN4R","headline":"RTN2 binds NgR1 (RTN4R) with nanomolar affinity in a single biophysical mapping paper, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"The paper reports novel nanomolar interactions of RTN2 and RTN3 with NgR1; effect on signalling is not reported in our evidence [PMID:17189258].","molecular_requirements":"Not reported for this pair; the abstract describes NgR1 mapping to the concave face of its leucine-rich-repeat domain [PMID:17189258].","affinity_potency":[],"species_and_systems":"Recombinant biophysical mapping across reticulon and NgR families; curators record human ligand and receptor. The human pair is ortholog-inferred [PMID:17189258].","localisation_and_range":"RTN4R is flagged transmembrane [flag]; RTN2 is a reticulon, typically intracellular, and its extracellular availability is not reported in our evidence.","caveats":"The exact affinity value is not in the abstract. The curator assay_class is direct_binding but the paper is abstract-only. Effect direction \"agonist\" is not stated in the abstract. No database records.","key_references":[{"PMID":"17189258","why":"Systematic mapping of reticulon-NgR interactions; RTN2/RTN3 bind NgR1"}],"covers":["LR003197","LR006417"]},"LR005294":{"pair":"RTN4 -> S1PR2","headline":"Nogo-A-Delta20 binds S1PR2 with KD about 142 nM and signals via G13/RhoA; one abstract-level paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Nogo-A-Delta20 acts at S1PR2 to counteract neurite outgrowth and signals via G13, LARG and RhoA; blockade of S1PR2 enhances LTP in wild-type but not Nogo-A-/- mice [PMID:24453941]. The paper describes an inhibitory (repressor) role of the axis, antagonist-labelled by curators.","molecular_requirements":"Nogo-A-Delta20 binds S1PR2 at sites distinct from the S1P pocket [PMID:24453941]. S1P did not change binding (KD MeOH ~192 nM; KD S1P ~202 nM) [PMID:24453941].","affinity_potency":[{"value":"KD ~142 nM","assay":"Bio-Layer interferometry, Nogo-A-ext on S1PR2 membranes","system":"S1PR2-overexpressing membranes","cite":"PMID:24453941"},{"value":"KD ~280 nM","assay":"Microscale thermophoresis, Delta20 to ECL2 peptide","system":"synthetic peptide","cite":"PMID:24453941"},{"value":"KD ~350 nM","assay":"Microscale thermophoresis, Delta20 to ECL3 peptide","system":"synthetic peptide","cite":"PMID:24453941"}],"species_and_systems":"Co-IP from mouse brain extracts (absent in Nogo-A-/- and S1PR2-/- extracts), S1PR2-overexpressing membranes, 3T3 cells [PMID:24453941]. Curators record human ligand and receptor; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Nogo-A is a membrane protein per the paper [PMID:24453941], so contact-dependent or via cleaved fragments; RTN4 flagged non-secreted [flag]. S1PR2 is internalised upon binding, with cell surface levels reduced by ~64% after 30 min [PMID:24453941].","caveats":"Only the Delta20 domain, not RTN4 isoforms generally, is shown to bind. Affinity values are apparent (\"~\") values from the full-text excerpts. No database records support the pair.","key_references":[{"PMID":"24453941","why":"S1PR2 as Nogo-A-Delta20 receptor, KD ~142 nM, repressing LTP"}],"covers":["LR001961","LR005294"]},"LR006419":{"pair":"RTN4R -> ADGRB1","headline":"Direct, high-affinity binding with a crystal structure, confirmed by two independent papers; RTN4R is the ligand for the BAI1 adhesion-GPCR.","interaction_type":"direct binding","direction_and_effect":"RTN4R ectodomain binds the thrombospondin type 1 repeat (TSR) region of ADGRB1 (BAI1); the Cell paper calls RTN4 receptors high-affinity ligands for BAIs [PMID:34758294]. Binding was also found by CRISPRa selection with an ADGRB1 probe and by AVEXIS [PMID:30477585]. Effect on signalling is not reported in our evidence; in human neurons RTN4 receptors regulate dendritic arborization, axonal elongation and synapse formation via glial versus neuronal BAIs [PMID:34758294].","molecular_requirements":"A single TSR domain of BAI1 is sufficient and binds the RTN4R leucine-rich repeat domain; C-mannosylation of tryptophan and O-fucosylation of threonine in the TSR domain form the interface [PMID:34758294]. TSR1-3 of ADGRB1 were sufficient for binding [PMID:30477585]. BAI2 does not bind RTN4Rs [PMID:34758294]. No requirement for other subunits is reported.","affinity_potency":[{"value":"Kd = 1.9 nM","assay":"surface plasmon resonance, recombinant ectodomains (highest of the BAI-RTN4R pairs; BAI3-RTN4R)","system":"purified recombinant proteins","cite":"PMID:34758294"},{"value":"Kd = 30.0 nM","assay":"surface plasmon resonance (lowest, BAI1-RTN4RL2)","system":"purified recombinant proteins","cite":"PMID:34758294"}],"species_and_systems":"Recombinant human ectodomains and HEK293 cells; the 1.65 A crystal structure used mouse RTN4R LRR with mouse BAI1 TSR3, and the paper says contact residues are conserved in human [PMID:34758294]. Human neurons were used for function [PMID:34758294]. Human and mouse pairs are both listed in the dossier.","localisation_and_range":"RTN4R is not flagged secreted but is a GPI-linked cell-surface protein in the text; trans-cellular adhesion between cells expressing BAIs and RTN4Rs was shown, so contact-dependent (juxtacrine) [PMID:34758294][PMID:30477585]. ADGRB1 carries a secreted flag [flag].","caveats":"The Kd values quoted are the extremes across BAI/RTN4R-family pairs, not necessarily this pair. ADGRB1 is flagged secreted although described as a membrane receptor [flag]. One study is a single CRISPRa screen per bait [PMID:30477585].","key_references":[{"PMID":"34758294","why":"SPR affinities, crystal structure, neuronal function"},{"PMID":"30477585","why":"independent CRISPRa and AVEXIS discovery of the interaction"}],"covers":["LR003199","LR006419"]},"LR006428":{"pair":"S100A10 -> HTR1B","headline":"p11/S100A10 is reported to interact with 5-HT1B and modulate its signalling; support rests on one abstract-only paper that mainly studied 5-HT4.","interaction_type":"functional only","direction_and_effect":"p11 interacts with 5-HTR1B, modulates its signal transduction and is required for antidepressant responses to receptor activation [PMID:19211900]. This is stated as background in the abstract.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Abstract states human-labelled entities; behavioural work is in vivo, species not stated in the abstract [PMID:19211900].","localisation_and_range":"S100A10 is not flagged secreted [flag]; p11 acts as an intracellular accessory protein, per the abstract's description of modulating receptor signalling [PMID:19211900].","caveats":"Curated from background sentence of a paper whose new findings concern HTR4. Abstract only. The curator noted a corrupted receptor-symbol field in the source record. The assay class 'direct_binding' is not directly shown in the abstract.","key_references":[{"PMID":"19211900","why":"Specificity screen of p11 against serotonin receptors"}],"covers":["LR003208","LR006428"]},"LR006437":{"pair":"S100A4 -> ERBB3","headline":"SPR and label transfer show S100A4 binds ErbB3 with Kd 58.0 nM; ErbB3 function is not established.","interaction_type":"direct binding","direction_and_effect":"S100A4 transferred label to ErbB3 and bound it in SPR; an anti-ErbB3 antibody did not significantly inhibit S100A4-induced neuroprotection (p = 0.15) [PMID:30083275].","molecular_requirements":"ErbB2 did not bind S100A4 but its knockdown abolished neuroprotection [PMID:30083275].","affinity_potency":[{"value":"Kd 58.0 \u00b1 30.0 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB3","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons; species not stated in excerpts [PMID:30083275]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and ERBB3 transmembrane [flag].","caveats":"Binding only; functional dependence is on ErbB4, not ErbB3. Kd error is large. Abstract-level curation.","key_references":[{"PMID":"30083275","why":"S100A4-ErbB binding by SPR"}],"covers":["LR003219","LR006437"]},"LR006446":{"pair":"S100A8 -> MCAM","headline":"MCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only, no affinity.","interaction_type":"functional only","direction_and_effect":"MCAM functions as an S100A8/A9 receptor, activating NF-kappaB (more prominently than ALCAM or RAGE) and ROS formation and promoting malignant melanoma progression [PMID:27151304]. Agonist-like.","molecular_requirements":"The ligand tested is the S100A8/A9 complex; S100A8 alone is not separated in our evidence [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted by flag [flag]; MCAM is flagged as a receptor but not transmembrane [flag], which looks inconsistent with a membrane receptor.","caveats":"Abstract only; the curator row is labelled direct_binding but the evidence sentence describes receptor function, not binding measurement. No Kd. No database support.","key_references":[{"PMID":"27151304","why":"MCAM as S100A8/A9 receptor driving NF-kB and ROS in melanoma"}],"covers":["LR003229","LR006446"]},"LR006455":{"pair":"S100A9 -> CD69","headline":"The S100A8/S100A9 complex binds CD69 on human PBMCs; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"The S100A8/S100A9 complex was identified as the natural ligand of CD69 in human PBMCs, confirmed by in vitro binding and competition assay; association was required for SOCS3 up-regulation, inhibited STAT3 signalling and supported Treg differentiation [PMID:26296369]. UniProt records the interaction [DB:UniProt]. Agonist-like.","molecular_requirements":"Complex-level ligand; S100A9 alone is not separated in our evidence. Binding was significantly abolished by peptide-N-glycosidase treatment of CD69, so CD69 glycosylation is required [PMID:26296369].","affinity_potency":[],"species_and_systems":"Human PBMCs and in vitro binding; mouse pair is ortholog-inferred [PMID:26296369].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD69 flagged as receptor [flag].","caveats":"Abstract only. UniProt cites the same paper, so is not independent. No affinity.","key_references":[{"PMID":"26296369","why":"S100A8/S100A9 as CD69 ligand"}],"covers":["LR003239","LR006455"]},"LR004727":{"pair":"S100A9 -> TLR4","headline":"S100A9 binding to TLR4 activates MAPK signalling and AML-cell differentiation; abstract-only, plus Reactome complex records.","interaction_type":"functional only","direction_and_effect":"Binding of S100A9 to TLR4 promotes activation of p38, ERK1/2 and JNK, leading to myelomonocytic and monocytic AML cell differentiation; recombinant S100A9 increased AML cell maturation and prolonged survival in an AML mouse model [PMID:28137827]. Agonist. Reactome lists S100A8:S100A9 binding TLR4:LY96 [DB:Reactome] and UniProt describes S100A9 binding TLR4 and AGER as an alarmin [DB:UniProt].","molecular_requirements":"S100A8 prevented S100A9-induced differentiation, so a high S100A9:S100A8 ratio is needed [PMID:28137827]. Reactome models the heterodimer with TLR4:LY96 [DB:Reactome].","affinity_potency":[],"species_and_systems":"AML mouse models and primary human AML samples; both human and mouse pairs are directly supported [PMID:28137827].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Abstract only; binding is stated, not measured with affinity, in our evidence. Two further papers were judged abstract_insufficient and are not shown.","key_references":[{"PMID":"28137827","why":"S100A9-TLR4 signalling drives AML differentiation"}],"covers":["LR001330","LR004727"]},"LR008921":{"pair":"SCGB3A1 -> MARCO","headline":"Same PMID as the SCGB3A2-MARCO pair; the paper concerns UGRP1, so assignment to SCGB3A1 is uncertain; BioGRID FRET record.","interaction_type":"database-asserted only","direction_and_effect":"The paper identified MARCO by expression cloning as a receptor for UGRP1, and UGRP1 bound bacteria and yeast; LPS competed with UGRP1 for MARCO binding [PMID:12847263]. BioGRID records a FRET interaction [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, lung tissue and expression cloning [PMID:12847263].","localisation_and_range":"Not reported in our evidence beyond the curated entity flags (receptor flag only) [flag].","caveats":"Read as abstract only; the evidence sentence is truncated. The abstract also describes HIN-1 and HIN-2/UGRP1 and does not state SCGB3A1 as the partner.","key_references":[{"PMID":"12847263","why":"MARCO identified as UGRP1 receptor"}],"covers":["LR008921"]},"LR006464":{"pair":"SCRG1 -> BST1","headline":"SCRG1 is proposed as a ligand of BST1 on human mesenchymal stem cells; one paper, functional plus co-IP, no affinity.","interaction_type":"functional only","direction_and_effect":"SCRG1 acts as an agonist: recombinant SCRG1 drives Akt, ERK and FAK phosphorylation and migration, and BST1 knockdown suppresses the Akt, ERK and FAK responses [PMID:24413464].","molecular_requirements":"BST1 appears to work with beta1 integrin: immunoprecipitated SCRG1-FLAG pulled down beta1 integrin and BST1, suggesting a BST1/beta1-integrin receptor complex. UE7T-13 cells lacked beta2 integrin [PMID:24413464].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells (UE7T-13 line), human ligand and receptor, recombinant SCRG1 and siRNA knockdown [PMID:24413464]. Mouse pair is projected from human.","localisation_and_range":"SCRG1 is flagged secreted [flag]; the paper describes it as secreted from hMSCs and autocrine [PMID:24413464].","caveats":"Only one paper, read from abstract plus excerpts. Binding is inferred from co-IP and knockdown, not purified-protein binding; no affinity reported. Not reported in our evidence whether SCRG1 binds BST1 directly without integrin.","key_references":[{"PMID":"24413464","why":"Identifies BST1 as the SCRG1 receptor in hMSCs; knockdown and co-IP"}],"covers":["LR003248","LR006464"]},"LR001964":{"pair":"SECTM1 -> CD7","headline":"SECTM1 binds CD7 in human cells with two supporting lines of evidence, but its effect is context dependent.","interaction_type":"direct binding","direction_and_effect":"A SECTM1-Fc fusion bound T and NK cells and a cDNA library screen identified CD7 as its cognate [PMID:10652336]. SECTM1 binds CD7 and increases monocyte migration via PI3K [PMID:24157461]. In leukemic KG1a cells recombinant SECTM1-Fc negatively regulated GM-CSF expression, an opposite functional effect [PMID:24211252].","molecular_requirements":"Not reported in our evidence beyond CD7 acting through the PI3K pathway [PMID:24157461]. A soluble N-terminal SECTM1 form is detected in metastatic melanoma sera [PMID:24157461].","affinity_potency":[],"species_and_systems":"Human proteins and cells (T/NK cells, monocytes, KG1a) [PMID:10652336] [PMID:24157461] [PMID:24211252]. BioGRID lists affinity capture-western and PDB holds a structure [DB:BioGRID] [DB:PDB 12NP].","localisation_and_range":"SECTM1 is flagged secreted [flag]; the papers describe a soluble form and a transmembrane protein, with paracrine action on monocytes and bone-marrow stroma [PMID:24157461] [PMID:24211252].","caveats":"All three papers were read as abstracts, with limited excerpts. Mouse K12 binds mouse but not human CD7, so species matters [PMID:10652336]. No affinity values.","key_references":[{"PMID":"10652336","why":"Identifies CD7 as the SECTM1 (K12) cognate"},{"PMID":"24157461","why":"SECTM1 binds CD7 on monocytes and drives migration"},{"PMID":"24211252","why":"SECTM1-Fc ligation of CD7 lowers GM-CSF in KG1a"}],"covers":["LR001964"]},"LR006473":{"pair":"SELENOP -> LRP5","headline":"SELENOP co-immunoprecipitates with LRP5 and LRP6 and amplifies WNT signalling; one paper with full text, interaction shown mainly for LRP6.","interaction_type":"direct binding","direction_and_effect":"SELENOP increased canonical WNT signalling; a SELENOP form lacking residues 258-299 failed to co-immunoprecipitate with FLAG-mLRP5 and decreased the WNT3A-induced TOPFlash effect, so the LRP5/6 interaction contributes to the effect [PMID:37166989]. SELENOP also promoted LRP6 internalization [PMID:37166989].","molecular_requirements":"The SELENOP region U258-U299 mediates LRP5/6 interaction; heparin prevented and HSPG-synthesis inhibition enhanced SELENOP-LRP6 co-IP [PMID:37166989]. LRP5 co-IP was shown with mouse constructs only (supplemental figure) [PMID:37166989].","affinity_potency":[],"species_and_systems":"Mouse SELENOP and mouse LRP5 constructs in 293T cells; mouse Apc-deletion adenoma model and organoids; human scRNA-seq expression [PMID:37166989].","localisation_and_range":"SELENOP is annotated secreted [flag]; paracrine or endocrine action is plausible but the paper mainly addresses epithelial and stromal expression in colon [PMID:37166989].","caveats":"Co-IP and proximity ligation are not affinity measurements; most direct data are for LRP6, with LRP5 shown for the deletion mutant only. Curator notes record the LRP5 row as direct binding, which co-IP alone does not prove. Paper is the sole support; no database records.","key_references":[{"PMID":"37166989","why":"SELENOP-LRP5/6 interaction and WNT signalling in colorectal cancer"}],"covers":["LR003257","LR006473"]},"LR008642":{"pair":"SELPLG -> ITGB2","headline":"Weak support: a myeloma drug-resistance paper links PSGL-1 with selectins and ICAM-1 with CD18, not PSGL-1 with CD18.","interaction_type":"functional only","direction_and_effect":"PSGL-1/selectin and ICAM-1/CD18 interactions each contributed to macrophage-mediated myeloma drug resistance; PSGL-1 knockdown abolished protection [PMID:22996336]. A direct PSGL-1-CD18 interaction is not shown.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human myeloma cell lines, primary myeloma cells and patient macrophages in vitro; human myeloma-SCID mouse model [PMID:22996336].","localisation_and_range":"Contact-dependent between macrophages and myeloma cells; coculture in transwells did not activate signalling [PMID:22996336].","caveats":"The pairings are crossed relative to this row (PSGL-1 with selectins, ICAM-1 with CD18). Full text excerpts name PSGL-1 with P/E-selectins and CD18 with ICAM-1 only [PMID:22996336]. No database records.","key_references":[{"PMID":"22996336","why":"myeloma drug resistance via PSGL-1/selectins and ICAM-1/CD18 (not a direct pair)"}],"covers":["LR008642"]},"LR004736":{"pair":"SEMA3A -> NRP1","headline":"Sema3A binds neuropilin-1 with strong literature and database support; signalling uses plexin co-receptors.","interaction_type":"direct binding","direction_and_effect":"Neuropilin-1 binds Sema III with high affinity [PMID:9331348]. Sema3A repels axons by binding NRP1 [PMID:15721238]. Upon Sema3A binding to NP-1, L1 and NP-1 are co-internalized [PMID:15121181]. Sema3A with NP-1/Plex 1 complexes induces adherent cells to round up [PMID:10520994].","molecular_requirements":"Plexin 1 alone does not bind Sema3A, but the NP-1/Plex 1 complex has a higher affinity for Sema3A than NP-1 alone (6-fold higher in the full text) [PMID:10520994]. Plexin-A4 mainly mediates signalling via Neuropilin-1 [PMID:15721238]. L1 associates with NP-1 and is required for repulsive responses [PMID:15121181].","affinity_potency":[],"species_and_systems":"Human labelled in one binding paper [PMID:9331348]; mouse in another [PMID:10520994]; 2005 and 2004 papers used neurons from mouse mutants and COS7/neuronal cultures [PMID:15721238][PMID:15121181].","localisation_and_range":"Sema3A is a secreted ligand and NRP1 is flagged transmembrane [flag]; paracrine signalling.","caveats":"No affinity value for the Sema3A-NRP1 pair is reported in our evidence. Several papers were read as abstracts only; one confirmed row cites the pairing as background [PMID:15721238]. Database records exist [DB:BioGRID 2563623] [DB:Reactome R-HSA-399933].","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema III with high affinity; NRP2 does not"},{"PMID":"10520994","why":"NP-1/Plexin complex is the physiological Sema3A receptor"},{"PMID":"15721238","why":"Plexin-A4 transduces Sema3A signalling via NRP1 in vivo"}],"covers":["LR001340","LR004736"]},"LR004745":{"pair":"SEMA3C -> NRP2","headline":"Single 1997 abstract-level binding paper reports NRP2 does not bind Sema III but binds Sema E, which the curators map to SEMA3C.","interaction_type":"direct binding","direction_and_effect":"The paper reports that neuropilin-2 shows high-affinity binding only to Sema E and Sema IV, not Sema III [PMID:9331348]. The curator labels the effect agonist and maps Sema E to SEMA3C.","molecular_requirements":"Neuropilins are described as receptors or components of receptors; any plexin co-receptor requirement is not reported in our evidence [PMID:9331348].","affinity_potency":[],"species_and_systems":"Human ligand and receptor were recorded for the experiment [PMID:9331348]. Both the human and mouse pair are ortholog-inferred, not tested in mouse.","localisation_and_range":"SEMA3C is annotated as secreted and NRP2 as transmembrane [flag].","caveats":"Abstract-only read; no affinity value in our evidence. The mouse and human pairs are projected from this evidence. Other judged rows (review_only, abstract_insufficient, different_entity) are not shown.","key_references":[{"PMID":"9331348","why":"Identifies NRP2 and its Sema E/Sema IV binding specificity"}],"covers":["LR001349","LR004745"]},"LR006482":{"pair":"SEMA3C -> PLXNA4","headline":"SEMA3C signals through a PlexinA4:PlexinD1 complex without neuropilins in U87MG cells; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Sema3C induced contraction and repulsion of plexin-D1-expressing U87MG cells with both neuropilins knocked out [PMID:29661844]. The curator labels the effect antagonist.","molecular_requirements":"In the absence of neuropilins, plexin-A4 formed complexes with plexin-D1 and was required in addition to plexin-D1 for Sema3C signal transduction [PMID:29661844]. Plexin-A4 alone is therefore not sufficient. Neuropilins act as enhancers: EC50 was 5.5 times higher without them [PMID:29661844].","affinity_potency":[],"species_and_systems":"Human U87MG glioblastoma cells with recombinant plexin-D1 and CRISPR neuropilin knockout [PMID:29661844]. The mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXNA4 is annotated transmembrane [flag].","caveats":"Abstract-only read. No direct PlexinA4 binding to SEMA3C is shown; U87MG cells with class-A plexins overexpressed did not contract to Sema3C without plexin-D1 [PMID:29661844]. Pair is better read as the PlexinA4:PlexinD1 complex.","key_references":[{"PMID":"29661844","why":"Plexin-A4 plus plexin-D1 convey Sema3C signals without neuropilins"}],"covers":["LR003266","LR006482"]},"LR003269":{"pair":"SEMA3D -> PLXNB3","headline":"Cell-surface binding assay shows Sema3D binds Plexin B3-expressing cells; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Either Sema3E or Sema3D bound to the cells expressing Plexin B3 in an AP-tagged ligand binding assay in HEK293 cells [PMID:38628398]. Effect direction is not reported in our evidence.","molecular_requirements":"Binding was stronger with cells co-expressing Plexin B3 and Neuropilin-1a, per the curator's note [PMID:38628398]; Plexin B3 alone was sufficient for binding.","affinity_potency":[],"species_and_systems":"HEK293 cells; the paper otherwise concerns zebrafish embryos [PMID:38628398]. The human pair is ortholog-inferred.","localisation_and_range":"SEMA3D is annotated secreted and PLXNB3 transmembrane [flag].","caveats":"Single paper, no affinity value; the main in vivo work in the paper concerned Sema3E, not Sema3D.","key_references":[{"PMID":"38628398","why":"AP-ligand binding of Sema3D to Plexin B3 cells"}],"covers":["LR003269"]},"LR006491":{"pair":"Sema3g -> Plxnd1","headline":"Mouse-only functional evidence from one paper; PlexinD1 acts with Nrp2, not as a direct Sema3G binder.","interaction_type":"functional only","direction_and_effect":"Sema3G induced cell collapse in an Nrp2/PlexinD1-dependent manner in vitro, and Sema3g or Plxnd1 inactivation caused similar lymphatic patterning defects in mice [PMID:27880905].","molecular_requirements":"Requires Nrp2 as binding receptor with PlexinD1 as complex partner; Sema3G-AP did not bind PlexinD1-expressing cells in the excerpts [PMID:27880905].","affinity_potency":[],"species_and_systems":"Mouse embryos and cells, full text read [PMID:27880905].","localisation_and_range":"Sema3G is described as artery-derived [PMID:27880905].","caveats":"Evidence sentence is truncated. Direct Sema3G-PlexinD1 binding is negative in the excerpts, so this is a complex-dependent functional link.","key_references":[{"PMID":"27880905","why":"Nrp2/PlexinD1-dependent Sema3G cell collapse"}],"covers":["LR006491"]},"LR004754":{"pair":"SEMA4A -> PLXND1","headline":"Sema4A acts on Plexin-D1 in endothelial cells and macrophages; binding and functional evidence, but only abstracts read.","interaction_type":"direct binding","direction_and_effect":"Sema4A suppresses VEGF-mediated endothelial migration, proliferation and angiogenesis via Plexin-D1, labelled antagonist by curators [PMID:17318185]. In macrophages, Sema4A acting via PlexinD1 increased migration and enhanced VEGF-A expression, a pro-angiogenic effect [PMID:22442441]. The effect is therefore context-dependent.","molecular_requirements":"Plexin-D1 alone is named as the receptor; no co-receptor is reported in our evidence. Sema4A uses TIM-2 rather than Plexin-D1 in T cells [PMID:17318185].","affinity_potency":[],"species_and_systems":"Endothelial cells (human labels, Sema4a-null mice used) [PMID:17318185]; mouse macrophages and mouse peritonitis and ischemia/reperfusion models [PMID:22442441]. The mouse pair is ortholog-inferred. IntAct lists surface plasmon resonance and solid-phase assays [DB:IntAct]; Reactome has a binding reaction [DB:Reactome].","localisation_and_range":"Ligand flagged both secreted and transmembrane [flag]; paper text does not settle the range.","caveats":"Both papers were read as abstracts only. Opposite functional valences between endothelium and macrophages. Binding in 17318185 is described only as 'binding and functional experiments'.","key_references":[{"PMID":"17318185","why":"Sema4A-Plexin-D1 binding and anti-angiogenic function"},{"PMID":"22442441","why":"Sema4A via PlexinD1 in macrophages"}],"covers":["LR001358","LR004754"]},"LR003278":{"pair":"SEMA4B -> PLXNB2","headline":"Plexin-B2 is reported as the Sema4B receptor on microglia, supported by matching knockouts in one 2024 paper; functional rather than binding evidence.","interaction_type":"functional only","direction_and_effect":"In vitro experiments indicate Plexin-B2 is the Sema4B receptor on microglia; astrocytic Sema4B enhances injury-induced microglia reactivity, and microglia/macrophage-specific Plexin-B2 knockout mice show similar attenuated reactivity and neuronal cell death after injury (agonist) [PMID:38781210].","molecular_requirements":"Plexin-B2 only; no co-receptor reported in our evidence. Sema4B/Plexin-B2 double heterozygotes also show reduced reactivity, supporting a shared pathway [PMID:38781210].","affinity_potency":[],"species_and_systems":"Experiments used mice (knockouts, cortical stab wound) and in vitro microglia/astrocyte cultures; the dossier labels species as human but the paper text describes mouse work [PMID:38781210]. The human pair is ortholog-inferred.","localisation_and_range":"Sema4B described as a transmembrane protein expressed by astrocytes [PMID:38781210]; our entity flag says not secreted [flag]. Action is by contact or shedding, not established here.","caveats":"No direct binding measurement or affinity in our evidence; abstract plus excerpts only mention that receptor identification was in vitro. No database support.","key_references":[{"PMID":"38781210","why":"Astrocyte-to-microglia Sema4B-Plexin-B2 axis, with knockouts"}],"covers":["LR003278","LR006494"]},"LR004763":{"pair":"SEMA6A -> PLXNA4","headline":"Plexin-A4 is reported to bind Sema6A and mediate repulsion independently of neuropilin-1; a cis interaction can also inhibit responses.","interaction_type":"direct binding","direction_and_effect":"Plexin-A4 bound Sema6A (and Sema6B) and mediated their axon-repulsive activity independently of neuropilin-1 [PMID:15814794]. Co-expression of Sema6A and Plexin-A4 hindered binding of exogenous ligand, suggesting a cis interaction that inhibits responsiveness [PMID:20606624].","molecular_requirements":"Neuropilin-1 is not required for the Sema6A response [PMID:15814794]. The Reactome complex also lists PLXNA2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse knockouts and neurons in the first paper; heterologous cell systems and sympathetic/sensory neurons in the second. Curator species fields say human; the abstracts describe mice, so check.","localisation_and_range":"Membrane-bound ligand [flag]; signals in trans between cells or inhibits in cis on the same cell [PMID:20606624].","caveats":"Both read as abstracts only. The cis interaction is inhibitory, opposite to trans signalling, which affects how co-expression should be interpreted.","key_references":[{"PMID":"15814794","why":"Plexin-A4 binds Sema6A/6B independently of neuropilin-1"},{"PMID":"20606624","why":"Cis Sema6A-Plexin-A4 interaction inhibits response"}],"covers":["LR001367","LR004763"]},"LR003287":{"pair":"SERPINC1 -> NRP1","headline":"Antithrombin III binds immobilised neuropilin-1 on an optical biosensor; a single paper, with no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Antithrombin III was among several heparin-binding proteins able to interact with Npn-1 immobilised on the sensor surface [PMID:15695515]. Effect on signalling is not reported in our evidence for antithrombin III.","molecular_requirements":"Interactions were ionic-strength dependent and inhibited by heparin, which the authors read as a heparin-mimetic site on Npn-1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Biosensor binding assay with immobilised Npn-1; the paper's functional work used FGF-2 on human umbilical vein endothelial cells, not antithrombin III [PMID:15695515]. Both human and mouse pairs here are ortholog-projected.","localisation_and_range":"NRP1 is flagged as secreted, receptor and transmembrane [flag]; localisation of the interaction is not reported.","caveats":"Single paper; the dossier shows its abstract was the curated read although full text is available. Antithrombin III is only listed among many binders; no kinetic values given for it. Multi-binder promiscuity of Npn-1 is a concern.","key_references":[{"PMID":"15695515","why":"Biosensor binding of antithrombin III to Npn-1"}],"covers":["LR003287","LR006503"]},"LR004772":{"pair":"SERPINE2 -> LRP1","headline":"Thrombin-protease nexin 1 complexes bind recombinant LRP1 regions; free SERPINE2 not shown.","interaction_type":"direct binding","direction_and_effect":"All three LRP1 homology regions (sLRP2, sLRP3, sLRP4) bound thrombin-protease nexin 1 complexes in solution-binding experiments [PMID:14596620].","molecular_requirements":"The ligand is the thrombin-protease nexin 1 complex, not free SERPINE2 [PMID:14596620].","affinity_potency":[],"species_and_systems":"Recombinant human LRP homology regions expressed in Pichia pastoris [PMID:14596620]. Mouse pair is ortholog-projected.","localisation_and_range":"SERPINE2 is flagged secreted [flag]; localisation not otherwise reported.","caveats":"Both confirmed rows come from the same abstract-only paper listing many ligands; not all ligand binding was RAP-competable [PMID:14596620].","key_references":[{"PMID":"14596620","why":"sLRP regions bind thrombin-protease nexin 1"}],"covers":["LR001377","LR004772"]},"LR001379":{"pair":"SERPING1 -> SELE","headline":"C1 inhibitor binds E-selectin through its glycans and inhibits endothelial-leukocyte adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Plasma C1INH bound P- and E-selectins by FACS and immunoprecipitation and inhibited endothelial-leukocyte adhesion dose-dependently, with significant (>50%) inhibition at 250 microg/mL or higher [PMID:14568956]. Curators label it antagonist.","molecular_requirements":"Binding is via sialyl Lewis(x)-related moieties on C1INH N-glycans, which sit on its amino-terminal domain rather than the serpin domain [PMID:14568956].","affinity_potency":[],"species_and_systems":"Plasma C1INH with cell-based and tissue-culture adhesion assays; species labelled human [PMID:14568956]. Mouse pair is ortholog-projected. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"E-selectin is flagged as receptor and transmembrane [flag]; contact-dependent at the endothelium.","caveats":"Glycan-mediated, not classic protein-protein binding; no affinity reported; abstract only.","key_references":[{"PMID":"14568956","why":"C1INH binds selectins and blocks adhesion"}],"covers":["LR001379","LR004774"]},"LR010955":{"pair":"SFRP1 -> WNT3A","headline":"No confirmed paper; support is a Reactome complex record.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a WNT3A:sFRP complex in the extracellular region [DB:Reactome, PMID:10347172].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Reactome places the complex extracellular [DB:Reactome]; SFRP1 is flagged secreted [flag].","caveats":"The one judged paper was a different entity. Rests on database records alone; the Reactome complex is for sFRP in general rather than SFRP1 specifically.","key_references":[],"covers":["LR010955"]},"LR001973":{"pair":"SFRP2 -> FZD5","headline":"SFRP2 binds FZD5 and activates NFATc3 signalling in endothelial cells; one full-text paper supports it.","interaction_type":"direct binding","direction_and_effect":"FZD5 is reported as a receptor for SFRP2 and the effect is agonist: FZD5 is necessary for SFRP2-induced tube formation and calcium flux, and required for SFRP2-induced NFATc3 activation [PMID:28840375].","molecular_requirements":"Not reported beyond FZD5 itself; co-receptors or other subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding by co-immunofluorescence, co-immunoprecipitation and ELISA, plus homology modelling, in human SFRP2/FZD5 and mouse endothelial cell lines (2H11, MS1, SVR) [PMID:28840375]. The dossier covers human and mouse pairs.","localisation_and_range":"SFRP2 is flagged secreted [flag], so paracrine or autocrine action is plausible.","caveats":"Single paper; the curator read depth is abstract-only, though full-text excerpts were available. Binding affinity is not quantified in the excerpts. Mouse cells were used with recombinant human SFRP2.","key_references":[{"PMID":"28840375","why":"Binding assays and FZD5 knockdown linking SFRP2 to NFATc3 and angiogenesis"}],"covers":["LR001973","LR005303"]},"LR006509":{"pair":"SFTPA1 -> LRP1","headline":"SP-A collagenous tails bind a calreticulin/CD91 complex and are pro-inflammatory; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Collagenous tails stimulate proinflammatory mediator production and phagocytosis through binding to calreticulin/CD91; agonist-like [PMID:14531999].","molecular_requirements":"The curator notes LRP1/CD91 may need calreticulin as an obligate co-receptor partner, so LRP1 alone may not be the direct binding partner [PMID:14531999].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; the human and mouse pairs are both ortholog-inferred [PMID:14531999].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"Single abstract-only paper; binding is to a calreticulin/CD91 complex, not demonstrated for LRP1 alone. The paper covers SP-A and SP-D without distinguishing SFTPA1.","key_references":[{"PMID":"14531999","why":"Dual-function collectin model: tails bind calreticulin/CD91"}],"covers":["LR003293","LR006509"]},"LR003296":{"pair":"SFTPA1 -> TLR4","headline":"SP-A binds recombinant TLR4 extracellular domain and antagonises LPS signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Antagonist: SP-A attenuated smooth-LPS cell-surface binding and NF-kappaB activation in TLR4/MD-2-expressing cells [PMID:16754682].","molecular_requirements":"MD-2 is also bound by SP-A, so the TLR4/MD-2 complex is the relevant target; binding is Ca2+-dependent and involves the CRD; oligomerisation is needed because the trimeric CRF had approximately 600-fold higher KD for TLR4 [PMID:16754682]. Reactome lists TLR4:LY96 [DB:Reactome].","affinity_potency":[{"value":"600-fold higher KD (CRF vs full SP-A), TLR4","assay":"BIAcore/solid-phase binding","system":"recombinant soluble TLR4","cite":"PMID:16754682"}],"species_and_systems":"Recombinant soluble human TLR4 and MD-2 (solid-phase, immunoprecipitation, BIAcore) and cell assays; mouse pair is ortholog-inferred [PMID:16754682].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; absolute KD not given.","key_references":[{"PMID":"16754682","why":"SP-A binds TLR4 and MD-2; oligomerisation matters"}],"covers":["LR003296","LR006512"]},"LR004781":{"pair":"SHH -> CDON","headline":"SHH binds CDON directly, shown by several binding papers; CDON acts as a positive co-receptor.","interaction_type":"direct binding","direction_and_effect":"Cdo and Boc bind Shh through a high-affinity interaction with a specific fibronectin repeat that is essential for activity; they enhance Shh signalling in its target field [PMID:16647304]. CDON binds SHH and positively regulates Hh signaling [PMID:20519495]. Ectopic expression can also sequester Shh non-cell-autonomously [PMID:16647304].","molecular_requirements":"CDON alone is shown to bind; a specific fibronectin repeat is required [PMID:16647304]. Co-receptor with PTCH: Reactome lists Hh-Npp:CDON:PTCH [DB:Reactome]. Crystal structures of Hh proteins with CDON and BOC active domains show all mammalian Hh proteins bind in the same manner [PMID:20519495].","affinity_potency":[],"species_and_systems":"Mouse neural tube, with Shh-dependent ventral cell fates [PMID:16647304]; the second paper used mouse Boc knockout and rat commissural axons, but is for BOC/CDON jointly [PMID:17086203]. Affinity is described only as high-affinity or micromolar, with no value given in the dossier [PMID:16647304] [PMID:20519495].","localisation_and_range":"Membrane protein on the receiving cell; SHH is flagged secreted [flag]. Binding to the receptor occurs in the target field [PMID:16647304].","caveats":"All three papers read as abstracts only. The axon-guidance paper names Boc as the receptor and CDON only as a binder [PMID:17086203]; the abstract of [PMID:20519495] is truncated.","key_references":[{"PMID":"16647304","why":"Cdo and Boc bind Shh; role in Shh signalling feedback"},{"PMID":"20519495","why":"All mammalian Hh proteins bind CDO and BOC; structures"},{"PMID":"17086203","why":"Boc and Cdon bind Shh; axon guidance"}],"covers":["LR001386","LR004781"]},"LR007409":{"pair":"SHH -> CDON:PTCH1","headline":"Complex CDON:PTCH1 is supported only by database records for SHH-PTCH1; CDON's contribution is not shown by a verified paper.","interaction_type":"database-asserted only","direction_and_effect":"SHH binds PTCH1 as receptor, relieving smoothened inhibition [DB:UniProt]. Reactome lists a Hh-Npp:CDON:PTCH complex [DB:Reactome].","molecular_requirements":"Structures of the human PTCH1-ShhN complex are deposited ([DB:PDB 6DMY], [DB:PDB 6E1H]); UniProt notes two PTCH1 molecules engage one hedgehog molecule [DB:UniProt]. The need for CDON alongside PTCH1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Records are for human proteins, including cryo-EM and NMR [DB:PDB 6DMY] [DB:IntAct]. No papers were confirmed for this pair.","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor.","caveats":"No curator-verified paper (two judged abstract-insufficient). Direct evidence is for SHH-PTCH1 only.","key_references":[],"covers":["LR007409"]},"LR006518":{"pair":"Shh -> Gpc6","headline":"Mouse Shh and Gpc6: one paper shows GPC6 interacts with Hh through its core protein; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"GPC6 interacts with Hh through its core protein and with Ptc1 through its glycosaminoglycan chains, increasing Hh binding to Ptc1 and stimulating Hh signaling [PMID:28696225].","molecular_requirements":"Core protein binds Hh; GAG chains bind Ptc1; GPC6 moves into the cilium upon addition of Hh [PMID:28696225].","affinity_potency":[],"species_and_systems":"Cultured-cell Hh-binding assay plus GPC6-null mouse embryos (E17.5-18.5), where Hh signaling is reduced in long bones [PMID:28696225]. The curated pair is mouse and ortholog-inferred.","localisation_and_range":"GPC6 is described at the primary cilium [PMID:28696225]; secretion status of the ligand and receptor is not given in the entity flags for this mouse record, not reported in our evidence.","caveats":"Single paper; the Hh used in the binding assay is stated as Hh and not specified as Shh in the dossier. No affinity.","key_references":[{"PMID":"28696225","why":"GPC6 binds Hh via core protein; null embryos"}],"covers":["LR006518"]},"LR001388":{"pair":"SHH -> HHIP","headline":"SHH binds HHIP directly, with a co-crystal structure; HHIP is an inhibitory receptor.","interaction_type":"direct binding","direction_and_effect":"Hip binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1 and attenuates Hedgehog signalling [PMID:10050855]. Crystal structures of human HHIP ectodomain with Shh were solved [PMID:19561611]. It is an inhibitor of Hh signaling [PMID:19561611].","molecular_requirements":"HHIP loops BL1 and BL2 of the beta-propeller contact ShhN; a Shh zinc ion contributes to the interface and Ca2+ likely prevents electrostatic repulsion [PMID:19561611]. A single-chain receptor is sufficient; structure PDB 3HO5 [DB:PDB 3HO5].","affinity_potency":[],"species_and_systems":"Human HHIP ectodomain and the ShhN domain, recombinant [PMID:19561611]; the 1999 paper used mammalian proteins, species unspecified [PMID:10050855]. Mouse pair is the curated one; human is ortholog-inferred.","localisation_and_range":"HHIP is a membrane glycoprotein tethered to the cell surface [PMID:10050855] [PMID:19561611]; SHH is flagged secreted [flag].","caveats":"A decoy-like negative feedback receptor, not a signalling receptor. Affinity described only as comparable to Ptc-1, no value in the dossier. One pending paper not shown.","key_references":[{"PMID":"19561611","why":"Crystal structure of HHIP-Shh complex"},{"PMID":"10050855","why":"Hip binds Hedgehog proteins; negative feedback"}],"covers":["LR001388","LR004783"]},"LR001982":{"pair":"SLAMF6 -> SLAMF6","headline":"SLAMF6 (NTB-A) is reported as its own ligand in a human NK-cell paper; supported by IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Trimeric recombinant NTB-A showed that NTB-A is its own ligand; homophilic engagement enhanced NK cell cytotoxicity and influenced proliferation and IFN-gamma secretion [PMID:15153464].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK cells and recombinant trimeric proteins [PMID:15153464].","localisation_and_range":"Not flagged secreted; a surface receptor on NK, T and B cells, so contact-dependent [PMID:15153464].","caveats":"Abstract only; no affinity. IntAct lists FACS and solid phase records and Reactome a SLAMF6 dimer and binding reaction [DB:IntAct] [DB:Reactome]. One further row is pending and not described.","key_references":[{"PMID":"15153464","why":"NTB-A homophilic ligand; enhances NK cytotoxicity"}],"covers":["LR001982","LR005311"]},"LR004790":{"pair":"SLIT2 -> ROBO1","headline":"SLIT2 binds ROBO1, a canonical repulsive-guidance pair with cell-overlay binding, a crystal structure and database support.","interaction_type":"direct binding","direction_and_effect":"Slit2 binds Robo proteins with specific, high-affinity binding and repels embryonic spinal motor axons in culture [PMID:10102268]. UniProt lists ROBO1 as a receptor for SLIT1 and SLIT2 [DB:UniProt].","molecular_requirements":"Conditioned medium contained mixed N-terminal, C-terminal and full-length hSlit2; which fragment binds ROBO1 is not resolved here [PMID:10102268].","affinity_potency":[],"species_and_systems":"Human Slit2 on COS cells expressing rat Robo1 (overlay binding) [PMID:10102268]. Dossier covers human and mouse pairs, both ortholog-inferred.","localisation_and_range":"ROBO1 flagged transmembrane, SLIT2 secreted [flag].","caveats":"The paper's 'high-affinity' claim has no number in our evidence. Supporting records: PDB 2V9T structure [DB:PDB 2V9T], IntAct surface plasmon resonance [DB:IntAct], Reactome [DB:Reactome]. One review-only row not shown.","key_references":[{"PMID":"10102268","why":"Slit2 binds Robo1/2 in overlay assay"}],"covers":["LR001395","LR004790"]},"LR001397":{"pair":"SLIT2 -> ROBO4","headline":"SLIT2 is a putative ROBO4 (Magic roundabout) ligand; one functional abstract and one BioGRID record.","interaction_type":"functional only","direction_and_effect":"Activation of MRB (ROBO4) via Slit2 inhibited VEGF- and FGF-induced endothelial migration, partly via Ras-Raf-Mek-Erk [PMID:15894287]. Annotated antagonist-type effect on migration.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells, human [PMID:15894287].","localisation_and_range":"Not reported in our evidence; SLIT2 flagged secreted [flag].","caveats":"Slit2 is called only a 'putative ligand', and MRB over-expression activates it ligand-independently, so physiological ligand role is not established [PMID:15894287]. Abstract only. BioGRID lists an affinity capture-Western record from a different paper [DB:BioGRID]. One review-only row not shown.","key_references":[{"PMID":"15894287","why":"Slit2 activation of MRB inhibits endothelial migration"}],"covers":["LR001397","LR004792"]},"LR001991":{"pair":"SLITRK2 -> PTPRS","headline":"SLITRK2-PTPsigma rests on one family-level cell aggregation assay.","interaction_type":"functional only","direction_and_effect":"Slitrk2-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436]. PTPsigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells and rat neurons [PMID:23345436]. Mouse pair ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; SLITRK2 flagged transmembrane [flag].","caveats":"Single paper, browser-read quote with spot-check pending; assay is family-wide, direct binding not reported in our evidence. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk2 and PTPsigma aggregation"}],"covers":["LR001991","LR005320"]},"LR006536":{"pair":"SPARC -> STAB1","headline":"SPARC binds the scavenger receptor stabilin-1, which mediates its endocytosis; one abstract-level paper plus a generic Reactome entry.","interaction_type":"direct binding","direction_and_effect":"SPARC interacts with stabilin-1 by phage display and in vitro binding; stabilin-1 internalises SPARC to an endosomal pathway and is required for its endocytosis in human macrophages, followed by degradation [PMID:16670288]. Scavenger/clearance receptor, not a signalling agonist.","molecular_requirements":"Binding is mediated by stabilin-1's extracellular EGF-like region containing the sequence FHGTAC [PMID:16670288].","affinity_potency":[],"species_and_systems":"CHO cells stably transfected with stabilin-1 and human macrophages; clearance was most efficient in IL-4/dexamethasone alternatively activated macrophages, not Th1/Th2 cytokines alone [PMID:16670288]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC flagged secreted [flag]; cell-surface receptor on macrophages.","caveats":"Abstract only. Reactome records are a generic STAB1 ligand-binding reaction [DB:Reactome]. No affinity.","key_references":[{"PMID":"16670288","why":"SPARC binds stabilin-1; clearance by alternatively activated macrophages"}],"covers":["LR003329","LR006536"]},"LR008228":{"pair":"SPP1 -> ITGA5:ITGB1","headline":"Osteopontin binds alpha5beta1 in K562 cells when the integrin is activated; one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"alpha5beta1 selectively interacted with an N-terminal osteopontin fragment (aa17-168); adhesion was RGD dependent, blocked by RGD to RAD mutation [PMID:10673366].","molecular_requirements":"Binding needs integrin activation (TPA, or alpha4 expression) and favours thrombin-cleaved N-terminal osteopontin; no interaction without TPA [PMID:10673366]. Both chains form the receptor.","affinity_potency":[],"species_and_systems":"Human K562 cells that express only alpha5beta1 as integrin, GST fusion proteins [PMID:10673366].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA5 and ITGB1 are not secreted [flag].","caveats":"One paper, abstract only. BioGRID record concerns SPP1-ITGB1 reconstituted complex [DB:BioGRID]; Reactome lists SPP1 with alpha5beta1 and alpha9beta1 [DB:Reactome].","key_references":[{"PMID":"10673366","why":"Activation-regulated alpha5beta1 binding to osteopontin in K562 cells"}],"covers":["LR008228"]},"LR008219":{"pair":"SPP1 -> ITGAV:ITGB1","headline":"alphavbeta1 is named among osteopontin integrins in one paper's background; this paper itself did not test it.","interaction_type":"database-asserted only","direction_and_effect":"The only paper cited lists alphavbeta1 among integrins osteopontin interacts with, as a summary of prior work [PMID:10673366].","molecular_requirements":"not reported in our evidence beyond the complex pairing alphaV with beta1.","affinity_potency":[],"species_and_systems":"Paper itself used K562 cells with alpha5beta1; alphavbeta1 not tested in this paper [PMID:10673366].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; matrix-adhesion context only.","caveats":"The curated paper's own finding is alpha5beta1, so support here is a background statement. The BioGRID record concerns SPP1-ITGB1 reconstituted complex [DB:BioGRID]; other literature on alphavbeta1 appears in the SPP1-ITGAV dossier, not this one.","key_references":[{"PMID":"10673366","why":"Background list including alphavbeta1; new finding is alpha5beta1"}],"covers":["LR008219"]},"LR004808":{"pair":"SST -> SSTR4","headline":"Somatostatin binds and activates SSTR4 (human), supported by cryo-EM structure, radioligand binding and GtoPdb; endogenous peptide is a partial agonist in one assay.","interaction_type":"direct binding","direction_and_effect":"SST-14 is an agonist at SSTR4: Gi-coupled cryo-EM complex of SST-14 with SSTR4 at 2.9 \u00c5 [PMID:35739238]. In a [35S]GTPgammaS assay somatostatin-14 behaved as a partial agonist relative to J-2156, though it acted as a full agonist in a cAMP assay, attributed to receptor reserve [PMID:15333679]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"SSTR4 couples to Gi1 in the structure (scFv16 used for stabilisation) [PMID:35739238]. SST-14 is a cyclic tetradecapeptide with a C3-C14 disulfide; the F7-W8-K9-T10 pharmacophore sits in the receptor pocket [PMID:35739238]. High-affinity agonist binding to hSSTR4 was reduced by GTP and pertussis toxin [PMID:8100352]. A PDB structure is recorded [DB:PDB 7XMS].","affinity_potency":[{"value":"Ki 1.1 nM","assay":"inhibition of 125I-[Leu8,D-Trp22,Tyr25]SST-28 binding","system":"COS-7 membranes expressing hSSTR4","cite":"PMID:8100352"},{"value":"1.5 nM","assay":"binding","system":"SST-14 at SSTR4 (SSTR2 1.4 nM)","cite":"PMID:35739238"},{"value":"pKi 8.4-9.3","assay":"GtoPdb range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in recombinant systems (COS-7, HEK293F cells, CCL39 cells) [PMID:8100352][PMID:35739238][PMID:9650799]. The mouse entry is projected from human evidence.","localisation_and_range":"SST is flagged secreted and SSTR4 transmembrane, implying paracrine or endocrine signalling [flag].","caveats":"Several papers were read as abstracts only. Some binding studies used radiolabelled SST analogues rather than SST-14 [PMID:9650799][PMID:8100352]. One study found SSTR4 reacts poorly with synthetic analogues [PMID:7988476]. No in vivo evidence in our dossier.","key_references":[{"PMID":"35739238","why":"cryo-EM structure of SST-14 bound to SSTR4-Gi1"},{"PMID":"8100352","why":"cloning and radioligand binding of hSSTR4, Ki values"},{"PMID":"15333679","why":"SST-14 as partial agonist at SSTR4"}],"covers":["LR001413","LR004808"]},"LR006545":{"pair":"SVEP1 -> PEAR1","headline":"SVEP1 interacts with PEAR1 with high affinity and drives AKT/mTOR signalling; one human genetics and proteomics study, projected to mouse.","interaction_type":"direct binding","direction_and_effect":"The interaction promotes PEAR1 phosphorylation and AKT/mTOR signalling in vascular cells and platelets; exogenous SVEP1 induces PEAR1-dependent platelet activation, and Svep1-lacking mice have reduced platelet activation [PMID:36792666]. UniProt states the same [DB:UniProt].","molecular_requirements":"A PEAR1 missense variant p.D343N in an EGF-like domain of the ectodomain was associated with increased plasma SVEP1 [PMID:36792666]. PEAR1 is required for SVEP1-mediated platelet activation [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human genomic and proteomic data, human cells and platelets, plus mouse platelets [PMID:36792666]. Both human and mouse pairs are marked ortholog-inferred in the dossier.","localisation_and_range":"SVEP1 is flagged secreted and PEAR1 a receptor [flag]; SVEP1 is described as an extracellular matrix protein [PMID:36792666].","caveats":"Single paper read as abstract with excerpts; 'high affinity' is stated without a number in our evidence. The excerpt shown is genetic association rather than binding data.","key_references":[{"PMID":"36792666","why":"SVEP1-PEAR1 interaction, signalling and platelet activation"}],"covers":["LR003338","LR006545"]},"LR004817":{"pair":"TAC4 -> TACR2","headline":"Hemokinin-1 (TAC4) is a full agonist at NK2 (TACR2) in tissue assays but binds human NK2 with much lower affinity; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"In isolated bioassays HEK-1 was a full agonist at tachykinin NK(1), NK(2) and NK(3) receptors [PMID:11786503]; GtoPdb lists a full agonist [DB:GtoPdb]. Its antagonism by nepadutant in rabbit pulmonary artery is reported [PMID:11786503].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 560 nM","assay":"[125I]-NKA displacement","system":"human NK2 receptor","cite":"PMID:11786503"}],"species_and_systems":"Human NK2 binding; rabbit pulmonary artery bioassay [PMID:11786503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted [flag].","caveats":"Abstract only. Binding at human NK2 is markedly lower than at NK1, and HEK-1 was about 500 fold less potent than NKA in the rabbit pulmonary artery [PMID:11786503].","key_references":[{"PMID":"11786503","why":"HEK-1 full agonist at NK2 with weak binding"}],"covers":["LR001422","LR004817"]},"LR006554":{"pair":"TAFA3 -> NRXN1","headline":"TAFA3 (FAM19A3) binds neurexins, including NRXN1; one paper, mainly recombinant HEK293T work.","interaction_type":"direct binding","direction_and_effect":"FAM19A3 was tested as a homologue of FAM19A1/A2 and, with FAM19A1-A4, bound all neurexin isoforms and splice variants tested in HEK293T surface-exposure assays [PMID:32706374]. Effect on neurexin function is reported only for FAM19A1 [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Recombinant FAM19A3 (V5-tagged) with Nrxn1\u03b2-ECD in HEK293T cells [PMID:32706374]. Human pair projected from mouse evidence.","localisation_and_range":"TAFA3 annotated secreted; NRXN1 annotated transmembrane [flag].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair. Excerpts for FAM19A3 specifically are brief.","key_references":[{"PMID":"32706374","why":"FAM19A1-A4, including FAM19A3, bind neurexins"}],"covers":["LR003351","LR006554"]},"LR007418":{"pair":"TENM1 -> ADGRL3","headline":"Database-asserted only: UniProt states ADGRL3 interacts with TENM1 by similarity.","interaction_type":"database-asserted only","direction_and_effect":"No curator-confirmed paper. UniProt records that ADGRL3 interacts, via its extracellular domain, with TENM1 (by similarity) [DB:UniProt, PMID:26235030].","molecular_requirements":"Extracellular domain of ADGRL3 is implicated [DB:UniProt].","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence.","localisation_and_range":"Both partners are annotated transmembrane [flag], so any interaction would be contact-dependent.","caveats":"The record is 'by similarity', not direct experiment [DB:UniProt]. Judged papers were review_only, abstract_insufficient or different_entity.","key_references":[],"covers":["LR007418"]},"LR003359":{"pair":"TENM2 -> ADGRL3","headline":"Strong evidence: cryo-EM structure of TEN2-LPHN3 complex plus cell adhesion and splice-dependence data.","interaction_type":"direct binding","direction_and_effect":"The 2.9 \u00c5 cryo-EM structure shows the LPHN3 N-terminal lectin domain binding the TEN2 barrel far from the alternatively spliced region [PMID:32358586]. Trans-synaptic TEN-LPHN interaction promotes excitatory synapse formation when LPHNs also bind FLRTs; an alternatively spliced TEN insertion abolishes binding and switches function to inhibitory synapses [PMID:32358586]. Latrophilin-expressing cells aggregate with Ten2 cells [PMID:24273166].","molecular_requirements":"A trimeric TEN2-LPHN3-FLRT3 complex exists [PMID:32358586]. Breaking ADGRL3-TEN2 binding preserved FLRT3 interaction [PMID:36746957]. An antibody LK30 binding the ADGRL3 Lec domain overlaps the teneurin epitope and agonises ADGRL3 but not ADGRL1 [PMID:36746957].","affinity_potency":[],"species_and_systems":"Human proteins in the cryo-EM study [PMID:32358586] and the LK30 work [PMID:36746957]; HEK293T aggregation assay [PMID:24273166]. Mouse pair ortholog-inferred. PDB 6VHH is listed [DB:PDB 6VHH].","localisation_and_range":"Both annotated transmembrane [flag]; trans-synaptic cell-contact interaction [PMID:32358586].","caveats":"Binding depends on the alternatively spliced TEN region: insertion abolishes it [PMID:32358586]. Affinity values are not in our excerpts. Key papers were partly read as abstracts.","key_references":[{"PMID":"32358586","why":"Cryo-EM structure of TEN2-LPHN3 and trimer with FLRT3"},{"PMID":"36746957","why":"Antibody overlapping TEN2 site on ADGRL3 separates TEN2 and FLRT3 binding"},{"PMID":"24273166","why":"Cell adhesion of latrophilin cells with Ten2 cells"}],"covers":["LR003359","LR006562"]},"LR004826":{"pair":"TFPI -> SDC4","headline":"TFPI binds purified human ryudocan (SDC4) with Kd 0.74 nM, mediated by heparan sulfate chains rather than the core protein.","interaction_type":"direct binding","direction_and_effect":"TFPI exhibits significant ryudocan binding; the abstract suggests possible anticoagulation function via heparan-sulfate-binding effectors [PMID:8621465].","molecular_requirements":"Binding depends on the heparan sulfate chains: heparitinase and heparin/HS abolished it, chondroitin ABC lyase and chondroitin sulfate did not [PMID:8621465].","affinity_potency":[{"value":"Kd 0.74 nM","assay":"solid-phase binding, apparent dissociation constant","system":"purified human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Purified human ryudocan in a solid-phase assay; the mouse pair is ortholog-inferred [PMID:8621465].","localisation_and_range":"TFPI is annotated secreted [flag]; syndecan is a membrane proteoglycan, though that is not in our evidence beyond the pair.","caveats":"Binding is to glycosaminoglycan chains, which other heparan sulfate proteoglycans also carry, so this is not core-protein-specific. Abstract only. One further paper was abstract-insufficient.","key_references":[{"PMID":"8621465","why":"Ryudocan binds TFPI via HS chains, Kd 0.74 nM"}],"covers":["LR001431","LR004826"]},"LR007427":{"pair":"TGFB1 -> ACVR1:TGFBR2","headline":"Supported mainly by an in silico paper on TGFBR2 plus database records for TGFB1-TGFBR2; ACVR1 itself is not evidenced.","interaction_type":"functional only","direction_and_effect":"The sole paper is a docking and molecular dynamics study of TGF-B binding to TGFBR2, labelled agonist [PMID:41084424]. GtoPdb lists TGFB1-TGFBR2 as agonist [DB:GtoPdb].","molecular_requirements":"ACVR1 is not named in the abstract; only TGFBR2 is addressed [PMID:41084424]. Reactome describes a TGFB1:TGFBR2:TGFBR1 complex [DB:Reactome R-HSA-170840].","affinity_potency":[],"species_and_systems":"Computational study, human proteins [PMID:41084424]. Databases hold SPR and co-IP records for TGFB1-TGFBR2 [DB:IntAct] and structures [DB:PDB 3KFD].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Complex flagged transmembrane [flag].","caveats":"Computational evidence only, read as abstract. Nothing in our evidence shows ACVR1 as a subunit of the ligand-binding complex; database support concerns TGFBR2 and TGFBR1.","key_references":[{"PMID":"41084424","why":"In silico docking/MD of TGF-B with TGFBR2"}],"covers":["LR007427"]},"LR003368":{"pair":"TGFB1 -> CDCP1","headline":"CDCP1 CUB domains bind TGF-beta1 directly by SPR and enhance TGF-beta1 signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CDCP1 CUB domains bind directly to TGF-beta1 and BMP4 on a BIAcore chip; CDCP1 enhances TGF-beta1 reporter activity and phospho-Smad2, proposed as a co-receptor [PMID:31302030].","molecular_requirements":"CUB domains mediate binding; the effect on Smad2 depends on Smad2 and TGFRI and not on Src or PKC-delta binding [PMID:31302030].","affinity_potency":[],"species_and_systems":"Human proteins (SPR) [PMID:31302030]; mouse pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. CDCP1 is described as a transmembrane glycoprotein, although the entity is also flagged secreted [flag] [PMID:31302030].","caveats":"Abstract read only; no affinity reported. CDCP1 is described as a co-receptor enhancing signalling, not a standalone signalling receptor. Also binds BMP4 but does not modulate BMP signalling [PMID:31302030].","key_references":[{"PMID":"31302030","why":"SPR binding of CDCP1 CUB domains to TGF-beta1"}],"covers":["LR003368","LR006569"]},"LR008651":{"pair":"TGFB1 -> ENG","headline":"Endoglin associates with TGF-beta1 only through signalling receptors; it does not bind ligand alone.","interaction_type":"conflicting","direction_and_effect":"Endoglin binds TGF-beta1 and -beta3 by associating with the TGF-beta type II receptor [PMID:9872992]. It is an accessory protein, not an autonomous receptor [PMID:9872992].","molecular_requirements":"Requires coexpression of the kinase receptor; 'Endoglin cannot bind ligands on its own' [PMID:9872992]. A second paper states it requires the signalling receptors for ligand binding [PMID:12015308].","affinity_potency":[],"species_and_systems":"Human endothelial and leukaemic cells, affinity labelling and coprecipitation [PMID:9872992]. UniProt notes high-affinity binding of TGFB1 and TGFB2 but not TGFB3 [DB:UniProt].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Endoglin is described as a transmembrane glycoprotein [PMID:9872992].","caveats":"One paper is a verified negative for a two-protein pair [PMID:12015308]; UniProt says binding of TGFB3 is absent, whereas the paper says TGF-beta3 binds [DB:UniProt] [PMID:9872992]. Both papers read as abstracts. A complex such as TGFBR2:ENG is the more accurate unit.","key_references":[{"PMID":"9872992","why":"Endoglin binds TGF-beta1/-beta3 via type II receptor"},{"PMID":"12015308","why":"Endoglin cannot bind ligand alone (negative)"}],"covers":["LR008651"]},"LR004835":{"pair":"TGFB1 -> ITGB6","headline":"Strong evidence: alphaVbeta6 binds the TGF-beta1 prodomain (structure and cell binding) and activates it.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds with high affinity to a RGDLXXL/I motif in the prodomains of TGF-beta1 and TGF-beta3 [PMID:25383667]. TGF-beta1 LAP is a ligand for alphaVbeta6, and expressing cells induce local TGF-beta1 activation [PMID:10025398]. UniProt records ITGAV:ITGB6 interacting with TGFB1 [DB:UniProt].","molecular_requirements":"Needs the alphaV partner chain; the LXXL/I helix sits in a hydrophobic pocket of the beta6 subunit [PMID:25383667]. Ligand is the latent prodomain/LAP [PMID:10025398].","affinity_potency":[],"species_and_systems":"Crystal structures and peptide affinity [PMID:25383667]; cell-based work with species unspecified [PMID:10025398]; PDB structure [DB:PDB 5FFO].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Latent complex engaged at cell surface; activation is spatially restricted [PMID:10025398].","caveats":"Affinity values not given in the dossier. Ligand is latent TGF-beta; two further papers abstract-insufficient. PMID:10025398 read as abstract only.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with TGF-beta prodomain"},{"PMID":"10025398","why":"TGF-beta1 LAP is a ligand for alphaVbeta6"}],"covers":["LR001440","LR004835"]},"LR004844":{"pair":"TGFB3 -> ACVRL1","headline":"TGF-beta3 activates a chimeric ALK-1 (ACVRL1) receptor in a signalling assay; binding was not measured.","interaction_type":"functional only","direction_and_effect":"TGF-beta1 and TGF-beta3 activated chimeric ALK-1; the interaction is mediated by the type II TGF-beta receptor [PMID:10187774].","molecular_requirements":"Type II TGF-beta receptor needed; endoglin's role is discussed but not reported here [PMID:10187774].","affinity_potency":[],"species_and_systems":"Chimeric ALK-1 with kinase domain swapped for TGFBR1 or ActRIB; species unspecified [PMID:10187774].","localisation_and_range":"Ligand secreted [flag]; ligand also flagged transmembrane [flag].","caveats":"Abstract-only; chimeric receptor, not native; two other papers abstract-insufficient.","key_references":[{"PMID":"10187774","why":"TGF-beta3 activates chimeric ALK-1 via type II receptor"}],"covers":["LR001449","LR004844"]},"LR003377":{"pair":"TGFBI -> STAB2","headline":"One paper reports TGFBI as a circulating ligand of STAB2 by pulldown and endocytosis; single-paper, abstract-level support.","interaction_type":"direct binding","direction_and_effect":"TGFBi was independently confirmed as a novel circulating ligand of Stab1/2 [PMID:36325910]. Clearance by the stabilins suppresses monocyte activation in this paper's model [PMID:36325910].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand binding used GST-pulldown and endocytosis assays; the atherosclerosis work used mice [PMID:36325910]. Which species the binding assays used is not stated in the abstract.","localisation_and_range":"TGFBI is flagged secreted [flag]; the paper describes circulating plasma ligands cleared by liver sinusoidal endothelial cells [PMID:36325910].","caveats":"Only one paper, read as abstract only; the abstract does not detail the binding result for this specific pair. Stab1 and Stab2 are paralogs, with the same claim made for both.","key_references":[{"PMID":"36325910","why":"Stab1/2 scavenger receptor ligands including TGFBi"}],"covers":["LR003377","LR006578"]},"LR004853":{"pair":"TGM2 -> ITGB3","headline":"TG2 binds integrin beta3 in co-IP and macrophage studies; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"TG2 interacts directly with beta1 and beta3 integrins but not beta2 [PMID:10684262]. TG2 binds integrin beta3 and MFG-E8 to build phagocytic portals; integrin beta3 signalling is impaired in TG2-null macrophages [PMID:19643138].","molecular_requirements":"TG2 stabilises accumulated integrin beta3 at the phagocytic cup; beta3 over-expression partially corrected the defect [PMID:19643138]. Association is noncovalent and independent of cross-linking activity [PMID:10684262].","affinity_potency":[],"species_and_systems":"Mouse macrophages for [PMID:19643138]; cultured cells with human tTG for [PMID:10684262]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; cell-surface and phagocytic cup contexts [PMID:19643138].","caveats":"Both papers were read as abstracts only for this pair. The beta3 partner alpha chain is not reported in our evidence.","key_references":[{"PMID":"10684262","why":"tTG interacts with beta1 and beta3 integrins"},{"PMID":"19643138","why":"TG2 binds integrin beta3 in macrophage phagocytosis"}],"covers":["LR001458","LR004853"]},"LR006581":{"pair":"TGM2 -> LRP6","headline":"TG2 binds the LRP6 extracellular domain and activates beta-catenin signalling; supported by one abstract.","interaction_type":"direct binding","direction_and_effect":"TG2 functions as an activating ligand of LRP5/6 and synergizes with LRP6 in beta-catenin gene expression in Cos-7 cells [PMID:23993960]. Interfering with LRP5/6 attenuates TG2-induced activation [PMID:23993960].","molecular_requirements":"TG2 binds directly to the extracellular domain of LRP6, which is also a substrate for TG2 cross-linking; cross-linking inhibitors quench activation [PMID:23993960].","affinity_potency":[],"species_and_systems":"Cos-7 cells; species not stated in the abstract [PMID:23993960]. The human pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; the ligand acts on the LRP6 extracellular domain [PMID:23993960].","caveats":"Abstract-only read. An earlier paper was judged pair_absent for LRP6 (it names LRP5) [PMID:18405667]. No affinity is reported.","key_references":[{"PMID":"23993960","why":"TG2 binds the LRP6 extracellular domain and activates beta-catenin"}],"covers":["LR003380","LR006581"]},"LR004862":{"pair":"THBS1 -> ITGA6","headline":"Reasonable evidence that alpha6beta1 recognizes the THBS1 N-terminal module, plus a co-IP in osteosarcoma cells.","interaction_type":"direct binding","direction_and_effect":"The THBS1 N-terminal pentraxin module is a ligand for alpha6beta1, which mediates adhesion and chemotaxis (stimulatory) of microvascular endothelial and HT-1080 cells; the peptide LALERKDHSG was identified as an alpha6beta1-binding sequence [PMID:12909644]. Co-IP confirmed THBS1 interacts with ITGA6 in human osteosarcoma cells [PMID:40083708].","molecular_requirements":"Acts as alpha6beta1; in microvascular cells activation by the anti-beta1 antibody TS2/16 is needed, and Glu90 of THBS1 was required for alpha6beta1 but not alpha4beta1 recognition [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human endothelial and HT-1080 cells [PMID:12909644]; human 143B and MG-63 osteosarcoma lines [PMID:40083708].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The 2003 paper was read as abstract only; its evidence is cell adhesion with a peptide, and the osteosarcoma co-IP does not prove direct binding. Activation-state dependent. No affinity reported.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognizes THBS1 N-terminal module; LALERKDHSG peptide"},{"PMID":"40083708","why":"Co-IP of THBS1 with ITGA6 (full text)"}],"covers":["LR001467","LR004862"]},"LR001469":{"pair":"THBS1 -> ITGB3","headline":"Supported by one 1989 abstract showing platelet GPIIb-IIIa and an alphaVbeta3-like integrin bind THBS1 on an affinity column; GPIIb-IIIa binds weakly.","interaction_type":"direct binding","direction_and_effect":"Platelet integrin complexes bound to thrombospondin-Sepharose and were specifically eluted with the peptide GRGDSP [PMID:2478219]. Agonist/antagonist action not reported in our evidence.","molecular_requirements":"The beta3 subunit is shared by GPIIb-IIIa and a second integrin with an alphaV-like alpha subunit; GPIIb-IIIa appears to bind relatively weakly [PMID:2478219]. Reactome lists integrin alphaIIbbeta3:THBS1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human platelet membrane proteins, solubilised and run on a thrombospondin-Sepharose column [PMID:2478219].","localisation_and_range":"THBS1 is flagged secreted [flag]; binding was tested with purified protein, so range is not addressed.","caveats":"Single paper, abstract only; five other judged rows were abstract_insufficient. No affinity measured. Beta3 is shared by two integrins, so the pair does not say which alpha chain is needed. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"2478219","why":"Platelet integrins bind thrombospondin-Sepharose"}],"covers":["LR001469","LR004864"]},"LR003386":{"pair":"THBS2 -> CD36","headline":"The N-terminal fragment of THBS2 acts via CD36 to inhibit tube formation and induce apoptosis in endothelial cells; full-length protein not tested.","interaction_type":"functional only","direction_and_effect":"N-TSP2-Fc inhibits VEGF-induced tube formation of HDMEC and induces apoptosis in a CD36-dependent manner; a blocking anti-CD36 antibody abolished the effect [PMID:20714802]. Antiangiogenic, receptor-dependent.","molecular_requirements":"Only the N-terminal region fused to IgG-Fc1 was tested; other subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human dermal microvascular endothelial cells in vitro and human breast tumour xenografts in mice [PMID:20714802].","localisation_and_range":"THBS2 flagged secreted [flag].","caveats":"Fragment-specific, not full-length THBS2; abstract plus some full text; no binding measured, CD36 dependence rests on antibody blockade.","key_references":[{"PMID":"20714802","why":"N-TSP2-Fc antiangiogenic activity depends on CD36"}],"covers":["LR003386","LR006587"]},"LR006590":{"pair":"THBS4 -> ITGB5","headline":"THBS4 binds ITGB5 by immunoprecipitation in HCC cells; browser-read quote pending spot-check.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation confirmed that THBS4 can bind ITGB1, ITGB5 and ITGA5 [PMID:32567740].","molecular_requirements":"Alpha partner for ITGB5 not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HCC cells; mouse pair ortholog-inferred [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"Quote is browser-read and unverified; IntAct co-IP record [DB:IntAct].","key_references":[{"PMID":"32567740","why":"THBS4 co-IP with ITGB5 in HCC"}],"covers":["LR003389","LR006590"]},"LR004871":{"pair":"THPO -> MPL","headline":"Well supported agonist pair with a cryo-EM structure of the TPO-MPL extracellular complex plus functional and database evidence.","interaction_type":"direct binding","direction_and_effect":"Agonist: TPO bridges two MPL chains and drives homodimeric MPL activation [PMID:37633268]; TPO-stimulated Mpl activation is proposed to occur through receptor homodimerisation [PMID:8521814]. GtoPdb lists the interaction as Agonist [DB:GtoPdb].","molecular_requirements":"Two MPL chains per TPO. TPO binds via a high-affinity site 1 and a low-affinity site 2; MPL CRM1 recognises TPO and CRM2 brings transmembrane and intracellular domains together [PMID:37633268].","affinity_potency":[],"species_and_systems":"Cryo-EM at 3.4 \u00c5 resolution using human TPO and human MPL; SPR with human MPL ectodomain; also mouse and in vitro cell work with TPO variants [PMID:37633268]. The 1995 study used mutant Mpl in FDC-P1 and Ba/F3 cells (abstract only) [PMID:8521814]. PDB 8G04 [DB:PDB 8G04].","localisation_and_range":"TPO is flagged secreted and MPL transmembrane [flag]; endocrine/paracrine cytokine acting on membrane receptor.","caveats":"Engineered TPO variants span neutral antagonists to partial and super-agonists [PMID:37633268]. The 1995 paper was read as abstract only and shows TPO action only indirectly [PMID:8521814]. No numeric affinity in our evidence.","key_references":[{"PMID":"37633268","why":"Cryo-EM structure of TPO-MPL complex and biased agonists"},{"PMID":"8521814","why":"Mpl dimer interface and TPO-stimulated homodimerisation"}],"covers":["LR001476","LR004871"]},"LR003395":{"pair":"THY1 -> ITGAX","headline":"The alphaX I-domain of CD11c/CD18 binds Thy-1 directly; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direction/effect not reported in our evidence beyond specific binding [PMID:15850796].","molecular_requirements":"The I-domain of alphaX-beta2 alone bound Thy-1 in a divalent-cation-dependent manner; D249 and KE243/244 on the betaD-alpha5 loop mutants lowered affinity [PMID:15850796].","affinity_potency":[{"value":"KD 1.16muM","assay":"alphaX I-domain binding to Thy-1","system":"purified I-domain","cite":"PMID:15850796"}],"species_and_systems":"Recombinant protein binding; species not stated in the dossier for this row [PMID:15850796].","localisation_and_range":"Both membrane proteins [flag]; contact-dependent.","caveats":"Abstract only; evidence is for an isolated I-domain rather than full integrin. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"15850796","why":"alphaX I-domain binds Thy-1, KD 1.16muM"}],"covers":["LR003395","LR006596"]},"LR005348":{"pair":"TIGIT -> PVR","headline":"TIGIT binds PVR (CD155) with high affinity and acts as an inhibitory receptor; two abstract-only papers plus structure.","interaction_type":"direct binding","direction_and_effect":"TIGIT-Fc inhibited T cell activation in vitro in a dendritic-cell dependent way; PVR binding on human DCs raised IL-10 and lowered IL-12p40 [PMID:19011627]. In NK cells TIGIT inhibits cytotoxicity directly via its ITIM [PMID:19815499].","molecular_requirements":"TIGIT contains an ITIM [PMID:19011627]. No additional subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human DCs and T cells with TIGIT-Fc; DTH in wild-type and IL-10-deficient mice [PMID:19011627]; human NK cells [PMID:19815499]. PDB 3UDW [DB:PDB 3UDW].","localisation_and_range":"TIGIT is membrane-bound; PVR carries a secreted flag [flag] but papers describe cell-surface PVR on DCs and target cells [PMID:19011627].","caveats":"'High affinity' is stated without a number [PMID:19011627]. Both papers abstract only. TIGIT knockdown in human memory T cells had no effect [PMID:19011627].","key_references":[{"PMID":"19011627","why":"TIGIT-PVR high-affinity binding and DC-mediated suppression"},{"PMID":"19815499","why":"Direct NK inhibition via TIGIT"}],"covers":["LR002020","LR005348"]},"LR001478":{"pair":"TIMP2 -> ITGA3","headline":"TIMP-2 acts on endothelial cells via alpha3beta1 integrin; one abstract-read paper, partly functional.","interaction_type":"functional only","direction_and_effect":"The anti-angiogenic effects of TIMP-2, independent of MMP inhibition, required alpha 3 beta 1 integrin-mediated binding of TIMP-2 to endothelial cells, decreasing PTP activity associated with beta1 and dissociating SHP-1 [PMID:12887919]. This is inhibitory for endothelial proliferation.","molecular_requirements":"Acts via the alpha3beta1 heterodimer; ITGA3 alone is not tested in our evidence [PMID:12887919].","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro and angiogenesis in vivo; species not specified in the curated row [PMID:12887919]. Mouse pair is ortholog-inferred.","localisation_and_range":"TIMP2 is flagged secreted and ITGA3 as a receptor [flag].","caveats":"Abstract-only; the cited sentence states a requirement for alpha3beta1, not direct binding to ITGA3. Two other papers were abstract_insufficient and one is pending.","key_references":[{"PMID":"12887919","why":"TIMP-2 requires alpha3beta1 for anti-angiogenic effect"}],"covers":["LR001478","LR004873"]},"LR006608":{"pair":"TIMP3 -> MMP2","headline":"TIMP-3 binds gelatinase A (MMP-2) with rapid association; inhibitor-enzyme interaction with database structural support.","interaction_type":"direct binding","direction_and_effect":"TIMP-3 showed rapid association with gelatinases A and B, and isolated complexes on gelatin-agarose showed TIMP-3 binds both proenzymes [PMID:10196161]. The curated effect is antagonist, i.e. inhibition of the enzyme [PMID:10196161].","molecular_requirements":"The hemopexin domain of gelatinase A contributes to the interaction; residues 568-631 of gelatinase A were required for rapid association [PMID:10196161].","affinity_potency":[],"species_and_systems":"In vitro biochemical assay with purified proteins (human); human and mouse pairs are both ortholog-inferred [PMID:10196161].","localisation_and_range":"MMP2 is flagged secreted [flag], and TIMP-3 is sequestered in the extracellular matrix per the authors [PMID:10196161].","caveats":"Abstract-only, no affinity value in the dossier. Enzyme-inhibitor interaction rather than signalling; MMP2 receptor status is a flag annotation.","key_references":[{"PMID":"10196161","why":"TIMP-3 association with gelatinases"}],"covers":["LR003407","LR006608"]},"LR004880":{"pair":"TNC -> ITGA7","headline":"Alpha7beta1 integrin associates with tenascin-C peptides in human-derived binding assays and mediates neurite outgrowth; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Function-blocking antibodies to alpha7 and beta1 abolished VFDNFVLK-mediated process extension from cerebellar granule neurons, and alpha7beta1 associated biochemically with peptides containing VFDNFVLK [PMID:14715956].","molecular_requirements":"Both alpha7 and beta1 were needed for the response [PMID:14715956]. The site lies in the alternatively spliced fibronectin type III repeat D of tenascin-C [PMID:14715956].","affinity_potency":[],"species_and_systems":"Human tenascin-C peptides; cerebellar granule neurons [PMID:14715956].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only read. Evidence concerns a peptide motif from a spliced repeat, not full-length TNC. The mutant peptide VSPNGSLK did not bind [PMID:14715956].","key_references":[{"PMID":"14715956","why":"alpha7beta1 binds VFDNFVLK of tenascin-C fnD"}],"covers":["LR001485","LR004880"]},"LR008525":{"pair":"TNC -> ITGA8:ITGB1","headline":"Reactome and UniProt support alpha8beta1 and tenascin-C; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; one abstract_insufficient and one review_only [outcome_counts]. Reactome records an alpha8beta1:tenascin-C hexamer complex [DB:Reactome]; UniProt describes a neuronal receptor for TNC regulating neurite outgrowth [DB:UniProt].","molecular_requirements":"Complex ITGA8:ITGB1 [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Rests on databases alone in our evidence; a separate pair TNC to ITGA8 has a confirming paper.","key_references":[],"covers":["LR008525"]},"LR001487":{"pair":"TNC -> ITGA9","headline":"Integrin alpha9beta1 is a TNC receptor driving migration and lung metastasis of human osteosarcoma cells in mouse xenografts.","interaction_type":"functional only","direction_and_effect":"ITGA9 knockdown abolished TNC-specific transwell migration, and knockdown of TNC or ITGA9 reduced lung metastasis in nude mice [PMID:29259017]. TNC/alpha9beta1 signalling destroys actin stress fibers and inhibits YAP target gene expression [PMID:29259017]. UniProt notes ITGA9:ITGB1 interacts with TNC via its third fibronectin type III domain [DB:UniProt].","molecular_requirements":"Alpha9beta1 heterodimer acts; the study knocked down the ITGA9 chain [PMID:29259017].","affinity_potency":[],"species_and_systems":"Human osteosarcoma KRIB and GBM T98G cell lines, grafted into nude mice [PMID:29259017].","localisation_and_range":"Autocrine and paracrine signalling suggested; TNC deposited as matrix substratum [PMID:29259017].","caveats":"Functional (knockdown) evidence; direct binding not shown in the paper excerpts. Two other papers were abstract_insufficient.","key_references":[{"PMID":"29259017","why":"TNC/integrin alpha9beta1 in osteosarcoma metastasis"}],"covers":["LR001487","LR004882"]},"LR001496":{"pair":"TNFSF11 -> TNFRSF11A","headline":"RANKL activates RANK, the core osteoclast axis; evidence here is a mouse RANKL structure, a human identification paper and database records.","interaction_type":"direct binding","direction_and_effect":"RANKL was isolated by expression screening and augments dendritic cell stimulation of naive T-cell proliferation and survival of RANK+ T cells [PMID:9367155]. Mutating surface loops of RANKL modulates RANK activation in in vitro osteoclastogenesis [PMID:11581298]. Effect: agonist.","molecular_requirements":"RANKL is a homotrimer; three RANK molecules bind a RANKL trimer in Reactome [PMID:11581298][DB:Reactome]. Complex formation increases with RANKL [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse RANKL crystal structure at 2.6 A [PMID:11581298]; human cells and proteins [PMID:9367155]. IntAct pull down and surface plasmon resonance [DB:IntAct].","localisation_and_range":"RANKL is flagged secreted and transmembrane, so soluble and membrane forms may act [flag].","caveats":"The structure solves RANKL alone, not the complex; both papers were read as abstracts. The GtoPdb record has no type or affinity [DB:GtoPdb].","key_references":[{"PMID":"9367155","why":"Identification of RANK and RANKL"},{"PMID":"11581298","why":"Structure of mouse RANKL and loop mutagenesis"}],"covers":["LR001496","LR004887"]},"LR006617":{"pair":"TNFSF13 -> SDC1","headline":"APRIL binds heparan sulfate proteoglycans on tumour cells; syndecan-1 transfectants bind more APRIL, but the effect runs through heparan sulfate chains.","interaction_type":"direct binding","direction_and_effect":"APRIL specifically binds heparan sulfate proteoglycans on tumour cells through the heparan sulfate chains, and this is inhibited by heparin; the interaction is crucial for APRIL's tumour growth-promoting activity but does not affect APRIL-induced T-cell proliferation [PMID:15846369]. Syndecan-1-transfected Namalwa cells showed higher binding than CD44 variant cells [PMID:15846369]. Role: co-receptor-like, not a signalling receptor.","molecular_requirements":"BCMA and HSPG can bind APRIL simultaneously. A mutation of three lysines in a putative heparan sulfate-binding motif destroys HSPG binding while BCMA binding is unaffected [PMID:15846369].","affinity_potency":[],"species_and_systems":"Tumour cells and transfectants; the species of the experiments is not stated in our evidence [PMID:15846369].","localisation_and_range":"APRIL is flagged secreted; syndecan-1 carries secreted and transmembrane flags [flag]. Interaction is with heparan sulfate side chains.","caveats":"The authors conclude HSPG either serve as a receptor or let APRIL reach another receptor [PMID:15846369]. The binding is mediated by sugar chains shared among proteoglycans, so specificity for syndecan-1 itself is not shown. Seven other papers were abstract_insufficient.","key_references":[{"PMID":"15846369","why":"APRIL binding to HSPG and syndecan-1 transfectants"}],"covers":["LR003416","LR006617"]},"LR004907":{"pair":"TSLP -> IL7R","headline":"TSLP acts through IL7R only as part of the TSLPR/IL-7Ralpha heterodimer; IL7R alone is insufficient.","interaction_type":"functional only","direction_and_effect":"Agonist: cells transfected with both receptor subunits proliferated in response to purified, recombinant human TSLP, with induced phosphorylation of Stat3 and Stat5 [PMID:11418668]. GtoPdb lists TSLP-IL7R as Agonist [DB:GtoPdb].","molecular_requirements":"Needs the heterodimer with TSLPR (CRLF2); the curator notes IL7R alone is insufficient [PMID:11418668].","affinity_potency":[],"species_and_systems":"Transfected cells, recombinant human TSLP [PMID:11418668]. Mouse pair ortholog-inferred.","localisation_and_range":"TSLP flagged secreted [flag].","caveats":"Chain-only pair: direct binding of TSLP to IL7R alone is not reported in our evidence; abstract read only. In CCC tools use the complex CRLF2:IL7R.","key_references":[{"PMID":"11418668","why":"TSLP responses need TSLPR and IL-7Ralpha together"}],"covers":["LR001517","LR004907"]},"LR006626":{"pair":"TULP1 -> AXL","headline":"Tulp1 binds Axl as one of three TAM receptors (Tyro3, Axl, MerTK); one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Axl-specific activation is not separately described in the abstract. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003425","LR006626"]},"LR007337":{"pair":"ULBP2 -> HCST:KLRK1","headline":"ULBP2 engages the NKG2D receptor on NK cells; one full-text functional paper plus database records, no affinity data.","interaction_type":"functional only","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445].","molecular_requirements":"NKG2D is required: anti-NKG2D antiserum blocked ULBP1-Fc binding to NKL cells, and the ULBPs are described as ligands for the activating receptor NKG2D/DAP10 [PMID:11239445]. HCST (DAP10) is named only through the statement that the receptor is 'probably NKG2D/DAP10'; HCST was not tested separately in our evidence [PMID:11239445].","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. IntAct lists FACS and surface plasmon resonance records [DB:IntAct] [PMID:19424970] [PMID:28559451]; UniProt notes interaction with KLRK1/NKG2D [DB:UniProt] [PMID:11777960].","localisation_and_range":"Annotation flags mark the ligand as both secreted and transmembrane [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445].","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR007337"]},"LR006635":{"pair":"UNC5B -> FLRT3","headline":"UNC5B-FLRT3 is supported by direct binding in a mouse-protein screen plus BioGRID and UniProt records.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5B is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"Unc5B stripes gave no significant neuronal response (n=3/380, 1% repulsive) [PMID:26633812]. BioGRID records a reconstituted complex [DB:BioGRID, PMID:21673655] and UniProt records extracellular-domain interaction [DB:UniProt]. No affinity is reported.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"},{"PMID":"21673655","why":"Source of the BioGRID reconstituted-complex record (abstract states Unc5B was shown to bind FLRT3)"}],"covers":["LR003434","LR006635"]},"LR004916":{"pair":"VCAM1 -> ITGA4","headline":"VCAM1 engages integrin alpha4 (as alpha4beta1/alpha4beta7); confirmed in adhesion assays, but evidence is abstract-level and chain-ambiguous.","interaction_type":"functional only","direction_and_effect":"Adhesion-mediated: alpha4beta7 on lymphocytes binds VCAM-1 depending on chemokine priming; CCL25 lowered and CXCL10 raised adhesion to VCAM-1 [PMID:29789438]. alpha4beta1 binds VCAM-1 and the VCAM-1 domain 2 forms an accessory binding site [PMID:9235944].","molecular_requirements":"The functional receptor is the alpha/beta heterodimer, not ITGA4 alone: alpha4beta1 and alpha4beta7 are both named [PMID:9235944]. The alpha4 blocking antibody HP2/1 abolished adhesion to both ligands [PMID:29789438].","affinity_potency":[],"species_and_systems":"Human lymphocyte (RPMI 8866-CXCR3) adhesion and single-cell force assays [PMID:29789438]; species unspecified for [PMID:9235944]. Mouse pair is ortholog-inferred.","localisation_and_range":"VCAM1 is flagged secreted and transmembrane [flag]; adhesion assays used immobilised or soluble VCAM-1 and cells, consistent with contact-mediated binding [PMID:29789438].","caveats":"Single integrin chain stored; scoring should use heterodimer. PMID 9235944 read as abstract only and is a chimera/mutagenesis study. BioGRID affinity capture-MS record [DB:BioGRID].","key_references":[{"PMID":"29789438","why":"alpha4beta7 conformers select VCAM-1 versus MAdCAM-1; full text read"},{"PMID":"9235944","why":"alpha4beta1/alpha4beta7 binding footprints on VCAM-1"}],"covers":["LR001527","LR004916"]},"LR007076":{"pair":"VCAM1 -> ITGA4:ITGB1","headline":"Complex pair supported only by databases (Reactome, UniProt, BioGRID, IntAct); no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states integrin alpha-4/beta-1 is a receptor for VCAM1 [DB:UniProt]; Reactome lists the binding reaction 'VCAM1 binds Integrin alpha4beta1' [DB:Reactome].","molecular_requirements":"Both chains, ITGA4 and ITGB1, form the receptor complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and cells not reported in our evidence; Reactome entries are human-pathway records [DB:Reactome].","localisation_and_range":"VCAM1 flagged secreted and transmembrane; ITGA4 and ITGB1 flagged receptors [flag].","caveats":"No curator-verified paper; one row was 'different_entity' and one 'abstract_insufficient'. BioGRID affinity capture-MS and IntAct cross-linking records are association evidence [DB:BioGRID][DB:IntAct].","key_references":[],"covers":["LR007076"]},"LR004925":{"pair":"VCAN -> TLR2","headline":"Versican activates TLR2 in myeloid and dendritic cells; human data come from DC studies, with mouse co-IP, direct binding not shown.","interaction_type":"functional only","direction_and_effect":"Versican from Lewis lung carcinoma medium activates macrophages via TLR2 with TLR6 and CD14, inducing TNF-alpha [PMID:19122641]. Tumour-derived versican activates TLR2 in DCs, driving IL-6/IL-10 immunosuppressive DCs [PMID:26711349].","molecular_requirements":"TLR2 with co-receptors TLR6 and CD14; the versican antibody co-precipitated TLR2 and CD14 but not TLR4 [PMID:19122641].","affinity_potency":[],"species_and_systems":"Mouse macrophages (Raw264.7) and LLC [PMID:19122641]; human and mouse DCs, TLR2 knockout mice and anti-TLR2 antibody [PMID:26711349]. Human pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted [flag]; acts as a soluble factor on DCs [PMID:26711349].","caveats":"Co-IP does not establish direct binding. PMID 19122641 quote is browser-read and unverified. Full-text read for PMID 26711349 only.","key_references":[{"PMID":"19122641","why":"versican activates TLR2:TLR6 in macrophages"},{"PMID":"26711349","why":"versican activates TLR2 in DCs"}],"covers":["LR001536","LR004925"]},"LR006644":{"pair":"VEGFA -> CD44","headline":"Direct, high-affinity binding of VEGF165 to the CD44v6 ectodomain, shown in one full-text paper; no other papers.","interaction_type":"direct binding","direction_and_effect":"VEGF binds CD44v6 directly (pull-down) with nanomolar affinity, and binding to cells depends on CD44v6; CD44v6 acts as a co-receptor that is required for VEGFR-2 (KDR) activation, so this is a coreceptor/potentiating role rather than a stand-alone receptor [PMID:26181364].","molecular_requirements":"The v6 variant exon is needed: CD44s showed no fit by MST and weak binding (1300\u00b1600 nM) by FCS. Binding is heparan sulfate-independent [PMID:26181364].","affinity_potency":[{"value":"Kd 51\u00b19 nM","assay":"MicroScale Thermophoresis, VEGF165 vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"},{"value":"Kd 200\u00b140 nM","assay":"FCS, VEGF165-NT647 vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"},{"value":"Kd 65\u00b18 nM","assay":"FCS, VEGF165-ATTO 647N vs CD44v6","system":"purified CD44v6 ectodomain","cite":"PMID:26181364"}],"species_and_systems":"Recombinant rat CD44v6 ectodomain made in HEK293T cells; cell binding in rat BSp73ASs6 cells and HUVEC; VEGF165 [PMID:26181364]. The mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA is flagged secreted and CD44 as transmembrane [flag]; the paper's assays used a soluble ectodomain, so a membrane-bound CD44v6 acting on secreted VEGF is the implied geometry.","caveats":"One paper, with the Kd values coming from three methods that differ about four-fold. No second group or in vivo support in our evidence. The affinity for CD44s is much lower.","key_references":[{"PMID":"26181364","why":"Pull-down, MST/FCS Kd values and isoform specificity for VEGF165 and CD44v6"}],"covers":["LR003443","LR006644"]},"LR004934":{"pair":"VEGFB -> NRP1","headline":"VEGF-B167 and VEGF-B186 bind NRP1 in one abstract-level study, with UniProt and a PDB structure supporting.","interaction_type":"direct binding","direction_and_effect":"Both VEGF-B splice isoforms bind specifically to NRP1; binding was competed by excess VEGF165 [PMID:10409677]. Agonist/antagonist effect not reported in our evidence.","molecular_requirements":"VEGF-B167 binding is mediated by its heparin-binding domain; VEGF-B186 binds NRP1 only after proteolytic processing exposes a short C-terminal proline-rich peptide [PMID:10409677].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; abstract-only reading [PMID:10409677]. Both interactions listed are ortholog-inferred, so the human pair itself was projected rather than separately tested.","localisation_and_range":"VEGFB flagged secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Single paper read as an abstract; no affinity reported. UniProt lists VEGFB among NRP1 binding partners [DB:UniProt] and BioGRID lists a reconstituted complex [DB:BioGRID]. A PDB entry exists [DB:PDB 6TKK]. NRP1 lacks intrinsic kinase signalling in our evidence, so co-receptor role is not established here.","key_references":[{"PMID":"10409677","why":"VEGF-B isoform binding to NRP1"}],"covers":["LR001545","LR004934"]},"LR004943":{"pair":"VIP -> SCTR","headline":"No curator-verified paper supports this pair; it rests on a single GtoPdb record.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists VIP at SCTR as agonist, action partial agonist [DB:GtoPdb VIP-SCTR].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human and mouse pairs are both ortholog-inferred.","localisation_and_range":"VIP is flagged secreted and SCTR transmembrane [flag].","caveats":"No papers were judged confirmed: seven were abstract_insufficient and two concerned a different entity. The GtoPdb record cites PMID:1646711 with pIC50 units, but the value is not shown in our evidence [DB:GtoPdb].","key_references":[],"covers":["LR001554","LR004943"]},"LR001559":{"pair":"VTN -> ITGA8","headline":"Human integrin alpha8beta1 is reported as a vitronectin receptor; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 localised to focal contacts on vitronectin, mediated adhesion of alpha8-transfected 293 cells to vitronectin, and bound vitronectin-Sepharose, from which it was eluted by the RGD peptide GRGDSP [PMID:7559467].","molecular_requirements":"The functional receptor is the alpha8beta1 heterodimer; alpha8 is tested together with beta1, not alone [PMID:7559467]. Binding is RGD-dependent and distinct from alpha5- and alphaV-containing integrins (stated in the abstract).","affinity_potency":[],"species_and_systems":"Human 293 cells transfected with alpha8 cDNA and cell lines plated on matrix; mouse pair is ortholog-inferred [PMID:7559467].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Abstract only, and the stored evidence sentence is truncated. No affinity reported. The curator note says rows stored per subunit should be folded into the ITGA8:ITGB1 complex.","key_references":[{"PMID":"7559467","why":"alpha8beta1 adhesion to and affinity chromatography on vitronectin"}],"covers":["LR001559","LR004948"]},"LR004952":{"pair":"VTN -> ITGB5","headline":"AlphaVbeta5 is a vitronectin-selective integrin in purified and hESC systems; three abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Purified placental alphaVbeta5 bound preferentially to vitronectin, unlike alphaVbeta3 [PMID:1694173]. In FG-2 lysates alphaVbeta5 bound exclusively to vitronectin and was eluted by RGD peptide [PMID:1532572]. In hESCs, blocking antibodies showed alphaVbeta5 mediates adhesion to vitronectin [PMID:18599809].","molecular_requirements":"ITGB5 acts with the alphaV chain as alphaVbeta5 [PMID:1694173].","affinity_potency":[],"species_and_systems":"Human purified protein, cell lysates and hESCs [PMID:1694173] [PMID:1532572] [PMID:18599809]. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry; all three papers abstract only. No affinity reported. One further paper was review only. Reactome also asserts the pair [DB:Reactome].","key_references":[{"PMID":"1694173","why":"Purification of alphaVbeta5 as a vitronectin receptor"},{"PMID":"1532572","why":"alphaVbeta5 binds vitronectin exclusively in FG-2 lysates"},{"PMID":"18599809","why":"alphaVbeta5 mediates hESC adhesion to vitronectin"}],"covers":["LR001563","LR004952"]},"LR003449":{"pair":"VWC2L -> CD36","headline":"VWC2L binds CD36 on transfected cells by flow cytometry in a CRISPRa screen paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Tetramerised VWC2L bound full-length CD36-transfected 293F cells by flow cytometry; the paper observed binding of LY6H, NRN1, VW2CL and SCRG1 to CD36 [PMID:36178190]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"CD36 alone in transfected cells was sufficient for tetramer staining; other requirements are not reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human proteins; 400 nM SA-647 tetramers on 293F cells, n=3 [PMID:36178190]. The mouse pair is ortholog-inferred.","localisation_and_range":"VWC2L is flagged secreted and CD36 transmembrane [flag]; the paper calls the ligands secreted [PMID:36178190].","caveats":"Cell surface staining only, no SPR or Kd for this pair. CD36 is a multifunctional scavenger receptor binding several ligands, and VWC2L was one of several related hits [PMID:36178190].","key_references":[{"PMID":"36178190","why":"CRISPRa screen identified CD36 as VWC2L receptor; flow cytometry confirmation"}],"covers":["LR003449","LR006650"]},"LR001568":{"pair":"VWF -> GP1BA","headline":"GPIbalpha is the platelet VWF receptor, supported by a co-crystal structure with the VWF A1 domain and many database records.","interaction_type":"direct binding","direction_and_effect":"Structures of the GpIbalpha N-terminal domain and its complex with VWF domain A1 show GpIbalpha wrapping around A1 with two contact areas [PMID:12183630]. An antibody to GPIb alpha blocked VWF binding to platelets, and there was no binding to Bernard-Soulier platelets [PMID:6336654]. Curated effect is stimulatory.","molecular_requirements":"The interaction uses the VWF A1 domain and the GPIbalpha amino-terminal domain [PMID:12183630]. Whether other complex subunits are needed is not reported in our evidence; Reactome lists GPIb:IX:V binding VWF multimer:collagen [DB:Reactome].","affinity_potency":[{"value":"Kd~1.5x10^-8 M","assay":"radiolabelled F(ab')2 antibody binding to GPIb on platelets (antibody, not VWF, affinity)","system":"human platelets","cite":"PMID:6336654"}],"species_and_systems":"Human proteins, crystallography and platelets [PMID:12183630] [PMID:6336654]. Structures are in [DB:PDB 1M10] and [DB:PDB 1SQ0]; BioGRID and IntAct record reconstituted complex, far Western and co-crystal evidence [DB:BioGRID] [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"VWF is flagged secreted; GP1BA is flagged transmembrane and a receptor [flag]. Platelet rolling at vascular damage [PMID:12183630].","caveats":"Both papers are abstract-only. The interaction is transient and shear-dependent per the curators, so a static affinity may mislead. The only affinity here is for an antibody, not VWF.","key_references":[{"PMID":"12183630","why":"co-crystal structure of GpIbalpha with VWF A1"},{"PMID":"6336654","why":"antibody blocks VWF binding to platelet GPIb alpha"}],"covers":["LR001568","LR004957"]},"LR006653":{"pair":"VWF -> ITGA9","headline":"The VWF propolypeptide promotes alpha9beta1-mediated cell adhesion; one paper, functional only.","interaction_type":"functional only","direction_and_effect":"pp-vWF promoted adhesion of G-361 cells via alpha9beta1; SW480 cells transfected with alpha9beta1, but not mock transfectants, adhered to pp-vWF and T2-15/BSA [PMID:10816592].","molecular_requirements":"alpha9beta1 is the integrin; the binding site is a 15 residue segment, T2-15, shared with alpha4beta1 [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cells (G-361, SW480 transfectants) [PMID:10816592]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only read. The ligand is the propolypeptide cleaved from the VWF precursor, not mature VWF. Cell adhesion only, no affinity.","key_references":[{"PMID":"10816592","why":"pp-vWF is a ligand for alpha9beta1"}],"covers":["LR003453","LR006653"]},"LR007445":{"pair":"VWF -> ITGAV:ITGB3","headline":"No paper judged for this complex; support is from databases only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states integrin alphaV/beta3 is a receptor for vitronectin and von Willebrand factor [DB:UniProt]. Reactome lists the integrin alphaVbeta3:VWF multimer complex [DB:Reactome], and IntAct records a solid phase assay [DB:IntAct].","molecular_requirements":"Both ITGAV and ITGB3 form the complex; individual chain contributions are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no curated paper. One paper was marked different entity and one review-only.","localisation_and_range":"Not reported in our evidence.","caveats":"Database assertion only; no verified primary paper for this complex. Functional evidence exists on the ITGAV pair page but is not part of this dossier.","key_references":[],"covers":["LR007445"]},"LR003458":{"pair":"VWF -> SCARA5","headline":"SCARA5 binds and internalises VWF; one abstract-only paper with some full-text support.","interaction_type":"direct binding","direction_and_effect":"VWF and the VWF-FVIII complex bound human recombinant SCARA5 in a dose- and calcium-dependent manner, and SCARA5-expressing HEK293T cells bound and internalised them into early endosomes [PMID:31126000]. SCARA5 deficiency had a modest influence on human VWF half-life in mice.","molecular_requirements":"Calcium is needed for binding [PMID:31126000]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant SCARA5 and HEK293T cells, mouse model, human tissue [PMID:31126000]. Mouse pair is ortholog-inferred.","localisation_and_range":"SCARA5 is a transmembrane type II protein [flag]; it is expressed by kidney podocytes and splenic littoral cells, where VWF colocalises [PMID:31126000].","caveats":"Modest in vivo effect suggests a supplementary role. No affinity reported.","key_references":[{"PMID":"31126000","why":"SCARA5 binds and internalises VWF"}],"covers":["LR003458","LR006658"]},"LR006662":{"pair":"WFIKKN2 -> PRTG","headline":"WFIKKN2 binds PRTG (protogenin) by SPR and is named as an axon-guidance ligand for it; binding evidence is full text, function is abstract only.","interaction_type":"direct binding","direction_and_effect":"WFIKKN2 ECD-Fc with PRTG analyte-Fc was observed in the apECIA screen and SPR-validated [PMID:32822567]. A preprint names Prtg among the DCC-family receptors for WFIKKN2; its Prtg-specific function is not delineated in the abstract [PMID:37398498].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human ECD-Fc proteins by SPR and apECIA [PMID:32822567]; mouse axon work from abstract [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; PRTG is flagged as a receptor [flag].","caveats":"The SPR legend notes PRTG:WFIKKN2 was run at 512 nM because of incomplete chip regeneration at higher concentrations [PMID:32822567]. No affinity value is reported in our evidence. The preprint was read as abstract only [PMID:37398498].","key_references":[{"PMID":"32822567","why":"SPR-validated WFIKKN2-PRTG binding"},{"PMID":"37398498","why":"WFIKKN2 as ligand for Punc/Nope/Prtg (abstract only)"}],"covers":["LR003462","LR006662"]},"LR004961":{"pair":"WNT1 -> FZD1","headline":"WNT1 acts through FZD1 in mouse-neuron functional work (abstract only); UniProt supports the pairing.","interaction_type":"functional only","direction_and_effect":"Exogenous Wnt1 was neuroprotective for dopaminergic neurons, and silencing Fzd-1 or beta-catenin in neurons counteracted astrocyte-induced neuroprotection, supporting a Wnt1/Fzd-1/beta-catenin loop [PMID:21752258]. UniProt states FZD1 is activated by WNT3A, WNT3, WNT1 and less by WNT2 [DB:UniProt].","molecular_requirements":"Beta-catenin dependence is shown functionally [PMID:21752258]. Co-receptor requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse midbrain dopaminergic neuron and astrocyte cultures plus mouse in vivo experiments; the human pair is listed with an ortholog-inferred human interaction [PMID:21752258].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence. The paper describes an astrocyte-to-neuron paracrine loop [PMID:21752258].","caveats":"No binding assay. Paper read as abstract only; Reactome lists WNT:FZD complex records with 13 entries [DB:Reactome]. The human interaction is ortholog-inferred.","key_references":[{"PMID":"21752258","why":"Wnt1/Fzd-1/beta-catenin loop in dopaminergic neuron survival"}],"covers":["LR001572","LR004961"]},"LR008039":{"pair":"WNT1 -> FZD1:LRP6","headline":"WNT1 to FZD1:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID]. Reactome complexes include Wnt1:Frizzled1:phospho LRP6 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"All three judged rows are review_only; no curator-verified paper. Reactome R-NUL entries are labelled with Frizzled1 specifically, not a generic FZD [DB:Reactome].","key_references":[],"covers":["LR008039"]},"LR005357":{"pair":"WNT1 -> FZD2","headline":"WNT1 signals through FZD2 in HEK293T knockout-rescue reporter experiments; functional, not direct binding.","interaction_type":"functional only","direction_and_effect":"Expressing FZD2 or FZD7 each rescued Wnt3- and Wnt1-dependent TCF4/Wnt reporter activity in FZD1/2/7 multiplex-CRISPR knockout cells [PMID:28733458].","molecular_requirements":"FZD2 alone sufficed in the rescue; FZD7 could substitute, so paralogs are redundant [PMID:28733458]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293T cells with CRISPR FZD knockouts; the mouse pair is ortholog-inferred [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Loss-of-function plus rescue supports receptor use but not physical binding. FZD7 is an alternative receptor in this system.","key_references":[{"PMID":"28733458","why":"Knockout-rescue map of Wnt-FZD functional pairs"}],"covers":["LR002031","LR005357"]},"LR008147":{"pair":"WNT1 -> FZD5:LRP5","headline":"WNT1 to FZD5:LRP5 is supported only by a FZD5 reporter result plus a UniProt LRP5 note.","interaction_type":"functional only","direction_and_effect":"Wnt1 induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458].","molecular_requirements":"LRP5 involvement is not tested in our evidence; UniProt notes an LRP5 interaction enhanced by WNT1 or WNT3A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Reporter cells with FZD knockouts [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"The paper supports only the FZD5 half; the complex is inferred.","key_references":[{"PMID":"28733458","why":"Wnt1 signals via FZD5 in reporter cells"}],"covers":["LR008147"]},"LR008084":{"pair":"WNT1 -> FZD7:LRP6","headline":"Database-asserted only: WNT1 with FZD7:LRP6, with no curated paper and nothing specific to FZD7.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence. BioGRID records an LRP6-WNT1 reconstituted complex [DB:BioGRID] and UniProt notes LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt].","molecular_requirements":"The records concern LRP6 and WNT1; FZD7 is not named in any record shown. Reactome lists a generic WNT:FZD complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and system of the database records are not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Rests on databases alone; the FZD7 member is unsupported here.","key_references":[],"covers":["LR008084"]},"LR010739":{"pair":"WNT1 -> FZD9:LRP6","headline":"Database-asserted only: WNT1 with FZD9:LRP6, no papers; FZD9 is not supported.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence. BioGRID lists an LRP6-WNT1 reconstituted complex [DB:BioGRID]; UniProt notes LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt].","molecular_requirements":"FZD9 not named in any record. Reactome entries involve Frizzled1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Database-only; one judged paper was a different entity.","key_references":[],"covers":["LR010739"]},"LR001577":{"pair":"WNT1 -> LRP5","headline":"WNT1 binds the LRP5 co-receptor in human-construct experiments; one verified paper.","interaction_type":"direct binding","direction_and_effect":"LRP-5 can bind Wnt-1, like LRP-6; LRP-5 alone did not change LEF-1 reporter activity but enhanced the effect of Wnt-1 [PMID:11336703].","molecular_requirements":"LRP-5 is described as a Wnt coreceptor acting with Frizzled; a Frizzled requirement was not tested in the excerpts [PMID:11336703].","affinity_potency":[],"species_and_systems":"Human LRP-5 constructs in fibroblast cells, co-culture with Wnt-1 transfected cells, full text [PMID:11336703]. The mouse pair is projected from human.","localisation_and_range":"Wnt-1 acted on LRP-5 as a secreted protein in a paracrine coculture [PMID:11336703]; WNT1 is flagged as secreted [flag].","caveats":"Seven other papers were abstract_insufficient. The binding sentence is brief and the paper's focus is Axin binding to the intracellular domain.","key_references":[{"PMID":"11336703","why":"LRP-5 binds Wnt-1; synergy with Wnt"}],"covers":["LR001577","LR004966"]},"LR008093":{"pair":"WNT10A -> FZD8:LRP6","headline":"Functional evidence for WNT10A signalling via FZD8 only; LRP6 contribution in this complex is not shown.","interaction_type":"functional only","direction_and_effect":"Wnt10a induced reporter signalling via FZD5 and FZD8 in HEK293 reporter cells [PMID:28733458].","molecular_requirements":"The evidence concerns FZD8 only; the paper's rescue used FZD genes, and a requirement for LRP6 is not reported in our evidence [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human reporter cells (HEK293) [PMID:28733458]; pair is human.","localisation_and_range":"Ligand flagged secreted; LRP6 flagged transmembrane [flag].","caveats":"The confirmed paper supports the FZD8 chain, not the full complex. Other papers were review-only, abstract-insufficient or a different entity. Functional readout, not binding.","key_references":[{"PMID":"28733458","why":"Wnt10a induces signalling via FZD5 and FZD8 in HEK293 reporter cells"}],"covers":["LR008093"]},"LR003467":{"pair":"WNT10B -> FZD5","headline":"Functional synergy in Xenopus embryos suggests WNT10B signals through mouse Fzd5; abstract only, no binding data.","interaction_type":"functional only","direction_and_effect":"Mouse Fzd5 specifically synergized with Wnt2, Wnt5a and Wnt10b in ectopic axis induction assays in Xenopus embryos; the authors call Wnt5a and Wnt10b likely physiological ligands because they co-localized with Fzd5 in the yolk sac [PMID:11092808].","molecular_requirements":"Not reported in our evidence; LRP co-receptor requirement is not tested in the abstract.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor expressed in Xenopus embryos, plus Fzd5 knockout mice [PMID:11092808]. The pair is human with ortholog-inferred entries for human and mouse.","localisation_and_range":"Ligand flagged secreted [flag]; co-localisation in yolk sac is reported by the authors, hedged [PMID:11092808].","caveats":"Heterologous synergy assay, not binding. The physiological-ligand claim is hedged and based on co-localisation. Abstract only.","key_references":[{"PMID":"11092808","why":"Fzd5 synergizes with Wnt10b in Xenopus axis induction; Fzd5 knockout phenotype"}],"covers":["LR003467","LR006667"]},"LR003476":{"pair":"WNT11 -> ROR2","headline":"WNT11 interacts with ROR2 by co-IP in human breast cancer cells; support is one paper.","interaction_type":"direct binding","direction_and_effect":"V5-WNT11 co-immunoprecipitated ROR2 in ROR2-overexpressing MCF-7 cells; the paper calls WNT11 a novel ligand for human ROR2, with agonist direction annotated [PMID:34911552].","molecular_requirements":"Curator notes say signalling acts via the ROR2 cysteine-rich domain; N-terminal deletion constructs were tested, but their co-IP result is not shown in the excerpts [PMID:34911552].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines (MCF-7, BT-474, MDA-MB-231) [PMID:34911552].","localisation_and_range":"Wnt11 is flagged secreted and ROR2 transmembrane [flag].","caveats":"Co-IP was in ROR2-overexpressing cells, and ROR2 overexpression itself induced WNT11; WNT5A is described as the established ROR2 ligand [PMID:34911552]. No affinity.","key_references":[{"PMID":"34911552","why":"WNT11 as novel ROR2 ligand: co-IP, breast cancer cells"}],"covers":["LR003476","LR006676"]},"LR005366":{"pair":"WNT2 -> FZD2","headline":"WNT2 interacts with FZD2 by co-IP and drives STAT3-dependent invasion in oesophageal cancer cells.","interaction_type":"direct binding","direction_and_effect":"WNT2 and FZD2 interacted (co-IP); WNT2 protein (50 ng/mL) increased FZD2, reduced FZD2 ubiquitination, and activated STAT3, with migration and invasion attenuated by FZD2 knockdown (agonist annotated) [PMID:32766155].","molecular_requirements":"FZD2 knockdown blunted the WNT2 response; no co-receptor requirement reported [PMID:32766155].","affinity_potency":[],"species_and_systems":"Human ESCC cell lines (KYSE30, KYSE150), plus xenograft work in the paper [PMID:32766155].","localisation_and_range":"WNT2 flagged secreted; CAF-secreted WNT2 acts on cancer cells [PMID:32766155]. Mouse pair is ortholog-inferred.","caveats":"Mechanism is non-canonical STAT3, not beta-catenin. No affinity. Co-IP is in overexpression or lysates; domain not reported.","key_references":[{"PMID":"32766155","why":"WNT2-FZD2 interaction and FZD2/STAT3 signalling in ESCC"}],"covers":["LR002040","LR005366"]},"LR004970":{"pair":"WNT2 -> FZD5","headline":"Mouse Fzd5 synergises with Wnt2 in Xenopus axis assays; a functional readout only.","interaction_type":"functional only","direction_and_effect":"Fzd5 specifically synergised with Wnt2, Wnt5a and Wnt10b in ectopic axis induction in Xenopus embryos [PMID:11092808].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse Fzd5 and Wnt2 expressed in Xenopus embryos, abstract only [PMID:11092808]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"No binding assay. The authors name Wnt5a and Wnt10b, not Wnt2, as likely physiological yolk sac ligands [PMID:11092808]. One abstract_insufficient and one review-only row. No affinity.","key_references":[{"PMID":"11092808","why":"Fzd5 synergy with Wnt2 in Xenopus axis induction"}],"covers":["LR001581","LR004970"]},"LR006680":{"pair":"WNT2B -> FZD5","headline":"Direct pull-down: Wnt2b-Fc pulled down Fzd5-CRD (and Fzd4-CRD) in a browser-read full text.","interaction_type":"direct binding","direction_and_effect":"Wnt2b-Fc pulled down Flag-tagged Fzd4-CRD and Fzd5-CRD, and also LRP5 extracellular domain [PMID:21856951].","molecular_requirements":"Cysteine-rich domain of Fzd5 was enough for pull-down; LRP5 extracellular domain also bound Wnt2b-Fc [PMID:21856951].","affinity_potency":[],"species_and_systems":"Recombinant tagged proteins; species not stated in the excerpt [PMID:21856951]. UniProt also notes FZD5 interacts with WNT2B [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Quote is browser-read and marked unverified in the curation notes. The paper is mainly about Fzd4 [PMID:21856951]. Mouse and human pairs are ortholog-inferred.","key_references":[{"PMID":"21856951","why":"Wnt2b-Fc pulls down Fzd5-CRD"}],"covers":["LR003480","LR006680"]},"LR003485":{"pair":"WNT3 -> FZD2","headline":"WNT3 signals through FZD2 in human HEK293T cells, shown by knockout plus rescue; mouse pair is projected from human.","interaction_type":"functional only","direction_and_effect":"Agonist: FZD1, FZD2 and FZD7 are required for Wnt3/3a-induced beta-catenin signalling, and re-expressing FZD2 or FZD7 rescues the TCF4/Wnt reporter and active beta-catenin levels [PMID:28733458].","molecular_requirements":"FZD2 alone rescues in the triple-mutant background; FZD1 and FZD7 are redundant paralogs, and co-receptor requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in HEK293T cells with multiplex CRISPR FZD knockouts [PMID:28733458]. The mouse interaction is ortholog-inferred, not tested.","localisation_and_range":"WNT3 carries a secreted annotation flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Functional rescue, not physical binding; paralog redundancy means FZD2 specificity is not isolated. Only one paper.","key_references":[{"PMID":"28733458","why":"Loss-of-function plus rescue of Wnt3 signalling by FZD2/FZD7"}],"covers":["LR003485","LR006685"]},"LR001595":{"pair":"WNT3 -> FZD7","headline":"WNT3 binds FZD7 by co-immunoprecipitation in two studies and activates beta-catenin signalling through it; the best-supported pair here.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt3 activates Wnt/beta-catenin through FZD7; FZD7 knockdown by siRNA abolished beta-catenin activation in Wnt3-overexpressing HCC cells, and co-immunoprecipitation showed a specific Wnt3-FZD7 interaction [PMID:18313787]. FZD7 binds Wnt3 and Wnt2b in intestinal stem cells; Fzd7 loss causes stem cell loss in vivo [PMID:25892522]. FZD2 or FZD7 re-expression rescues Wnt3 signalling in FZD-mutant HEK293T [PMID:28733458].","molecular_requirements":"FZD7 alone suffices for rescue of Wnt3 signalling in FZD1,2,7 mutant cells [PMID:28733458]; LRP involvement is not tested in these excerpts.","affinity_potency":[],"species_and_systems":"Human HCC cells [PMID:18313787]; epitope-tagged FZD7 and WNT3 co-immunoprecipitated in HEK293T cells, with Fzd7 knockout mice and organoids used in the same study [PMID:25892522]; human HEK293T CRISPR cells [PMID:28733458]. Mouse pair is ortholog-inferred. IntAct lists co-immunoprecipitation and pull-down records [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Co-immunoprecipitation uses overexpressed or tagged proteins; no affinity reported. Paralogs FZD1/FZD2 are redundant [PMID:28733458]. One of the intestinal paper's own sentences cites earlier work for FZD7 as a WNT3 receptor, which is background.","key_references":[{"PMID":"18313787","why":"Wnt3-FZD7 co-IP and FZD7 knockdown in HCC cells"},{"PMID":"25892522","why":"Fzd7 binds Wnt3, required for intestinal stem cells"},{"PMID":"28733458","why":"Knockout plus rescue of Wnt3 signalling"}],"covers":["LR001595","LR004984"]},"LR008903":{"pair":"WNT3A -> APCDD1","headline":"APCDD1 extracellular domain co-precipitates WNT3A in one full-text paper; APCDD1 acts as a Wnt inhibitor rather than a classical signalling receptor.","interaction_type":"direct binding","direction_and_effect":"APCDD1 inhibited WNT3A/LRP5/FZD2-driven TOP/FOP reporter activity in a dose-dependent manner (about 2-fold) in HEK293T cells, so it acts as an inhibitor of Wnt signalling, not an activating receptor [PMID:20393562]. The authors propose it may prevent Wnt receptor complex formation [PMID:20393562].","molecular_requirements":"The APCDD1 extracellular domain alone (APCDD1 delta TM) co-precipitated tagged WNT3A and LRP5; no interaction was found with Fzd2, Fzd8 and Dkk4 [PMID:20393562]. Whether binding is direct or bridged is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant tagged human APCDD1, WNT3A and LRP5 in HEK293T cells; inhibition also seen in chick neural tube and Xenopus embryos [PMID:20393562]. IntAct and UniProt list the same study [DB:IntAct] [DB:UniProt].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence. APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562].","caveats":"Single study; binding shown in vitro with the truncated extracellular domain. No affinity reported. The pair behaves as a decoy-like inhibitor, which matters when using it in signalling-activation inference.","key_references":[{"PMID":"20393562","why":"co-IP of APCDD1 extracellular domain with WNT3A and LRP5, plus reporter inhibition"}],"covers":["LR008903"]},"LR001586":{"pair":"WNT3A -> FZD2","headline":"Well supported: binding and functional evidence across four abstract-level papers for WNT3A acting through FZD2.","interaction_type":"direct binding","direction_and_effect":"WNT3A activates canonical signalling through FZD2: it activated the beta-catenin pathway in FZD2-expressing 32D cells [PMID:25605717], and Fz2 was required for Wnt3a-dependent beta-catenin accumulation [PMID:19910923]. Wnt5a competed with Wnt3a for Fz2 binding and inhibited the beta-catenin pathway [PMID:19910923].","molecular_requirements":"Ror2 enhanced Wnt3a canonical signalling in H441 cells in a manner dependent on cooperation with Fzd2 [PMID:18215320]. Other co-receptor needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding competition in vitro and in intact cells, species unspecified [PMID:19910923]; bio-layer interferometry and 32D cell assays [PMID:25605717]; multiplex FZD1/FZD2/FZD7 mutant HEK293T rescue [PMID:28733458]; H441 lung carcinoma cells [PMID:18215320]. BioGRID lists Affinity Capture-Western and IntAct a bio-layer interferometry record [DB:BioGRID] [DB:IntAct].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"All four papers shown were read as abstracts (the CRISPR paper has excerpts on FZD genes generally). Seven papers are confirmed but only four are shown. No affinity value is given in our abstracts.","key_references":[{"PMID":"25605717","why":"WNT-3A activates canonical signalling through FZD2; binding mapped"},{"PMID":"19910923","why":"Wnt5a competes with Wnt3a at Fz2"},{"PMID":"28733458","why":"CRISPR FZD rescue map"}],"covers":["LR001586","LR004975"]},"LR008129":{"pair":"WNT3A -> FZD2:LRP5","headline":"One full-text paper supports FZD1/2/7 signalling with Wnt3/Wnt3a; the LRP5 component is not specifically tested.","interaction_type":"functional only","direction_and_effect":"FZD1, FZD2 and FZD7 share up to 75% homology and specifically induce signalling after binding Wnt3 and Wnt3a [PMID:28733458]; Wnt3/Wnt3a signalled via all FZDs in rescue experiments [PMID:28733458].","molecular_requirements":"The paper concerns FZD genes; LRP5 involvement is not tested in the quoted passages. FZD2 chain evidence is from a TCF4/Wnt reporter in FZD1,2,7-mutant HEK293T cells [PMID:28733458]. UniProt says an LRP5 interaction is enhanced by WNT1 or WNT3A, without naming a direct WNT3A contact [DB:UniProt] [PMID:11336703].","affinity_potency":[],"species_and_systems":"Human cell lines (HEK293T) with CRISPR-mutant FZD alleles [PMID:28733458].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Chain-only evidence for FZD2; the evidence sentence does not mention LRP5. assay_class is direct_binding though the cited work is a functional reporter rescue. Read depth full text but no affinity.","key_references":[{"PMID":"28733458","why":"FZD1/2/7 rescue of Wnt3a signalling"}],"covers":["LR008129"]},"LR008156":{"pair":"WNT3A -> FZD5:LRP5","headline":"No curated paper for this complex; only database notes.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"Complex requirement is not shown; UniProt notes mention FZD5 interactions of other proteins [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records are UniProt subunit notes and an IntAct pull-down [DB:IntAct]; none shows WNT3A binding to the FZD5:LRP5 complex. Papers were review_only.","key_references":[],"covers":["LR008156"]},"LR010784":{"pair":"WNT3A -> FZD9:LRP6","headline":"No curated paper for this complex; database records on WNT3A and LRP6 only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]; nothing addresses FZD9.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID [DB:BioGRID], IntAct [DB:IntAct] and Reactome complexes with FZD unspecified [DB:Reactome]. FZD9 is not addressed; papers were review_only or abstract_insufficient.","key_references":[],"covers":["LR010784"]},"LR003494":{"pair":"WNT3A -> LGR5","headline":"LGR5 joins a Wnt3a plus R-spondin1 induced complex with LRP6 and Fzd5; direct Wnt3a-LGR5 binding is not shown.","interaction_type":"functional only","direction_and_effect":"After costimulation with R-spondin1 and Wnt3a, LGR5 forms a supercomplex with LRP6 and Fzd5 that is internalised and degraded; LGR5 becomes part of the Wnt complex at the membrane and enhances signalling [PMID:22473993].","molecular_requirements":"Needs R-spondin1 as well as Wnt3a; LRP6 and Fzd5 are in the complex. A C-terminal tail deletion mutant still interacts with LRP6 [PMID:22473993].","affinity_potency":[],"species_and_systems":"Cell-based signalling and internalisation assays; human proteins [PMID:22473993]. Mouse version projected from human.","localisation_and_range":"LGR5 is flagged transmembrane [flag]; membrane-level co-assembly [PMID:22473993].","caveats":"Abstract only. The evidence describes complex co-assembly, not direct binding of Wnt3a to LGR5; the R-spondin ligand drives LGR5 function.","key_references":[{"PMID":"22473993","why":"LGR5 forms a supercomplex with LRP6/Fzd5 on Wnt3a + R-spondin1"}],"covers":["LR003494","LR006694"]},"LR007643":{"pair":"WNT3A -> SFRP2","headline":"Only Reactome complex records support WNT3A:sFRP; the curated paper pool has no verified paper for SFRP2.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory ligand-ligand interaction: sFRP binds Wnt, a decoy that blocks receptor engagement [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond Reactome records.","localisation_and_range":"Both are secreted proteins [flag]; Reactome places the complex in the extracellular region [DB:Reactome].","caveats":"No curator-verified paper; one row was review-only. The Reactome complex is the generic 'WNT3A:sFRP' record, not specific to one sFRP. This is a ligand-ligand pair, not a receptor.","key_references":[],"covers":["LR007643"]},"LR007670":{"pair":"WNT4 -> SFRP2","headline":"Supported only by a BioGRID record (BioGRID Affinity Capture-Western); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory ligand-ligand interaction [DB:BioGRID]. Direction not tested in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the BioGRID record.","localisation_and_range":"Both are secreted proteins [flag].","caveats":"No curator-verified paper; this is a ligand-ligand pair, not a receptor interaction.","key_references":[],"covers":["LR007670"]},"LR008057":{"pair":"WNT5A -> FZD3:LRP6","headline":"No paper-level evidence for WNT5A with the FZD3:LRP6 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records an Affinity Capture-Western for LRP6 - WNT5A [DB:BioGRID] (PMID 19910923).","molecular_requirements":"The complex combines FZD3 and LRP6; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR008057"]},"LR006707":{"pair":"WNT5A -> PTK7","headline":"WNT5A co-immunoprecipitates with PTK7 in human cells and PTK7 is needed for Wnt5a signalling in Xenopus; PTK7 also associates with ROR2.","interaction_type":"direct binding","direction_and_effect":"PTK7 and ROR2 physically and functionally interact with WNT5A, leading to JNK activation and cell movements; Ptk7 is required for Wnt5a-induced papc activation in Xenopus [PMID:26499793]. Curated agonist.","molecular_requirements":"The entire PTK7 extracellular region is required for WNT5A interaction; loops 4-7 are needed for optimal binding. WNT5A binding persisted after ROR2 depletion, so it is not mediated by ROR2 [PMID:26499793].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in HEK 293T cells, MEFs and Xenopus embryos [PMID:26499793].","localisation_and_range":"PTK7 is flagged secreted [flag], but the paper treats it as a membrane receptor with an intracellular domain released after Wnt5a stimulation [PMID:26499793].","caveats":"Co-immunoprecipitation of overexpressed tagged proteins; no affinity measured. Does not distinguish direct binding fully, though ROR2 depletion did not impair it.","key_references":[{"PMID":"26499793","why":"WNT5A-PTK7 co-IP and PCP signalling in Xenopus"}],"covers":["LR003507","LR006707"]},"LR006716":{"pair":"WNT5B -> ROR2","headline":"Wnt5b is stated to bind Ror2 in zebrafish; the paper shows cytoneme transfer of Wnt5b-Ror2 complexes.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt5b with Ror2 triggers Wnt-PCP signalling; active Wnt5b-Ror2 complexes form in the producing cell and are handed over via cytonemes [PMID:38123680].","molecular_requirements":"Receiving cells can start PCP signalling irrespective of their own Ror2 status [PMID:38123680].","affinity_potency":[],"species_and_systems":"Zebrafish embryo [PMID:38123680]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only. Transfer along cytonemes is paracrine contact-based [PMID:38123680].","caveats":"Direct binding is cited as background, not shown in this abstract. Abstract-only reading [PMID:38123680].","key_references":[{"PMID":"38123680","why":"cytoneme transfer of Wnt5b-Ror2 complexes in zebrafish"}],"covers":["LR003516","LR006716"]},"LR005375":{"pair":"WNT7A -> FZD1","headline":"No paper evidence; UniProt states FZD1 is apparently not activated by WNT7A.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper confirms this pair. UniProt says FZD1 is activated by WNT3A, WNT3, WNT1 and less by WNT2, but apparently not by WNT4, WNT5A, WNT5B, WNT6, WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; FZD1 is flagged as a receptor [flag].","caveats":"The only record argues against the pair. Eight abstracts were judged insufficient or about a different entity, so no positive evidence exists in our dossier. Treat as unsupported.","key_references":[],"covers":["LR002049","LR005375"]},"LR008165":{"pair":"WNT7A -> FZD7:LRP5","headline":"Complex support is the WNT7A linker-FZD7 binding only; LRP5 is untested.","interaction_type":"direct binding","direction_and_effect":"The WNT7A C-terminal linker binds FZD7 without activating non-canonical signalling [PMID:36420144].","molecular_requirements":"LRP5 is not addressed in the evidence shown.","affinity_potency":[],"species_and_systems":"Myogenic cells [PMID:36420144].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP5 is flagged transmembrane [flag].","caveats":"Chain-only evidence for FZD7; abstract only; fragment binding.","key_references":[{"PMID":"36420144","why":"WNT7A linker binds FZD7"}],"covers":["LR008165"]},"LR006725":{"pair":"WNT7A -> RECK","headline":"WNT7A binds RECK directly; the best-supported pair here, with a structure and UniProt support.","interaction_type":"direct binding","direction_and_effect":"WNT7A directly binds purified soluble RECK and cell-surface RECK; RECK is described as a selective WNT7 receptor that stabilises active WNT7A, supporting GPR124/FZD/LRP-dependent canonical signalling [PMID:30304675]. A PDB structure has WNT7A and RECK chains [DB:PDB 8TZP]. UniProt records RECK conferring Wnt7 selectivity in brain endothelial cells [DB:UniProt].","molecular_requirements":"RECK and WNT7A associate with 1:1 stoichiometry [PMID:30304675]. WNT7A signalling also needs GPR124, FZD and LRP co-receptors; WNT3A does not bind RECK [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 cells; RECK also tested in rat brain vessels [PMID:30304675]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. RECK is a GPI-anchored protein per the abstract [PMID:30304675].","caveats":"Curated row read from abstract only, though the same paper is full-text verified for other pairs. No affinity reported in our evidence.","key_references":[{"PMID":"30304675","why":"Direct WNT7A-RECK binding, 1:1 stoichiometry"}],"covers":["LR003525","LR006725"]},"LR008066":{"pair":"WNT7B -> FZD4:LRP6","headline":"WNT7B with FZD4 and LRP6 has only a UniProt in vitro note; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records a FZD4 interaction as in vitro [DB:UniProt].","molecular_requirements":"Complex pairs FZD4 with LRP6; no evidence on subunit need.","affinity_potency":[],"species_and_systems":"In vitro per UniProt [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Only review-only papers; support is database-only.","key_references":[],"covers":["LR008066"]},"LR006743":{"pair":"WNT9A -> LRP6","headline":"WNT9A signalling through LRP6 supported by antibody-blocking data in a reporter assay; one paper.","interaction_type":"functional only","direction_and_effect":"Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) inhibited Wnt9a signalling, so LRP6 acts as a co-receptor for Wnt9a; antibodies act as antagonists of the interaction [PMID:20713706].","molecular_requirements":"Antibodies binding LRP6 propeller 1 block Wnt9a, placing its requirement at the first propeller region; Wnt9a is grouped in the Wnt1 class [PMID:20713706].","affinity_potency":[],"species_and_systems":"SuperTopFlash reporter in HEK293 cells; human ligand and receptor [PMID:20713706]; mouse version is projected from human evidence.","localisation_and_range":"WNT9A/WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor chains are membrane receptors [flag].","caveats":"Inference is indirect (antibody blockade); no direct binding or affinity of Wnt9a to LRP6 is reported. Curator read the full text in a browser, but the dossier shows abstract only and the quote is flagged as unverifiable and awaiting spot-check.","key_references":[{"PMID":"20713706","why":"Wnt1-class anti-LRP6 Fabs inhibit Wnt9a signalling"}],"covers":["LR003543","LR006743"]},"LR005384":{"pair":"WNT9B -> FZD10","headline":"WNT9B activates canonical signalling through FZD10 in a human reporter-cell rescue map; one functional study.","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD4 and FZD10 as well as FZD5 and FZD8; effect is activating [PMID:28733458].","molecular_requirements":"FZD10 was tested as a single receptor in rescue; FZD4 and FZD10 cluster together by signalling profile; co-receptor not reported in the evidence for this pair [PMID:28733458].","affinity_potency":[],"species_and_systems":"HEK293 Wnt reporter cells (human; TCF4 luciferase) with FZD knockout and rescue [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional reporter only; no binding data. Reads as 'induced signalling with' rather than demonstrated direct binding.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR002058","LR005384"]},"LR008048":{"pair":"WNT9B -> FZD10:LRP6","headline":"Database-asserted WNT9B to FZD10:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD10 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR008048"]},"LR003548":{"pair":"YBX1 -> NOTCH3","headline":"Single abstract-read paper reports direct, Notch3-selective binding of soluble YBX1 with activation; Reactome also lists the complex.","interaction_type":"direct binding","direction_and_effect":"Soluble Yb-1 (YBX1) interacted specifically with Notch3 but not Notch1 in ligand-binding and signalling assays, and transduced signal to the intracellular domain through the negative regulatory region, consistent with an activating (agonist) effect [PMID:30321499].","molecular_requirements":"Notch3 EGF-like repeats 17-24 were identified as the binding site; modelling predicted the interface as repeats 20-23, different from those used by canonical DSL ligands [PMID:30321499]. Reactome lists NOTCH3 binding YBX1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; the abstract does not state the cell system. A mouse pair is listed but projected from human evidence (ortholog-inferred).","localisation_and_range":"YBX1 is flagged secreted and NOTCH3 transmembrane [flag]; the paper calls it a soluble non-canonical ligand [PMID:30321499].","caveats":"Only one paper, read as abstract only, with no affinity reported. YBX1 is an unconventional secreted ligand; the mouse pair has no experiments of its own.","key_references":[{"PMID":"30321499","why":"Soluble Yb-1 binds Notch3 EGF repeats 17-24, not Notch1"}],"covers":["LR003548","LR006748"]},"LR012377":{"pair":"ZNRF3 -> FZD4:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD4 partner is named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012377"]},"LR010658":{"pair":"ZP3 -> MERTK","headline":"Weak support: a 1995 abstract describes a 95-kDa sperm tyrosine kinase as ZP3 receptor, but MERTK is not named in the abstract.","interaction_type":"functional only","direction_and_effect":"A 95-kDa mouse sperm protein with tyrosine kinase characteristics was identified as a ZP3 receptor; human ZP3 stimulated the kinase activity of the human 95-kDa sperm protein, an agonist-like effect [PMID:7541556].","molecular_requirements":"Not reported in our evidence. Synthetic peptides from the predicted extracellular domain inhibited sperm binding to human zona pellucida [PMID:7541556].","affinity_potency":[],"species_and_systems":"Mouse sperm protein identified; human homolog cloned from a testis expression library and tested on human sperm [PMID:7541556].","localisation_and_range":"ZP3 is flagged secreted and MERTK transmembrane [flag]; the interaction is between egg zona pellucida and sperm, i.e. contact between gametes [PMID:7541556].","caveats":"Abstract only. The abstract does not name MERTK; the link to MERTK rests on the curator's identification. The curator notes medium confidence and a contested history of the sperm ZP3 receptor [PMID:7541556].","key_references":[{"PMID":"7541556","why":"Sperm tyrosine kinase as ZP3 receptor; human ZP3 stimulates it"}],"covers":["LR010658"]},"LR007238":{"pair":"GDF6 -> BMPR1A:BMPR2","headline":"GDF6 signals through BMPR1A (ALK3) with BMPR2; supported by two abstract-read papers, binding to BMPR1A reported as weak.","interaction_type":"direct binding","direction_and_effect":"Stimulatory. ALK3 (BMPR1A) overexpression conferred GDF6 signalling in COS7 cells, ALK3 shRNA suppressed it in MC3T3 cells, and BMPRII shRNA also suppressed signalling; the response is Smad1/5/8-type [PMID:16049014].","molecular_requirements":"Both chains are supported: ALK3 gain of function plus BMPRII loss of function [PMID:16049014]. Binding studies show CDMP-2 (GDF6) has affinity for BMPR-IB and BMPR-II and only weakly for BMPR-IA; BMPR-IB with BMPR-II transduced the signal there [PMID:9525338].","affinity_potency":[],"species_and_systems":"Recombinant proteins in COS7 and MC3T3 cells [PMID:16049014]; ATDC5, ROB-C26 and MC3T3-E1 cells [PMID:9525338]. Human pair; species of the cell lines is not reported in our evidence.","localisation_and_range":"Ligand flagged secreted; receptor complex flagged transmembrane [flag].","caveats":"BMPR1A binding was weak, and BMPR1B was the stronger partner [PMID:9525338]. Both papers read as abstracts only. BioGRID lists GDF6 with BMPR1B and BMPR2 reconstituted complexes, not BMPR1A [DB:BioGRID].","key_references":[{"PMID":"16049014","why":"ALK3 and BMPRII required for GDF6 signalling"},{"PMID":"9525338","why":"Binding of CDMP-2 to BMP receptors, weak for BMPR-IA"}],"covers":["LR007238"]},"LR004718":{"pair":"RSPO4 -> LGR4","headline":"R-spondins bind LGR4 and potentiate Wnt signalling; RSPO4-specific support comes mainly from databases and family-level papers.","interaction_type":"direct binding","direction_and_effect":"R-spondins act as agonist ligands of LGR4 and LGR5, enhancing Wnt/beta-catenin signalling by increasing Wnt-induced LRP6 phosphorylation [PMID:21693646]. Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]. GtoPdb lists RSPO4-LGR4 as a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 does not signal alone: it associates with the Frizzled/Lrp Wnt receptor complex and enhances Wnt signals; it is not coupled to G proteins or beta-arrestin [PMID:21727895][PMID:21693646].","affinity_potency":[],"species_and_systems":"Human cells with Wnt reporter assays and mouse intestinal crypt cultures [PMID:21693646][PMID:21727895]. Mouse pair is projected from human evidence.","localisation_and_range":"RSPO4 annotated as secreted, LGR4 as transmembrane [flag].","caveats":"Both papers were read as abstracts and describe R-spondins generally; RSPO4 is not singled out in them. RSPO1 was the one tested in HEK293 cells [PMID:21727895]. BioGRID, IntAct and Reactome records support binding [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins bind LGR4/5 and potentiate Wnt signalling"},{"PMID":"21727895","why":"Lgr4/5 associate with Frizzled/Lrp and mediate R-spondin signalling"}],"covers":["LR001321","LR004718"]},"LR005339":{"pair":"SPX -> GALR2","headline":"Spexin activates GALR2 in a ligand-receptor study and mediates adipocyte effects via GALR2; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Spexin activates human, Xenopus and zebrafish GALR2/3 receptors but not GALR1 [PMID:24517231]. In adipocytes, spexin effects are mediated via GALR2 and GALR3 [PMID:30305242]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the receptor itself; GALR3 is a companion receptor in the adipocyte study [PMID:30305242].","affinity_potency":[],"species_and_systems":"Human, Xenopus and zebrafish receptors in a ligand-receptor study [PMID:24517231]; murine 3T3-L1 and human adipocytes [PMID:30305242]. Mouse pair is listed as not projected.","localisation_and_range":"Spexin annotated as secreted; GALR2 as transmembrane [flag].","caveats":"Abstract-only reading. The ligand-receptor paper stresses GALR3 potency more than GALR2. The adipocyte paper is functional and does not show binding. UniProt also states spexin is a ligand for GALR2 and GALR3 [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"24517231","why":"Spexin activates GALR2/3 but not GALR1"},{"PMID":"30305242","why":"Spexin effects on adipocytes mediated via GALR2/GALR3"}],"covers":["LR002011","LR005339"]}};